INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('vn-canh-01', 'canh-chua-ca-loc-nam-bo', 0, 'Canh chua cá lóc Nam Bộ', 'Canh cá lóc chua thanh từ me chín, ngọt dịu dứa thơm cùng đậu bắp, bạc hà và rau thơm đặc trưng miền Tây', 'Bát canh chua cá lóc Nam Bộ đậm đà với thịt cá trắng ngọt săn chắc, nước dùng thanh nhẹ hòa quyện vị chua dịu từ me chín, ngọt thanh của dứa chín và rau củ giòn tươi.', 'Dọn canh nóng vào tô lớn, rắc tỏi phi thơm cùng rau ngổ, ngò gai; ăn kèm cơm trắng và chén nước mắm ớt mặn để chấm thịt cá.', 'Nên dùng hết trong ngày để giữ độ giòn của rau; nếu bảo quản tủ mát tối đa 24 giờ, nên vớt riêng phần rau sống/giá đỗ và đun sôi lại phần nước canh cùng cá trước khi ăn.', 'vietnamese', 'mon_canh', 'nam', 'medium', 20, 25, 4, 'https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=800&q=80', '["Món canh","Nam Bộ","Thanh nhiệt","Cá tươi","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["fish"]', 262, 262.3, 1097, 22.6, 7.9, 1.5, 27.3, 3.8, 17.8, 1278, 3.2, '["NIN VN Doc Mung Ref","USDA FDC 169124","USDA FDC 169230","USDA FDC 169260","USDA FDC 169655","USDA FDC 169918","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","VN Culinary Herb Ref","VN Herb Ref"]', '3a3ad657206f987f6806c371e38da6a65eae87d0214f2686ecd072a3817f0533', 'c9e27ff168ca194acc847981e540d9900d783f2bb253fd7c863ddc6d411de725', 4),
('vn-canh-02', 'canh-cua-dong-rau-day-mong-toi', 1, 'Canh cua đồng rau đay mồng tơi mướp hương', 'Món canh giải nhiệt trứ danh mùa hè miền Bắc với tảng riêu cua đồng béo ngậy nấu cùng rau đay, mồng tơi và mướp hương thơm ngọt', 'Bát canh cua đồng thanh mát chuẩn vị Bắc Bộ với phần riêu cua kết mảng dày béo thơm, gạch cua chưng vàng óng quyện cùng rau đay, mồng tơi mềm mướt và mướp hương ngọt dịu.', 'Dọn canh nóng vào tô lớn, gạt nhẹ tảng riêu cua nổi lên mặt cho đẹp mắt; ăn kèm cơm trắng và đĩa cà pháo muối giòn.', 'Canh cua rau đay ngon nhất khi dùng hết trong ngày vì rau dễ bị nhớt và xuống màu; nếu bảo quản tủ mát, chỉ giữ phần nước riêu tối đa 12 giờ và đun sôi lại kỹ.', 'vietnamese', 'mon_canh', 'bac', 'medium', 25, 20, 4, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món canh","Miền Bắc","Mùa hè","Cua đồng","Cơm nhà"]', '["lunch","dinner"]', '["simmer"]', '["crab","crustaceans","fish","shrimp"]', 124, 123.5, 517, 15.3, 4.2, 0.7, 6.9, 2.6, 1.8, 1420, 3.55, '["Asian Shrimp Paste Ref","USDA FDC 168421","USDA FDC 169249","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","VN/Asian Seasoning Powder Avg"]', '5eec2917a08d21f741299b6de1690b65e5f63840a73fab47c56db3fd8115dc93', 'b930d88edece775932bda17c441e2ab6dabeb1d3fc85ee2dc884535695bb4bc1', 4),
('vn-canh-03', 'canh-kho-qua-nhoi-thit', 2, 'Canh khổ qua nhồi thịt thanh mát', 'Khổ qua xanh giòn dịu vị đắng, ôm trọn nhân thịt heo xay quyện mộc nhĩ thơm bùi trong nước dùng trong ngọt thanh nhiệt', 'Món canh truyền thống thanh mát với từng khoanh khổ qua xanh mềm vừa phải, giảm hẳn vị đắng gắt, bao bọc nhân thịt heo xay đậm đà giòn sần sật mộc nhĩ cùng nước canh ngọt dịu.', 'Cắt khúc khổ qua nhồi thịt thành khoanh vừa ăn, xếp vào tô chan nước dùng nóng, rắc hành ngò và tiêu xay; dùng kèm cơm trắng hoặc chén nước mắm ớt.', 'Mở hé nắp khi canh vừa nguội để tránh đọng hơi nước làm canh nhanh chua; bảo quản ngăn mát tối đa 24 giờ và đun sôi kỹ trước khi dùng lại.', 'vietnamese', 'mon_canh', 'nam', 'medium', 25, 30, 4, 'https://images.unsplash.com/photo-1603105037880-880cd4edfb0d?auto=format&fit=crop&w=800&q=80', '["Món canh","Nam Bộ","Thanh nhiệt","Truyền thống","Cơm nhà"]', '["lunch","dinner"]', '["boil","simmer"]', '["egg","pork"]', 240, 240.1, 1004, 14.5, 14.7, 5.3, 13.8, 7.8, 3.7, 984, 2.46, '["USDA FDC 167902","USDA FDC 168393","USDA FDC 168437","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '0de3c6ecd03c2f29ddd622ca434d51afd492038b3e0d628c8130417b73283ff6', '6abd7d7a9fc37b760601f15afc8859b80df857bc21ae0d32410ecc383888e229', 4),
('vn-canh-04', 'canh-suon-bi-dao', 3, 'Canh sườn hầm bí đao ngọt thanh', 'Sườn non heo ninh mềm róc xương hòa quyện vị ngọt mát tự nhiên của bí đao xanh, thơm mùi hành lá và ngò gai', 'Món canh gia đình quen thuộc với nước hầm sườn non trong veo, thịt sườn mềm tơi thấm vị, kết hợp bí đao chín tới trong mướt, giữ trọn vị ngọt mát và thanh nhẹ.', 'Múc canh sườn bí đao ra tô lớn khi còn nóng, rắc hành lá, ngò gai và chút tiêu xay; dọn cùng cơm trắng và các món mặn như thịt kho hoặc cá chiên.', 'Canh sườn bí đao bảo quản trong hộp kín ở ngăn mát tủ lạnh được 1–2 ngày; khi ăn lại chỉ cần đun sôi lăn tăn vừa đủ nóng để bí không bị nhũn nát.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 35, 4, 'https://images.unsplash.com/photo-1574484284002-952d92456975?auto=format&fit=crop&w=800&q=80', '["Món canh","Cơm nhà","Bổ dưỡng","Thanh mát","Dễ nấu"]', '["lunch","dinner"]', '["boil","simmer"]', '["fish","pork"]', 260, 260.4, 1089, 12.7, 20.6, 6.8, 6.1, 3.3, 2.3, 1458, 3.65, '["USDA FDC 167861","USDA FDC 169214","USDA FDC 169231","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN/Asian Seasoning Powder Avg"]', '8241f864d7db77000fc64fe6c0c64fedbada174536a0cc6c4b3173bc74311c55', '93d56a3a6a6c3b3e6f53f0df50d388ba59e9795201ef2abb5db486c50f44aee3', 4),
('vn-canh-05', 'canh-bi-do-thit-bam', 4, 'Canh bí đỏ thịt bằm hạt sen', 'Bí đỏ chín bùi sánh mịn nấu cùng thịt heo nạc băm ngọt đậm và hạt sen bở thơm, giàu dinh dưỡng cho mọi lứa tuổi', 'Tô canh vàng óng bắt mắt với từng miếng bí đỏ mềm bùi tan nhẹ, hạt sen bở thơm quyện cùng thịt heo băm xào tơi đậm đà và mùi thơm dịu của hành lá, ngò gai.', 'Dọn canh nóng vào tô lớn, rắc thêm ngò gai thái nhỏ và chút tiêu xay; ăn kèm cơm trắng rất hợp cho bữa tối gia đình có trẻ nhỏ và người lớn tuổi.', 'Để canh nguội hoàn toàn rồi bảo quản trong hộp kín ở ngăn mát tối đa 24 giờ; khi hâm lại nên đun lửa nhỏ và khuấy nhẹ để phần bí sánh không bén đáy nồi.', 'vietnamese', 'mon_canh', 'toan_quoc', 'easy', 15, 22, 4, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Món canh","Bổ dưỡng","Cơm nhà","Trẻ em thích","Nhanh gọn"]', '["lunch","dinner"]', '["simmer"]', '["fish","pork"]', 231, 230.6, 965, 11.2, 14.2, 4.5, 15.6, 1.4, 5.8, 1282, 3.21, '["USDA FDC 167902","USDA FDC 168448","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170148 Fresh","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN/Asian Seasoning Powder Avg"]', 'eb715f5672a55698fa18e87c1af029e5e17ae8287d8e9a983fa9644f4e859131', '2f8650c56faac564cd7ca5190567ebcafaa5bf78f7380470babc0b3e4c8b6a95', 4),
('vn-canh-06', 'canh-ngao-nau-chua-thi-la', 5, 'Canh ngao nấu chua thì là', 'Nước luộc ngao ngọt khiết kết hợp vị chua dịu từ dứa, cà chua và hương thơm nồng đặc trưng của rau thì là chuẩn vị Bắc', 'Món canh giải nhiệt thanh đạm quen thuộc trong mâm cơm miền Bắc với phần nước luộc ngao trong vắt ngọt tự nhiên, chua dịu hài hòa từ dứa và cà chua cùng mùi thơm quyến rũ của thì là.', 'Múc canh ngao ra tô lớn khi vừa chín tới, ăn nóng cùng cơm trắng hoặc chan bún tươi đều rất bắt vị; dùng kèm rau sống hoặc cà muối càng thêm đưa cơm.', 'Canh hải sản ngon nhất khi ăn ngay trong bữa; không nên để qua đêm vì ngao dễ có mùi tanh và rau thì là bị úa màu.', 'vietnamese', 'mon_canh', 'bac', 'easy', 20, 20, 4, 'https://images.unsplash.com/photo-1534939561126-855b8675edd7?auto=format&fit=crop&w=800&q=80', '["Món canh","Miền Bắc","Hải sản","Thanh mát","Dễ nấu"]', '["lunch","dinner"]', '["boil","simmer"]', '["fish","molluscs"]', 180, 179.6, 752, 18.1, 4.7, 0.6, 16.7, 1.9, 8.8, 1382, 3.46, '["USDA FDC 169124","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 174212","VN/Asian Seasoning Powder Avg"]', '5c17f77b7c3bfd8f61d1d5e1eb434cae477589a6d1c8de3393660a2edc1e3fd9', '2d3bc431fb2ce9462ef188afe54d92bcaf740675305e6d7f1940f64c75368655', 4),
('vn-kho-01', 'thit-kho-trung', 6, 'Thịt kho tàu nước dừa trứng gà', 'Thịt ba chỉ cắt vuông kho nhừ cùng nước dừa xiêm và trứng gà luộc, lên màu cánh gián óng ả chuẩn vị Nam Bộ', 'Nồi thịt kho tàu Nam Bộ mềm rệu với phần mỡ trong veo không ngấy, thịt nạc thấm vị mặn ngọt hài hòa từ nước dừa tươi và nước mắm ngon, quyện cùng trứng gà bùi thơm.', 'Múc thịt và trứng ra tô sâu lòng, chan nước kho óng ả, dùng nóng với cơm trắng dẻo và dưa giá hoặc cải chua giải ngấy.', 'Để nguội hoàn toàn rồi bảo quản ngăn mát tối đa 4 ngày trong hộp kín; khi ăn hâm lại trên lửa nhỏ cho thịt nóng đều, nước kho càng kho lại càng đậm đà.', 'vietnamese', 'mon_kho', 'nam', 'medium', 25, 65, 4, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', '["Món kho","Nam Bộ","Cơm nhà","Món Tết","Thịt heo"]', '["lunch","dinner"]', '["braise","boil"]', '["egg","fish","pork"]', 819, 818.6, 3424, 20.4, 74.9, 26.5, 14.9, 1.5, 11.5, 1256, 3.14, '["USDA FDC 167820","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170174","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'de8d934322eee9a2246700b4161fc4288eb1199c02d632affe549f1db9357c3b', '5b0c2b906316a39470d9ac647dfa6324a3f842bac19c336ee3174711029d2ccc', 4),
('vn-kho-02', 'ca-loc-kho-to-tieu-den', 7, 'Cá lóc kho tộ tiêu đen', 'Cá lóc đồng cắt khứa kho săn trong tộ đất cùng tóp mỡ giòn béo, nước mắm đường sánh kẹo và tiêu đen cay nồng', 'Khứa cá lóc đồng chắc thịt thấm đẫm nước sốt kho sánh bóng màu cánh gián, béo thơm tóp mỡ rán giòn, cay ấm vị ớt hiểm và tiêu đen xay.', 'Dọn nguyên tộ cá nóng hổi lên bàn ăn cùng cơm trắng hoặc cơm cháy giòn, kèm dưa leo và đĩa rau luộc chấm nước kho.', 'Bảo quản tộ cá trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn thêm 1–2 muỗng nước ấm và đun lửa nhỏ cho nước sốt sánh bóng lại.', 'vietnamese', 'mon_kho', 'nam', 'medium', 20, 35, 3, 'https://images.unsplash.com/photo-1617093727343-374698b1b08d?auto=format&fit=crop&w=800&q=80', '["Món kho","Niêu đất","Nam Bộ","Cá lóc","Đậm đà"]', '["lunch","dinner"]', '["braise","pan_fry"]', '["fish","pork"]', 417, 416.8, 1743, 30.6, 27.2, 9, 11.2, 0.8, 8.2, 1403, 3.51, '["USDA FDC 167820","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175176","VN/Asian Seasoning Powder Avg"]', '7dc7bc1032f3c2af9796fe30c400fc6071a2f3d8a90c954003680554c2566f83', '777da9d686e142d26bbbe889280f1deabca2292407b72cd10e43e7ea7d763dfd', 4),
('vn-kho-03', 'ga-ta-kho-gung-sa', 8, 'Gà ta kho gừng sả', 'Thịt đùi gà ta dai ngọt kho săn cùng gừng tươi thái sợi và sả băm thơm nồng, nước sốt sánh óng cực bắt cơm', 'Thịt đùi gà ta giữ nguyên da dai giòn, từng thớ thịt thấm đẫm vị mặn ngọt hài hòa quyện mùi thơm cay ấm của gừng thái sợi và sả băm vàng ruộm.', 'Múc gà kho ra đĩa sâu lòng, rưới nước sốt gừng sả óng vàng lên trên và ăn nóng cùng cơm trắng, canh rau cải xanh.', 'Bảo quản trong hộp đậy kín ở ngăn mát tối đa 3 ngày; khi dùng thêm 1 muỗng canh nước lọc và đun lửa nhỏ đến khi gà nóng đều.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 15, 25, 4, 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=800&q=80', '["Món kho","Gà ta","Gừng sả","Ấm bụng","Cơm nhà"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["chicken","fish"]', 318, 317.6, 1329, 25.1, 18.3, 4.4, 12.7, 0.6, 6.2, 1312, 3.28, '["USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'b9671283feb805c51afb893ec88f2a23b1850532f3ae99da86773afaf6e6fbe4', 'c7375faf000974751aa0584fd29a91768141fedfadbb800b65f64c72469f3a1f', 4),
('vn-kho-04', 'suon-heo-xao-chua-ngot', 9, 'Sườn heo xào chua ngọt', 'Sườn non chiên vàng giòn bên ngoài, mềm róc xương bên trong, áo đẫm nước sốt cà chua giấm đường sánh bóng đậm vị', 'Từng dẻ sườn non chiên xém vàng quyện lớp sốt đỏ cam sánh mịn có vị chua thanh từ giấm gạo, ngọt dịu từ đường và cà chua chín, thịt mềm ngọt dễ tách xương.', 'Bày sườn ra đĩa lớn, rưới đều sốt chua ngọt và rắc hành lá thái nhỏ cùng tiêu xay; ăn nóng với cơm trắng và canh rau ngót.', 'Bảo quản hộp kín trong ngăn mát tối đa 2 ngày; khi ăn cho thêm 1–2 muỗng canh nước lọc và đảo lại trên chảo lửa nhỏ cho sốt sánh nóng.', 'vietnamese', 'mon_kho', 'bac', 'medium', 20, 25, 4, 'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?auto=format&fit=crop&w=800&q=80', '["Sườn non","Chua ngọt","Bắc Bộ","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","pan_fry","boil"]', '["fish","pork"]', 387, 387.4, 1621, 15.8, 28.3, 8.8, 17.6, 1.5, 13.3, 1283, 3.21, '["USDA FDC 167861","USDA FDC 169076","USDA FDC 169230","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '98d6bef98544fab9ed73df043e58483dde6947c373466e03cb335dec25902c81', 'c9f7886eed78dfa0d9f31cd5eb7c0de60c616a80cf29aee453bdba55b2e885e6', 4),
('vn-kho-05', 'tom-rim-man-ngot', 10, 'Tôm rim mặn ngọt tỏi ớt', 'Tôm tươi vỏ giòn thịt ngọt rim săn cùng nước mắm đường sánh keo và tỏi ớt thơm lừng, món mặn nhanh gọn cho bữa cơm gia đình', 'Tôm tươi giữ nguyên vỏ rang săn rồi rim kẹo với nước mắm ngon và đường thắng cánh gián, vị mặn ngọt hài hòa, thịt tôm săn chắc thơm mùi hành tỏi phi.', 'Trút tôm rim ra đĩa, rắc hành lá và tiêu xay; ăn nóng với cơm trắng cùng rau muống luộc hoặc canh chua thanh mát.', 'Ngon nhất khi ăn trong bữa; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và làm nóng nhanh trên chảo lửa nhỏ với chút nước lọc.', 'vietnamese', 'mon_kho', 'toan_quoc', 'easy', 10, 15, 3, 'https://images.unsplash.com/photo-1559742811-822873691df8?auto=format&fit=crop&w=800&q=80', '["Món rim","Hải sản","Nhanh gọn","Đưa cơm","Cơm nhà"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["crustaceans","fish","shrimp"]', 195, 194.9, 816, 24.8, 6.2, 0.9, 10.9, 0.6, 8.7, 1241, 3.1, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179"]', '41b7213a4c5c8d49f45de7f3ea3f41a6b72a218b15314482cd37383a8c437dce', 'a033e72763755cd86724fe240f41ad8d88e9d9f4c04d2fd17452b7a648f4bc93', 4),
('vn-kho-06', 'thit-ba-chi-kho-cu-cai', 11, 'Thịt ba chỉ kho củ cải trắng', 'Thịt ba chỉ heo mềm béo kho hai lần lửa cùng củ cải trắng ngọt thanh, nước kho hổ phách sóng sánh chuẩn cơm nhà Bắc Bộ', 'Những miếng thịt ba chỉ đan xen nạc mỡ mềm tan hòa cùng từng khúc củ cải trắng thấm vị ngọt thanh và nước màu hổ phách đậm đà, cực kỳ hao cơm trong những ngày se lạnh.', 'Múc thịt và củ cải ra đĩa sâu lòng, chan nước kho óng ả và rắc hành lá, tiêu xay; ăn nóng cùng cơm trắng và đĩa rau cải luộc.', 'Bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi ăn đun nóng lại trên lửa nhỏ, thịt và củ cải thấm vị càng mềm ngon.', 'vietnamese', 'mon_kho', 'bac', 'easy', 20, 45, 4, 'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80', '["Món kho","Bắc Bộ","Mùa đông","Cơm nhà","Thịt heo"]', '["lunch","dinner"]', '["braise","stir_fry"]', '["fish","pork"]', 739, 739.2, 3092, 13.4, 70.6, 24.8, 12.6, 2.2, 9, 1513, 3.78, '["USDA FDC 167820","USDA FDC 168452","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'b91e783ed6acd2a35a38516f81070643a25c53c38d90ec7fff228bfc45ec2ade', '0286660156bbe2f9cbba0690eb825eb6d29f1902beda66b678037e82f5e983a5', 4),
('vn-xao-01', 'rau-muong-xao-toi', 12, 'Rau muống xào tỏi xanh giòn', 'Rau muống ngọn non xanh mướt giòn sần sật, dậy mùi thơm nồng của tỏi ta phi vàng và chút tỏi tươi đảo cuối', 'Đĩa rau muống xào tỏi chuẩn vị cơm nhà với cọng rau xanh mướt không bị thâm đen, giòn ngọt tự nhiên quyện vị đậm đà của nước mắm ngon và hương tỏi phi vàng ruộm thơm lừng.', 'Gắp rau muống ra đĩa, rắc thêm vài lát ớt sừng đỏ lên trên; ăn nóng ngay cùng cơm trắng và chấm kèm nước tương tỏi ớt hoặc nước mắm chanh ớt.', 'Món rau xào ngon nhất khi ăn ngay lúc vừa bắc xuống để giữ độ giòn và màu xanh; hạn chế để qua đêm hoặc hâm lại nhiều lần vì rau dễ bị nhũn và sẫm màu.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 12, 8, 3, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', '["Món xào","Rau xanh","Thanh đạm","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["fish"]', 115, 115, 481, 3.3, 8.6, 1.3, 8.2, 2, 2, 945, 2.36, '["USDA FDC 169230","USDA FDC 169378","USDA FDC 169655","USDA FDC 170106","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'b8210bec08577514fd03576f30f5d7970c28c2710e8e7481154c5581133f0d0f', 'e4fa01e17a4e3a0c553743e572b0709d55fca5f2b45993bbec40afd2e8b9ac58', 4),
('vn-xao-02', 'bo-xao-can-toi-hanh-tay', 13, 'Bò xào cần tỏi hành tây mềm ngọt', 'Thịt thăn bò thái mỏng xào lửa lớn giữ trọn độ mềm mọng nước, quyện hương thơm nồng đặc trưng của cần tây, tỏi tây và hành tây giòn ngọt', 'Món bò xào cần tỏi hành tây kiểu Bắc đậm đà truyền thống với những lát thịt bò thăn mềm mọng, không hề bị dai, hòa quyện cùng sắc xanh giòn của cần tây, tỏi tây và vị ngọt thanh từ hành tây, cà chua.', 'Trút thịt bò xào ra đĩa rộng, rắc thêm tiêu đen xay lên trên; ăn nóng kèm cơm trắng dẻo và chén nước tương dầm ớt.', 'Ngon nhất khi ăn nóng ngay sau khi xào; nếu còn dư, cất hộp kín trong ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo lửa lớn trong 1 phút trước khi ăn để thịt bò không bị chín kỹ quá mức.', 'vietnamese', 'mon_xao', 'bac', 'easy', 18, 12, 3, 'https://images.unsplash.com/photo-1512058564366-18510be2db19?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Miền Bắc","Cơm nhà","Giàu đạm"]', '["lunch","dinner"]', '["stir_fry"]', '["beef","celery","molluscs","soybean","wheat"]', 345, 345.4, 1445, 23.4, 20.7, 5.6, 17.1, 3.1, 6.7, 1161, 2.9, '["USDA FDC 169230","USDA FDC 169246","USDA FDC 169655","USDA FDC 169988","USDA FDC 170000","USDA FDC 170187","USDA FDC 170457","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', 'fa07e902d49b5fd75329c964adb92f486caf1afd826a6d1fdb1809f0df746184', '673fac71b7b05d2ee74f2cf36fc698319e5d9776a53ac8843c9c9156944dcb6f', 4),
('vn-xao-03', 'muc-xao-can-toi-dua', 14, 'Mực ống xào cần tỏi dứa chua ngọt', 'Mực ống tươi dày mình giòn sần sật xào lửa lớn cùng dứa chín, cà chua, cần tây và tỏi tây đậm đà hương vị biển', 'Món mực ống xào cần tỏi dứa hài hòa sắc màu đỏ cam của cà chua, vàng tươi của dứa chín và xanh mướt của cần tỏi tây. Từng miếng mực giòn ngọt sần sật, thấm vị nước mắm thơm ngon mà không hề bị tanh hay ra nước.', 'Dọn mực xào ra đĩa bầu dục khi còn bốc khói, rắc tiêu xay và vài lát ớt sừng; ăn nóng với cơm trắng hoặc chấm thêm nước mắm ớt gừng.', 'Mực xào nên dùng hết trong bữa để giữ độ giòn đặc trưng; nếu bảo quản tủ mát trong ngày, hâm nóng lại rất nhanh trên chảo lửa lớn khoảng 1 phút để tránh mực bị dai.', 'vietnamese', 'mon_xao', 'toan_quoc', 'medium', 20, 12, 3, 'https://images.unsplash.com/photo-1535400255456-984241443b29?auto=format&fit=crop&w=800&q=80', '["Món xào","Hải sản","Chua ngọt","Đãi khách","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["celery","fish","molluscs","squid"]', 304, 303.5, 1270, 23.3, 10.6, 1.8, 30.1, 3.9, 12.6, 1017, 2.54, '["USDA FDC 169124","USDA FDC 169230","USDA FDC 169231","USDA FDC 169246","USDA FDC 169655","USDA FDC 169988","USDA FDC 170000","USDA FDC 170106","USDA FDC 170457","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 174223","VN/Asian Seasoning Powder Avg"]', '4d7b7c10adae4a05ff60fc48351103f50bf9e9328c7e4130939c5f3a570f1e29', 'd321d932925a72b1fdfb4bb61f94ab8c6723f2b6ee9774d5fe563ce3e9186305', 4),
('vn-xao-04', 'thit-bo-xao-bong-cai', 15, 'Thịt bò xào bông cải xanh cà rốt', 'Bông cải xanh giòn mát và cà rốt ngọt thanh xào lửa lớn cùng thịt thăn bò mềm thơm đậm vị dầu hào', 'Đĩa thịt bò xào bông cải xanh cà rốt bắt mắt với sắc xanh ngọc của súp lơ, cam tươi của cà rốt và lát thịt bò mềm mọng nước thấm sốt dầu hào, vừa thanh mát giàu chất xơ vừa đủ đạm cho bữa cơm gia đình.', 'Bày thịt bò xào bông cải ra đĩa lớn khi còn nóng, rắc hành lá và tiêu xay; ăn kèm cơm trắng và chén nước tương ớt lát.', 'Dùng ngon nhất ngay sau khi nấu; nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, hãy đảo nhanh lại trên chảo nóng trong 1 phút trước khi ăn.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 18, 12, 3, 'https://images.unsplash.com/photo-1543339308-43e59d6b73a6?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Rau xanh","Giàu chất xơ","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["beef","fish","molluscs","soybean","wheat"]', 325, 325.2, 1361, 24.5, 19.4, 5.4, 14.4, 3.6, 5, 1233, 3.08, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170187","USDA FDC 170379","USDA FDC 170393","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '15e87e3fef83f1df41088209d666edadc003ab6af5fd48648a20cf1ff92747a1', 'dbd512ab1e1f4c18119ba49ac42322bd375a93b50cedd3e36f4da06f8ee4fb01', 4),
('vn-xao-05', 'su-su-xao-trung-ga', 16, 'Su su xào trứng gà thanh ngọt', 'Su su non thái sợi giòn ngọt tự nhiên ôm lấy từng mảng trứng gà vàng ươm béo nhẹ, thơm mùi hành tím và ngò rí', 'Su su xào trứng gà là món xào mộc mạc quen thuộc của mâm cơm miền Bắc. Từng sợi su su giữ được độ giòn ngọt thanh mát quyện cùng lớp trứng gà tơi mềm vàng óng và hương thơm dịu của hành lá, ngò rí.', 'Múc su su xào trứng ra đĩa phẳng, rắc ngò rí thái nhỏ và chút tiêu đen xay lên trên; dùng nóng cùng cơm trắng và chén nước mắm ớt.', 'Món xào trứng nên ăn hết ngay trong bữa khi còn nóng để không bị tanh và su su giữ được độ giòn; tránh để qua đêm.', 'vietnamese', 'mon_xao', 'bac', 'easy', 15, 10, 3, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=800&q=80', '["Món xào","Rau củ","Tiết kiệm","Dưới 20 phút","Miền Bắc"]', '["lunch","dinner"]', '["stir_fry"]', '["egg","fish"]', 187, 186.9, 781, 7.9, 12.8, 2.7, 11.9, 3.9, 4.4, 1176, 2.94, '["USDA FDC 169990","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', 'a77d2b3e81d45150e5ca4600198ff4903f3f09f25163d1a7494bf0dbc55b76e6', 'e52004f1799a9f27034437332931523b62ea80aa3752b48f1fb2902943210803', 4),
('vn-xao-06', 'dau-cove-xao-thit-bo', 17, 'Đậu cô ve xào thịt bò giòn ngọt', 'Đậu cô ve tước xơ xào vừa chín tới giữ màu xanh non mướt, quyện thịt thăn bò mềm thơm đậm đà sốt dầu hào', 'Đậu cô ve xào thịt bò là món xào kinh điển của bữa cơm Việt với những khúc đậu giòn sần sật, xanh mướt không bị hăng kết hợp cùng lát thịt thăn bò mềm ngọt đậm vị tỏi phi và dầu hào.', 'Bày đậu cô ve xào thịt bò ra đĩa lớn, rắc hành lá và tiêu đen xay; ăn nóng với cơm trắng cùng chén nước tương dầm ớt.', 'Món ăn ngon nhất khi dùng nóng ngay; nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và đảo nhanh lại trên chảo lửa lớn 1 phút khi ăn.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 18, 12, 3, 'https://images.unsplash.com/photo-1550547660-d9450f859349?auto=format&fit=crop&w=800&q=80', '["Món xào","Thịt bò","Rau xanh","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["beef","fish","molluscs","soybean","wheat"]', 353, 353.1, 1478, 26.7, 22.4, 6.3, 12, 2.9, 5, 1371, 3.43, '["USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170005","USDA FDC 170187","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '9719d53b601c3db5f71b97d1b1104c84aafe595bec82415c7bd76294630b5509', '331a3279e32e6d2e69b3c3d0f31ee3ccd657272862d6acd01907540b36234aaa', 4),
('vn-chien-01', 'dau-phu-sot-ca-chua', 18, 'Đậu phụ lướt ván sốt cà chua', 'Đậu phụ chiên vàng vỏ ngoài mềm núng nính bên trong, quyện sốt cà chua đỏ sánh thơm hành lá', 'Đậu phụ lướt ván sốt cà chua là món cơm nhà dân dã quen thuộc khắp ba miền. Miếng đậu phụ trắng được thấm khô và chiên nhanh lửa vừa để lớp vỏ vàng mỏng giòn nhẹ, ruột vẫn mềm béo, sau đó om dịu trong sốt cà chua chín đỏ đậm vị nước mắm và hành lá.', 'Dọn nóng ra đĩa sâu lòng, rưới phần sốt cà chua sánh mịn lên mặt đậu, rắc tiêu xay và ăn kèm cơm trắng nóng cùng rau muống luộc.', 'Món ngon nhất khi dùng ngay trong bữa; nếu còn dư, cất hộp kín trong ngăn mát tủ lạnh tối đa 24 giờ và hâm lại trên chảo lửa nhỏ với chút nước lọc để sốt không khô cháy.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 10, 15, 3, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chiên","Đậu phụ","Cơm nhà","Tiết kiệm","Dưới 30 phút"]', '["lunch","dinner"]', '["pan_fry","simmer"]', '["fish","molluscs","soybean","wheat"]', 262, 262.1, 1096, 18.3, 15.7, 2.3, 17.2, 3.6, 8, 1303, 3.26, '["USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172475","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '68e886d5f176160904065430a905bc5a59aef0804e273b6a1b3b4519afeec8d9', '0a896a530add4f15a1a418658443afe13f916473040e45928bb272f7aa391880', 4),
('vn-chien-02', 'trung-chien-thit-bam-nam-rom', 19, 'Trứng chiên thịt bằm nấm rơm', 'Trứng gà đánh sữa tươi chiên phồng mềm xốp, quyện nhân thịt heo xay đậm đà và nấm rơm giòn ngọt', 'Trứng chiên thịt bằm nấm rơm là món ăn nhanh giàu dinh dưỡng rất được yêu thích trong bữa cơm gia đình Việt. Nhân thịt bằm và nấm rơm được xào ráo nước trước khi hòa cùng hỗn hợp trứng gà đánh sữa tươi và chút dầu mè, giúp miếng trứng chiên phồng dày, thơm béo mà không bị chảy nước.', 'Cắt miếng trứng thành hình tam giác như miếng bánh, bày ra đĩa cùng vài lát dưa leo, dùng nóng với cơm trắng và nước tương ớt hoặc nước mắm tỏi ớt.', 'Ngon nhất ngay sau khi chiên khi mặt trứng còn phồng mềm. Có thể bảo quản hộp kín trong ngăn mát tủ lạnh 24 giờ và hâm áp chảo lửa nhỏ 2–3 phút mỗi mặt không cần thêm dầu.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 15, 12, 3, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=800&q=80', '["Món chiên","Trứng chiên","Nhanh gọn","Cơm nhà","Dưới 30 phút"]', '["lunch","dinner"]', '["pan_fry","stir_fry"]', '["egg","fish","milk","pork","sesame"]', 395, 395.2, 1653, 22.5, 30.9, 9.1, 6.3, 1.1, 2.3, 1025, 2.56, '["USDA FDC 167902","USDA FDC 169230","USDA FDC 169251","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171028","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', '3f739d82232247a2cf22e750db1a35f587b990c125207b0455a9ae93bd269984', '0681f57394935147485f01dbb818a3cdcb2c453b2b3358a3e2a75bee12dff821', 4),
('vn-chien-03', 'canh-ga-chien-nuoc-mam', 20, 'Cánh gà chiên nước mắm tỏi ớt', 'Cánh gà chiên ngập dầu da giòn rụm thịt mọng nước, áo đều sốt nước mắm tỏi ớt chua ngọt óng ánh', 'Cánh gà chiên nước mắm tỏi ớt là món khoái khẩu của cả trẻ nhỏ lẫn người lớn nhờ lớp da vàng giòn rụm bên ngoài, thịt gà bên trong vẫn giữ độ mọng mềm không khô bã, quyện sốt nước mắm tỏi ớt cân bằng vị mặn, ngọt, cay nhẹ rất bắt cơm.', 'Xếp cánh gà ra đĩa lót xà lách và cà chua thái lát, rưới phần tỏi ớt phi thơm còn lại trong chảo lên trên, ăn nóng cùng cơm trắng hoặc bánh mì.', 'Nên ăn nóng ngay sau khi xóc sốt để giữ độ giòn của da gà. Nếu bảo quản tủ lạnh tối đa 2 ngày, làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4–5 phút.', 'vietnamese', 'mon_chien', 'toan_quoc', 'medium', 15, 25, 4, 'https://images.unsplash.com/photo-1527477396000-e27163b481c2?auto=format&fit=crop&w=800&q=80', '["Món chiên","Cánh gà","Món nhậu","Trẻ em thích","Đậm đà"]', '["lunch","dinner"]', '["deep_fry","pan_fry"]', '["chicken","fish","wheat"]', 478, 478.3, 2001, 26.4, 32, 7.5, 20.2, 0.9, 7.1, 1215, 3.04, '["Panko / Batter Mix Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171080","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC Sriracha Ref"]', '9e56f9cba2cbfe234ef7c625290e674d086dbd8fa9857aaff882a4e39806aadf', 'dea084be57237c16209dea3708cc6402438f6f54a65438a19b8f5ad5565199c8', 4),
('vn-chien-04', 'cha-ca-hai-phong', 21, 'Chả cá chiên thì là hạt tiêu', 'Chả cá thác lác quết dai giòn cùng mỡ heo hạt lựu, thơm nức mùi thì là tươi và tiêu xay cay ấm', 'Chả cá chiên thì là hạt tiêu mang hương vị đặc trưng của ẩm thực vùng duyên hải Bắc Bộ. Thịt cá tươi được giữ lạnh rồi quết nhuyễn cùng thịt nạc vai và mỡ heo hạt lựu, hòa quyện hương thơm nồng nàn của rau thì là tươi và hạt tiêu xay, tạo nên từng miếng chả vàng phồng dai giòn hấp dẫn.', 'Dọn chả cá chiên nóng hổi ra đĩa, chấm cùng tương ớt hoặc nước mắm chanh tỏi ớt, ăn kèm cơm trắng nóng hoặc kẹp bánh mì, rau sống.', 'Chả cá chiên sơ có thể bọc kín bảo quản ngăn mát 2 ngày hoặc cấp đông 2 tuần; khi ăn chỉ cần chiên lại lửa vừa 4–5 phút hoặc quay nồi chiên không dầu ở 180°C trong 5 phút.', 'vietnamese', 'mon_chien', 'bac', 'medium', 25, 15, 4, 'https://images.unsplash.com/photo-1534766555764-ce878a5e3a2b?auto=format&fit=crop&w=800&q=80', '["Món chiên","Chả cá","Bắc Bộ","Hải sản","Đặc sản"]', '["lunch","dinner"]', '["deep_fry","boil"]', '["egg","fish","pork"]', 436, 435.6, 1823, 31.7, 29, 8, 11.2, 1.1, 3.6, 1399, 3.5, '["USDA FDC 167820","USDA FDC 167847","USDA FDC 169655","USDA FDC 169717","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172233","USDA FDC 173468","USDA FDC 175148","USDA FDC Sriracha Ref","VN/Asian Seasoning Powder Avg"]', '6805b7bec90940e090ccc0a7c0b6362b28f76a8a308aca3df2b46f65617314a6', '7112704967a85a7cd37cfce73f27f39d92b60e4ac057400db1fbc2d9919e9742', 4),
('vn-chien-05', 'nem-ran-truyen-thong-ha-noi', 22, 'Nem rán truyền thống Hà Nội', 'Vỏ bánh đa nem giòn tan vàng ruộm nhờ chiên hai lần, ôm trọn nhân thịt tôm nấm củ ngọt thơm chấm mắm chua ngọt', 'Nem rán truyền thống Hà Nội là món ăn tinh hoa không thể thiếu trong mâm cỗ ngày Tết và bữa cơm sum họp. Nhân nem kết hợp hài hòa thịt nạc vai xay, tôm tươi, mộc nhĩ, nấm hương, miến dong cùng củ đậu, cà rốt, su hào và lòng đỏ trứng, gói bằng bánh đa nem phết nước giấm loãng rồi rán hai lửa để vỏ giòn lâu.', 'Cắt nem thành khúc vừa ăn, bày lên đĩa cùng rau sống, kinh giới, tía tô và chén nước mắm chua ngọt tỏi ớt nổi đẹp, ăn kèm cơm nóng hoặc bún rối.', 'Sau khi rán sơ lần một và để nguội hẳn, có thể xếp nem vào hộp có lót giấy nến cấp đông tới 1 tháng; khi ăn rã đông sơ rồi rán lần hai ở lửa vừa đến khi vàng giòn rụm.', 'vietnamese', 'mon_chien', 'bac', 'hard', 35, 25, 4, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80', '["Món chiên","Nem rán","Hà Nội","Truyền thống","Tiệc tùng"]', '["lunch","dinner"]', '["deep_fry","assemble"]', '["crustaceans","egg","fish","pork","shrimp"]', 748, 748.1, 3130, 31.4, 40.3, 11.7, 64.8, 5.2, 9.1, 1636, 4.09, '["USDA FDC 167902","USDA FDC 168436","USDA FDC 168437","USDA FDC 168952","USDA FDC 169230","USDA FDC 169655","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170072","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Rice Paper Ref","VN/Asian Seasoning Powder Avg"]', 'c944a310cea20c00d5d3ff57e718205e8170a3c39fce8c99b5e1c5d285c71331', '45b82a5e1ec3659b620dc477a5d6185d5f36cae5f2294973967c827ff1135dbd', 4),
('vn-chien-06', 'ca-ro-phi-chien-gion-mam-gung', 23, 'Cá rô phi chiên giòn chấm mắm gừng', 'Cá rô phi khía vảy áo lớp bột mì mỏng chiên vàng giòn rụm, thịt trắng ngọt chấm nước mắm gừng tỏi ớt ấm nồng', 'Cá rô phi chiên giòn chấm mắm gừng là món ăn quen thuộc trong mâm cơm Việt nhờ nguyên liệu bình dân nhưng cực kỳ đưa cơm. Cá được làm sạch kỹ màng đen, khía sâu thân, áo lớp bột mì mỏng pha gia vị rồi chiên lửa vừa cho lớp da phồng giòn rụm, thịt cá bên trong vẫn mềm ngọt tự nhiên.', 'Bày cá nguyên con ra đĩa lớn, dùng nóng cùng cơm trắng, rau muống luộc hoặc cuốn bánh tráng rau sống, chấm đẫm chén nước mắm gừng chanh tỏi ớt.', 'Món ngon nhất khi ăn nóng ngay sau khi chiên để cảm nhận độ giòn tan của da cá; nếu còn dư, bảo quản tủ mát tối đa 24 giờ và làm nóng bằng nồi chiên không dầu ở 180°C trong 6 phút.', 'vietnamese', 'mon_chien', 'toan_quoc', 'easy', 15, 20, 4, 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&w=800&q=80', '["Món chiên","Cá tươi","Cơm nhà","Dễ làm","Đưa cơm"]', '["lunch","dinner"]', '["deep_fry"]', '["fish","wheat"]', 326, 325.9, 1363, 36.3, 12.7, 2.4, 15.3, 0.9, 5, 1400, 3.5, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169761","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176"]', '6830c3d9044ab33d82fd1aac59794a32ea5b34d18ce3320ac8d5bc54b71463ee', 'aa1e4e091a39b466f05d5027bd50ab239e3a53cd57e8cebacdb685a3b7456aec', 4),
('vn-hap-01', 'ga-ta-hap-la-chanh', 24, 'Gà ta hấp lá chanh da giòn thịt ngọt', 'Gà ta thả vườn hấp cách thủy cùng sả gừng thơm lừng, da vàng giòn mọng nước quyện hương lá chanh thái chỉ', 'Gà ta hấp cách thủy giữ trọn vị ngọt thanh tự nhiên của thịt săn chắc, lớp da vàng óng giòn sần sật, thấm đẫm hương thơm ấm nồng từ sả cây, gừng tươi và lá chanh bánh tẻ.', 'Chặt gà thành miếng vừa ăn xếp ra đĩa, rắc đều lá chanh thái chỉ và vài lát ớt sừng lên trên; dọn nóng kèm chén muối tiêu chanh ớt.', 'Gà hấp ngon nhất khi dùng ngay trong ngày. Nếu còn dư, bọc kín bảo quản ngăn mát tối đa 24 giờ rồi hấp lại 5–7 phút ở lửa vừa để thịt nóng mà không bị khô.', 'vietnamese', 'mon_hap_luoc', 'bac', 'medium', 20, 30, 4, 'https://images.unsplash.com/photo-1563245372-f21724e3856d?auto=format&fit=crop&w=800&q=80', '["Món hấp","Gà ta","Thanh đạm","Đãi tiệc","Cơm nhà"]', '["lunch","dinner"]', '["steam"]', '["chicken"]', 312, 311.7, 1305, 25.8, 20.6, 5.9, 4.7, 0.6, 1.3, 1175, 2.94, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '80050a49f8622bf81450665feb58cac70447d431f8bed1143736f7958b6ac512', 'ffea52549a962b3529bdeabbbd4be000d974a3f79f1d13350f268e9ad4cee92b', 4),
('vn-hap-02', 'thit-ba-chi-luoc-mam-tom', 25, 'Thịt ba chỉ luộc chấm mắm tôm cà pháo', 'Thịt ba chỉ rút sườn luộc trắng giòn, thái lát mỏng đều chấm mắm tôm đánh sủi bọt bông cùng cà pháo muối chua giòn', 'Thịt ba chỉ rút sườn nạc mỡ đan xen luộc chín tới giữ được độ trắng ngần và giòn sần sật phần bì, ăn kèm cà pháo muối giòn tan, rau sống mát lành và bát mắm tôm chanh ớt đánh bông thơm lừng.', 'Xếp thịt ba chỉ thái mỏng ra đĩa hoặc mẹt lót lá chuối, dọn cạnh đĩa cà pháo muối, đĩa rau thơm dưa leo và bát mắm tôm sủi bọt ăn kèm cơm trắng nóng.', 'Thịt luộc bảo quản nguyên khối trong hộp kín ở ngăn mát tối đa 2 ngày; khi ăn chỉ thái lát vừa dùng hoặc trụng nhanh qua nước sôi nóng 1 phút cho mềm ẩm rồi thái.', 'vietnamese', 'mon_hap_luoc', 'bac', 'easy', 15, 25, 4, 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80', '["Món luộc","Cơm nhà","Món Bắc","Thanh đạm","Kinh điển"]', '["lunch","dinner"]', '["boil"]', '["crustaceans","pork","shrimp","sulphites"]', 635, 635.2, 2658, 12.9, 61, 21.7, 8.8, 2, 4.7, 784, 1.96, '["Asian Shrimp Paste Ref","USDA FDC 167820","USDA FDC 168155","USDA FDC 168409","USDA FDC 169228","USDA FDC 169230","USDA FDC 169231","USDA FDC 169247","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 171413","USDA FDC 172238","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647"]', '23eecb1e63a74a9cfa9ca4beca1c68dc8fdf9bbf4946326c518500a07703fa12', '23fb1a29a07a3d1e2e7b859914536aeda85c98878f0e251bdd0c10fd06366431', 4),
('vn-hap-03', 'ca-dieu-hong-hap-hanh-gung', 26, 'Cá điêu hồng hấp hành gừng xì dầu', 'Cá điêu hồng tươi nguyên con hấp chín tới mềm ngọt, rưới sốt xì dầu dầu hào thơm nức hành gừng xối dầu nóng', 'Cá điêu hồng nguyên con làm sạch kỹ hấp cách thủy vừa chín tới cho thớ thịt trắng ngần ngọt dịu, hòa quyện sốt xì dầu dầu hào sánh nhẹ cùng hương thơm nồng nàn của gừng sợi, hành lá và nấm hương.', 'Đặt đĩa cá hấp nóng hổi lên bàn ăn, rưới đều dầu hành gừng thơm lừng; dùng nóng với cơm trắng hoặc cuốn bánh tráng cùng bún tươi và rau sống.', 'Món cá hấp ngon nhất khi ăn nóng ngay sau khi chế biến. Nếu còn thừa, tách bỏ xương rồi bảo quản ngăn mát tối đa 24 giờ, khi dùng hấp cách thủy lại 5 phút.', 'vietnamese', 'mon_hap_luoc', 'toan_quoc', 'medium', 20, 25, 4, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80', '["Món hấp","Cá tươi","Đãi khách","Thanh đạm","Cơm nhà"]', '["lunch","dinner"]', '["steam"]', '["fish","molluscs","sesame","soybean","wheat"]', 271, 270.6, 1132, 32.7, 10.7, 2, 10, 1.3, 3.3, 1155, 2.89, '["Shaoxing Wine Ref","USDA FDC 168436","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171028","USDA FDC 171369","USDA FDC 171413","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175176","VN/Asian Seasoning Powder Avg"]', '57dc6dcaf2c49474819fa72da12630d11267d9c77683c309f2c3273e34926d8f', 'a893fcffbf82fe4a8277249c503cad9d70083fdaeaa40797e58da2c8003cba93', 4),
('vn-hap-04', 'rau-cu-luoc-kho-quet', 27, 'Rau củ luộc thập cẩm chấm kho quẹt tóp mỡ', 'Súp lơ xanh, cà rốt, su su luộc giòn xanh mướt chấm cùng niêu kho quẹt tóp mỡ tôm khô đậm đà chuẩn vị Nam Bộ', 'Đĩa rau củ luộc giòn ngọt giữ trọn sắc xanh cam tươi tắn chấm ngập trong niêu kho quẹt sánh kẹo mặn ngọt hài hòa, thơm lừng tóp mỡ giòn rụm, tôm khô dai ngọt và tiêu xanh cay nồng.', 'Bày súp lơ xanh, cà rốt và su su luộc ra đĩa lớn, đặt bên cạnh niêu kho quẹt nóng hổi còn sôi lăn tăn, ăn kèm cơm trắng hoặc cơm cháy giòn.', 'Rau củ luộc nên ăn hết trong bữa để giữ độ giòn và màu sắc tươi ngon. Phần kho quẹt có thể bảo quản hũ kín trong ngăn mát 3–4 ngày, hâm nóng trên lửa nhỏ cùng 1 muỗng nước trước khi dùng.', 'vietnamese', 'mon_hap_luoc', 'nam', 'easy', 20, 25, 4, 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', '["Món luộc","Rau củ","Kho quẹt","Món Nam","Cơm nhà"]', '["lunch","dinner"]', '["boil","simmer"]', '["crustaceans","fish","pork","shrimp"]', 336, 336.4, 1407, 11.8, 23.2, 8.3, 22.1, 4.5, 12.5, 1525, 3.81, '["Green Peppercorn Ref","USDA / Asian Dried Shrimp Ref","USDA FDC 167820","USDA FDC 169230","USDA FDC 169655","USDA FDC 169990","USDA FDC 170005","USDA FDC 170106","USDA FDC 170379","USDA FDC 170393","USDA FDC 170499","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', 'a83ef6f2d387fe9c8ea90a15835d5c6bc473a73cf56cec54a728e390a5f23ab8', '03ccdf1e6fa7cc16b3f8f4d44f1b665c586f04397b5e04e0891b4dae03ead8ac', 4),
('vn-hap-05', 'muc-hap-gung-sa', 28, 'Mực ống hấp gừng sả giòn ngọt', 'Mực ống tươi dày mình hấp nhanh cùng sả đập dập và gừng non thái chỉ giữ trọn độ giòn sần sật, chấm muối tiêu chanh', 'Mực ống tươi làm sạch khéo léo hấp cách thủy lửa lớn cùng sả cây, gừng non và lá chanh, từng miếng mực trắng ngần giòn sần sật, mọng nước tự nhiên, thơm dịu không hề tanh.', 'Gắp mực hấp ra đĩa lớn, rắc thêm vài sợi gừng và ớt sừng trang trí; dọn ăn ngay khi còn nóng chấm cùng chén muối tiêu chanh hoặc nước mắm gừng.', 'Mực hấp ngon nhất khi thưởng thức nóng ngay để giữ độ giòn sần sật. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ và hấp lại nhanh 2–3 phút, tránh hấp lâu làm mực dai.', 'vietnamese', 'mon_hap_luoc', 'trung', 'easy', 15, 12, 3, 'https://images.unsplash.com/photo-1535400255456-984241443b29?auto=format&fit=crop&w=800&q=80', '["Món hấp","Hải sản","Dưới 20 phút","Miền Trung","Tươi ngọt"]', '["lunch","dinner"]', '["steam"]', '["molluscs","squid","sulphites"]', 179, 179.3, 750, 27.1, 2.5, 0.7, 10.7, 0.8, 0.8, 1124, 2.81, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223"]', '4d5f1acbbd3cfe923434eaf42ee64cf738406e850db6bef0650a9b7ff9291de4', '941a101cc187b292e7c505f554296096dee4f5fe83505b0fffae4966e2a6c426', 4),
('vn-hap-06', 'tom-hap-nuoc-dua-tuoi', 29, 'Tôm sú hấp nước dừa tươi ngọt lịm', 'Tôm sú tươi roi rói hấp cùng nước dừa xiêm thanh ngọt và sả đập dập, thịt tôm săn chắc đỏ au dậy hương dừa dịu nhẹ', 'Tôm sú tươi sống hấp trực tiếp trong nước dừa xiêm ngọt thanh cùng sả cây và gừng lát giúp vỏ tôm lên màu đỏ cam bắt mắt, thịt tôm săn chắc giòn ngọt và thấm vị dừa dịu mát đặc trưng miền Tây.', 'Xếp tôm đỏ au ra đĩa hoặc quanh vành trái dừa xiêm, trang trí ớt sừng thái chỉ và vài cọng rau thơm, ăn nóng chấm muối tiêu chanh ớt.', 'Tôm hấp ngon nhất khi dùng nóng ngay sau khi chín. Nếu còn dư, bóc vỏ rồi bảo quản ngăn mát tối đa 24 giờ và hấp lại nhanh 2–3 phút hoặc dùng chế biến món xào, salad.', 'vietnamese', 'mon_hap_luoc', 'nam', 'easy', 15, 10, 3, 'https://images.unsplash.com/photo-1559742811-822873691df8?auto=format&fit=crop&w=800&q=80', '["Món hấp","Hải sản","Dưới 20 phút","Đặc sản Nam Bộ","Đãi tiệc"]', '["lunch","dinner"]', '["steam"]', '["crustaceans","shrimp"]', 152, 151.5, 634, 29.6, 1, 0.3, 6.9, 1.4, 3.4, 962, 2.41, '["USDA FDC 168155","USDA FDC 168573","USDA FDC 169231","USDA FDC 169655","USDA FDC 170106","USDA FDC 170174","USDA FDC 170499","USDA FDC 170931","USDA FDC 173468","USDA FDC 175179"]', '4666e450ee9b1e7bb2b4754ed22ef632da1f053e6fb7ff627290deb5f4dc8bde', '24ff694cfd9c5834568e14ef1fdc7698dcccf4a7f64ae02e6f97141345ca95b9', 4),
('vn-cuon-01', 'goi-cuon-tom-thit-nam-bo', 30, 'Gỏi cuốn tôm thịt chấm tương phộng Nam Bộ', 'Bánh tráng dẻo trong veo cuốn tôm sú đỏ au, thịt ba chỉ béo mềm, bún tươi và rau thơm mát lành cùng tương đen bơ đậu phộng bùi béo', 'Gỏi cuốn tôm thịt Nam Bộ hấp dẫn với lớp bánh tráng mỏng dai bọc trọn tôm sú đỏ au, thịt ba chỉ luộc thái mỏng, bún tươi, dưa leo giòn mát và hẹ lá xanh, chấm cùng chén tương đen bơ đậu phộng thơm bùi sánh mịn.', 'Xếp gỏi cuốn ra đĩa, dọn kèm chén tương đen bơ đậu phộng rắc lạc rang giã dập, ớt băm và đĩa đồ chua cà rốt củ cải giòn ngọt.', 'Gỏi cuốn ngon nhất khi ăn ngay sau khi cuốn; nếu cần giữ trong vài giờ, bọc từng cuốn bằng màng bọc thực phẩm hoặc khăn ẩm sạch trong ngăn mát tủ lạnh và hâm ấm nhẹ nước chấm trước khi dùng.', 'vietnamese', 'mon_cuon_nom', 'nam', 'medium', 25, 20, 4, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=800&q=80', '["Món cuốn","Nam Bộ","Thanh mát","Khai vị","Tương đậu phộng"]', '["lunch","dinner"]', '["boil","assemble"]', '["crustaceans","peanut","pork","sesame","shrimp","soybean","wheat"]', 777, 777.4, 3253, 26.4, 46, 14.6, 66.5, 4.3, 16.4, 899, 2.25, '["NIN VN Fresh Bun Ref","USDA FDC 167820","USDA FDC 168409","USDA FDC 168452","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169963","USDA FDC 169994","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171370","USDA FDC 171413","USDA FDC 172232","USDA FDC 172238","USDA FDC 172430","USDA FDC 172470","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","USDA FDC Rice Paper Ref"]', '44b2991bde1bbe1234f5537c66e3900b9caaa5c36f75d889d87f29e79e2f3b7e', 'f8e2f68c90a7a9807b9ed2f8f55fb2d7137593f87fa1858baf14b9d2bbdaa4a5', 4),
('vn-cuon-02', 'pho-cuon-bo-ha-noi', 31, 'Phở cuốn bò xào rau thơm Hà Nội', 'Bánh phở tươi vuông mềm mượt cuốn gọn thịt bò thăn xào tỏi thơm lừng cùng xà lách, húng Láng và ngò rí, chấm nước mắm dưa góp chua ngọt', 'Phở cuốn bò xào rau thơm mang đậm phong vị phố Trúc Bạch Hà Nội với lá bánh phở tươi trắng mượt ôm lấy thịt bò thăn xào tỏi mềm ngọt, quyện cùng xà lách giòn tươi, húng Láng thơm nồng và bát nước mắm dưa góp đu đủ cà rốt chua ngọt thanh tao.', 'Xếp phở cuốn nguyên cuốn hoặc cắt đôi vát chéo ra đĩa, dọn ăn ngay khi thịt bò còn ấm cùng chén nước mắm chua ngọt thả dưa góp đu đủ cà rốt giòn sần sật.', 'Nên thưởng thức ngay sau khi cuốn để bánh phở giữ độ mềm mượt và thịt bò không bị nguội; nếu chưa dùng ngay, bọc kín đĩa phở cuốn bằng màng bọc thực phẩm để ngăn mát tối đa 4 giờ.', 'vietnamese', 'mon_cuon_nom', 'bac', 'easy', 20, 10, 3, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', '["Phở cuốn","Hà Nội","Thịt bò","Khai vị","Món cuốn"]', '["lunch","dinner"]', '["stir_fry","assemble"]', '["beef","fish"]', 501, 501.2, 2098, 27, 23.1, 6.1, 46.4, 3.9, 10.3, 1627, 4.07, '["NIN VN Fresh Pho Noodle Ref","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 169997","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Green Papaya Ref","USDA FDC Sriracha Ref","VN/Asian Seasoning Powder Avg"]', 'c2db10ef69ce7ead3cb13bb81fd5bd98fabca80a5627409c2a47bf0ae329813a', 'b5cec0d6ff4dc86da8364e14005a9f1e1d6a3adb99229c0abcd8b39a40f3f237', 4),
('vn-cuon-03', 'nom-hoa-chuoi-tai-heo', 32, 'Nộm hoa chuối tai heo giòn sần sật', 'Hoa chuối tây bào mỏng trắng giòn quyện tai heo luộc sần sật, cà rốt, giá đỗ cùng nước trộn chua ngọt tỏi ớt và lạc rang bùi thơm', 'Nộm hoa chuối tai heo là món khai vị truyền thống miền Bắc với từng sợi hoa chuối trắng muốt không chát thâm, kết hợp tai heo luộc giòn sần sật, rau củ thanh mát, nước mắm chanh tỏi ớt đậm đà cùng lạc rang và hành phi thơm nức.', 'Gắp nộm ra đĩa sâu lòng, rắc lạc rang giã dập, hành phi vàng giòn và vài lát ớt sừng lên mặt; dùng ngay làm món khai vị hoặc ăn kèm bánh phồng tôm.', 'Nên trộn nộm ngay trước bữa ăn để hoa chuối và rau giữ độ giòn; nếu còn dư, đậy kín bảo quản ngăn mát tối đa 12 giờ nhưng lưu ý nộm sẽ dịu mềm và tiết thêm nước.', 'vietnamese', 'mon_cuon_nom', 'bac', 'medium', 30, 20, 4, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80', '["Món nộm","Khai vị","Giòn sần sật","Miền Bắc","Chống ngán"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["fish","peanut","pork"]', 479, 478.7, 2003, 30.7, 26.7, 7, 30.6, 9.3, 14.1, 1391, 3.48, '["SE Asian Banana Blossom Ref","USDA FDC 167879","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169963","USDA FDC 170000","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","VN Rau Ram Ref"]', '08c2c2598afb14bc323632fbca15b0ac00877dcc928e044eb364d9621a6e35d0', 'b118cf65452b8828eeb37675d7f78d7cb4aab80ce969fd5caf336d9757a6bead', 4),
('vn-cuon-04', 'goi-ga-xe-phay-bap-cai', 33, 'Gỏi gà xé phay bắp cải hành tây', 'Thịt gà ta luộc mềm ngọt xé sợi trộn cùng bắp cải bào giòn, hành tây ngâm giấm đá thanh dịu, rau răm và lá chanh thơm lừng', 'Gỏi gà xé phay bắp cải hành tây hài hòa giữa thịt gà ta luộc dai ngọt xé sợi, bắp cải trắng bào mỏng giòn rụm, hành tây ngâm giấm đá dịu hăng và hương thơm đặc trưng của rau răm, lá chanh thái chỉ cùng nước trộn chua ngọt vừa vặn.', 'Bày gỏi ra đĩa lớn, rắc hành phi, đậu phộng rang giã dập và ớt sừng thái sợi lên mặt; có thể ăn kèm bánh phồng tôm hoặc cháo gà nóng.', 'Gỏi ngon nhất ngay sau khi trộn; nếu làm trước cho bữa tiệc, bảo quản riêng gà xé, rau củ ráo nước và nước trộn trong ngăn mát tủ lạnh rồi trộn trước khi dọn 10 phút.', 'vietnamese', 'mon_cuon_nom', 'trung', 'easy', 20, 25, 4, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800&q=80', '["Gỏi gà","Miền Trung","Thanh mát","Khai vị","Đãi tiệc"]', '["lunch","dinner"]', '["boil","toss_mix"]', '["chicken","fish","peanut"]', 395, 394.7, 1652, 29.3, 20.5, 4.6, 25, 5, 15.9, 1471, 3.68, '["Citrus Leaf Culinary Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169975","USDA FDC 170000","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172385","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","VN Rau Ram Ref"]', '80290697fd37f7de83e491f4fe20dc55495d4b0bc00f6370b142e3b5e56f292c', '1c6a40ca10a060d76792ba3e2fd43a2ccb2aafb44ee423817c11e3d971747f5f', 4),
('vn-cuon-05', 'nom-du-du-bo-kho', 34, 'Nộm đu đủ bò khô phố cổ Hà Nội', 'Sợi đu đủ xanh và cà rốt nạo giòn sần sật quyện nước mắm giấm đường chua ngọt cay nhẹ, điểm thịt bò khô xé sợi, rau thơm và lạc rang', 'Nộm đu đủ bò khô mang nét đặc trưng ẩm thực phố cổ Hà Nội với sợi đu đủ xanh và cà rốt giòn tan không chát, thấm đẫm nước trộn mắm chanh chua ngọt dịu cay, kết hợp thịt bò khô xé sợi thơm lừng, rau kinh giới và lạc rang bùi ngậy.', 'Gắp nộm đu đủ ra đĩa sâu lòng, xếp thêm thịt bò khô xé sợi, rắc lạc rang giã dập và hành phi giòn lên trên; trộn đều ngay trước khi thưởng thức.', 'Không nên rưới nước trộn quá lâu trước khi ăn vì đu đủ sẽ tiết nước và làm ỉu lạc rang; bảo quản phần nguyên liệu khô và nước trộn riêng trong ngăn mát tủ lạnh tối đa 24 giờ.', 'vietnamese', 'mon_cuon_nom', 'bac', 'easy', 20, 10, 3, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món nộm","Phố cổ Hà Nội","Đu đủ xanh","Ăn vặt","Khai vị"]', '["lunch","dinner"]', '["pan_fry","toss_mix"]', '["beef","fish","peanut"]', 315, 314.6, 1317, 16.2, 15.7, 3.4, 30.8, 5.2, 20.9, 1517, 3.79, '["USDA FDC 168155","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170187","USDA FDC 170393","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Green Papaya Ref"]', '5007af4b39dd747b39696ef4d069bc54ee0a58c15f862a6a35da972abc1eaeb6', 'dc0a447c57936908896a5f40196a75c35dc392ca5380bcb6216faf85ae27fd7a', 4),
('vn-cuon-06', 'nem-lui-hue-nuong-sa', 35, 'Nem lụi Huế nướng sả cuốn bánh tráng', 'Nem thịt heo giò sống quết dẻo bọc thân cây sả nướng vàng xém cạnh thơm lừng, cuốn bánh tráng bún tươi, rau sống, chuối chát chấm nước mắm tỏi ớt', 'Nem lụi Huế nướng sả thơm nức với lớp nhân thịt nạc vai xay, giò sống và tôm tươi quết dẻo bọc quanh thân sả nướng xém cạnh, quét mật ong dầu điều bóng đẹp, cuốn bánh tráng cùng bún tươi, chuối chát, dứa thơm và rau sống.', 'Dọn nem lụi nóng hổi ra đĩa cùng bánh tráng, bún tươi, đĩa rau sống thái lát chuối chát, dưa leo, dứa thơm và chén nước mắm tỏi ớt chua ngọt.', 'Nem lụi đã nướng có thể bảo quản ngăn mát tối đa 2 ngày trong hộp kín; khi ăn làm nóng lại bằng nồi chiên không dầu ở 160°C khoảng 4–5 phút cho nóng thơm.', 'vietnamese', 'mon_cuon_nom', 'trung', 'medium', 40, 30, 4, 'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?auto=format&fit=crop&w=800&q=80', '["Nem lụi Huế","Món nướng","Món cuốn","Miền Trung","Đặc sản"]', '["lunch","dinner"]', '["grill_roast","assemble"]', '["crustaceans","fish","molluscs","pork","shrimp","soybean","wheat"]', 604, 603.8, 2526, 29, 23.3, 6.9, 71.6, 3.7, 17.3, 1698, 4.25, '["Annatto Infused Oil Ref","NIN VN Fresh Bun Ref","NIN VN Gio Lua Ref","SE Asian Banana Blossom Ref","USDA FDC 167902","USDA FDC 168155","USDA FDC 168409","USDA FDC 168573","USDA FDC 169124","USDA FDC 169230","USDA FDC 169247","USDA FDC 169640","USDA FDC 169655","USDA FDC 169717","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 173647","USDA FDC 175179","USDA FDC Rice Paper Ref","VN/Asian Seasoning Powder Avg"]', '0259185d3e4bc592624bcf846a5504313df7aa795e09149229cdee4c8605053c', '5ac38bfbc1b0f4bde396e88afefd7a9501c996a1ddd34044c042ddff382e668f', 4),
('vn-bun-01', 'pho-bo-tai-lan-ha-noi', 36, 'Phở bò tái lăn Hà Nội', 'Thịt thăn bò đảo nhanh tay trên chảo lửa lớn dậy mùi tỏi gừng, chan nước dùng ninh xương ống bò thơm hoa hồi, quế thanh và thảo quả', 'Phở bò tái lăn chuẩn vị Hà Nội nổi bật với thịt thăn bò ướp tỏi gừng xào nhanh trên lửa lớn cho mặt thịt săn thơm xém cạnh, hòa cùng nước dùng ninh xương ống bò quyện hương thảo mộc nướng.', 'Dọn tô phở nóng hổi kèm chanh tươi, ớt tươi thái lát, hành tây ngâm đá, giá đỗ và rau thơm để thưởng thức ngay khi nước dùng còn nghi ngút khói.', 'Nước dùng hầm xong có thể bảo quản ngăn mát 2 ngày hoặc cấp đông 1 tháng; khi ăn đun sôi sùng sục nước dùng, xào tái lăn thịt bò tươi và trụng bánh phở mới.', 'vietnamese', 'mon_bun_pho', 'bac', 'hard', 35, 180, 4, 'https://images.unsplash.com/photo-1582878826629-29b7ad1cdc43?auto=format&fit=crop&w=800&q=80', '["Phở bò","Hà Nội","Nước dùng ninh xương","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["simmer","stir_fry","boil","assemble"]', '["beef","fish"]', 634, 633.9, 2653, 35.7, 26.9, 9.1, 62.4, 4.2, 10.7, 1983, 4.96, '["NIN VN Fresh Pho Noodle Ref","USDA Beef Rib / Bone Ref","USDA FDC 168155","USDA FDC 169230","USDA FDC 169231","USDA FDC 169963","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170499","USDA FDC 170919","USDA FDC 170922","USDA FDC 170931","USDA FDC 171316","USDA FDC 171320","USDA FDC 171321","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647","USDA FDC Sucrose Ref","VN Culinary Herb Ref"]', '914ec5170cac36d8d75e8f4a89e9f1746d6685fd665b4f4a0fd7bf422db0fcbc', 'aae7c45468b9619c4a6101573f7dbe14029ab2ecedeb9d1e09818e421525901b', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('vn-bun-02', 'bun-cha-ha-noi-than-hoa', 37, 'Bún chả nướng than hoa Hà Nội', 'Chả miếng ba chỉ và chả viên nạc vai nướng xém vàng ươm thơm mùi sả hành, thả trong bát nước mắm ấm chua ngọt cùng dưa góp đu đủ cà rốt', 'Bún chả Hà Nội chuẩn vị với thịt ba chỉ thái miếng và thịt nạc vai xay nặn viên ướp đậm nước cốt sả hành, mắm tôm và nước hàng, nướng than hoa xém cạnh thơm lừng, ăn cùng nước mắm pha ấm, dưa góp giòn và rau sống.', 'Xếp chả miếng và chả viên nóng hổi vào bát nước mắm ấm cùng dưa góp đu đủ cà rốt, rắc thêm chút tiêu xay nếu thích rồi ăn kèm bún tươi và đĩa rau sống tía tô, kinh giới.', 'Thịt đã ướp có thể bảo quản ngăn mát qua đêm; chả đã nướng bảo quản ngăn mát tối đa 2 ngày và làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4–5 phút trước khi thả vào nước mắm ấm.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 35, 35, 4, 'https://images.unsplash.com/photo-1569058242253-92a9c755a0ec?auto=format&fit=crop&w=800&q=80', '["Bún chả","Hà Nội","Món nướng","Đặc sản miền Bắc"]', '["lunch","dinner"]', '["grill_roast","toss_mix","assemble"]', '["crustaceans","fish","pork","shrimp"]', 856, 855.9, 3581, 23.7, 53.3, 18.8, 71.4, 5.3, 19, 2168, 5.42, '["Asian Shrimp Paste Ref","MEXT Shiso Ref","NIN VN Fresh Bun Ref","USDA FDC 167820","USDA FDC 167902","USDA FDC 168155","USDA FDC 168573","USDA FDC 168833","USDA FDC 169230","USDA FDC 169247","USDA FDC 169655","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Green Papaya Ref","VN/Asian Seasoning Powder Avg"]', 'f2b4c33d2e5794ff019853d26640f0db6cdd7664c70bdf601bcb23b5f01ec235', 'c173276e266cb419e5c6a9f9bb334bb458997f18117f8fdc59119dc9bb319c5b', 4),
('vn-bun-03', 'bun-bo-hue-chuan-vi', 38, 'Bún bò Huế giò heo chả cua', 'Nước dùng ninh xương bò giò heo đậm đà hương sả và mắm ruốc Huế, nổi bật cùng bắp bò thái lát, chả cua dai ngọt và sa tế ớt đỏ au', 'Tô bún bò Huế trứ danh có nước dùng trong veo ánh sắc cam đẹp mắt từ dầu màu điều và sa tế sả ớt, hòa quyện vị thanh ngọt của xương bò giò heo cùng mùi thơm nồng đặc trưng của mắm ruốc Huế.', 'Chan nước dùng thật nóng lên tô bún, rắc hành tây thái mỏng, hành lá và ngò rí; dọn kèm hoa chuối bào, giá đỗ, chanh tươi và chén sa tế ớt để điều chỉnh độ cay theo khẩu vị.', 'Nước dùng, giò heo và bắp bò luộc bảo quản ngăn mát tối đa 2 ngày; khi ăn đun sôi lại nước dùng, thả giò heo vào làm nóng rồi chan lên tô bún vừa trụng.', 'vietnamese', 'mon_bun_pho', 'trung', 'hard', 35, 120, 4, 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', '["Bún bò Huế","Ẩm thực miền Trung","Cay nồng","Món nước"]', '["breakfast","lunch","dinner"]', '["simmer","boil","stir_fry","assemble"]', '["beef","crustaceans","fish","pork","shrimp"]', 871, 871.1, 3645, 46.6, 42.6, 14.3, 76.3, 6.3, 9.4, 2292, 5.73, '["Annatto Infused Oil Ref","Asian Shrimp Paste Ref","NIN VN Fresh Bun Ref","SE Asian Banana Blossom Ref","USDA / MEXT Fish Cake Ref","USDA Beef Rib / Bone Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169231","USDA FDC 169963","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170198","USDA FDC 170499","USDA FDC 171319","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC Pork Leg Ref","USDA FDC Sucrose Ref","VN/Asian Seasoning Powder Avg"]', '16caf93c618eaeba3bf83331dc14c3ff561962f5971582dce46984523ed2e8e1', 'ddfd5b316feb5fac3a188ff9da6838f6806419a59fce78034dae520b3c52c925', 4),
('vn-bun-04', 'bun-rieu-cua-dong', 39, 'Bún riêu cua đồng bắp bò giấm bỗng', 'Nước dùng riêu cua đồng béo ngậy đóng tảng vàng ruộm hòa vị chua dịu từ giấm bỗng và cơm mẻ, ăn kèm đậu phụ rán giòn và bắp bò chần tái', 'Bún riêu cua đồng truyền thống miền Bắc có phần riêu cua đóng tảng xốp mềm, nước dùng đỏ cam tự nhiên từ gạch cua xào cà chua, dậy vị chua thanh từ giấm bỗng và cơm mẻ ăn cùng thịt bò chần mềm và đậu phụ rán vàng.', 'Múc bún vào tô, xếp tảng riêu cua, đậu phụ rán, cà chua và thịt bò chần nóng, chan nước riêu ngập mặt bún rồi rắc hành lá; ăn kèm rau xà lách, kinh giới, tía tô, ớt tươi và chút mắm tôm.', 'Nước riêu cua và đậu rán bảo quản ngăn mát tối đa 24 giờ; khi dùng hâm nóng nhẹ lửa vừa tránh khuấy mạnh làm vỡ mảng riêu, sau đó mới chần thịt bò và trụng bún.', 'vietnamese', 'mon_bun_pho', 'bac', 'medium', 30, 35, 4, 'https://images.unsplash.com/photo-1552611052-33e04de081de?auto=format&fit=crop&w=800&q=80', '["Bún riêu","Cua đồng","Miền Bắc","Món nước"]', '["breakfast","lunch","dinner"]', '["simmer","pan_fry","boil","assemble"]', '["beef","crab","crustaceans","fish","shrimp","soybean"]', 636, 636.3, 2662, 47.4, 21.5, 5.2, 64.8, 6.3, 7.1, 2324, 5.81, '["Asian Shrimp Paste Ref","MEXT Shiso Ref","NIN VN Fresh Bun Ref","USDA FDC 169247","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170187","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172475","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC 174208","VN Com Me Ref","VN/Asian Seasoning Powder Avg"]', 'acb7379335f1a5e71423cf91c0fb87b5aaf9116746968e1a7fb5c3fe771a0b2e', 'a8ae362535e6540628d6230396ec4e4d808154bfd2e0796706250940c826ef78', 4),
('vn-bun-05', 'bun-thit-nuong-nam-bo', 40, 'Bún thịt nướng Nam Bộ chả giò mỡ hành', 'Thịt nạc dăm ướp sả mật ong nướng vàng xém thơm lừng, ăn kèm chả giò chiên giòn rụm, mỡ hành béo thơm, đậu phộng rang và nước mắm chua ngọt', 'Tô bún thịt nướng Nam Bộ đầy đặn sắc màu với thịt nạc dăm nướng sả mật ong mềm thơm, chả giò cuốn thịt heo giòn tan, đồ chua củ cải cà rốt, mỡ hành xanh mướt và chén nước mắm tỏi ớt chua ngọt sánh vị.', 'Lót rau xà lách và rau thơm thái nhỏ dưới đáy tô, xếp bún tươi, thịt nướng, chả giò cắt khúc, dưa leo, giá đỗ, đồ chua, rưới mỡ hành và đậu phộng rang giã dập rồi chan nước mắm chua ngọt trộn đều.', 'Thịt đã ướp và chả giò cuốn sẵn có thể bảo quản ngăn mát 1 ngày; thịt nướng xong hoặc chả giò dư khi ăn lại làm nóng bằng nồi chiên không dầu ở 180°C trong 4 phút để giữ độ giòn thơm.', 'vietnamese', 'mon_bun_pho', 'nam', 'medium', 40, 30, 4, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80', '["Bún thịt nướng","Nam Bộ","Chả giò","Món trộn"]', '["lunch","dinner"]', '["grill_roast","deep_fry","toss_mix","assemble"]', '["fish","molluscs","peanut","pork","soybean","wheat"]', 874, 874.3, 3658, 35.3, 39.8, 11.6, 95.9, 6.4, 22.3, 1911, 4.78, '["NIN VN Fresh Bun Ref","USDA FDC 167847","USDA FDC 167902","USDA FDC 168409","USDA FDC 168452","USDA FDC 168573","USDA FDC 169230","USDA FDC 169247","USDA FDC 169640","USDA FDC 169655","USDA FDC 169963","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 171369","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172430","USDA FDC 173468","USDA FDC 173474","USDA FDC 173647","USDA FDC Rice Paper Ref"]', 'cf825f7eca83ca34b52302ef8e34ec14289b7f73309942a8266533c86860b598', '998ca95a1b5eb4f4a5d226b1d39f7b07d8e771423e0373fa3cb2001384e8e602', 4),
('vn-bun-06', 'mien-ga-nam-huong', 41, 'Miến gà nấm hương mộc nhĩ', 'Sợi miến dong dai trong chan nước luộc gà ta ngọt thanh, thơm lừng nấm hương khô, mộc nhĩ giòn sần sật và thịt gà xé phay mềm ngọt', 'Tô miến gà nấm hương mộc nhĩ thanh tao chuẩn vị Bắc có nước dùng trong veo ngọt tự nhiên từ gà ta luộc cùng gừng hành nướng, kết hợp sợi miến dong dai mịn và thịt gà xé xào nấm thơm nức.', 'Chia miến đã chần ra tô, xếp thịt gà xào nấm hương mộc nhĩ lên trên, chan nước dùng gà đang sôi nóng, rắc hành lá, rau răm và tiêu đen xay.', 'Nên bảo quản riêng phần nước dùng, thịt gà xào nấm và miến chưa chần trong ngăn mát tối đa 2 ngày; khi ăn đun sôi nước dùng, trụng miến mới và làm nóng thịt gà.', 'vietnamese', 'mon_bun_pho', 'bac', 'easy', 25, 45, 4, 'https://images.unsplash.com/photo-1612927601601-6638404737ce?auto=format&fit=crop&w=800&q=80', '["Miến gà","Nấm hương","Món nước thanh nhẹ","Ẩm thực miền Bắc"]', '["breakfast","lunch","dinner"]', '["boil","simmer","stir_fry","assemble"]', '["chicken","fish"]', 749, 748.6, 3133, 41.1, 36.8, 9.7, 63.2, 7.8, 2.8, 2132, 5.33, '["USDA FDC 168436","USDA FDC 168437","USDA FDC 168952","USDA FDC 169231","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN Rau Ram Ref","VN/Asian Seasoning Powder Avg"]', '118dde6310dd3b831e37bf148ab4ce7a6569f85ba1a48567dc7ad5ab1c0e99ff', '7441852c5ae8f7e65ef0ed41ac701d228a9137c3f8e2bf4b7261f6d350aec14a', 4),
('vn-chay-01', 'dau-phu-kho-nam-dong-co', 42, 'Đậu phụ kho nấm đông cô tiêu đen', 'Đậu phụ rán vàng ươm kho sánh cùng nấm đông cô ngọt bùi, dậy hương nước tương, dầu mè và tiêu đen cay ấm', 'Đậu phụ chiên vàng giòn bên ngoài nhưng giữ trọn độ mềm béo bên trong, kho liu riu cùng nấm đông cô tươi giòn ngọt trong phần nước sốt tương sánh bóng, thơm lừng hành boa-rô, dầu mè và tiêu đen cay nồng.', 'Dọn nóng ngay trong nồi đất hoặc đĩa sâu lòng, rắc thêm tiêu đen xay và ớt sừng thái lát; dùng kèm cơm trắng dẻo nóng và rau luộc.', 'Để nguội hoàn toàn rồi bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 2 ngày; khi ăn hâm nóng lại trên lửa nhỏ và thêm 1–2 muỗng canh nước lọc nếu sốt đặc.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 15, 20, 3, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chay","Món kho","Đậu phụ","Nấm đông cô","Đưa cơm"]', '["lunch","dinner"]', '["pan_fry","braise"]', '["sesame","soybean","wheat"]', 227, 226.9, 949, 14.9, 14.7, 2.1, 13.1, 2.8, 7, 1271, 3.18, '["USDA FDC 169246","USDA FDC 169251","USDA FDC 169655","USDA FDC 170106","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref","Vegetarian Seasoning Powder Ref"]', '9490a52629f558e5207701d43c8ad51861441a5cbe221fec7c023afeea7ae356', '7e757d0e68c91ef5fb1d227c8ea807a463d79ac06431bde95530884ab5c43bba', 4),
('vn-chay-02', 'canh-nam-hat-sen-tao-do', 43, 'Canh nấm hạt sen táo đỏ thanh lọc', 'Nước canh trong ngọt thanh từ củ sen, bắp ngọt, hạt sen bở bùi, táo đỏ, kỷ tử và hai loại nấm tươi giòn ngọt', 'Bát canh chay thanh mát giàu dưỡng chất với nước dùng trong veo ngọt dịu tự nhiên từ củ sen giòn bùi, bắp ngọt, cà rốt và táo đỏ, kết hợp hạt sen ninh mềm tơi cùng nấm đùi gà và nấm kim châm giòn sần sật.', 'Múc canh ra tô lớn khi còn nóng hổi, rắc mùi tàu thái nhỏ và lá boa-rô xanh; thưởng thức cùng cơm trắng hoặc ăn riêng như món canh bồi bổ.', 'Dùng hết trong ngày để nấm kim châm giữ độ giòn ngọt; nếu bảo quản tủ mát tối đa 24 giờ, đun sôi lại trên lửa vừa 3–5 phút trước khi dùng.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 20, 30, 4, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món chay","Món canh","Thanh lọc","Hạt sen","Bổ dưỡng"]', '["lunch","dinner"]', '["simmer"]', '[]', 201, 200.7, 840, 6.2, 4.3, 0.6, 38.6, 6.8, 11.3, 1110, 2.78, '["USDA FDC 168580","USDA FDC 169246","USDA FDC 169248","USDA FDC 169253","USDA FDC 169998","USDA FDC 170148 Fresh","USDA FDC 170393","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC Jujube Ref","VN Culinary Herb Ref","Vegetarian Seasoning Powder Ref"]', '3df5b97c8d14f1651b80f2c55ab5ae11932558eb3defedb367cc5c36de2e38c2', '5b7aeb5a623cff7471d8b6c2d9766918dcd70545127f4aaf5dcd79475aa9e284', 4),
('vn-chay-03', 'mi-xao-chay-rau-nam', 44, 'Mì xào giòn chay nấm rau củ', 'Sợi mì vàng chiên phồng giòn rụm phủ nước sốt nấm đùi gà, cải ngọt và cà rốt sánh bóng đậm đà hương dầu hào chay', 'Đĩa mì xào giòn chay hấp dẫn với sợi mì vàng chiên phồng giòn tan, không ngấm dầu, kết hợp phần nhân xào nóng hổi gồm nấm đùi gà dai ngọt, cải ngọt xanh mướt, cà rốt giòn sần sật hòa quyện trong lớp sốt dầu hào chay sánh bóng.', 'Xếp mì chiên giòn ra đĩa lớn rồi rưới sốt nấm rau củ nóng hổi lên trên ngay trước khi ăn, rắc thêm ngò rí và tiêu đen; ăn kèm chén nước tương ớt.', 'Nên bảo quản riêng phần mì đã chiên trong hộp kín ở nhiệt độ phòng và phần sốt rau củ trong ngăn mát tủ lạnh (tối đa 24 giờ); hâm nóng sốt trên chảo rồi mới chan lên mì khi ăn.', 'vietnamese', 'mon_chay', 'toan_quoc', 'medium', 15, 15, 3, 'https://images.unsplash.com/photo-1585032226651-759b368d7246?auto=format&fit=crop&w=800&q=80', '["Món chay","Mì xào giòn","Nấm đùi gà","Rau củ","Đổi vị"]', '["breakfast","lunch","dinner"]', '["deep_fry","stir_fry"]', '["sesame","soybean","wheat"]', 341, 341.4, 1428, 7.1, 13.2, 1.9, 50.7, 3.8, 4.6, 1277, 3.19, '["NIN VN Fresh Rice Noodle Ref","USDA FDC 168580","USDA FDC 169246","USDA FDC 169655","USDA FDC 169717","USDA FDC 169997","USDA FDC 170390","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref","Vegetarian Seasoning Powder Ref"]', '4f044ada5b9efac080102cfda241bfcf11628a5a7c1132769562ce1f436f8e25', '69f59c33f1ef62b31af878aa70258bd61d8df2b543b61db7c3b952ceee2c333d', 4),
('vn-chay-04', 'ca-tim-nuong-mo-hanh', 45, 'Cà tím nướng mỡ hành nước tương tỏi ớt', 'Cà tím nướng mềm mọng ngọt thơm quyện mỡ hành xanh mướt, nước tương tỏi ớt đậm đà và đậu phộng rang bùi béo', 'Món cà tím nướng mỡ hành dân dã chuẩn vị Nam Bộ với phần thịt cà trắng mềm mọng ngọt tự nhiên, thơm nhẹ hương khói, phủ lớp mỡ hành xanh bóng béo ngậy, rưới sốt nước tương tỏi ớt chua mặn ngọt hài hòa và đậu phộng rang giòn bùi.', 'Bày cà tím nướng nóng hổi ra đĩa dài, rưới thêm nước tương tỏi ớt và rắc đậu phộng rang giã dập cùng tiêu xay; ăn kèm cơm trắng nóng.', 'Món ngon nhất khi dùng ngay lúc vừa nướng xong; nếu còn dư có thể bọc kín bảo quản ngăn mát tối đa 24 giờ và làm nóng lại bằng lò nướng ở 170°C trong 5 phút.', 'vietnamese', 'mon_chay', 'nam', 'easy', 10, 25, 3, 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=800&q=80', '["Món chay","Nam Bộ","Món nướng","Cà tím","Dân dã"]', '["lunch","dinner"]', '["grill_roast"]', '["peanut","soybean","wheat"]', 184, 184, 771, 4.9, 12.9, 1.8, 15.5, 6, 8, 980, 2.45, '["USDA FDC 169228","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170931","USDA FDC 171413","USDA FDC 172430","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', '020aa2d7430620bff82eabf7fa88aa7ebfcd7a16184150ea97c552c7be6bcd20', '151b7bb79a79cc49c8ce6f1e586342ad48ea95e98b78f36a18a18df3bb370879', 4),
('vn-chay-05', 'dau-hu-non-sot-nam-rom', 46, 'Đậu hũ non sốt nấm rơm dầu hào chay', 'Những khoanh đậu hũ non hấp nóng mềm mịn như lụa, phủ sốt nấm rơm xào dầu hào chay và xì dầu sánh bóng', 'Từng khoanh đậu hũ non hấp nóng giữ trọn độ mềm mịn tan ngay đầu lưỡi, kết hợp phần sốt nấm rơm búp giòn ngọt được xào thơm với hành tím, tỏi băm cùng dầu hào chay và nước tương đậm đà sánh bóng.', 'Rưới sốt nấm rơm nóng hổi phủ kín đĩa đậu hũ non vừa hấp xong, rắc hành lá, ngò rí, tiêu xay và ớt lát; dùng ngay cùng cơm trắng nóng.', 'Món ăn ngon nhất ngay khi vừa chế biến vì đậu hũ non để lâu dễ tiết nước làm loãng sốt; nếu còn dư nên đun sôi lại phần sốt trước rồi rưới lên đậu đã hấp ấm.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 10, 15, 3, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=800&q=80', '["Món chay","Đậu hũ non","Nấm rơm","Mềm mịn","Nhanh gọn"]', '["lunch","dinner"]', '["steam","stir_fry"]', '["soybean","wheat"]', 185, 184.9, 773, 9.9, 10.2, 1.5, 14.7, 1.8, 5.7, 913, 2.28, '["USDA FDC 169230","USDA FDC 169251","USDA FDC 169655","USDA FDC 169698","USDA FDC 169997","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172476","USDA FDC 173647","USDA FDC 174277","Vegan Mushroom Sauce Ref","Vegetarian Seasoning Powder Ref"]', '389623c58be403a2bc276b70ce7332dac8d3a34021fcef8d03d3d2be98aa5d2a', '9ee2c7caf10b8271048311cdf5606397a5ed09850d03ca29bd5341d7b91c6594', 4),
('vn-chay-06', 'canh-cai-nau-dau-phu-non', 47, 'Canh cải xanh gừng đậu phụ thanh mát', 'Bát canh cải bẹ xanh giữ sắc xanh mướt cùng đậu phụ trắng béo mềm và gừng già đập dập cay ấm bụng', 'Bát canh cải bẹ xanh thanh đạm mà ấm bụng với vị hăng ngọt dịu nhẹ đặc trưng của rau cải non, hòa quyện hương gừng già cay thơm nồng giúp làm ấm cơ thể cùng những miếng đậu phụ trắng béo mềm thấm vị.', 'Múc canh ra tô lớn khi còn bốc khói, rắc hành lá, ngò rí và chút tiêu đen xay; dùng nóng trong bữa cơm chay gia đình.', 'Canh cải xanh ngon nhất khi ăn nóng trong ngày vì để lâu hoặc hâm lại nhiều lần rau dễ ngả màu vàng và tăng vị đắng.', 'vietnamese', 'mon_chay', 'toan_quoc', 'easy', 10, 12, 4, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Món chay","Món canh","Cải bẹ xanh","Ấm bụng","Dưới 20 phút"]', '["lunch","dinner"]', '["simmer"]', '["soybean","wheat"]', 132, 132.1, 552, 11.1, 8.3, 1.2, 6.5, 2.2, 2.6, 830, 2.08, '["USDA FDC 169231","USDA FDC 169655","USDA FDC 169997","USDA FDC 170005","USDA FDC 170390","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","Vegetarian Seasoning Powder Ref"]', '44e292f9764c33808acc4ef1cfa60944714ca154cf320ab72cc8ad44070e55c8', '01c4f8b61dbf7432c6ad25d359c08567041bd55c1dffcf39132056639133d743', 4),
('vn-sang-01', 'com-chien-trung-toi-hanh-hoa', 48, 'Cơm chiên trứng tỏi phi hành hoa', 'Cơm nguội rang tơi vàng óng bọc trứng gà béo thơm, dậy mùi tỏi phi giòn rụm và hành lá tươi', 'Đĩa cơm chiên trứng tỏi phi vàng ươm với từng hạt cơm săn tơi rời rạc, áo lớp trứng gà mượt mà, thơm nức hương tỏi phi giòn tan, hành lá xanh mát và nước mắm dậy mùi.', 'Múc cơm chiên ra đĩa ngay khi còn nóng giòn, rắc thêm tiêu xay và hành lá, ăn kèm dưa leo thái lát, cà chua bi và chén xì dầu ớt.', 'Ngon nhất khi thưởng thức ngay sau khi rang để hạt cơm và tỏi phi giữ độ giòn. Nếu còn dư, bảo quản hộp kín trong ngăn mát tối đa 24 giờ rồi đảo lại trên chảo nóng không dầu 3 phút.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 2, 'https://images.unsplash.com/photo-1603133872878-684f208fb84b?auto=format&fit=crop&w=800&q=80', '["Ăn sáng","Cơm chiên","Nhanh gọn","Tiết kiệm","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["pan_fry","stir_fry"]', '["egg","fish"]', 442, 442.4, 1851, 12, 17.3, 3.4, 58.8, 1.7, 2.8, 1079, 2.7, '["USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170931","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', '7f0e7bd407d6a215419d22b17b64dc7762e26d38e33e1963fd6b6ac634ed167c', '15a0af0b7daa6b1f020e3fa177f32d8fd430f274edd946b64d67500a0b442ca7', 4),
('vn-sang-02', 'banh-mi-op-la-pate', 49, 'Bánh mì ốp la pate dưa leo', 'Ổ bánh mì vỏ giòn rụm phết pate gan béo mịn, kẹp trứng ốp la lòng đào chiên bơ và dưa leo ngò rí mát lành', 'Món sáng quốc dân chuẩn vị quán Việt với hai ổ bánh mì nóng giòn, lớp pate gan mịn béo phủ đều ruột bánh, trứng gà ốp la lòng đào chiên bơ thơm ngậy cùng dưa leo giòn mát, ngò rí, xì dầu và tương ớt cay dịu.', 'Kẹp nhẹ ổ bánh mì và thưởng thức ngay khi vỏ bánh còn giòn rụm và lòng đỏ trứng còn ấm sóng sánh; dùng kèm ly cà phê sữa đá hoặc sữa đậu nành.', 'Bánh mì ốp la ngon nhất khi ăn liền sau khi làm. Nếu cần chuẩn bị trước, chỉ nên nướng giòn bánh và chiên trứng ngay trước khi ăn; phần pate và rau rửa sạch bảo quản riêng trong ngăn mát tối đa 2 ngày.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 6, 8, 2, 'https://images.unsplash.com/photo-1626804475297-41608ea09aeb?auto=format&fit=crop&w=800&q=80', '["Bánh mì","Ăn sáng","Nhanh gọn","Quốc dân","Dưới 20 phút"]', '["breakfast","lunch"]', '["pan_fry","grill_roast","assemble"]', '["egg","milk","pork","soybean","wheat"]', 435, 435.3, 1821, 23.4, 13.1, 5.7, 54.9, 3, 5.6, 1398, 3.5, '["USDA FDC 167871","USDA FDC 168409","USDA FDC 169997","USDA FDC 170106","USDA FDC 170931","USDA FDC 171287","USDA FDC 172686","USDA FDC 173430","USDA FDC 173468","USDA FDC 174277","USDA FDC Sriracha Ref"]', '7b7076981a3efe4065aa2f9e32b5b9a1626b4e9ba471be9dd55f49f6338a8126', '4cafb25782c35857efb3413889f8453723ba5bd549ff2f40a30168e34f8a7469', 4),
('vn-sang-03', 'chao-thit-bam-gung-tia-to', 50, 'Cháo thịt bằm gừng tía tô giải cảm', 'Cháo gạo rang sánh mịn nấu thịt heo nạc băm ngọt thanh cùng lá tía tô và gừng già ấm bụng', 'Tô cháo thịt bằm nóng hổi với hạt gạo tẻ kết hợp gạo nếp rang thơm nở bung sánh mịn, thịt heo nạc băm mềm ngọt không vón cục, hòa quyện hương cay ấm của gừng già, tiêu đen và lá tía tô giải cảm hiệu quả.', 'Múc cháo nóng sôi lên bát đã lót sẵn lá tía tô, hành lá và gừng thái chỉ, rắc nhiều tiêu đen xay rồi dùng ngay khi còn nóng để ra mồ hôi nhẹ.', 'Nên ăn nóng ngay sau khi nấu. Nếu còn dư, để nguội rồi cất hộp kín trong ngăn mát tối đa 24 giờ; khi hâm lại trên lửa nhỏ cần thêm chút nước sôi khuấy đều tránh khê đáy và chỉ rắc tía tô tươi lúc ăn.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 25, 3, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Cháo nóng","Giải cảm","Ăn sáng","Ấm bụng","Dễ tiêu"]', '["breakfast","dinner"]', '["simmer","boil"]', '["fish","pork"]', 324, 323.9, 1355, 14, 13.1, 4.8, 36.2, 1.7, 1.2, 1301, 3.25, '["MEXT Shiso Ref","USDA FDC 167902","USDA FDC 168881","USDA FDC 169231","USDA FDC 169756","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '84e9b48bdef89661ade44837bafecab38d877cf0f5594b2a38717aea4500d945', 'e1c873b76448ec53784b6d3a15ab83906520aeaae1d14e6327628be4fcfbada0', 4),
('vn-sang-04', 'mi-tom-xao-bo-trung-long-dao', 51, 'Mì gói xào bò trứng lòng đào', 'Sợi mì dai giòn xào lửa lớn cùng thịt bò thăn mềm ngọt, cải ngọt xanh giòn và trứng ốp la lòng đào béo ngậy', 'Món mì xào bò trứng lòng đào hấp dẫn với từng sợi mì săn dai không bết dính, thịt bò thăn xào tái mềm đậm đà nước tương dầu hào, rau cải ngọt giòn xanh và quả trứng ốp la lòng đào tan chảy béo mượt.', 'Bày mì xào bò ra đĩa lớn, đặt trứng ốp la lên trên cùng vài cọng ngò rí, rắc tiêu đen xay và thưởng thức nóng kèm tương ớt hoặc ớt tươi thái lát.', 'Ngon nhất khi dùng ngay lúc sợi mì còn săn dai và lòng đỏ trứng còn chảy béo. Không nên để qua đêm vì sợi mì sẽ hút ẩm và bị mềm nhũn.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 10, 12, 2, 'https://images.unsplash.com/photo-1569718212165-3a8278d5f624?auto=format&fit=crop&w=800&q=80', '["Mì xào","Ăn nhanh","Dưới 20 phút","Bò xào","Sinh viên"]', '["breakfast","lunch","dinner"]', '["boil","stir_fry","pan_fry"]', '["beef","egg","molluscs","soybean","wheat"]', 667, 666.5, 2789, 38.6, 29.7, 7.9, 60.7, 3.9, 4.1, 1729, 4.32, '["USDA / MEXT Wheat Noodle Ref","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170187","USDA FDC 170390","USDA FDC 170499","USDA FDC 170931","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 173647","USDA FDC 174277","VN/Asian Seasoning Powder Avg"]', '5ca50b7b588852f676f56c11c30fe59c5e5bbe32e9d814c72540acbde10e1203', '276a431d4168d3353edd66d61fce98959ee9198ea03a8db2df7723c76bbc0f44', 4),
('vn-sang-05', 'trung-cuon-rau-cu-han-quoc', 52, 'Trứng cuộn rau củ mềm mịn', 'Trứng gà đánh tan lọc rây pha sữa tươi, tráng nhiều lớp cuộn tròn cùng cà rốt, hành tây và hành lá đẹp mắt', 'Món trứng cuộn rau củ mềm mịn từng lớp, vàng ươm bắt mắt điểm xuyết màu cam tươi của cà rốt, xanh non của hành lá và vị ngọt dịu từ hành tây cùng sữa tươi không đường.', 'Xếp từng khoanh trứng cuộn dày dặn ra đĩa, dùng nóng kèm cơm trắng hoặc bánh mì; chấm cùng tương ớt, tương cà hoặc xốt mayonnaise.', 'Nên ăn nóng hoặc ấm trong ngày để giữ độ ẩm xốp của trứng. Nếu bảo quản hộp kín trong ngăn mát tối đa 24 giờ, khi dùng có thể hấp cách thủy nhẹ 2 phút cho trứng mềm trở lại.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 8, 10, 2, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=800&q=80', '["Trứng cuộn","Ăn sáng","Dưới 20 phút","Giàu đạm","Bé thích"]', '["breakfast","lunch","dinner"]', '["pan_fry"]', '["egg","fish","milk"]', 217, 217.1, 908, 12.6, 14.9, 3.9, 8.2, 1.6, 4, 939, 2.35, '["USDA FDC 170000","USDA FDC 170005","USDA FDC 170393","USDA FDC 170931","USDA FDC 171265","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","VN/Asian Seasoning Powder Avg"]', '535e7a632d705e9345d785766560c07be579229d1d4b82008948f5e3dd01e37f', '5a4cfbfe4cf87a4bfbe852f66959131412933dae5f09e0867e4e6ab76db91a84', 4),
('vn-sang-06', 'sup-ga-ngo-non-nam-huong', 53, 'Súp gà ngô non nấm hương trứng hoa', 'Nước dùng gà ngọt thanh quyện hạt ngô ngọt giòn, nấm hương thái chỉ và những vân hoa trứng mềm mịn', 'Nồi súp gà ngô non nấm hương nóng hổi sánh nhẹ óng ả với vị ngọt tự nhiên từ ức gà ta luộc xé sợi và hạt ngô ngọt, thơm nồng hương nấm hương khô, điểm xuyết những dải vân trứng hoa mềm mượt, dầu mè và tiêu trắng.', 'Múc súp nóng ra bát sâu lòng, nhỏ vài giọt dầu mè, rắc thêm ngò rí, hành lá và tiêu trắng xay; dùng nóng ngay để cảm nhận độ sánh mượt.', 'Súp ngon nhất khi ăn nóng vừa nấu xong. Nếu bảo quản ngăn mát tối đa 24 giờ, khi hâm lại trên lửa nhỏ cần khuấy liên tục và thêm 2–3 muỗng nước lọc nếu súp đặc lại.', 'vietnamese', 'mon_nhanh_sang', 'toan_quoc', 'easy', 15, 20, 4, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=800&q=80', '["Súp nóng","Ăn sáng","Khai vị","Thanh nhẹ","Dễ tiêu"]', '["breakfast","lunch","dinner"]', '["boil","simmer"]', '["chicken","egg","sesame"]', 242, 242.2, 1013, 22.2, 8.3, 1.7, 20.9, 2.1, 4.2, 905, 2.26, '["USDA FDC 168436","USDA FDC 169717","USDA FDC 169997","USDA FDC 169998","USDA FDC 170005","USDA FDC 170499","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 171477","USDA FDC 173468","USDA FDC 173647","VN/Asian Seasoning Powder Avg"]', '388e059f16dff7358380e001fa0bad8640c6281aeb89ccd24caa1d2d5fc2e1e5', '8b1d6dbbffe79a42bc0e742db07b1e8106178b298773a78d2dcde5398fb248e3', 4),
('vn-lau-01', 'lau-rieu-cua-dong-bap-bo-suon-sun', 54, 'Lẩu riêu cua đồng sườn sụn bắp bò', 'Nồi lẩu riêu cua Bắc Bộ thơm nồng giấm bỗng, tảng riêu cua béo ngậy nhúng cùng bắp bò hoa giòn và sườn sụn heo sần sật', 'Lẩu riêu cua đồng sườn sụn bắp bò là đặc sản trứ danh đất Bắc. Nước lẩu chua thanh thơm nức mùi giấm bỗng và mắm tôm, nổi bật với lớp riêu cua đồng vàng ươm béo bùi, kết hợp sườn sụn ninh mềm giòn, bắp bò hoa thái mỏng, đậu phụ rán vàng và rổ rau sống tươi mát.', 'Đặt nồi lẩu sôi lăn tăn giữa bàn trên bếp từ hoặc bếp ga mini; nhúng bắp bò, đậu rán, váng đậu, rau muống chẻ và hoa chuối bào ăn kèm bún tươi cùng rau kinh giới, tía tô.', 'Nếu còn dư nước lẩu, lọc tách riêng rau và bún, để nguội rồi bảo quản ngăn mát tối đa 24 giờ; khi dùng lại đun sôi 3–5 phút và nhúng phần thịt, rau mới.', 'vietnamese', 'mon_lau_tiec', 'bac', 'hard', 35, 45, 6, 'https://images.unsplash.com/photo-1547928576-a4a33237cbc3?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Riêu cua đồng","Bắc Bộ","Bắp bò","Tiệc gia đình"]', '["lunch","dinner"]', '["simmer","pan_fry","boil"]', '["beef","crab","crustaceans","fish","pork","shrimp","soybean"]', 720, 719.6, 3010, 52.9, 35.4, 9.7, 48.4, 6.2, 4.9, 1640, 4.1, '["Annatto Infused Oil Ref","Asian Shrimp Paste Ref","Chili Oil / Satay Ref","MEXT Shiso Ref","NIN VN Fresh Rice Noodle Ref","SE Asian Banana Blossom Ref","USDA / MEXT Fish Cake Ref","USDA FDC 167861","USDA FDC 169378","USDA FDC 170005","USDA FDC 170187","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 172238","USDA FDC 172472","USDA FDC 172475","USDA FDC 173468","USDA FDC 173647","USDA FDC 174208","VN/Asian Seasoning Powder Avg"]', '829dd0c22b82199533e9b110f1beca7584bec832ae8dbfa13e9e47a5bf285646', 'd1408e19aa26f4c656afcda20baef90787134e461c1a02fc3b91f14ce541a380', 4),
('vn-lau-02', 'lau-ga-la-giang-chua-cay', 55, 'Lẩu gà ta lá giang chua cay Nam Bộ', 'Thịt gà ta săn chắc da giòn hòa quyện nước lẩu lá giang vò dập chua thanh dịu mát, thơm nồng mùi sả ớt và rau ngổ miền Tây', 'Lẩu gà ta lá giang là món lẩu đặc sản Nam Bộ rất được ưa chuộng trong những bữa tiệc sum họp hay ngày mưa se lạnh. Nước dùng hầm từ thịt gà ta ngọt đậm, kết hợp vị chua thanh tự nhiên của lá giang vò dập cùng hương thơm sả, ớt hiểm và ngò gai, rau ngổ.', 'Dọn nồi lẩu nóng giữa bàn trên bếp giữ sôi lăn tăn, nhúng rau muống chẻ và hoa chuối bào; ăn kèm bún gạo tươi và chén muối ớt hoặc nước mắm ớt mặn chấm thịt gà.', 'Nếu còn dư nước lẩu và thịt gà, vớt bỏ phần lá giang để tránh nước bị chua gắt thêm, để nguội rồi bảo quản ngăn mát tối đa 24 giờ và đun sôi lại 5 phút trước khi dùng.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 25, 40, 5, 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Gà ta","Lá giang","Nam Bộ","Chua cay"]', '["lunch","dinner"]', '["simmer","boil"]', '["chicken","fish"]', 634, 634.3, 2654, 37.1, 30.5, 7.9, 53, 6.6, 6.6, 1692, 4.23, '["Chili Oil / Satay Ref","NIN VN Fresh Bun Ref","SE Asian Banana Blossom Ref","USDA FDC 168573","USDA FDC 169230","USDA FDC 169378","USDA FDC 169655","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 171413","USDA FDC 171711","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","VN Culinary Herb Ref","VN Herb Ref","VN/Asian Seasoning Powder Avg"]', '42cd3e2abca824757ad4354e956d4adc163dd02c5b399339b918ac805731a3ce', 'e48f58e80a256085f35b6d02707c33b17b18f1f06a476ead6c627ccf859133ed', 4),
('vn-lau-03', 'lau-hai-san-thap-cam-chua-cay', 56, 'Lẩu hải sản tôm mực chua cay', 'Nước lẩu chua cay đậm đà từ me chín, sả riềng và lá chanh, nhúng tôm sú tươi giòn, mực ống sần sật và cá phi lê ngọt thịt', 'Lẩu hải sản tôm mực chua cay có nồi nước dùng sóng sánh màu đỏ cam hấp dẫn, hòa quyện hương thơm nồng nàn của sả, riềng, lá chanh cùng vị chua thanh của me chín và dứa. Hải sản tươi sống nhúng vừa chín tới giữ trọn độ giòn ngọt mọng nước.', 'Bày đĩa tôm sú, mực ống, cá phi lê, nấm tươi, rau muống và cải thảo quanh nồi lẩu sôi trên bàn; nhúng chín tới và thưởng thức cùng bún tươi, chấm muối tiêu chanh hoặc nước mắm ớt.', 'Hải sản chỉ nên nhúng đủ ăn trong bữa; phần nước lẩu chưa nhúng hải sản có thể bảo quản ngăn mát tối đa 24 giờ và đun sôi lại 3 phút khi dùng tiếp.', 'vietnamese', 'mon_lau_tiec', 'toan_quoc', 'medium', 25, 35, 5, 'https://images.unsplash.com/photo-1547928576-a4a33237cbc3?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Hải sản","Tôm mực","Chua cay","Tiệc gia đình"]', '["lunch","dinner"]', '["simmer","boil"]', '["crustaceans","fish","molluscs","shrimp","squid"]', 541, 540.7, 2262, 46.6, 8.7, 1.6, 72.3, 6.8, 15.6, 1319, 3.3, '["Citrus Leaf Culinary Ref","NIN VN Fresh Rice Noodle Ref","USDA / SE Asian Galangal Ref","USDA FDC 168573","USDA FDC 168580","USDA FDC 169076","USDA FDC 169124","USDA FDC 169230","USDA FDC 169253","USDA FDC 169378","USDA FDC 169655","USDA FDC 169918","USDA FDC 169977","USDA FDC 170106","USDA FDC 170457","USDA FDC 170499","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 174223","USDA FDC 175148","USDA FDC 175179","USDA FDC Sriracha Ref"]', '104e325901f970349c52433310e6f8b884f00e5f57c59b912ec9e83cd322d79c', 'fb770647253158181263da2e39acd9136d645159e8a78ef502eadf53f551733e', 4),
('vn-lau-04', 'lau-nam-thap-cam-thanh-dam', 57, 'Lẩu nấm thập cẩm gà ta thanh đạm', 'Nước dùng ninh từ gà ta, xương heo cùng táo đỏ, kỷ tử và củ cải ngọt thanh, nhúng cùng nhiều loại nấm tươi giòn dai bổ dưỡng', 'Lẩu nấm thập cẩm gà ta là món lẩu thanh đạm, ít dầu mỡ và giàu dưỡng chất. Nước lẩu ngọt tự nhiên từ xương ống, gà ta thả vườn kết hợp bắp ngọt, củ cải, cà rốt và vị thảo mộc nhẹ của táo đỏ kỷ tử, tôn lên độ giòn ngọt tinh tế của các loại nấm tươi.', 'Bày khay nấm tươi thập cẩm, đậu phụ non, cải thảo, rau cải cúc và mì trứng vắt trụng ráo quanh nồi lẩu; nhúng nấm chín vừa trong 2–3 phút rồi dùng nóng với nước tương ớt hoặc muối tiêu chanh.', 'Nước dùng gà và nấm chưa nhúng rau có thể để nguội, bảo quản ngăn mát tối đa 24 giờ; khi dùng lại đun sôi 5 phút và nhúng rau nấm mới.', 'vietnamese', 'mon_lau_tiec', 'toan_quoc', 'medium', 25, 45, 5, 'https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Lẩu nấm","Gà ta","Thanh đạm","Bổ dưỡng"]', '["lunch","dinner"]', '["simmer","boil"]', '["chicken","egg","fish","pork","soybean","wheat"]', 717, 717, 3000, 48.6, 33.4, 8.9, 58.3, 8.2, 11.9, 1635, 4.09, '["Pork Bone Stock Extraction Ref","USDA / MEXT Wheat Noodle Ref","USDA FDC 168452","USDA FDC 168580","USDA FDC 169230","USDA FDC 169249","USDA FDC 169251","USDA FDC 169253","USDA FDC 169977","USDA FDC 169998","USDA FDC 170393","USDA FDC 170499","USDA FDC 170931","USDA FDC 171077","USDA FDC 171413","USDA FDC 172185","USDA FDC 172476","USDA FDC 173468","USDA FDC 173647","USDA FDC Jujube Ref","VN/Asian Seasoning Powder Avg"]', '87490711f30e6eb4fd84516b2237176e3b5d9c83e36dc40077c7455b4f11bf19', 'c3b77b88bf61ebbd78b79053a87fde8215b5799de7367956fb168e5d0156d78b', 4),
('vn-lau-05', 'lau-ca-thac-lac-kho-qua', 58, 'Lẩu cá thác lác khổ qua thanh mát', 'Chả cá thác lác quết dai dẻo thơm mùi thì là hành tiêu, thả vào nước dùng xương ngọt trong nhúng cùng khổ qua bào mỏng giòn mát', 'Lẩu cá thác lác khổ qua là món ăn giải nhiệt đặc sắc của miền Nam. Nước lẩu hầm từ xương heo cùng hành tây và cà rốt ngọt thanh trong veo, kết hợp những viên chả cá thác lác quết dai sần sật và từng lát khổ qua ướp lạnh bào mỏng giòn rụm dịu đắng.', 'Múc từng viên cá thác lác thả vào nồi lẩu sôi cho đến khi nổi phồng, nhúng nhanh khổ qua bào mỏng, cải cúc và nấm khoảng 15–20 giây để giữ độ giòn ngọt; dùng nóng với bún gạo tươi và nước mắm ớt nguyên chất.', 'Nếu còn dư nước dùng và viên chả cá đã luộc chín, bảo quản riêng với khổ qua trong ngăn mát tối đa 24 giờ; khi ăn đun sôi nước dùng rồi mới thả khổ qua tươi vào.', 'vietnamese', 'mon_lau_tiec', 'nam', 'medium', 25, 35, 4, 'https://images.unsplash.com/photo-1603105037880-880cd4edfb0d?auto=format&fit=crop&w=800&q=80', '["Món lẩu","Cá thác lác","Khổ qua","Nam Bộ","Thanh mát"]', '["lunch","dinner"]', '["simmer","boil"]', '["fish","pork"]', 438, 437.8, 1832, 35.3, 10.5, 2.6, 52.2, 8.4, 8.6, 1693, 4.23, '["NIN VN Fresh Bun Ref","Pork Bone Stock Extraction Ref","USDA FDC 168393","USDA FDC 169249","USDA FDC 169251","USDA FDC 169253","USDA FDC 169378","USDA FDC 169997","USDA FDC 170000","USDA FDC 170005","USDA FDC 170106","USDA FDC 170393","USDA FDC 170499","USDA FDC 170933","USDA FDC 171413","USDA FDC 172185","USDA FDC 172233","USDA FDC 173468","USDA FDC 173647","USDA FDC 175148","USDA FDC Sucrose Ref","VN/Asian Seasoning Powder Avg"]', 'b3823fa6d30a2ad712f1077df3272163880217167ec7fb8fb251ad5184b2e9f6', 'abbe4c1e99b1532036954fb89139bb92a1bc8c9db4fd55611b8900583d32641c', 4),
('gl-01', 'pasta-pomodoro', 59, 'Mì Ý sốt cà chua Pomodoro', 'Mì Spaghetti dai vừa chuẩn Ý hòa quyện sốt cà chua ninh sánh mịn, thơm mùi tỏi phi dầu ô liu và lá húng quế tươi', 'Mì Ý sốt cà chua Pomodoro là biểu tượng tối giản của ẩm thực Ý với vị chua ngọt tự nhiên từ cà chua chín lột vỏ ninh chậm, thơm dịu tỏi phi dầu ô liu nguyên chất và lá húng quế Tây tươi mát.', 'Chia mì ra đĩa sâu lòng đã làm ấm, rắc thêm phô mai Parmesan bào mịn và vài lá húng quế tươi lên trên, dùng nóng ngay khi sợi mì còn bóng sốt.', 'Phần sốt cà chua có thể bảo quản trong hộp kín ở ngăn mát tủ lạnh tối đa 3 ngày; khi ăn đun nóng lại sốt trên chảo rồi trộn với mì mới luộc để giữ độ dai ngon.', 'italian', 'mon_bun_pho', NULL, 'easy', 10, 25, 2, '/frigo/recipes/global/pasta-pomodoro.webp', '["Món Ý","Mì Ý","Sốt cà chua","Thanh đạm","Nấu nhanh"]', '["lunch","dinner"]', '["boil","simmer","toss_mix"]', '["milk","wheat"]', 605, 604.9, 2531, 20.5, 18.6, 4, 91, 7.2, 11.6, 997, 2.49, '["USDA FDC 168927","USDA FDC 169072","USDA FDC 169230","USDA FDC 170848","USDA FDC 170931","USDA FDC 171413","USDA FDC 172232","USDA FDC 173468","USDA FDC 173647"]', '57f35b2d9e1efad53f79716ccc3496baf9d081ed63603e453d4939990a42849e', 'fc1a46b441522ada0f516fa151c0d4d833948df8c227c09f6b9b019954be4cbb', 4),
('gl-02', 'mapo-tofu', 60, 'Đậu phụ sốt Mapo Tofu Tứ Xuyên', 'Đậu phụ non mềm mịn hòa quyện thịt heo băm xào giòn trong sốt tương ớt đậu bản cay nồng và hoa tiêu tê đầu lưỡi', 'Đậu phụ sốt Mapo Tofu Tứ Xuyên nổi tiếng với sự kết hợp hài hòa giữa đậu phụ non béo mịn, thịt heo xay săn thơm và lớp sốt đỏ óng từ tương ớt đậu bản, đậu tương đen lên men cùng hoa tiêu tê nồng.', 'Dọn nóng trong đĩa sâu lòng, rắc phần lá hành xanh và bột hoa tiêu còn lại lên mặt; thưởng thức cùng cơm trắng dẻo nóng.', 'Ngon nhất khi dùng ngay lúc nóng. Nếu bảo quản tủ mát trong hộp kín tối đa 2 ngày, hâm lại bằng chảo trên lửa nhỏ và thêm 1–2 muỗng canh nước lọc để sốt không bị khô.', 'chinese', 'mon_kho', NULL, 'medium', 15, 20, 4, '/frigo/recipes/global/mapo-tofu.webp', '["Tứ Xuyên","Cay tê","Đậu phụ","Đưa cơm"]', '["lunch","dinner"]', '["stir_fry","braise"]', '["pork","sesame","soybean","wheat"]', 305, 304.5, 1274, 14.8, 22.1, 5, 12.3, 1.8, 2.6, 1232, 3.08, '["Douchi Reference","Pixian Doubanjiang Ref","Spice Reference","USDA FDC 167902","USDA FDC 169230","USDA FDC 169231","USDA FDC 169655","USDA FDC 169698","USDA FDC 170005","USDA FDC 171028","USDA FDC 171319","USDA FDC 171413","USDA FDC 172476","USDA FDC 172883","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'de3870eb0a7cf7152e859aff991cd0b76b8086a321d42eceea2af2f084d5bea8', 'dbd0608a0c31c2952692a42faaf9a2cd11a74351d9b92701edf107b423395585', 4),
('gl-03', 'tomato-egg-stir-fry', 61, 'Cà chua xào trứng kiểu Trung Hoa', 'Trứng gà đánh với rượu Thiệu Hưng chiên xốp mềm, hòa quyện sốt cà chua đỏ mọng chua ngọt thanh nhẹ chuẩn bữa cơm gia đình', 'Cà chua xào trứng kiểu Trung Hoa là món ăn gia đình kinh điển với lớp trứng chiên tơi xốp ngấm trọn nước sốt cà chua đỏ sánh, vị chua ngọt dịu nhẹ và mùi thơm thoang thoảng của dầu mè cùng rượu Thiệu Hưng.', 'Dùng nóng ngay sau khi tắt bếp, rắc thêm hành lá xanh và ăn kèm cơm trắng nóng hoặc mì trộn.', 'Món ăn ngon nhất khi dùng trong bữa; nếu còn dư, bảo quản tủ mát tối đa 24 giờ và làm nóng nhanh trên chảo lửa vừa với 1 muỗng canh nước lọc.', 'chinese', 'mon_xao', NULL, 'easy', 8, 10, 2, '/frigo/recipes/global/tomato-egg-stir-fry.webp', '["Trung Hoa","Nhanh gọn","Cà chua trứng","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","sesame","wheat"]', 339, 338.9, 1417, 13.4, 25.6, 5.2, 15.1, 3.3, 10.9, 914, 2.29, '["Shaoxing Wine Ref","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170933","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647"]', 'c0f76c1cb5240e6fa59947ecfb566f725eb14c76a63f94895cc6e0bb528ed5d6', '90009ddd3488d3e5aabf2acdb087499fd949491c0abad7f40d2224cdd082d932', 4),
('gl-04', 'oyakodon', 62, 'Cơm gà trứng Oyakodon Nhật Bản', 'Cơm donburi Nhật truyền thống với thịt đùi gà mềm ngọt om nước dùng dashi, quyện lớp trứng gà đánh lướt mịn mượt trên nền cơm trắng dẻo nóng', 'Oyakodon là món cơm tô gia đình quen thuộc của Nhật Bản, kết hợp thịt đùi gà cắt miếng vừa ăn nấu cùng hành tây ngọt mềm trong nước dùng dashi đậm vị xì dầu và rượu ngọt mirin, phủ lớp trứng đánh nhẹ chín tới mịn mượt.', 'Xới cơm Nhật nóng ra hai tô sâu lòng, nhẹ nhàng trút trọn phần gà trứng còn nóng hổi lên trên, rắc hành lá thái nhỏ và ớt bột Shichimi rồi thưởng thức ngay.', 'Nên dùng ngay khi trứng còn mềm mịn; nếu dư, tách riêng phần cơm và nhân gà trứng cho vào hộp kín bảo quản tủ lạnh tối đa 1 ngày, hâm nóng bằng lò vi sóng hoặc chảo nhỏ có nắp trước khi ăn.', 'japanese', 'mon_nhanh_sang', NULL, 'easy', 10, 15, 2, '/frigo/recipes/global/oyakodon.webp', '["Nhật Bản","Cơm donburi","Thịt gà","Nhanh gọn","Bữa trưa"]', '["lunch","dinner"]', '["simmer"]', '["chicken","egg","fish","sesame","soybean","wheat"]', 672, 672.2, 2813, 42.8, 21.8, 6.3, 68.2, 1.8, 12.7, 1380, 3.45, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","MEXT Spice Ref","USDA FDC 168878","USDA FDC 169655","USDA FDC 170000","USDA FDC 170005","USDA FDC 171287","USDA FDC 172385","USDA FDC 174277"]', '5404e3189ccd13e8d38f2831f6768cf2ce3320ae978bf19955aa882b0baf955b', '82378c9b6531fdd69f26b28ce3a562a18de77317838e12ad12ef69071b92e139', 4),
('gl-05', 'kimchi-fried-rice', 63, 'Cơm chiên kim chi Hàn Quốc', 'Cơm chiên kim chi chua cay đậm vị tương ớt Gochujang, hạt cơm săn tơi phủ trứng ốp la lòng đào béo ngậy', 'Cơm chiên kim chi Hàn Quốc là món ăn nhanh gọn nhưng tròn vị nhờ sự kết hợp giữa cơm nguội hạt săn tơi, kim chi cải thảo ủ chua giòn sần sật và sốt tương ớt Gochujang cay ngọt hài hòa. Lớp trứng ốp la lòng đào bên trên giúp món ăn thêm béo thơm hấp dẫn.', 'Xới cơm nóng ra đĩa, đặt trứng ốp la lòng đào lên trên, rắc hạt mè trắng rang và rong biển lá khô xé nhỏ; ăn ngay khi còn nóng và trộn đều lòng đỏ trứng vào cơm.', 'Món ngon nhất khi dùng ngay sau khi chiên. Phần cơm còn dư có thể bảo quản hộp kín trong ngăn mát tối đa 24 giờ và áp chảo lại trên lửa vừa 3–4 phút với chút dầu ăn trước khi dùng.', 'korean', 'mon_nhanh_sang', NULL, 'easy', 10, 15, 2, '/frigo/recipes/global/kimchi-fried-rice.webp', '["Hàn Quốc","Món nhanh","Chua cay","Cơm chiên","Bữa sáng"]', '["breakfast","lunch","dinner"]', '["stir_fry","pan_fry"]', '["egg","sesame","soybean","wheat"]', 508, 508.2, 2127, 14.8, 15.3, 3.1, 77.1, 4.4, 6.1, 1210, 3.03, '["USDA / Korean Gochujang Ref","USDA FDC 168456","USDA FDC 168878","USDA FDC 170000","USDA FDC 170005","USDA FDC 170150","USDA FDC 170393","USDA FDC 170497","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 174277"]', 'e180571a64206c91489bd3e7da92daf18d12ebd4de535036f2ddeb998d97bc54', '892cd104c8842994b37e0c4c607ce72bec5078f45beec3fa4128c7b93edc4c11', 4),
('gl-06', 'pad-krapow', 64, 'Thịt heo băm xào lá quế kiểu Thái (Pad Krapow)', 'Thịt heo băm xào tỏi ớt thơm nồng hương húng quế Thái, đậm vị nước tương và nước mắm, ăn kèm cơm trắng trứng ốp la giòn viền', 'Pad Krapow là món cơm đĩa đường phố trứ danh của Thái Lan với thịt heo băm xào săn trên lửa lớn cùng tỏi ớt giã dập, đậu que giòn ngọt, sốt nước tương đậm đà và lá húng quế thơm nồng.', 'Xới cơm trắng nóng ra đĩa sâu lòng, múc thịt heo xào húng quế lên bên cạnh, đặt trứng gà ốp la viền giòn lên trên và dọn kèm chén nước mắm ớt chanh.', 'Ngon nhất khi ăn nóng ngay sau khi xào; phần thịt xào có thể bảo quản hộp kín trong ngăn mát 2 ngày, hâm nóng bằng chảo lửa lớn và chiên trứng mới khi dùng.', 'thai', 'mon_xao', NULL, 'easy', 10, 12, 2, '/frigo/recipes/global/pad-krapow.webp', '["Thái Lan","Món xào","Cay nồng","Cơm đĩa","Nhanh gọn"]', '["lunch","dinner"]', '["stir_fry","pan_fry"]', '["egg","fish","pork","soybean","wheat"]', 813, 812.9, 3401, 38.2, 48.8, 15.1, 53.4, 2.3, 6.1, 1578, 3.95, '["Dark Soy Sauce Label Ref","USDA FDC 167902","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 169961","USDA FDC 170106","USDA FDC 171287","USDA FDC 171413","USDA FDC 172185","USDA FDC 172232","USDA FDC 173647","USDA FDC 174277"]', '76b23f3e7bc5408231bcdb454b1e9942ddabdbb2035f37618a9201a42ee36870', '028df0d24c7c63e643d13bb5ce435c77e2c59fef920a04654cca3b26f0814f84', 4),
('gl-07', 'kimbap-han-quoc', 65, 'Cơm cuộn Kimbap Hàn Quốc', 'Cuộn rong biển chắc tay với cơm dẻo thơm dầu mè, thịt bò xào đậm đà, trứng tráng, rau chân vịt, cà rốt và củ cải vàng giòn', 'Cơm cuộn Kimbap Hàn Quốc hài hòa sắc màu và dinh dưỡng với lớp cơm trắng trộn dầu mè thơm bùi, ôm trọn nhân thịt bò xào xì dầu, trứng gà rán vàng, rau chân vịt chần, cà rốt giòn ngọt và thanh củ cải muối vàng chua dịu.', 'Cắt cuộn Kimbap thành từng khoanh tròn dày khoảng 1,5–2 cm, bày ra đĩa cùng chút củ cải muối vàng hoặc kim chi ăn kèm.', 'Gói kín từng cuộn bằng màng bọc thực phẩm và bảo quản ngăn mát tối đa 24 giờ; không nên hâm nóng bằng lò vi sóng quá lâu để tránh dai lá rong biển, chỉ cần để nhiệt độ phòng 15 phút trước khi ăn.', 'korean', 'mon_cuon_nom', NULL, 'easy', 25, 20, 3, '/frigo/recipes/global/kimchi-fried-rice.webp', '["Hàn Quốc","Cơm cuộn","Dã ngoại","Meal prep","Rong biển"]', '["breakfast","lunch"]', '["pan_fry","boil","assemble"]', '["beef","egg","sesame","soybean","wheat"]', 683, 683, 2858, 29.4, 30.1, 6.9, 72.9, 4.1, 5.1, 1702, 4.26, '["MEXT Takuan Ref","USDA FDC 168456","USDA FDC 168462","USDA FDC 168878","USDA FDC 169230","USDA FDC 169655","USDA FDC 170150","USDA FDC 170187","USDA FDC 170393","USDA FDC 170931","USDA FDC 171028","USDA FDC 171287","USDA FDC 171413","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277"]', 'dcd097ef76bce9e3c6c65e2b0932d100a0225ac6a153142f242fe85428d9b642', 'afdc1eddfcc34bf64597d910ef75f5eaba5cc340f4a5c166d78be0086f50df2c', 4),
('gl-08', 'tokbokki-cay-ngot', 66, 'Bánh gạo Tokbokki sốt cay ngọt', 'Bánh gạo dẻo mềm quyện sốt tương ớt Gochujang cay ngọt sánh đỏ cùng chả cá Hàn Quốc, bắp cải ngọt dịu và trứng gà luộc', 'Bánh gạo Tokbokki sốt cay ngọt chuẩn vị đường phố Seoul với từng thỏi bánh gạo dẻo bùi thấm đẫm nước sốt Gochujang đỏ óng sánh mịn, hòa quyện vị ngọt thanh của bắp cải, chả cá mềm dai và trứng gà luộc béo bùi.', 'Múc Tokbokki nóng hổi ra đĩa sâu lòng, cắt đôi trứng gà luộc đặt lên trên và rắc thêm chút hạt mè trắng rang, dùng ngay khi nước sốt còn sánh ấm.', 'Nếu còn dư, cất hộp kín trong ngăn mát tối đa 2 ngày; khi ăn lại thêm 2–3 muỗng canh nước lọc vào chảo rồi đun nhỏ lửa 4–5 phút cho bánh gạo mềm dẻo trở lại.', 'korean', 'mon_nhanh_sang', NULL, 'easy', 10, 20, 2, '/frigo/recipes/global/kimchi-fried-rice.webp', '["Hàn Quốc","Ăn vặt","Cay ngọt","Bánh gạo","Đường phố"]', '["lunch","dinner"]', '["boil","simmer"]', '["egg","fish","sesame","soybean","wheat"]', 646, 646, 2703, 22.5, 9.7, 2.3, 117, 4.4, 24.3, 1722, 4.31, '["Korean Anchovy Kelp Stock Ref","Korean Chili Flake Ref","Korean Tteok Ref","USDA / Korean Gochujang Ref","USDA / MEXT Fish Cake Ref","USDA FDC 168836","USDA FDC 169230","USDA FDC 169655","USDA FDC 169975","USDA FDC 170005","USDA FDC 170150","USDA FDC 171028","USDA FDC 171287","USDA FDC 174277"]', '36b39d26d4528a39803b3e102890771109e4a56391158ed5ad4f5fdec73ae925', 'ab9f053061a47942160f5c1219eb77e309f71d477303a35579d428250f46f386', 4),
('gl-09', 'chawanmushi', 67, 'Trứng hấp Chawanmushi tôm nấm Nhật Bản', 'Trứng hấp custard mặn kiểu Nhật mềm mịn như thạch lụa, hòa quyện vị ngọt thanh của tôm tươi, thịt đùi gà, nấm hương và nước dùng dashi', 'Chawanmushi là món trứng hấp khai vị tinh tế của ẩm thực Nhật Bản, nổi bật với kết cấu custard mịn màng không rỗ bọt khí nhờ tỷ lệ trứng và nước dùng dashi chuẩn xác cùng kỹ thuật hấp lửa nhỏ cách thủy.', 'Dọn nguyên chén sứ hấp nóng hổi lên bàn ăn cùng thìa nhỏ, rắc thêm hành lá tươi lên mặt chén và dùng làm món khai vị hoặc ăn kèm cơm trắng.', 'Ngon nhất khi thưởng thức ngay sau khi hấp; phần chưa dùng hết đậy kín nắp chén bảo quản tủ lạnh tối đa 1–2 ngày và hấp cách thủy lại lửa nhỏ 3–4 phút cho nóng đều.', 'japanese', 'mon_hap_luoc', NULL, 'easy', 15, 25, 2, '/frigo/recipes/global/oyakodon.webp', '["Nhật Bản","Món hấp","Thanh đạm","Hải sản","Bữa tối nhẹ"]', '["lunch","dinner"]', '["steam"]', '["chicken","crustaceans","egg","fish","shrimp","soybean","wheat"]', 214, 214.4, 897, 22.7, 8.5, 2.5, 9, 1.2, 2.5, 943, 2.36, '["MEXT Hon-Mirin 16031","MEXT Ichiban Dashi Ref","MEXT Sake 16021","USDA / MEXT Fish Cake Ref","USDA FDC 168436","USDA FDC 169251","USDA FDC 170005","USDA FDC 171287","USDA FDC 172385","USDA FDC 173468","USDA FDC 173647","USDA FDC 174277","USDA FDC 175179"]', '3da81fc2d0c9bac89140870fb368c7a9f4d8eebb11623b710679a20d4deea784', '2dfffdcadb918a1ab59dc5f018d63d7ca85fac722696e3245259877be09580fa', 4),
('gl-10', 'thai-green-curry', 68, 'Cà ri xanh thịt gà kiểu Thái (Green Curry)', 'Thịt đùi gà om mềm trong nước cốt dừa béo ngậy hòa quyện sốt cà ri xanh, lá chanh Thái thơm nồng và cà tím giòn ngọt', 'Cà ri xanh (Kaeng Khiao Wan) nổi bật với màu xanh ngọc tự nhiên của ớt xanh và rau thơm, nước sốt cốt dừa tách dầu béo mịn quyện cùng đùi gà mềm ngọt, cà tím và hương lá chanh Thái.', 'Múc cà ri xanh nóng ra tô sâu lòng, rắc thêm vài lá húng quế Thái tươi và ớt đỏ thái lát; dọn ăn kèm cơm trắng gạo lài hoặc bún gạo tươi.', 'Cà ri ngon hơn khi để nghỉ 1–2 giờ cho thấm vị; bảo quản ngăn mát tối đa 2 ngày trong hộp kín, khi ăn đun nóng lại trên lửa nhỏ và khuấy đều để cốt dừa không tách lớp.', 'thai', 'mon_kho', NULL, 'medium', 15, 25, 3, '/frigo/recipes/global/pad-krapow.webp', '["Thái Lan","Cà ri","Cốt dừa","Cay nồng","Món om"]', '["lunch","dinner"]', '["simmer"]', '["chicken","crustaceans","fish","shrimp"]', 544, 544.4, 2278, 31, 39.2, 25.3, 19.9, 5, 13.3, 1473, 3.68, '["Asian Shrimp Paste Ref","Citrus Leaf Culinary Ref","Thai Curry Paste Ref","USDA FDC 169228","USDA FDC 170106","USDA FDC 170108","USDA FDC 170172","USDA FDC 172185","USDA FDC 172232","USDA FDC 172385","USDA FDC 172883","USDA FDC Palm Sugar Ref"]', '448a3c4b018afa2d937a5bc0ced993742499bc0b4dc367d4ffb8fb7e36f0302f', '5ba88aab04ed1c87188debb87454d34094772613cebefbcdbb0e8650b2377899', 4),
('gl-11', 'spaghetti-bolognese', 69, 'Mì Ý sốt bò bằm Bolognese', 'Mì Spaghetti dai ngon thấm đẫm sốt thịt bò xay hầm chậm cùng ba chỉ xông khói, rau củ soffritto, rượu vang trắng và sữa tươi béo dịu', 'Món mì Ý sốt bò bằm Bolognese chuẩn vị với nền rau củ cà rốt, cần tây, hành tây xào ngọt, kết hợp thịt bò xay và ba chỉ xông khói hầm chậm cùng sốt cà chua Passata, rượu vang trắng và sữa tươi tạo độ béo mượt tròn vị.', 'Bày mì Ý ra đĩa sâu lòng, chan ngập sốt thịt bò Bolognese nóng hổi lên trên, rắc thêm phô mai Parmesan bào mịn và ít tiêu đen xay.', 'Sốt Bolognese bảo quản trong hộp kín ở ngăn mát được 3 ngày hoặc cấp đông đến 1 tháng; khi dùng hâm nóng sốt trên lửa nhỏ với chút nước lọc rồi trộn mì mới luộc.', 'italian', 'mon_bun_pho', NULL, 'medium', 15, 60, 3, '/frigo/recipes/global/carbonara.webp', '["Món Ý","Mì Ý","Thịt bò bằm","Sốt cà chua","Gia đình"]', '["lunch","dinner"]', '["boil","braise","simmer"]', '["beef","celery","milk","pork","sulphites","wheat"]', 777, 776.8, 3250, 38.4, 31.7, 11.3, 77.9, 5.8, 11, 1477, 3.69, '["USDA FDC 167923","USDA FDC 168927","USDA FDC 169072","USDA FDC 169988","USDA FDC 170000","USDA FDC 170393","USDA FDC 170848","USDA FDC 170931","USDA FDC 171265","USDA FDC 171413","USDA FDC 171593","USDA FDC 173190","USDA FDC 173468","USDA FDC 173647","USDA FDC 174036"]', '925c81e34822c95c39b075ac74d3ba4f938f5356176c8205847f25f613378e2c', '1a1c522311074da7a5627214324d311d092356c45167a8b4598aa757beaed704', 4),
('gl-12', 'chinese-tomato-egg', 70, 'Trứng xào cà chua sốt tương kiểu Quảng Đông', 'Biến tấu kiểu quán cơm Hồng Kông với trứng đánh sữa tươi béo mượt, cà chua hai kiểu cắt hòa quyện tương cà, xì dầu và dầu hào', 'Khác với phiên bản truyền thống dùng muối và rượu Thiệu Hưng, trứng xào cà chua kiểu Quảng Đông kết hợp sữa tươi giúp miếng trứng mềm mịn như kem, quyện cùng nước sốt đậm vị từ tương cà, xì dầu nhạt, dầu hào và gừng thơm.', 'Dọn nóng ra đĩa hoặc chan trực tiếp lên tô cơm trắng nóng hổi, rắc hành lá thái nhỏ lên mặt.', 'Nên dùng ngay trong bữa để giữ độ mềm mịn của trứng; nếu bảo quản tủ mát tối đa 24 giờ, hâm lại nhẹ nhàng trên chảo lửa nhỏ.', 'chinese', 'mon_xao', NULL, 'easy', 10, 12, 2, '/frigo/recipes/vietnam/dau-phu-sot-ca-chua.webp', '["Quảng Đông","Nhanh gọn","Cà chua trứng","Cơm nhà"]', '["breakfast","lunch","dinner"]', '["stir_fry"]', '["egg","milk","molluscs","soybean","wheat"]', 297, 297.1, 1242, 11.8, 20.3, 4.2, 18.8, 3, 13.2, 905, 2.26, '["USDA FDC 169076","USDA FDC 169231","USDA FDC 169655","USDA FDC 170005","USDA FDC 170457","USDA FDC 170933","USDA FDC 171265","USDA FDC 171287","USDA FDC 171369","USDA FDC 171413","USDA FDC 174277"]', 'ea7e0eb62b2be5003789bf95bb399eda7a64a0201cc45979960aa74031eccece', '94473a9416d77bfe679402fc255ff3b3427400e6d20b78e6e88d8608dca1f003', 4),
('imp-199ff78d3d8c8ab3', 'canh-bi-do-nau-tom-tuoi-ngot-nuoc', 71, 'Canh bí đỏ nấu tôm tươi ngọt nước', 'Bí đỏ chín mềm bùi quyện cùng nước dùng lọc từ đầu tôm và thịt tôm tươi săn ngọt, dễ nấu cho bữa cơm gia đình', 'Món canh dân dã Nam Bộ có màu vàng cam đẹp mắt, vị bùi ngọt tự nhiên của bí đỏ hòa cùng nước ngọt thanh từ đầu tôm ninh kỹ và thịt tôm tươi săn giòn.', 'Múc canh nóng ra tô lớn, rắc hành lá, ngò rí và chút tiêu xay lên mặt; dùng kèm cơm trắng và đĩa cá kho hoặc thịt ram.', 'Để nguội hoàn toàn rồi bảo quản ngăn mát tối đa 24 giờ; khi hâm lại nên đun lửa vừa vừa đủ sôi lăn tăn để bí đỏ không bị nát vụn và tôm không bị dai.', 'vietnamese', 'mon_canh', 'nam', 'easy', 15, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món canh","Nam Bộ","Bổ dưỡng","Cơm nhà","Dễ nấu"]', '["lunch","dinner"]', '["simmer"]', '["crustaceans","fish","shrimp"]', 106, 106.2, 445, 11.4, 3.7, 0.6, 8.2, 0.9, 3.1, 1229, 3.07, '["USDA FDC 168448","USDA FDC 169230","USDA FDC 169997","USDA FDC 170005","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '03da674d31a12b4e08a29cd88c8136bf4b487f80a5d10e075b75a7778303025d', 'a8081ff83a2ac825f385bff7669e57af39fc52c59efb56603a87e98075b4296b', 4),
('imp-ab36e38b07f3a57b', 'suon-non-kho-dua-chua-ngot-dam-vi', 72, 'Sườn non kho dứa chua ngọt', 'Sườn non heo kho mềm cùng dứa chín vàng thơm, nước kho sánh màu cánh gián chua ngọt hài hòa chuẩn vị cơm nhà Nam Bộ', 'Từng dẻ sườn non thấm đẫm nước cốt dứa tự nhiên giúp thịt nhanh mềm ngọt, kết hợp cùng miếng dứa xào chín dịu vị chua và nước sốt kho cánh gián sánh bóng.', 'Múc sườn kho dứa ra đĩa sâu lòng, rắc hành lá và tiêu đen xay lên mặt, dùng nóng với cơm trắng và đĩa dưa leo thái lát.', 'Để nguội hoàn toàn và bảo quản trong hộp kín ở ngăn mát tối đa 3 ngày; khi ăn đun nóng lại trên lửa nhỏ với 1–2 muỗng nước ấm.', 'vietnamese', 'mon_kho', 'nam', 'medium', 20, 45, 4, '/frigo/illustrations/delicious-meal.png', '["Món kho","Sườn non","Nam Bộ","Chua ngọt","Đưa cơm"]', '["lunch","dinner"]', '["braise","stir_fry","boil"]', '["fish","pork"]', 378, 378.4, 1583, 16.6, 28, 9.2, 15.2, 1.1, 11.8, 1340, 3.35, '["USDA FDC 167861","USDA FDC 169124","USDA FDC 169230","USDA FDC 169655","USDA FDC 170005","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647"]', '034d85de96b214769eed94699a2a243c719d673a409f026f3bd2f487bdb9086f', 'd0f7485cdbb43ce2dc5613af94e477cffb777a6d3ad1a8a67fe20255d5355595', 4);
INSERT OR IGNORE INTO recipe_standard_v4_catalog (id, slug, runtime_order, title, subtitle, description, serving_suggestion, storage_and_reheat, cuisine, category, region, difficulty, prep_time_minutes, cook_time_minutes, servings, image_url, tags_json, meal_types_json, methods_json, allergen_tags_json, calories, energy_kcal, energy_kj, protein_g, fat_g, saturated_fat_g, carb_g, fiber_g, sugar_g, sodium_mg, salt_g, source_references_json, v1_fingerprint, v2_sha256, recipe_version) VALUES
('imp-26a36c69306143bc', 'tom-xao-bong-cai-xanh-toi-gion-ngot', 73, 'Tôm xào bông cải xanh tỏi giòn ngọt', 'Tôm tươi săn chắc quyện sốt sánh nhẹ cùng bông cải xanh giòn mướt, thơm lừng tỏi phi và vài giọt dầu mè', 'Tôm tươi lột vỏ rút chỉ xào nhanh lửa lớn giữ được độ ngọt giòn săn chắc, kết hợp cùng bông cải xanh chần sốc nhiệt giòn mát và lớp sốt bột bắp óng ả thơm mùi tỏi phi.', 'Xếp tôm và bông cải xanh ra đĩa rộng khi còn nóng, rắc tiêu đen xay lên trên; dùng ngay với cơm trắng nóng hổi.', 'Món hải sản xào ngon nhất khi ăn nóng trong bữa; nếu bảo quản tủ mát tối đa 24 giờ, hãy đảo nhanh lại trên chảo nóng khoảng 1 phút để tôm không bị khô cứng.', 'vietnamese', 'mon_xao', 'toan_quoc', 'easy', 15, 10, 3, '/frigo/illustrations/delicious-meal.png', '["Món xào","Hải sản","Rau xanh","Dưới 20 phút","Cơm nhà"]', '["lunch","dinner"]', '["stir_fry","boil"]', '["crustaceans","fish","sesame","shrimp"]', 207, 207.1, 866, 19.2, 10, 1.5, 12.3, 2.8, 2.8, 1127, 2.82, '["USDA FDC 169230","USDA FDC 169698","USDA FDC 170000","USDA FDC 170379","USDA FDC 170931","USDA FDC 171028","USDA FDC 171413","USDA FDC 172185","USDA FDC 173468","USDA FDC 173647","USDA FDC 175179","VN/Asian Seasoning Powder Avg"]', '28ec40c79a59d454b15dcd6ba27af587d645b9bdbfd9884b703c2c1d822f7077', '887a69516490cf41a247b31b2d0950a397a9a35cf29d4846213bfd402c879b0f', 4),
('imp-b87b71d57128cc07', 'ca-loc-chien-sa-ot-vang-gion', 74, 'Cá lóc chiên sả ớt vàng giòn', 'Khúc cá lóc ướp sả nghệ chiên vàng giòn rụm phủ sả phi thơm lừng, thịt cá ngọt săn chấm mắm ớt', 'Cá lóc chiên sả ớt vàng giòn là món ăn đậm chất miền Tây Nam Bộ, hấp dẫn bởi lớp vỏ ngoài vàng óng màu nghệ và giòn tan quyện sả tỏi phi thơm nức, trong khi thớ thịt cá lóc bên trong vẫn trắng ngọt, săn chắc.', 'Xếp các khúc cá ra đĩa, phủ đều phần sả tỏi phi vàng giòn lên trên cùng vài lát ớt sừng trang trí, ăn nóng với cơm trắng và chén nước mắm chanh ớt.', 'Nên dùng hết trong ngày để giữ độ giòn của lớp vỏ và sả phi; nếu bảo quản tủ mát tối đa 24 giờ, nên làm nóng lại bằng nồi chiên không dầu ở 180°C trong 4–5 phút.', 'vietnamese', 'mon_chien', 'nam', 'medium', 25, 20, 4, '/frigo/illustrations/delicious-meal.png', '["Món chiên","Cá lóc","Nam Bộ","Sả ớt","Đưa cơm"]', '["lunch","dinner"]', '["deep_fry","pan_fry"]', '["fish","wheat"]', 292, 291.6, 1220, 29.1, 10.6, 2, 19.6, 0.9, 3.1, 1297, 3.24, '["Panko / Batter Mix Ref","USDA FDC 168155","USDA FDC 168573","USDA FDC 169230","USDA FDC 169655","USDA FDC 170106","USDA FDC 170499","USDA FDC 170931","USDA FDC 171413","USDA FDC 172185","USDA FDC 172231","USDA FDC 173468","USDA FDC 173647","USDA FDC 175176","VN/Asian Seasoning Powder Avg"]', '04355739d8bb1e4fe581c7028028d40de1b1103497f0f349e5ac29e858e37183', '2dde0993324ae9b03754e24509761127888f47067fa853fb659d86e88c567f8a', 4);

