('imp-b87b71d57128cc07_v4_ing_2', 'imp-b87b71d57128cc07', 1, 'LEMONGRASS', 'Sả tươi', '5 cây (khoảng 100 g)', 'bỏ bẹ già, rửa sạch, băm thật nhuyễn (chia 1/2 ướp cá, 1/2 phi vàng giòn)', 'aromatics', 5, 'piece', 100, 0.75, 75, 0, 1),
('imp-b87b71d57128cc07_v4_ing_3', 'imp-b87b71d57128cc07', 2, 'CHILI', 'Ớt sừng và ớt hiểm', '3 quả (khoảng 15 g)', '2 quả băm nhỏ ướp cá và phi thơm, 1 quả thái lát pha nước chấm và trang trí', 'aromatics', 3, 'piece', 15, 0.9, 13.5, 0, 1),
('imp-b87b71d57128cc07_v4_ing_4', 'imp-b87b71d57128cc07', 3, 'GARLIC', 'Tỏi khô', '1 củ (25 g)', 'bóc vỏ, băm nhuyễn (chia 1/2 ướp cá, 1/2 phi vàng sau sả)', 'aromatics', 1, 'piece', 25, 0.87, 21.75, 0, 1),
('imp-b87b71d57128cc07_v4_ing_5', 'imp-b87b71d57128cc07', 4, 'SHALLOT', 'Hành tím', '20 g (~2 củ)', 'bóc vỏ, băm nhuyễn để ướp khử tanh cá', 'aromatics', 20, 'g', 20, 0.88, 17.6, 1, 1),
('imp-b87b71d57128cc07_v4_ing_6', 'imp-b87b71d57128cc07', 5, 'CRISPY_BATTER_MIX', 'Bột chiên giòn', '50 g (~3,5 muỗng canh)', 'hòa với 60 ml nước và chút muối tạo hỗn hợp bột sệt áo cá', 'main', 50, 'g', 50, 0.9, 45, 0, 1),
('imp-b87b71d57128cc07_v4_ing_7', 'imp-b87b71d57128cc07', 6, 'TURMERIC', 'Bột nghệ', '3 g (~1/2 muỗng cà phê)', 'tạo sắc vàng ươm bắt mắt và khử tanh cá', 'marinade', 3, 'g', 3, 1, 3, 0, 1),
('imp-b87b71d57128cc07_v4_ing_8', 'imp-b87b71d57128cc07', 7, 'SALT', 'Muối ăn', '8 g (~1,5 muỗng cà phê)', '4 g chà xát rửa sạch nhớt cá rồi xả bỏ, 2 g ướp cá và 2 g pha bột', 'marinade', 8, 'g', 8, 0.5, 4, 0, 1),
('imp-b87b71d57128cc07_v4_ing_9', 'imp-b87b71d57128cc07', 8, 'SUGAR', 'Đường cát trắng', '8 g (~2 muỗng cà phê)', 'chia 4 g ướp cá, 4 g pha nước chấm', 'marinade', 8, 'g', 8, 0.9, 7.2, 0, 1),
('imp-b87b71d57128cc07_v4_ing_10', 'imp-b87b71d57128cc07', 9, 'SEASONING_POWDER', 'Hạt nêm', '4 g (~1 muỗng cà phê)', 'ướp vào thịt cá', 'marinade', 4, 'g', 4, 1, 4, 0, 1),
('imp-b87b71d57128cc07_v4_ing_11', 'imp-b87b71d57128cc07', 10, 'BLACK_PEPPER', 'Tiêu đen xay', '2 g (~1/2 muỗng cà phê)', 'ướp khử tanh cá', 'marinade', 2, 'g', 2, 1, 2, 0, 1),
('imp-b87b71d57128cc07_v4_ing_12', 'imp-b87b71d57128cc07', 11, 'LIME', 'Chanh tươi', '1/2 quả', 'dùng một phần chà rửa cá cho sạch nhớt, vài giọt vắt vào nước mắm chấm', 'marinade', 0.5, 'piece', 22.5, 0.3, 6.75, 0, 1),
('imp-b87b71d57128cc07_v4_ing_13', 'imp-b87b71d57128cc07', 12, 'FISH_SAUCE', 'Nước mắm ngon (pha chấm)', '30 ml (~2 muỗng canh)', 'pha nước mắm ớt chanh ăn kèm cá chiên', 'sauce', 30, 'ml', 36, 0.85, 30.6, 0, 1),
('imp-b87b71d57128cc07_v4_ing_14', 'imp-b87b71d57128cc07', 13, 'COOKING_OIL', 'Dầu ăn (chiên cá và sả tỏi)', '250 ml', 'dùng để phi vàng giòn sả tỏi trước rồi chiên ngập mặt cá', 'main', 250, 'ml', 230, 0.12, 27.6, 0, 1),
('imp-b87b71d57128cc07_v4_ing_15', 'imp-b87b71d57128cc07', 14, 'COOKING_WATER', 'Nước lọc', '60 ml', 'hòa tan bột chiên giòn thành dạng sệt', 'main', 60, 'ml', 60, 0.9, 54, 0, 0);

INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('vn-canh-01_v4_step_1', 'vn-canh-01', 1, 'prep', 'Làm sạch nhớt và ướp cá lóc', 'Đánh sạch vảy, bỏ mang, moi ruột và cạo sạch màng đen trong bụng cá lóc. Chà xát mình cá với 3 g muối hạt trong 2 phút để hết nhớt, rửa lại nước lạnh rồi để ráo, cắt khúc dày 2,5 cm. Ướp cá với 10 ml nước mắm, 2 g muối và 2 g tiêu đen xay trong 10 phút cho thịt cá săn và đậm vị.', 'Không rửa cá bằng nước nóng vì sẽ làm nhớt đông lại khó làm sạch; muối hạt hoặc nước cốt chanh giúp khử tanh hiệu quả nhất.', 10),
('vn-canh-01_v4_step_2', 'vn-canh-01', 2, 'prep', 'Lọc nước cốt me và sơ chế rau củ', 'Ngâm 50 g cơm me chín vào 100 ml nước ấm trong 5 phút, dùng thìa dằm nát rồi lọc qua rây lấy phần nước cốt sánh, bỏ hạt và xơ. Đeo găng tay để tước bỏ lớp vỏ xơ xanh bên ngoài dọc mùng, thái lát xéo dày 0,5 cm, bóp nhẹ với 3 g muối rồi rửa sạch nhiều lần với nước và vắt nhẹ cho hết ngứa. Thái múi cau cà chua, cắt lát dứa, thái vát đậu bắp, nhặt giá đỗ và cắt khúc 2 cm hành lá, ngò gai, rau ngổ.', 'Bóp dọc mùng với muối rồi xả sạch và vắt ráo trước khi nấu sẽ giúp bạc hà giòn ngon mà không gây ngứa họng.', 5),
('vn-canh-01_v4_step_3', 'vn-canh-01', 3, 'cook', 'Phi thơm tỏi làm tỏi phi vàng giòn', 'Làm nóng nồi đáy dày trên lửa vừa với 25 ml dầu ăn, cho 2/3 lượng tỏi băm vào phi đều tay đến khi dậy mùi thơm và vừa chuyển màu vàng nhạt thì lập tức vớt phần tỏi phi ra chén giấy thấm dầu, giữ lại toàn bộ phần dầu thơm trong nồi.', 'Vớt tỏi phi ngay khi hơi ngả vàng nhạt vì lượng nhiệt dư sẽ tiếp tục làm tỏi vàng giòn hoàn hảo mà không bị đắng khét.', NULL),
('vn-canh-01_v4_step_4', 'vn-canh-01', 4, 'cook', 'Xào sơ nền cà chua và dứa tạo màu', 'Cho 1/3 phần tỏi băm còn lại cùng đầu hành lá vào nồi dầu nóng phi thơm 30 giây trên lửa vừa, tiếp tục thả một nửa lượng cà chua bổ múi cau và dứa vào xào nhanh 2 phút cho cà chua tiết màu đỏ cam tự nhiên, rồi đổ 1,4 lít nước lọc vào đun lửa lớn đến khi sôi bùng.', NULL, 2),
('vn-canh-01_v4_step_5', 'vn-canh-01', 5, 'cook', 'Nêm nước dùng chua ngọt và nấu chín cá', 'Khi nước sôi mạnh, hạ lửa vừa và từ từ rót nước cốt me đã lọc vào, nêm 25 ml nước mắm, 25 g đường cát trắng và 3 g muối sao cho đạt vị chua thanh ngọt dịu cân bằng. Thả nhẹ từng khúc cá lóc đã ướp vào nồi nước sôi, nấu sôi liu riu khoảng 6 phút đồng thời hớt sạch bọt nổi để nước canh thật trong. Khi mắt cá đục trắng và thịt cá chín chắc hoàn toàn, dùng vá lỗ nhẹ nhàng vớt cá ra tô riêng.', 'Hạ lửa vừa để nước chỉ sôi lăn tăn khi thả cá và vớt cá ra trước khi cho rau sẽ giữ được từng khúc cá nguyên vẹn, không bị nát vụn.', 6),
('vn-canh-01_v4_step_6', 'vn-canh-01', 6, 'finish', 'Chần chín rau củ và hoàn thiện tô canh', 'Thả đậu bắp và phần cà chua còn lại vào nồi canh nấu 2 phút trên lửa vừa, sau đó thêm dọc mùng nấu thêm 1 phút cho vừa chín tới vẫn giữ màu xanh mướt. Cuối cùng thả giá đỗ vào rồi tắt bếp ngay, xếp các khúc cá lên mặt tô canh, chan nước dùng nóng hổi cùng rau củ và rắc rau ngổ, ngò gai, hành lá, ớt sừng thái lát cùng tỏi phi vàng lên trên.', NULL, NULL),
('vn-canh-02_v4_step_1', 'vn-canh-02', 1, 'prep', 'Làm sạch cua đồng và khêu gạch cua', 'Ngâm 500 g cua đồng trong chậu nước sạch khoảng 15–20 phút cho nhả hết bùn đất, xóc rửa nhiều lần đến khi nước trong. Tách bỏ mai cua, lột bỏ phần yếm và chất bẩn ở miệng cua; dùng tăm nhọn khêu lấy toàn bộ phần gạch cua màu vàng cam trong mai ra chén riêng.', 'Tự sơ chế cua sống giúp nước canh ngọt đậm và sạch cát; nếu dùng cua xay sẵn, hãy chọn hàng tươi mới xay trong ngày.', 15),
('vn-canh-02_v4_step_2', 'vn-canh-02', 2, 'prep', 'Giã thịt cua và lọc lấy nước cốt cua', 'Cho phần thân cua đã làm sạch vào cối cùng 3 g muối ăn, giã thật nhuyễn mịn. Đổ 600 ml nước lọc vào bóp nhẹ cho thịt cua tan đều rồi gạn qua rây lưới mịn vào nồi nấu canh; tiếp tục đổ 600 ml nước lọc còn lại vào phần bã vỏ, bóp và lọc lần hai để thu trọn phần thịt cua, bỏ sạch xác vỏ.', 'Cho chút muối khi giã giúp đạm cua kết dính dẻo hơn, khi đun sẽ đóng thành tảng riêu dày và không bị bở vụn.', 8),
('vn-canh-02_v4_step_3', 'vn-canh-02', 3, 'prep', 'Sơ chế rau đay, mồng tơi, mướp hương và hành tím', 'Nhặt bỏ cọng già của 400 g rau đay và rau mồng tơi, giữ phần lá và đọt non, rửa sạch rồi thái khúc nhỏ khoảng 1 cm để canh có độ sánh mịn. Mướp hương gọt vỏ, rửa sạch, bổ đôi dọc thân và thái lát chéo dày 0,7 cm. Hành tím bóc vỏ, băm nhuyễn 15 g và chia làm hai phần bằng nhau.', NULL, NULL),
('vn-canh-02_v4_step_4', 'vn-canh-02', 4, 'cook', 'Đun nước cua cho đóng tảng riêu nổi mặt', 'Hòa một nửa lượng hành tím băm vào nồi nước lọc cua, đặt lên bếp đun ở lửa vừa và khuấy nhẹ một chiều trong 2 phút đầu để thịt cua không lắng bén đáy nồi. Khi nước bắt đầu nóng già và thịt cua tách lớp, ngừng khuấy hoàn toàn, hạ lửa nhỏ vừa để riêu cua từ từ kết thành mảng dày nổi lên mặt nồi mà không bị trào.', 'Tuyệt đối không khuấy khi nước cua gần sôi và không đun lửa lớn quá mức vì bọt cua dễ trào ra ngoài và làm vỡ tảng riêu.', 8),
('vn-canh-02_v4_step_5', 'vn-canh-02', 5, 'cook', 'Phi hành tím chưng gạch cua vàng thơm', 'Trong lúc đợi nồi canh sôi, bắc chảo nhỏ với 15 ml dầu ăn trên lửa vừa, cho nửa lượng hành tím băm còn lại vào phi thơm. Khi hành dậy mùi, trút chén gạch cua vào chưng nhanh tay khoảng 1–2 phút cho gạch chuyển màu vàng cam óng ả và chín thơm.', NULL, 2),
('vn-canh-02_v4_step_6', 'vn-canh-02', 6, 'cook', 'Thả mướp hương, rau đay và mồng tơi vào canh', 'Dùng vá gạt nhẹ tảng riêu cua sang một bên mép nồi. Thả mướp hương vào khoảng trống trước, đợi nước sôi lăn tăn lại rồi cho rau đay và mồng tơi vào theo mép nồi, ấn nhẹ cho rau ngập nước. Nêm 3 g muối còn lại, 6 g hạt nêm, 10 ml nước mắm ngon và 5 g mắm tôm (nếu dùng).', 'Thả rau vào mép nồi thay vì đổ thẳng lên giữa mặt nước sẽ giữ nguyên vẹn tảng riêu cua đẹp mắt.', 3),
('vn-canh-02_v4_step_7', 'vn-canh-02', 7, 'finish', 'Trút gạch cua chưng và hoàn thiện tô canh', 'Nấu thêm 2 phút ở lửa vừa đến khi rau mồng tơi, rau đay chín mềm xanh mướt và mướp hương vừa chuyển trong, thịt cua chín kỹ hoàn toàn. Rưới phần gạch cua đã chưng lên mặt nồi, khuấy nhẹ mép nồi rồi tắt bếp ngay để giữ trọn vị ngọt và sắc xanh của rau.', NULL, NULL),
('vn-canh-03_v4_step_1', 'vn-canh-03', 1, 'prep', 'Nạo sạch ruột và chần khổ qua giảm đắng', 'Rửa sạch 4 trái khổ qua, cắt bỏ hai đầu, dùng mũi dao rạch một đường dọc thân rồi dùng cán muỗng nạo sạch toàn bộ hạt và phần màng trắng gây đắng bên trong. Đun sôi một nồi nước nhỏ pha 4 g muối, chần nhanh khổ qua trong 30–45 giây rồi vớt ngay vào thau nước lạnh cho nguội hẳn, để ráo nước. Tận dụng nước nóng trụng mềm vài cọng lá hành lá để làm dây buộc.', 'Nạo thật sạch lớp màng trắng sát ruột và chần nhanh rồi ngâm nước lạnh giúp khổ qua hết đắng gắt mà vẫn giữ màu xanh tươi.', 5),
('vn-canh-03_v4_step_2', 'vn-canh-03', 2, 'prep', 'Ngâm mộc nhĩ và băm nhỏ rau thơm', 'Ngâm 20 g mộc nhĩ khô vào nước ấm khoảng 15 phút cho nở mềm hoàn toàn, rửa lại nhiều lần cho sạch sạn, cắt bỏ chân nấm cứng và băm nhỏ. Băm nhuyễn hành tím, tỏi và phần đầu trắng của hành lá; phần lá hành còn lại và ngò rí rửa sạch, thái nhỏ.', NULL, 15),
('vn-canh-03_v4_step_3', 'vn-canh-03', 3, 'marinate', 'Trộn và ướp nhân thịt heo xay mộc nhĩ', 'Cho 250 g thịt heo xay vào tô lớn cùng mộc nhĩ băm, hành tím, tỏi, đầu hành lá băm, 1 quả trứng gà đánh tan, 6 g hạt nêm, 3 g đường và 2 g tiêu đen xay. Trộn và quết đều theo một chiều khoảng 2 phút cho khối nhân dẻo quánh, ướp nghỉ 10 phút cho thấm vị.', 'Quết nhân kỹ theo một chiều kết hợp trứng gà giúp nhân thịt kết dính chặt, không bị rời rạc hay trào ra khi hầm.', 10),
('vn-canh-03_v4_step_4', 'vn-canh-03', 4, 'prep', 'Nhồi thịt vào khổ qua và buộc cố định', 'Múc từng thìa nhân thịt nhồi chặt tay vào lòng mỗi trái khổ qua, dùng ngón tay nén nhẹ hai đầu cho nhân đầy khít không còn khe rỗng. Dùng cọng hành lá đã trụng mềm quấn nhẹ một vòng ngang thân mỗi trái khổ qua và thắt nút cố định để giữ miệng khổ qua khép kín khi nấu.', NULL, NULL),
('vn-canh-03_v4_step_5', 'vn-canh-03', 5, 'cook', 'Hầm khổ qua trong nước sôi mở vung', 'Đun sôi 1,5 lít nước lọc trong nồi sâu lòng trên lửa lớn. Khi nước sôi bùng, nhẹ nhàng thả từng trái khổ qua nhồi thịt vào, hạ xuống lửa vừa và để mở nắp hoàn toàn, hầm trong 22–25 phút. Thường xuyên dùng vá hớt sạch bọt nổi để nước canh trong vắt.', 'Chỉ thả khổ qua khi nước đã sôi già và tuyệt đối không đậy nắp trong lúc hầm để vỏ khổ qua không bị ngả vàng xỉn màu.', 24),
('vn-canh-03_v4_step_6', 'vn-canh-03', 6, 'cook', 'Kiểm tra độ chín và nêm gia vị nước dùng', 'Dùng đầu đũa xiên thử phần thân khổ qua thấy mềm mượt và nhân thịt bên trong chín chắc hoàn toàn (không còn nước hồng tiết ra). Nêm 6 g hạt nêm còn lại, 4 g muối và 3 g đường vào nước canh, khuấy nhẹ cho tan đều rồi nếm lại vị thanh ngọt hài hòa và tắt bếp.', 'Không nên nêm nước mắm vào canh khổ qua vì dễ làm nước canh ngả vị chua nhẹ nếu để qua bữa.', NULL),
('vn-canh-03_v4_step_7', 'vn-canh-03', 7, 'finish', 'Cắt khoanh và hoàn thiện tô canh khổ qua', 'Nhẹ nhàng vớt các trái khổ qua ra đĩa, cắt khoanh tròn dày khoảng 2,5–3 cm vừa ăn rồi xếp ngay ngắn vào tô lớn. Chan ngập nước canh nóng hổi, rắc hành lá cắt nhỏ, ngò rí và 1 g tiêu đen xay lên trên mặt rồi thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('vn-canh-04_v4_step_1', 'vn-canh-04', 1, 'prep', 'Chần sạch sườn non khử mùi hôi', 'Rửa sạch 450 g sườn non đã chặt khúc 3–4 cm. Đun sôi một nồi nước riêng với 3 g muối ăn, thả sườn vào chần nhanh 2–3 phút trên lửa lớn để đẩy hết máu thừa và tạp chất. Vớt sườn ra rổ, xả sạch lại dưới vòi nước lạnh rồi để thật ráo.', 'Chần sơ sườn với chút muối và xả sạch lại giúp nước canh sau khi ninh trong veo, không bị đục hay có mùi hôi.', 3),
('vn-canh-04_v4_step_2', 'vn-canh-04', 2, 'marinate', 'Ướp sườn non và sơ chế bí đao', 'Ướp sườn đã ráo với 10 ml nước mắm ngon, 5 g hạt nêm và 1 g tiêu đen xay trong 10–15 phút. Trong lúc chờ, gọt bỏ vỏ xanh của 1 quả bí đao, bổ dọc bỏ hết phần ruột xốp và hạt, rửa sạch rồi cắt khúc dày khoảng 2 cm để khi nấu không bị nát. Băm nhỏ 20 g hành tím, đập dập 10 g gừng, thái nhỏ hành lá và ngò gai.', NULL, 12),
('vn-canh-04_v4_step_3', 'vn-canh-04', 3, 'cook', 'Phi thơm hành tím và xào săn sườn non', 'Làm nóng nồi đáy dày với 15 ml dầu ăn trên lửa vừa, cho đầu hành đập dập và hành tím băm vào phi thơm 30 giây. Trút sườn non đã ướp vào đảo đều khoảng 3–4 phút cho miếng sườn săn chắc các mặt và dậy mùi thơm.', NULL, 4),
('vn-canh-04_v4_step_4', 'vn-canh-04', 4, 'cook', 'Hầm sườn non lấy nước dùng ngọt trong', 'Đổ 1,5 lít nước lọc vào nồi sườn, bật lửa lớn đun sôi bùng rồi hớt sạch lớp bọt nổi trên mặt. Thả lát gừng đập dập vào nồi, hạ xuống lửa nhỏ liu riu và hầm khoảng 25 phút cho đến khi thịt sườn chín mềm, dễ dàng xiên đũa qua.', 'Hầm sườn ở lửa nhỏ liu riu và mở hé nắp giúp chất ngọt tiết ra từ từ mà nước dùng vẫn giữ được độ trong suốt.', 25),
('vn-canh-04_v4_step_5', 'vn-canh-04', 5, 'cook', 'Nấu bí đao chín tới giữ độ ngọt mát', 'Khi sườn đã mềm, thả toàn bộ bí đao cắt miếng vào nồi, tăng nhẹ lên lửa vừa để nước sôi trở lại rồi nấu khoảng 5–6 phút cho đến khi thịt bí chuyển màu trắng trong mờ, xiên nhẹ thấy mềm nhưng vẫn giữ nguyên góc cạnh.', 'Bí đao chín rất nhanh, không nên nấu quá 7 phút kẻo bí nhũn nát và mất đi hương vị thanh mát.', 6),
('vn-canh-04_v4_step_6', 'vn-canh-04', 6, 'finish', 'Nêm gia vị và rắc rau thơm hoàn thiện', 'Nêm thêm 15 ml nước mắm ngon, 5 g hạt nêm và 3 g muối còn lại, khuấy nhẹ tránh làm nát bí rồi nếm lại vừa miệng. Tắt bếp, thả hành lá và ngò gai thái nhỏ cùng 1 g tiêu đen xay lên mặt nồi rồi múc ra tô dùng nóng.', NULL, NULL),
('vn-canh-05_v4_step_1', 'vn-canh-05', 1, 'prep', 'Sơ chế hạt sen và cắt miếng bí đỏ', 'Rửa sạch 100 g hạt sen tươi, tách nhẹ đầu hạt để rút bỏ hoàn toàn phần tâm sen xanh nếu còn sót vì tâm sen gây vị đắng. Bí đỏ gọt vỏ, bỏ sạch phần ruột xơ và hạt, rửa qua nước lạnh rồi cắt miếng vuông cỡ 2,5 cm để bí chín nhanh mà không dễ vỡ vụn.', 'Nếu dùng hạt sen khô thay cho sen tươi, hãy ngâm nước ấm trước 30 phút rồi ninh hạt sen trước 10 phút cho bở đều cùng bí đỏ.', NULL),
('vn-canh-05_v4_step_2', 'vn-canh-05', 2, 'marinate', 'Ướp thịt heo nạc xay cho đậm đà', 'Cho 200 g thịt heo nạc xay vào tô, ướp với một nửa chỗ hành tím băm, 7 ml nước mắm ngon, 4 g hạt nêm và 1 g tiêu đen xay. Trộn đều rồi ướp 10 phút cho thịt ngấm gia vị; trong lúc chờ, thái nhỏ hành lá và ngò gai, băm nhỏ tỏi và phần hành tím còn lại.', NULL, 10),
('vn-canh-05_v4_step_3', 'vn-canh-05', 3, 'cook', 'Phi thơm hành tỏi và xào săn thịt băm', 'Đặt nồi lên bếp với 15 ml dầu ăn ở lửa vừa, cho tỏi băm và phần hành tím băm còn lại vào phi thơm vàng nhẹ. Trút thịt heo xay đã ướp vào đảo nhanh tay cho thịt tơi rời và săn lại hoàn toàn, thêm 8 g đường và 8 ml nước mắm còn lại, xào thêm 1 phút cho dậy mùi.', 'Dùng đũa đảo tơi liên tục khi thịt mới vào nồi nóng giúp thịt băm không bị vón cục lớn.', 3),
('vn-canh-05_v4_step_4', 'vn-canh-05', 4, 'cook', 'Xào sơ bí đỏ thấm gia vị trước khi đổ nước', 'Cho toàn bộ bí đỏ cắt miếng vào nồi thịt, nêm 5 g muối ăn rồi đảo đều trên lửa vừa khoảng 2 phút cho miếng bí săn bề mặt và áo đều hương thơm của thịt xào.', NULL, 2),
('vn-canh-05_v4_step_5', 'vn-canh-05', 5, 'cook', 'Ninh bí đỏ và hạt sen chín bở mềm', 'Đổ 1,2 lít nước lọc vào nồi, đun lửa lớn đến khi nước sôi bùng thì hớt sạch bọt nổi. Thả 100 g hạt sen tươi vào, hạ xuống lửa vừa đậy hé vung và nấu khoảng 15 phút cho đến khi hạt sen chín bở và dùng đũa xiên qua miếng bí đỏ dễ dàng.', 'Hớt bọt kỹ ngay khi nước vừa sôi và không khuấy mạnh khi bí đã mềm sẽ giúp nước canh trong và vàng đẹp.', 15),
('vn-canh-05_v4_step_6', 'vn-canh-05', 6, 'finish', 'Tạo độ sánh nhẹ và hoàn thiện tô canh', 'Nêm 6 g hạt nêm còn lại vào nồi, nếm thử lại cho vừa vị ngọt thanh tự nhiên rồi dùng lưng muôi dầm nhẹ 2–3 miếng bí đỏ chín cho nước canh hơi sánh vàng. Tắt bếp, rắc hành lá, ngò gai thái nhỏ cùng 1 g tiêu đen xay rồi múc ra tô thưởng thức nóng.', NULL, NULL),
('vn-canh-06_v4_step_1', 'vn-canh-06', 1, 'prep', 'Ngâm sạch cát và sơ chế rau thơm', 'Ngâm 1 kg ngao tươi trong thau nước pha 3 g muối ăn và vài lát ớt tươi khoảng 30 phút để ngao nhả hết bùn cát, sau đó chà rửa sạch lớp vỏ ngoài và xả kỹ qua 2–3 lần nước. Trong lúc ngâm ngao, bổ múi cau 2,5 quả cà chua, gọt vỏ bỏ mắt thái lát 0,5 quả dứa, băm nhỏ 20 g hành tím, cắt khúc 2 cm thì là và hành lá, phần ớt còn lại thái lát.', 'Ngâm ngao với nước muối loãng thêm vài lát ớt cay là cách đơn giản nhất giúp ngao mở vỏ nhả sạch cát mà không bị chết.', 30),
('vn-canh-06_v4_step_2', 'vn-canh-06', 2, 'cook', 'Luộc ngao mở miệng và gạn lấy nước dùng trong', 'Cho ngao sạch vào nồi cùng 1,4 lít nước lọc, đun ở lửa lớn đến khi nước sôi và toàn bộ vỏ ngao vừa há mở miệng hoàn toàn thì tắt bếp ngay để thịt ngao không bị teo dai. Vớt ngao ra rổ, loại bỏ những con không há miệng, tách bỏ vỏ lấy phần thịt ngao rồi rửa nhanh qua nước lọc cho sạch hẳn cát; phần nước luộc ngao đổ ra tô lớn để yên 5 phút cho lắng hết cặn dưới đáy.', 'Không luộc ngao quá lâu sau khi vỏ đã mở miệng kẻo thịt ngao bị quắt nhỏ và dai mất độ ngọt.', 7),
('vn-canh-06_v4_step_3', 'vn-canh-06', 3, 'marinate', 'Ướp thịt ngao và xào cùng cà chua tạo màu', 'Ướp phần thịt ngao với 1/3 chỗ hành tím băm và 7 ml nước mắm cốt khoảng 5 phút. Làm nóng nồi khô với 15 ml dầu ăn trên lửa vừa, phi thơm phần hành tím băm còn lại rồi cho thịt ngao vào đảo nhanh tay 1 phút, trút ra đĩa riêng. Dùng tiếp nồi đó xào cà chua bổ múi cau với 1 g muối còn lại khoảng 2 phút cho cà chua mềm tơi và tiết màu đỏ cam.', NULL, 5),
('vn-canh-06_v4_step_4', 'vn-canh-06', 4, 'cook', 'Chắt nước luộc ngao và nấu chín dứa chua ngọt', 'Từ từ rót phần nước luộc ngao đã lắng vào nồi cà chua xào, khéo léo chừa lại phần cặn cát đọng dưới đáy tô. Bật lửa lớn đun sôi, sau đó thả các lát dứa vào nấu trên lửa vừa khoảng 5 phút cho dứa chín mềm và tiết vị chua ngọt thanh dịu hòa quyện cùng nước ngao.', 'Chắt nước luộc ngao thật nhẹ tay để giữ phần nước trong vắt và loại bỏ hoàn toàn cặn sạn dưới đáy tô.', 5),
('vn-canh-06_v4_step_5', 'vn-canh-06', 5, 'cook', 'Nêm gia vị và trút thịt ngao vào nồi canh', 'Nêm vào nồi 6 g hạt nêm, 5 g đường cát trắng và 8 ml nước mắm cốt còn lại, khuấy nhẹ và nếm thử lại cho đạt vị chua thanh, ngọt hậu, mặn vừa. Trút đĩa thịt ngao đã xào vào nồi, đun sôi lăn tăn lại 1 phút cho thịt ngao ngấm đều nước canh.', NULL, NULL),
('vn-canh-06_v4_step_6', 'vn-canh-06', 6, 'finish', 'Thả thì là, hành lá và hoàn thiện món canh', 'Tắt bếp ngay rồi cho toàn bộ thì là tươi, hành lá cắt khúc và ớt thái lát vào đảo nhẹ một lượt để rau vừa chín tới bằng hơi nóng, giữ được màu xanh tươi và hương thơm nồng đặc trưng của thì là. Múc canh ra tô lớn dùng nóng với cơm trắng.', NULL, NULL),
('vn-kho-01_v4_step_1', 'vn-kho-01', 1, 'prep', 'Làm sạch, chần sơ và cắt khối thịt ba chỉ', 'Cạo sạch phần bì của 500 g thịt ba chỉ, chà xát đều với 5 g muối hạt rồi rửa sạch dưới vòi nước lạnh. Đun sôi nồi nước, thả thịt vào chần sơ 3 phút để loại bỏ tạp chất và mùi hôi, vớt ra rửa lại nước mát, để ráo và cắt thành các miếng vuông đều nhau cỡ 4x4 cm.', 'Chọn miếng ba chỉ dưới có lớp nạc mỡ đan xen đều và phần da mỏng để khi kho xong thịt mềm béo mà không bị bở nát.', 5),
('vn-kho-01_v4_step_2', 'vn-kho-01', 2, 'prep', 'Luộc chín và bóc vỏ trứng gà', 'Cho 5 quả trứng gà vào nồi nước ngập mặt, đun lửa vừa từ lúc nước nguội đến khi sôi thì hạ lửa nhỏ luộc thêm 8 phút cho lòng đỏ vừa chín tới. Vớt trứng ngâm ngay vào tô nước lạnh 5 phút rồi bóc sạch vỏ.', 'Dùng tăm nhọn xăm nhẹ vài lỗ nhỏ quanh lòng trắng sau khi bóc vỏ sẽ giúp trứng dễ thấm nước kho hơn.', 8),
('vn-kho-01_v4_step_3', 'vn-kho-01', 3, 'marinate', 'Ướp thịt ba chỉ thấm gia vị', 'Trộn thịt ba chỉ trong tô lớn với một nửa lượng hành tím và tỏi băm nhuyễn, 15 ml nước mắm ngon, 15 g đường cát trắng, 5 g hạt nêm và 1 g tiêu đen xay. Xoa đều gia vị lên từng mặt thịt, bọc kín và ướp ít nhất 30 phút cho ngấm sâu.', NULL, 30),
('vn-kho-01_v4_step_4', 'vn-kho-01', 4, 'sauce', 'Thắng nước màu cánh gián', 'Làm nóng nồi đáy dày trên lửa nhỏ với 5 ml dầu ăn và 15 g đường cát trắng còn lại. Đun nhẹ cho đường tan chảy và nổi bọt chuyển màu nâu cánh gián thì lập tức đổ từ từ 100 ml nước lọc ấm vào khuấy tan đều để hãm nhiệt, tránh cháy đắng.', 'Không khuấy đường khi mới bắc lên bếp ở giai đoạn đầu; chỉ lắc nhẹ nồi để đường tan đều và lên màu hổ phách trong đẹp.', 5),
('vn-kho-01_v4_step_5', 'vn-kho-01', 5, 'cook', 'Xào săn thịt và đổ nước dừa xiêm', 'Cho 10 ml dầu ăn vào nồi, phi thơm phần hành tím và tỏi băm còn lại trên lửa vừa trong 1 phút. Trút toàn bộ thịt ba chỉ đã ướp vào đảo săn các mặt khoảng 5 phút rồi rưới nước màu cánh gián vào đảo đều cho thịt áo màu đẹp. Đổ 400 ml nước dừa tươi cùng 20 ml nước mắm còn lại vào ngập mặt thịt, đun lửa lớn cho sôi bùng và hớt sạch bọt nổi.', NULL, 6),
('vn-kho-01_v4_step_6', 'vn-kho-01', 6, 'cook', 'Kho liu riu không đậy nắp cho thịt mềm rệu', 'Hạ lửa nhỏ nhất, không đậy nắp và kho liu riu trong 40 phút cho thịt chín mềm từ từ và phần mỡ trở nên trong veo. Nếu nước cạn nhanh mà thịt chưa đủ mềm, châm thêm 200 ml nước lọc nóng sao cho vừa xâm xấp mặt thịt.', 'Kho mở nắp giúp hơi nước thoát đều, nước kho trong và thịt lên màu đỏ nâu tự nhiên không bị đục.', 40),
('vn-kho-01_v4_step_7', 'vn-kho-01', 7, 'finish', 'Kho cùng trứng gà và hoàn thiện món', 'Thả nhẹ 5 quả trứng gà đã bóc vỏ và 1 quả ớt sừng đỏ nguyên trái vào nồi, kho thêm 15 phút trên lửa nhỏ cho trứng ngấm vị và nước kho sánh nhẹ, không khuấy mạnh tránh làm vỡ trứng. Tắt bếp, múc thịt và trứng ra đĩa sâu lòng, rắc 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng.', NULL, 15),
('vn-kho-02_v4_step_1', 'vn-kho-02', 1, 'prep', 'Làm sạch nhớt và ướp khứa cá lóc', 'Chà xát đều 5 g muối hạt lên các khứa cá lóc để khử sạch nhớt và mùi tanh, rửa lại nước lạnh rồi thấm thật khô. Ướp cá với 35 ml nước mắm, 8 g đường cát trắng, 4 g hạt nêm, 2 g tiêu đen xay, phần đầu hành lá băm cùng một nửa tỏi và hành tím băm trong 25 phút cho thịt cá săn chắc.', 'Ướp cá đủ thời gian với nước mắm ngon giúp thịt cá săn cứng tự nhiên, khi kho không bị bở nát.', 25),
('vn-kho-02_v4_step_2', 'vn-kho-02', 2, 'cook', 'Thắng tóp mỡ giòn và phi thơm gia vị', 'Bắc tộ đất hoặc chảo lên bếp, cho 120 g thịt ba chỉ thái mỏng vào đảo trên lửa vừa khoảng 6 phút cho đến khi thịt tiết mỡ và chuyển vàng giòn thành tóp mỡ. Vớt phần tóp mỡ ra chén riêng, giữ lại phần mỡ heo nóng trong nồi cùng 5 ml dầu ăn để phi thơm phần hành tím và tỏi băm còn lại.', NULL, 6),
('vn-kho-02_v4_step_3', 'vn-kho-02', 3, 'sauce', 'Áp chảo sơ cá và thắng nước màu', 'Cho 5 ml dầu ăn còn lại vào chảo khác, chiên áp chảo nhẹ từng khứa cá đã ướp khoảng 1 phút mỗi mặt cho săn se bề mặt rồi gắp riêng. Dùng chảo đó cho 12 g đường vào đun lửa nhỏ đến khi chuyển màu nâu cánh gián đậm, thêm 20 ml nước ấm khuấy đều để làm nước màu.', NULL, NULL),
('vn-kho-02_v4_step_4', 'vn-kho-02', 4, 'cook', 'Xếp cá vào tộ và kho thấm lửa nhỏ', 'Xếp các khứa cá vào tộ đất có sẵn hành tỏi phi và mỡ heo, rưới toàn bộ phần nước ướp cá, nước màu vừa thắng cùng 100 ml nước ấm vào xâm xấp mặt cá. Đun lửa lớn cho sôi bùng 1 phút rồi hạ lửa nhỏ liu riu, thả 2 quả ớt hiểm vào kho mở hé vung trong 20 phút.', 'Không dùng đũa đảo cá trong tộ; chỉ cầm quai tộ lắc nhẹ hoặc dùng muỗng múc nước kho rưới lên mặt cá để khứa cá nguyên vẹn.', 20),
('vn-kho-02_v4_step_5', 'vn-kho-02', 5, 'cook', 'Sánh kẹo nước kho trên lửa vừa', 'Mở hẳn nắp tộ, tăng lên lửa vừa kho thêm 5 phút cho nước kho rút cạn bớt và sánh sệt óng ả bám đều quanh khứa cá. Nếm thử nước kho xem độ mặn ngọt đã hài hòa chưa.', NULL, 5),
('vn-kho-02_v4_step_6', 'vn-kho-02', 6, 'finish', 'Rắc tóp mỡ, tiêu đen và hành lá', 'Khi nước sốt vừa sệt kẹo và khứa cá chín chắc hoàn toàn, rắc phần tóp mỡ vàng giòn, 1 g tiêu đen xay còn lại và phần lá hành cắt khúc lên mặt tộ cá rồi tắt bếp. Dọn nóng ngay khi còn sôi lăn tăn trong tộ đất.', 'Cho tóp mỡ vào sau cùng ngay trước khi tắt bếp để tóp mỡ giữ được độ giòn rụm hòa quyện với nước sốt béo thơm.', NULL),
('vn-kho-03_v4_step_1', 'vn-kho-03', 1, 'prep', 'Khử mùi, chặt miếng gà và sơ chế gừng sả', 'Chà xát 600 g đùi gà với 5 g muối hạt và vài lát gừng đập dập để khử mùi hôi, rửa sạch lại với nước rồi để ráo, chặt thành từng miếng vừa ăn cỡ 3–4 cm. Gừng tươi thái sợi nhỏ; sả tươi, hành tím và tỏi băm nhuyễn; ớt hiểm thái lát mỏng.', 'Không chặt miếng gà quá nhỏ vì thịt gà sẽ co lại khi kho, dễ bị khô và nát xương.', NULL),
('vn-kho-03_v4_step_2', 'vn-kho-03', 2, 'marinate', 'Ướp thịt gà với nước mắm và sả gừng', 'Cho gà vào tô lớn, ướp cùng một nửa lượng gừng thái sợi, một nửa lượng sả băm, một nửa tỏi băm, 15 ml nước mắm, 5 g đường cát trắng, 5 g hạt nêm, 3 g muối và 1 g tiêu đen xay. Trộn đều và để 25 phút cho gia vị thấm vào từng thớ thịt.', NULL, 25),
('vn-kho-03_v4_step_3', 'vn-kho-03', 3, 'sauce', 'Thắng nước màu và phi thơm sả gừng', 'Làm nóng chảo sâu lòng trên lửa vừa với 25 ml dầu ăn và 15 g đường cát trắng còn lại, khuấy nhẹ đến khi đường tan và chuyển màu nâu cánh gián. Hạ lửa nhỏ rồi trút nhanh phần hành tím, tỏi, sả băm và gừng sợi còn lại vào đảo thơm 30 giây.', 'Cho sả và gừng vào ngay khi đường vừa chuyển màu cánh gián để hãm nhiệt, vừa tạo mùi thơm nức vừa giúp nước màu không bị cháy khét.', NULL),
('vn-kho-03_v4_step_4', 'vn-kho-03', 4, 'cook', 'Xào săn thịt gà trên lửa lớn', 'Vặn lửa lớn, cho toàn bộ thịt gà đã ướp vào chảo đảo liên tục trong 5 phút đến khi da gà săn lại, bề mặt miếng thịt đổi màu vàng nâu đẹp mắt và thấm đều dầu thơm.', NULL, 5),
('vn-kho-03_v4_step_5', 'vn-kho-03', 5, 'cook', 'Kho nhỏ lửa cho gà chín mềm sánh sốt', 'Rót 120 ml nước lọc ấm vào chảo cho xâm xấp mặt thịt gà, thêm 15 ml nước mắm còn lại và ớt thái lát. Đợi nước sôi lại thì hạ lửa nhỏ, đậy nắp kho liu riu 18 phút, thỉnh thoảng đảo nhẹ để thịt gà chín thấu vào tận xương không còn đỏ hồng.', NULL, 18),
('vn-kho-03_v4_step_6', 'vn-kho-03', 6, 'finish', 'Cô cạn nhẹ nước sốt và trình bày', 'Mở nắp, tăng lên lửa vừa đảo thêm 2–3 phút đến khi nước kho cạn sệt và bám bóng quanh từng miếng thịt gà. Nêm nếm lại vừa miệng, tắt bếp rồi rắc 1 g tiêu đen xay còn lại lên trên và dọn ăn nóng.', 'Giữ lại một ít nước kho sánh sệt dưới đáy chảo để chan cơm hoặc chấm rau luộc sẽ rất đậm vị.', NULL),
('vn-kho-04_v4_step_1', 'vn-kho-04', 1, 'prep', 'Chần sơ sườn non và sơ chế rau củ', 'Chặt 550 g sườn non thành miếng dài 3–4 cm. Đun sôi nồi nước với 4 g muối ăn, thả sườn vào chần nhanh 3 phút để sạch bọt bẩn rồi vớt ra rửa lại nước mát, thấm thật khô ráo. Cà chua bỏ cuống thái hạt lựu, hành tây thái múi cau mỏng, tỏi và hành tím băm nhuyễn, hành lá thái nhỏ.', 'Không luộc sườn quá lâu ở bước chần để tránh làm thịt mất chất ngọt và bị khô xác khi chiên.', 3),
('vn-kho-04_v4_step_2', 'vn-kho-04', 2, 'marinate', 'Ướp sườn non và pha chén sốt chua ngọt', 'Ướp sườn với 15 ml nước mắm, 10 g đường cát trắng, 3 g hạt nêm, 2 g muối, 1 g tiêu đen xay và một nửa hành tím băm trong 20 phút. Trong chén riêng, khuấy tan 15 ml nước mắm còn lại, 30 ml giấm gạo, 20 ml tương cà, 25 g đường, 3 g hạt nêm và 100 ml nước lọc.', NULL, 20),
('vn-kho-04_v4_step_3', 'vn-kho-04', 3, 'cook', 'Chiên sườn vàng xém hai mặt', 'Làm nóng chảo với 35 ml dầu ăn trên lửa vừa, gạt bớt hành băm bám trên miếng sườn rồi xếp từng dẻ sườn vào chiên khoảng 8 phút đến khi bề mặt sườn vàng ruộm và xém cạnh đều hai mặt. Gắp sườn ra đĩa có lót giấy thấm dầu, chắt bớt dầu thừa trong chảo.', 'Thấm thật khô sườn trước khi chiên và giữ lửa vừa giúp sườn không bị bắn dầu và không cháy xém phần đường ướp.', 8),
('vn-kho-04_v4_step_4', 'vn-kho-04', 4, 'cook', 'Xào nhuyễn sốt cà chua và đun sôi gia vị', 'Dùng lại chảo với 10 ml dầu ăn còn lại, phi thơm phần hành tím và tỏi băm trên lửa vừa trong 1 phút. Cho cà chua thái hạt lựu vào đảo đều 4 phút đến khi cà chua chín nhuyễn ra sốt đỏ đẹp, rồi đổ chén nước sốt chua ngọt đã pha vào đun sôi lăn tăn.', NULL, 5),
('vn-kho-04_v4_step_5', 'vn-kho-04', 5, 'cook', 'Rim sườn thấm đẫm sốt chua ngọt', 'Trút toàn bộ sườn đã chiên vàng vào chảo sốt, đảo đều rồi hạ lửa nhỏ, đậy nắp rim trong 10 phút cho thịt sườn mềm róc xương và thấm sâu vị chua ngọt. Mở nắp, thả hành tây vào đảo thêm 2 phút trên lửa vừa đến khi sốt sánh bóng áo đều quanh từng miếng sườn.', 'Cho hành tây vào giai đoạn cuối để hành vừa chín tới, giữ được độ giòn ngọt mà không bị nhũn nát.', 12),
('vn-kho-04_v4_step_6', 'vn-kho-04', 6, 'finish', 'Nêm lại sốt và trình bày ra đĩa', 'Nếm thử phần sốt xem độ chua ngọt đã cân bằng vừa ý chưa rồi tắt bếp. Xếp sườn ra đĩa, rưới phần sốt sánh còn lại lên trên, rắc hành lá thái nhỏ và 1 g tiêu đen xay còn lại để dậy mùi thơm rồi dùng nóng.', NULL, NULL),
('vn-kho-05_v4_step_1', 'vn-kho-05', 1, 'prep', 'Làm sạch tôm và khử mùi nước muối loãng', 'Cắt bỏ râu, chân và phần ngạnh đầu nhọn của 450 g tôm tươi, khều sạch chỉ đen trên lưng. Rửa nhanh tôm qua nước pha 5 g muối rồi xả lại nước sạch, trút ra rổ để thật ráo nước trước khi chế biến.', 'Để tôm thật ráo nước và giữ nguyên vỏ khi rim sẽ giúp vỏ tôm giòn ngon, thịt bên trong ngọt chắc không bị ra nước.', NULL),
('vn-kho-05_v4_step_2', 'vn-kho-05', 2, 'prep', 'Sơ chế hành tím, tỏi, hành lá và ớt', 'Bóc vỏ hành tím và tỏi khô rồi băm thật nhỏ, chia làm 2 phần bằng nhau để phi thơm và cho vào lúc rim. Hành lá rửa sạch thái nhỏ; ớt tươi bỏ cuống rồi thái lát mỏng để ráo.', NULL, NULL),
('vn-kho-05_v4_step_3', 'vn-kho-05', 3, 'cook', 'Phi thơm hành tỏi và rang săn tôm trên lửa lớn', 'Làm nóng chảo rộng với 20 ml dầu ăn trên lửa vừa, phi thơm 1/2 lượng hành tím và tỏi băm trong 1 phút. Tăng lên lửa lớn rồi trút tôm vào đảo nhanh tay trong 3–4 phút cho đến khi vỏ tôm chuyển màu đỏ cam rực, thịt tôm cong săn khoảng 70% và hơi sém thơm.', NULL, 4),
('vn-kho-05_v4_step_4', 'vn-kho-05', 4, 'sauce', 'Nêm nước mắm đường và hành tỏi còn lại', 'Hạ nhỏ bếp hoặc nhấc tạm chảo ra khỏi lửa để tránh đường cháy khét. Rưới 35 ml nước mắm ngon, 22 g đường cát trắng, 40 ml nước lọc và 1/2 phần hành tím tỏi băm còn lại vào chảo, xóc đều tay cho gia vị hòa quyện bám quanh thân tôm.', 'Nhấc chảo khỏi bếp trong vài giây khi cho đường và nước mắm sẽ giúp đường tan từ từ mà không bị cháy đen đắng.', NULL),
('vn-kho-05_v4_step_5', 'vn-kho-05', 5, 'cook', 'Rim mở nắp cho tôm chín kỹ và keo sốt', 'Đặt chảo lại lên bếp ở lửa vừa nhỏ, tuyệt đối không đậy nắp, rim trong 5 phút và đảo nhẹ thường xuyên đến khi tôm chín hồng hoàn toàn, phần nước mắm đường cô đặc sánh bóng áo đẹp quanh vỏ tôm.', 'Không đậy vung khi rim tôm để hơi nước bay đi nhanh, nước sốt sánh kẹo và không gây mùi nồng của vỏ tôm.', 5),
('vn-kho-05_v4_step_6', 'vn-kho-05', 6, 'finish', 'Trộn hành lá, ớt tiêu và dọn dùng nóng', 'Khi nước sốt đã keo bóng, cho hành lá cắt nhỏ, ớt thái lát và 1,5 g tiêu đen xay vào đảo nhanh 15 giây rồi tắt bếp ngay. Gắp tôm ra đĩa, rưới phần sốt keo lên trên và ăn nóng cùng cơm trắng.', NULL, NULL),
('vn-kho-06_v4_step_1', 'vn-kho-06', 1, 'prep', 'Sơ chế thịt ba chỉ và khử hăng củ cải trắng', 'Cạo sạch bì 500 g thịt ba chỉ, xát với 3 g muối hạt rồi rửa sạch, thấm khô và thái miếng vuông dày 2,5–3 cm. Củ cải trắng gọt vỏ, cắt khúc hình con chì to khoảng 3 cm, xóc nhẹ với 2 g muối hạt trong 5 phút rồi rửa lại bằng nước sạch để giảm mùi hăng.', 'Cắt củ cải miếng hơi dày vì trong quá trình kho củ cải sẽ ngót bớt nước và dễ bị nát nếu thái quá mỏng.', 5),
('vn-kho-06_v4_step_2', 'vn-kho-06', 2, 'marinate', 'Ướp thịt ba chỉ thấm gia vị', 'Cho thịt ba chỉ vào tô lớn, ướp với một nửa hành tím băm, 20 ml nước mắm ngon, 8 g hạt nêm, 5 g đường cát trắng, 3 g muối, 1 g tiêu đen xay và đầu hành lá đập dập. Trộn đều và ướp trong 30 phút cho thịt ngấm gia vị.', NULL, 30),
('vn-kho-06_v4_step_3', 'vn-kho-06', 3, 'sauce', 'Thắng nước màu và xào săn thịt', 'Làm nóng nồi đáy dày với 20 ml dầu ăn và 12 g đường cát trắng còn lại trên lửa nhỏ đến khi đường tan chảy chuyển màu nâu cánh gián. Nhanh tay rót 50 ml nước lọc nóng vào khuấy tan rồi cho phần hành tím băm còn lại vào phi thơm. Trút thịt ba chỉ đã ướp vào đảo săn trên lửa vừa trong 5 phút.', NULL, 5),
('vn-kho-06_v4_step_4', 'vn-kho-06', 4, 'cook', 'Kho thịt lửa một cho mềm thớ thịt', 'Chế 300 ml nước lọc nóng vào xâm xấp mặt thịt, đun sôi rồi hớt sạch bọt để nước kho thật trong. Hạ lửa nhỏ, đậy hé nắp kho liu riu 20 phút cho thịt bắt đầu mềm và tiết ra vị ngọt béo.', 'Luôn dùng nước nóng để chế vào nồi thịt đang xào giúp thịt không bị co cứng và giữ được độ trong của nước kho.', 20),
('vn-kho-06_v4_step_5', 'vn-kho-06', 5, 'cook', 'Cho củ cải trắng vào kho lửa hai', 'Thả củ cải trắng vào nồi thịt, tắt bếp để nghỉ 10 phút cho thịt và củ cải hồi nhiệt ngấm màu rồi bật bếp lại kho thêm 15 phút trên lửa nhỏ. Khi củ cải chuyển trong mềm, nêm tiếp 15 ml nước mắm và 3 g đường cát trắng còn lại, đun thêm 2 phút cho nước kho sánh hổ phách.', 'Kỹ thuật kho hai lửa giúp miếng thịt lên màu nâu bóng tự nhiên, củ cải thấm đều vị ngọt béo từ thịt mà không bị nát vụn.', 15),
('vn-kho-06_v4_step_6', 'vn-kho-06', 6, 'finish', 'Rắc hành lá, tiêu xay và hoàn thiện món ăn', 'Nêm nếm lại độ mặn ngọt vừa miệng, cho hành lá cắt khúc, ớt tươi thái lát và 1 g tiêu đen xay còn lại vào nồi, đảo nhẹ rồi tắt bếp. Múc thịt kho củ cải ra đĩa sâu lòng và dùng nóng với cơm trắng.', NULL, NULL),
('vn-xao-01_v4_step_1', 'vn-xao-01', 1, 'prep', 'Nhặt rửa rau muống và chuẩn bị tỏi ớt', 'Nhặt bỏ lá úa, lá già và phần gốc xơ cứng của rau muống, ngắt thành từng đoạn dài 6–8 cm. Rửa sạch nhiều lần rồi ngâm nước muối loãng 5 phút, vớt ra rổ để thật ráo nước. Bóc vỏ tỏi ta, đập dập rồi băm nhỏ, chia thành hai phần (2/3 để phi thơm đầu và 1/3 để cho vào cuối). Ớt sừng đỏ rửa sạch, thái lát xéo mỏng.', 'Chọn mớ rau muống ngọn nhỏ, thân non mềm thì khi xào sẽ giòn ngọt và ít bị dai xơ.', NULL),
('vn-xao-01_v4_step_2', 'vn-xao-01', 2, 'prep', 'Chần rau muống và sốc nhiệt nước đá', 'Đun sôi một nồi nước lớn (đủ ngập rau) trên lửa lớn, thả 6 g muối ăn và 5 ml giấm gạo vào khuấy tan. Khi nước sôi bùng, thả rau muống vào đảo nhanh trong 30–45 giây cho rau vừa chuyển màu xanh ngọc tươi rồi vớt ra ngay, thả vào thau nước đá lạnh ngâm 2 phút cho nguội hẳn trước khi vớt ra vắt nhẹ để thật ráo.', 'Không đậy vung khi chần và sốc nhiệt ngay bằng nước đá là bí quyết giúp rau muống giữ màu xanh lục bảo và độ giòn sần sật.', 3),
('vn-xao-01_v4_step_3', 'vn-xao-01', 3, 'cook', 'Phi thơm phần tỏi băm ban đầu', 'Đặt chảo sâu lòng lên bếp ở lửa vừa, làm nóng 30 ml dầu ăn rồi cho 2/3 lượng tỏi băm vào phi đều tay khoảng 30–40 giây đến khi tỏi vừa chuyển màu vàng nhạt và tỏa mùi thơm lừng.', 'Canh lửa vừa và tắt bớt nhiệt nếu chảo quá nóng để tỏi không bị cháy sẫm gây vị đắng.', NULL),
('vn-xao-01_v4_step_4', 'vn-xao-01', 4, 'cook', 'Xào rau muống lửa lớn và nêm gia vị', 'Bật bếp lên lửa lớn nhất, trút toàn bộ phần rau muống đã để ráo vào chảo dầu tỏi và đảo nhanh tay liên tục. Rưới đều 10 ml nước mắm ngon, rắc 5 g hạt nêm, 3 g đường cát trắng và 2 g muối ăn còn lại, đảo đều trong khoảng 1–2 phút cho rau bóng dầu và thấm gia vị.', 'Xào nhanh trên lửa lớn giúp rau không bị tiết nước và giữ nguyên độ giòn thanh.', 2),
('vn-xao-01_v4_step_5', 'vn-xao-01', 5, 'cook', 'Thêm phần tỏi tươi cuối cùng dậy mùi', 'Khi rau đã ngấm đều gia vị và nóng hổi, rắc nốt 1/3 lượng tỏi băm tươi còn lại vào chảo, đảo nhanh tay thêm 20–30 giây cho hương tỏi tươi hòa quyện nồng nàn mà không bị cháy.', NULL, NULL),
('vn-xao-01_v4_step_6', 'vn-xao-01', 6, 'finish', 'Trình bày và thưởng thức nóng', 'Tắt bếp ngay, gắp rau muống xào tỏi ra đĩa lớn, rưới chút nước xào còn trong chảo lên mặt rau và xếp vài lát ớt sừng đỏ lên trên. Dọn dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('vn-xao-02_v4_step_1', 'vn-xao-02', 1, 'prep', 'Thái mỏng và thấm khô thịt thăn bò', 'Rửa nhanh thịt thăn bò qua nước sạch rồi dùng khăn giấy thấm thật khô bề mặt. Đặt miếng thịt lên thớt, thái lát mỏng ngang thớ dày khoảng 0,3 cm để khi xào thịt nhanh chín và giữ độ mềm ngọt.', 'Thấm khô thịt trước khi ướp giúp thịt ngấm gia vị tốt hơn và không bị ra nước lênh láng lúc xào.', NULL),
('vn-xao-02_v4_step_2', 'vn-xao-02', 2, 'marinate', 'Ướp thịt bò mềm đậm đà', 'Cho thịt bò vào tô, ướp cùng 1/3 lượng tỏi băm, 10 ml nước tương (xì dầu), 5 ml dầu hào, 2,5 g hạt nêm, 1,5 g đường cát trắng, 1 g tiêu đen xay và 5 ml dầu ăn. Trộn đều nhẹ tay và ướp trong 15 phút để thịt thấm vị và giữ độ ẩm mượt.', 'Thêm một chút dầu ăn vào bước ướp giúp các thớ thịt tách rời khi gặp chảo nóng và không bị khô cứng.', 15),
('vn-xao-02_v4_step_3', 'vn-xao-02', 3, 'prep', 'Sơ chế cần tây, tỏi tây, hành tây và cà chua', 'Cần tây nhặt bỏ bớt lá già, rửa sạch từng nhánh rồi cắt khúc xéo 3–4 cm. Tỏi tây tách kỹ từng bẹ để rửa sạch cát, vẩy ráo rồi thái vát tương tự. Hành tây bóc vỏ, bổ múi cau; cà chua bỏ cuống, bổ 6 múi cau. Phần tỏi khô còn lại băm nhỏ.', NULL, NULL),
('vn-xao-02_v4_step_4', 'vn-xao-02', 4, 'cook', 'Áp chảo thịt bò nhanh trên lửa lớn', 'Đặt chảo rộng lên bếp lửa lớn, đun nóng già 15 ml dầu ăn rồi cho một nửa lượng tỏi băm còn lại vào phi thơm. Trút toàn bộ thịt bò đã ướp vào dàn đều mặt chảo, đảo nhanh tay liên tục khoảng 1–2 phút đến khi thịt bò vừa chuyển màu chín tái 80% thì lập tức trút ra đĩa riêng.', 'Chỉ xào bò vừa chín tái rồi vớt ra ngay để thịt giữ được độ mọng nước, không bị dai khi đảo lại cùng rau.', 2),
('vn-xao-02_v4_step_5', 'vn-xao-02', 5, 'cook', 'Xào chín tới hành tây, cần tây, tỏi tây và cà chua', 'Dùng lại chảo vừa xào bò, thêm 15 ml dầu ăn vào đun nóng trên lửa lớn, phi thơm nốt phần tỏi băm. Cho hành tây vào đảo 1 phút cho hơi trong, tiếp tục cho cà chua, cần tây và tỏi tây vào xào chung. Nêm 10 ml dầu hào, 2,5 g hạt nêm, 3 g muối ăn và 1,5 g đường cát trắng, đảo đều 2 phút đến khi rau củ chín tới, vẫn giữ màu xanh giòn.', NULL, 2),
('vn-xao-02_v4_step_6', 'vn-xao-02', 6, 'finish', 'Đảo quyện thịt bò và hoàn thiện đĩa xào', 'Trút đĩa thịt bò cùng phần nước tiết ra trở lại chảo rau củ, bật lửa lớn nhất và đảo nhanh tay trong 30–45 giây cho thịt bò chín hoàn toàn và quyện đều vị sốt. Tắt bếp, bày ra đĩa rộng và rắc 1 g tiêu đen xay còn lại lên trên, dùng nóng với cơm trắng.', NULL, NULL),
('vn-xao-03_v4_step_1', 'vn-xao-03', 1, 'prep', 'Làm sạch mực ống và khứa vảy rồng', 'Lột bỏ lớp màng tím ngoài thân mực ống, rút nhẹ đầu mực để lấy hết túi mực, nội tạng và thanh nang trắng bên trong, bỏ mắt và răng mực. Rửa thật sạch dưới vòi nước lạnh, xẻ đôi thân mực, khứa đường chéo vảy rồng rồi cắt miếng vuông khoảng 3 x 4 cm, để ráo.', 'Chọn mực ống thân dày, da sáng ánh nhũ, mắt trong và đầu dính chặt vào thân để món xào được giòn ngọt tự nhiên.', NULL),
('vn-xao-03_v4_step_2', 'vn-xao-03', 2, 'prep', 'Chần gừng và sốc nhiệt nước đá giúp mực giòn', 'Đun sôi một nồi nước với 25 g gừng tươi đập dập trên lửa lớn. Cho mực vào vợt, nhúng nhanh vào nước sôi trong 15–20 giây đến khi miếng mực vừa cuộn nhẹ và chuyển màu trắng đục thì lập tức vớt ra ngâm ngay vào thau nước đá lạnh 2 phút rồi để thật ráo nước.', 'Chần nhanh qua nước gừng rồi sốc nhiệt nước đá vừa khử sạch mùi tanh, vừa giúp mực ráo nước và giòn sần sật khi xào.', 2),
('vn-xao-03_v4_step_3', 'vn-xao-03', 3, 'prep', 'Sơ chế rau củ, dứa và gia vị', 'Dứa gọt sạch mắt, bỏ lõi cứng rồi thái lát mỏng vừa ăn. Cà chua và hành tây bổ múi cau. Cần tây và tỏi tây tách bẹ rửa thật sạch, cắt khúc dài 4 cm. Tỏi khô bóc vỏ băm nhỏ; ớt sừng đỏ thái lát xéo.', NULL, NULL),
('vn-xao-03_v4_step_4', 'vn-xao-03', 4, 'cook', 'Xào săn mực ống trên lửa lớn', 'Đặt chảo lên bếp lửa lớn, đun nóng 15 ml dầu ăn rồi phi thơm một nửa phần tỏi băm. Trút mực ống đã ráo nước vào đảo nhanh tay liên tục, nêm 15 ml nước mắm ngon và 5 g hạt nêm, xào khoảng 1–2 phút cho mực săn giòn, nở hoa đều thì trút ra đĩa riêng.', 'Xào mực riêng trên lửa thật lớn giúp mực chín đều, săn giòn mà không bị tiết nước làm loãng rau củ.', 2),
('vn-xao-03_v4_step_5', 'vn-xao-03', 5, 'cook', 'Xào cà chua, hành tây, dứa và cần tỏi', 'Dùng lại chảo, thêm 15 ml dầu ăn đun nóng rồi phi thơm nốt phần tỏi băm còn lại. Cho cà chua vào xào 1–2 phút trên lửa vừa-lớn cho hơi mềm tạo màu, sau đó tăng lửa lớn cho hành tây và dứa vào đảo 1 phút. Tiếp tục thả cần tây và tỏi tây vào, nêm 3 g hạt nêm và 5 g đường cát trắng, đảo đều 2 phút cho rau củ chín tới.', NULL, 3),
('vn-xao-03_v4_step_6', 'vn-xao-03', 6, 'finish', 'Trộn mực với rau củ và trình bày', 'Trút đĩa mực đã xào trở lại chảo rau củ, đảo nhanh tay trên lửa lớn khoảng 30–45 giây cho mực nóng hổi, chín kỹ và hòa quyện cùng sốt dứa cà chua. Thêm ớt sừng đỏ thái lát đảo sơ rồi tắt bếp, gắp ra đĩa và rắc 2 g tiêu đen xay lên trên.', NULL, NULL),
('vn-xao-04_v4_step_1', 'vn-xao-04', 1, 'marinate', 'Thái mỏng và ướp thịt thăn bò', 'Thấm thật khô thịt thăn bò rồi thái lát mỏng ngang thớ. Cho thịt vào tô, ướp với 10 ml nước tương (xì dầu), 5 ml dầu hào, 2 g hạt nêm, 3 g đường cát trắng, 1 g tiêu đen xay và 5 ml dầu ăn, trộn đều rồi để nghỉ 15 phút cho thịt ngấm gia vị.', 'Thái thịt bò ngang thớ và thêm chút dầu ăn khi ướp giúp thịt giữ độ mềm ẩm và không bị dai khi xào lửa lớn.', 15),
('vn-xao-04_v4_step_2', 'vn-xao-04', 2, 'prep', 'Sơ chế và chần sơ bông cải xanh, cà rốt', 'Tách bông cải xanh thành từng nhánh nhỏ vừa ăn, gọt bỏ phần vỏ xơ quanh cuống rồi rửa sạch. Cà rốt gọt vỏ, thái lát mỏng hoặc tỉa hoa dày 0,3 cm. Đun sôi nồi nước với 4 g muối ăn, thả cà rốt vào chần trước 30 giây rồi cho bông cải xanh vào chần chung thêm 45 giây, vớt ngay ra thau nước lạnh ngâm 1 phút rồi để ráo.', 'Chần sơ bông cải xanh giúp loại bỏ mùi hăng nhẹ, giữ màu xanh mướt và rút ngắn thời gian xào trên chảo.', 2),
('vn-xao-04_v4_step_3', 'vn-xao-04', 3, 'prep', 'Chuẩn bị tỏi băm và hành lá', 'Tỏi khô bóc vỏ, băm nhuyễn và chia làm hai phần bằng nhau. Hành lá rửa sạch, thái nhỏ phần đầu hành trắng để phi thơm, phần lá xanh cắt khúc 3 cm.', NULL, NULL),
('vn-xao-04_v4_step_4', 'vn-xao-04', 4, 'cook', 'Xào tái thịt bò trên lửa lớn', 'Đặt chảo lên bếp lửa lớn, đun nóng 10 ml dầu ăn rồi cho một nửa lượng tỏi băm vào phi thơm. Đổ thịt bò đã ướp vào dàn đều, đảo nhanh tay khoảng 1–2 phút đến khi thịt vừa săn lại và chín tái thì trút ra đĩa riêng.', NULL, 2),
('vn-xao-04_v4_step_5', 'vn-xao-04', 5, 'cook', 'Xào cà rốt và bông cải xanh thấm vị dầu hào', 'Dùng lại chảo vừa xào bò, thêm 15 ml dầu ăn vào đun nóng, phi thơm nốt phần tỏi băm và đầu hành lá trắng. Cho cà rốt và bông cải xanh đã ráo nước vào đảo đều trên lửa lớn, nêm 10 ml dầu hào, 3 g hạt nêm và 2 g muối ăn còn lại, xào khoảng 2 phút cho rau củ chín tới nhưng vẫn giòn ngọt.', 'Không xào bông cải quá lâu sau khi đã chần sơ để giữ độ giòn sần sật và hàm lượng vitamin tự nhiên.', 2),
('vn-xao-04_v4_step_6', 'vn-xao-04', 6, 'finish', 'Đảo quyện bò với rau củ và hoàn thiện', 'Trút đĩa thịt bò đã xào tái trở lại chảo bông cải cà rốt, đảo nhanh tay trên lửa lớn 45 giây cho thịt bò chín hoàn toàn và thấm sốt. Rưới 5 ml nước mắm ngon, thả hành lá cắt khúc vào đảo đều rồi tắt bếp, bày ra đĩa và rắc 1 g tiêu đen xay lên trên.', NULL, NULL),
('vn-xao-05_v4_step_1', 'vn-xao-05', 1, 'prep', 'Gọt vỏ và thái sợi su su không dính nhựa', 'Ngâm 3 quả su su trong chậu nước khoảng 2 phút hoặc gọt vỏ trực tiếp dưới vòi nước chảy để nhựa su su không làm rít tay. Bổ đôi quả, khoét bỏ phần hạt non ở giữa rồi thái thành sợi dày khoảng 0,3 cm đều nhau, rửa lại nước sạch và để thật ráo.', 'Chọn su su quả non có vỏ xanh sáng, bấm nhẹ thấy mọng nước để món xào được ngọt và không bị xơ.', NULL),
('vn-xao-05_v4_step_2', 'vn-xao-05', 2, 'prep', 'Chuẩn bị hành tím, rau thơm và đánh trứng gà', 'Hành tím khô bóc vỏ, băm nhỏ. Hành lá và ngò rí rửa sạch, thái nhỏ. Đập 3 quả trứng gà ta vào tô, thêm 3 ml nước mắm ngon (giúp trứng thơm và không tanh), dùng đũa đánh tan đều lòng đỏ với lòng trắng.', NULL, NULL),
('vn-xao-05_v4_step_3', 'vn-xao-05', 3, 'cook', 'Phi thơm hành tím và xào su su lửa lớn', 'Bắc chảo lên bếp lửa vừa, làm nóng 30 ml dầu ăn rồi cho hành tím băm vào phi thơm khoảng 30 giây. Tăng lên lửa lớn, trút toàn bộ sợi su su vào đảo nhanh tay liên tục, nêm 5 g hạt nêm, 4 g muối ăn và 7 ml nước mắm ngon còn lại, xào khoảng 3 phút đến khi sợi su su hơi trong và chín tới 80%.', 'Xào su su trên lửa lớn giúp su su nhanh chín mà không bị ra nhiều nước làm nhão trứng.', 3),
('vn-xao-05_v4_step_4', 'vn-xao-05', 4, 'cook', 'Đổ trứng gà và đảo quyện đều cùng su su', 'Hạ xuống lửa vừa, dàn đều su su ra khắp mặt chảo rồi rưới từ từ tô trứng gà đã đánh tan lên trên. Đợi 15–20 giây cho phần trứng tiếp xúc mặt chảo hơi se lại rồi dùng đũa đảo đều nhẹ tay khoảng 1–2 phút đến khi trứng chín hoàn toàn, bám đều quanh từng sợi su su thành mảng tơi mềm.', 'Không đảo quá mạnh ngay khi vừa đổ trứng để tránh trứng bị nát vụn và bết dính.', 2),
('vn-xao-05_v4_step_5', 'vn-xao-05', 5, 'cook', 'Thêm hành lá và nêm nếm lại', 'Khi trứng đã chín ráo mặt và thơm ngậy, cho toàn bộ hành lá thái nhỏ vào chảo đảo nhanh tay thêm 20 giây cho hành chín xanh, nếm lại gia vị cho vừa khẩu vị rồi tắt bếp.', NULL, NULL),
('vn-xao-05_v4_step_6', 'vn-xao-05', 6, 'finish', 'Trình bày và thưởng thức', 'Múc su su xào trứng gà ra đĩa, rắc ngò rí và 1,5 g tiêu đen xay lên trên cho thơm. Dọn dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('vn-xao-06_v4_step_1', 'vn-xao-06', 1, 'marinate', 'Thái mỏng và ướp thịt bò thấm gia vị', 'Rửa sạch thịt thăn bò, thấm thật khô rồi thái lát mỏng ngang thớ. Ướp thịt với 1/3 lượng tỏi băm, 5 g hạt nêm, 2 g muối ăn, 3 g đường cát trắng, 1 g tiêu đen xay và 5 ml dầu ăn; trộn đều và để thấm 15 phút.', 'Thái thịt ngang thớ giúp từng lát bò mềm mượt, không bị dai sau khi xào.', 15),
('vn-xao-06_v4_step_2', 'vn-xao-06', 2, 'prep', 'Tước xơ và chần sơ đậu cô ve', 'Nhặt bỏ hai đầu và tước sạch đường xơ dọc hai bên thân đậu cô ve, rửa sạch rồi thái vát chéo hoặc cắt khúc dài 4 cm. Đun sôi nồi nước với 2 g muối ăn, chần nhanh đậu cô ve trong 45–60 giây rồi vớt ra ngâm nước lạnh 1 phút và để thật ráo.', 'Chần sơ đậu cô ve giúp khử vị ngai ngái, giữ sắc xanh mướt và giúp đậu chín đồng đều khi xào.', 1),
('vn-xao-06_v4_step_3', 'vn-xao-06', 3, 'cook', 'Xào tái thịt bò trên lửa lớn', 'Làm nóng 15 ml dầu ăn trên chảo lửa lớn, phi thơm 1/3 lượng tỏi băm rồi cho thịt bò đã ướp vào dàn đều. Đảo nhanh tay liên tục khoảng 1,5–2 phút đến khi thịt vừa chín tái 80% thì trút ngay ra đĩa riêng.', NULL, 2),
('vn-xao-06_v4_step_4', 'vn-xao-06', 4, 'cook', 'Xào đậu cô ve giòn xanh', 'Dùng lại chảo vừa xào bò, thêm 15 ml dầu ăn đun nóng rồi phi thơm 1/3 lượng tỏi băm còn lại. Cho đậu cô ve vào đảo nhanh trên lửa lớn 1 phút, thêm 2 g muối ăn và 60 ml nước lọc, đậy nắp om nhanh khoảng 2 phút cho đậu chín tới mà vẫn giữ độ giòn.', 'Chỉ thêm một lượng nước nhỏ và đậy nắp nhanh để hơi nóng làm đậu chín đều từ trong ra ngoài mà không bị nát.', 2),
('vn-xao-06_v4_step_5', 'vn-xao-06', 5, 'cook', 'Đảo chung thịt bò với sốt dầu hào', 'Mở nắp, bật lửa lớn và trút toàn bộ đĩa thịt bò đã xào tái trở lại chảo. Nêm 15 ml dầu hào và 10 ml nước mắm ngon, đảo nhanh tay 1 phút cho thịt bò chín hoàn toàn và sốt sánh quyện đều lên đậu cô ve.', NULL, NULL),
('vn-xao-06_v4_step_6', 'vn-xao-06', 6, 'finish', 'Thêm hành lá và dọn nóng', 'Thả hành lá cắt khúc vào đảo nhanh một lượt rồi tắt bếp ngay. Bày đậu cô ve xào thịt bò ra đĩa, rắc 1 g tiêu đen xay còn lại lên trên và thưởng thức nóng cùng cơm trắng.', NULL, NULL),
('vn-chien-01_v4_step_1', 'vn-chien-01', 1, 'prep', 'Thấm khô đậu phụ và cắt miếng vừa ăn', 'Rửa nhẹ đậu phụ trắng dưới vòi nước lạnh cho sạch, đặt lên khăn giấy sạch thấm thật khô hai mặt rồi cắt thành miếng vuông dày khoảng 2 cm. Nếu thích lớp vỏ xốp giòn, lăn nhẹ các miếng đậu qua 12 g bột năng rồi giũ bỏ bột thừa; còn để giữ đúng độ mềm mướt kiểu lướt ván thì chiên trực tiếp.', 'Thấm khô bề mặt đậu phụ là bí quyết quan trọng nhất để khi thả vào chảo dầu không bị bắn và miếng đậu lên màu vàng đều.', NULL),
('vn-chien-01_v4_step_2', 'vn-chien-01', 2, 'prep', 'Sơ chế cà chua và các loại hành thơm', 'Cà chua chín đỏ rửa sạch, bỏ cuống, thái hạt lựu nhỏ để khi xào nhanh nhừ thành sốt mịn. Hành tím bóc vỏ, thái lát mỏng hoặc băm nhỏ. Hành lá rửa sạch, tách riêng phần đầu hành trắng băm nhỏ và phần lá xanh cắt khúc dài 2 cm.', NULL, NULL),
('vn-chien-01_v4_step_3', 'vn-chien-01', 3, 'cook', 'Chiên lướt ván đậu phụ vàng đều hai mặt', 'Đặt chảo chống dính lên bếp, cho 125 ml dầu ăn vào đun trên lửa vừa đến khi đầu đũa chạm đáy chảo sủi tăm nhẹ. Thả từng miếng đậu phụ vào chiên khoảng 3 phút mỗi mặt đến khi lớp vỏ bên ngoài vừa se vàng nhạt nhưng bên trong vẫn mềm núng nính thì vớt ra đĩa có giấy thấm dầu.', 'Không chiên quá lâu ở lửa lớn khiến vỏ đậu bị cứng và ruột bị rỗ khô; đậu vừa vàng xém nhẹ hai mặt là đạt.', 6),
('vn-chien-01_v4_step_4', 'vn-chien-01', 4, 'sauce', 'Phi thơm hành tím và xào nhừ cà chua', 'Chắt bớt dầu thừa trong chảo, giữ lại khoảng 10–12 ml dầu ăn, đun nóng trên lửa vừa rồi cho hành tím và đầu hành lá vào phi thơm 1 phút. Trút toàn bộ cà chua vào xào cùng 2 g hạt nêm, đậy nắp chảo nấu 3 phút cho cà chua mềm nát và tiết màu đỏ cam.', NULL, 3),
('vn-chien-01_v4_step_5', 'vn-chien-01', 5, 'sauce', 'Nêm gia vị và nấu sánh sốt cà chua', 'Mở nắp, dùng muôi dằm nhẹ phần cà chua cho nhuyễn mịn rồi đổ 80 ml nước lọc vào khuấy đều. Nêm 25 ml nước mắm ngon, 15 ml dầu hào (nếu dùng), 6 g đường cát trắng và 4 g hạt nêm còn lại, nấu sôi nhẹ 2 phút. Hòa 4 g bột năng với 20 ml nước lọc rồi rót từ từ vào chảo khuấy đều cho sốt sánh bóng.', 'Dầu hào và đường giúp làm dịu vị chua gắt của cà chua, tạo độ sánh mượt tự nhiên cho phần sốt rưới cơm.', 2),
('vn-chien-01_v4_step_6', 'vn-chien-01', 6, 'finish', 'Om đậu thấm sốt và hoàn thiện món ăn', 'Hạ lửa nhỏ, nhẹ nhàng xếp từng miếng đậu phụ đã chiên vào chảo sốt cà chua, dùng thìa rưới đều sốt lên mặt đậu và rim khoảng 3 phút cho sốt thấm quanh miếng đậu mà không bị vỡ. Rắc hành lá cắt khúc vào đảo nhẹ rồi tắt bếp, gắp ra đĩa và rắc thêm tiêu đen xay lên trên.', NULL, 3),
('vn-chien-02_v4_step_1', 'vn-chien-02', 1, 'marinate', 'Ướp thịt bằm và sơ chế trụng nấm rơm', 'Cho thịt heo xay vào tô, ướp cùng 3 g hạt nêm, 1 g muối ăn và 1 g tiêu đen xay trong 10 phút cho thấm vị. Nấm rơm gọt bỏ gốc bẩn, rửa qua nước muối pha 1 g muối còn lại, sau đó thả vào 500 ml nước lọc đang sôi trụng nhanh 1 phút, vớt ra xả ngay nước lạnh, vắt ráo nhẹ rồi thái lát mỏng hoặc băm nhỏ.', 'Trụng nhanh nấm rơm rồi xả lạnh giúp nấm giữ được độ giòn ngọt, không bị thâm đen và ra ít nước khi xào.', 10),
('vn-chien-02_v4_step_2', 'vn-chien-02', 2, 'prep', 'Sơ chế hành lá, hành tím và tỏi băm', 'Hành lá rửa sạch, để ráo rồi thái nhỏ. Hành tím bóc vỏ thái lát mỏng (nếu tự phi), tỏi bóc vỏ băm nhuyễn. Chuẩn bị sẵn tô lớn để đánh trứng.', NULL, NULL),
('vn-chien-02_v4_step_3', 'vn-chien-02', 3, 'cook', 'Xào ráo nhân nấm rơm và thịt bằm', 'Làm nóng chảo với 10 ml dầu ăn trên lửa vừa, phi thơm hành tím và tỏi băm rồi cho nấm rơm vào đảo nhanh 2 phút cùng 2 g hạt nêm cho ráo nước, trút ra đĩa. Giữ nguyên chảo, tăng lửa lớn và cho thịt heo xay đã ướp vào đảo tơi đến khi thịt chuyển màu trắng đục chín hoàn toàn, trút nấm vào đảo chung 1 phút cho ráo hẳn nước rồi tắt bếp để nguội bớt.', 'Phải xào thịt và nấm thật ráo nước trên lửa lớn trước khi trộn vào trứng, nếu nhân còn ướt miếng trứng sẽ bị bở và vỡ khi lật.', 4),
('vn-chien-02_v4_step_4', 'vn-chien-02', 4, 'prep', 'Đánh tan trứng cùng sữa tươi và trộn nhân', 'Đập 5 quả trứng gà vào tô lớn, thêm 25 ml sữa tươi không đường, 15 ml nước mắm ngon, 5 ml dầu mè thơm (nếu dùng) và 1 g tiêu đen xay. Dùng đũa khuấy đều nhẹ tay cho lòng trắng và lòng đỏ hòa quyện mà không tạo quá nhiều bọt khí, rồi cho hành lá thái nhỏ cùng toàn bộ nhân thịt nấm đã nguội vào trộn đều.', NULL, NULL),
('vn-chien-02_v4_step_5', 'vn-chien-02', 5, 'cook', 'Chiên phồng mặt đáy trứng trên lửa nhỏ', 'Đặt chảo chống dính đường kính 22–24 cm lên bếp, đun nóng 20 ml dầu ăn còn lại trên lửa vừa rồi hạ xuống lửa nhỏ. Đổ hỗn hợp trứng thịt nấm vào chảo, dàn đều nhân khắp mặt, đậy nắp chảo chiên khoảng 5 phút cho mặt dưới chín vàng và mặt trên se đặc lại.', 'Đậy nắp và giữ lửa nhỏ giúp hơi nóng làm chín phần thịt trứng ở giữa mà không làm cháy sém mặt đáy.', 5),
('vn-chien-02_v4_step_6', 'vn-chien-02', 6, 'finish', 'Lật mặt chiên vàng đều và cắt miếng dọn nóng', 'Khi mặt trên trứng đã se lại không còn lỏng, úp một chiếc đĩa lớn lên miệng chảo rồi lật ngược chảo để lấy trứng ra đĩa, sau đó trượt nhẹ mặt chưa chín trở lại chảo. Chiên tiếp không đậy nắp thêm 2 phút trên lửa nhỏ cho đến khi hai mặt vàng ruộm và phần nhân chín kỹ hoàn toàn, gắp ra đĩa cắt thành 6 miếng tam giác và dùng nóng.', NULL, 2);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('vn-chien-03_v4_step_1', 'vn-chien-03', 1, 'prep', 'Làm sạch và trụng sơ khử mùi cánh gà', 'Chà xát kỹ cánh gà với 5 g muối hạt và 1/2 quả chanh tươi trong 2 phút, rửa sạch lại nhiều lần rồi khía nhẹ 2 đường mặt trong để thịt nhanh chín. Đun sôi 950 ml nước lọc cùng 5 g muối hạt, 10 ml giấm gạo, gừng tươi đập dập và 10 g hành tím đập dập, thả cánh gà vào trụng 4 phút rồi vớt ra để thật ráo nước.', 'Trụng sơ giúp loại bỏ tạp chất, làm da gà săn lại nên khi chiên sẽ ít bắn dầu và thịt bên trong giữ được độ ẩm ngọt.', 4),
('vn-chien-03_v4_step_2', 'vn-chien-03', 2, 'prep', 'Thấm khô, áo bột và băm nhuyễn tỏi ớt', 'Dùng khăn giấy sạch thấm khô hoàn toàn từng chiếc cánh gà. Nếu dùng bột chiên giòn, cho cánh gà vào tô xóc đều với 60 g bột chiên giòn khô rồi giũ bỏ bột thừa để chỉ còn một lớp áo mỏng. Băm nhuyễn tỏi ta, ớt sừng đỏ và 15 g hành tím còn lại để riêng.', NULL, NULL),
('vn-chien-03_v4_step_3', 'vn-chien-03', 3, 'cook', 'Chiên cánh gà ngập dầu đến khi vàng giòn', 'Đổ 385 ml dầu ăn vào chảo sâu lòng, đun nóng già ở lửa vừa đến khi đầu đũa sủi bọt mạnh. Thả cánh gà vào chiên ngập mặt dầu khoảng 10–12 phút, trở đều các mặt cho đến khi lớp da vàng ruộm, giòn rụm và thịt sát xương chín hoàn toàn không còn nước hồng. Vớt gà ra rây hoặc giấy thấm dầu cho ráo.', 'Không xếp quá nhiều cánh gà trong một mẻ để giữ nhiệt độ dầu ổn định, giúp da gà giòn lâu và không bị ngấm dầu.', 12),
('vn-chien-03_v4_step_4', 'vn-chien-03', 4, 'sauce', 'Pha hỗn hợp sốt nước mắm chua ngọt', 'Trong chén nhỏ, hòa tan hoàn toàn 35 ml nước mắm truyền thống, 20 g đường cát trắng, 20 ml tương ớt, 5 ml giấm gạo, 50 ml nước lọc và 1 g tiêu đen xay cho đến khi đường tan hết.', NULL, NULL),
('vn-chien-03_v4_step_5', 'vn-chien-03', 5, 'sauce', 'Phi thơm tỏi ớt và nấu sánh keo sốt mắm', 'Đặt một chảo sạch lên bếp, cho 15 ml dầu ăn vào đun nóng ở lửa vừa rồi phi thơm hành tím băm, tỏi băm và ớt băm trong 1 phút. Đổ chén sốt nước mắm đã pha vào chảo, hạ lửa nhỏ và khuấy đều khoảng 3 phút đến khi sốt sôi sủi bọt và sánh kẹo lại.', 'Phải nấu cho sốt thật sánh kẹo trước khi cho gà vào; nếu sốt còn loãng sẽ làm lớp da gà bị ỉu mềm ngay lập tức.', 3),
('vn-chien-03_v4_step_6', 'vn-chien-03', 6, 'finish', 'Đảo cánh gà áo sốt và dọn nóng', 'Trút toàn bộ cánh gà đã chiên giòn vào chảo sốt, bật lửa vừa và xóc đảo nhanh tay khoảng 1–2 phút cho sốt mắm tỏi ớt bóng đẹp bám đều quanh từng chiếc cánh gà. Tắt bếp, rắc 1 g tiêu đen xay còn lại, xếp ra đĩa và thưởng thức ngay khi còn nóng giòn.', NULL, 2),
('vn-chien-04_v4_step_1', 'vn-chien-04', 1, 'prep', 'Luộc mỡ heo hạt lựu và sơ chế rau thơm', 'Đun sôi 400 ml nước lọc, cho 80 g phần thịt mỡ heo vào luộc chín tới khoảng 5 phút, vớt ra để nguội ráo rồi thái hạt lựu nhỏ 0,5 cm, trộn ướp với 3 g đường cát trắng trong 10 phút cho mỡ trong giòn. Thì là tươi, đầu hành hoa rửa sạch để thật ráo nước rồi thái nhỏ; hành tím băm nhuyễn.', NULL, 5),
('vn-chien-04_v4_step_2', 'vn-chien-04', 2, 'marinate', 'Ướp lạnh thịt cá trước khi quết dai', 'Cho 450 g thịt cá thác lác nạo vào tô lớn, ướp cùng 20 ml nước mắm ngon, 8 g hạt nêm, 3 g muối ăn và 3 g tiêu đen xay. Trộn sơ rồi bọc kín đặt trong ngăn mát tủ lạnh 15 phút để thịt cá giữ độ lạnh sâu, giúp liên kết protein bền chặt khi quết.', 'Giữ cá thật lạnh trước và trong khi quết là bí quyết giúp chả cá dai giòn sần sật tự nhiên mà không bị bở.', 15),
('vn-chien-04_v4_step_3', 'vn-chien-04', 3, 'prep', 'Quết dẻo thịt cá với nạc vai và bột năng', 'Lấy tô cá lạnh ra, dùng muôi gỗ bản to hoặc tay đeo găng quết mạnh, miết sát vào thành tô liên tục trong 10 phút đến khi thịt cá dẻo quánh và nặng tay. Tiếp tục cho 100 g thịt nạc vai heo xay vào quết thêm 4 phút cho hai loại thịt quyện mịn vào nhau.', NULL, 14),
('vn-chien-04_v4_step_4', 'vn-chien-04', 4, 'prep', 'Trộn mỡ hạt lựu, thì là và hạt tiêu', 'Thêm phần mỡ heo hạt lựu đã ướp đường, lòng trắng 1 quả trứng gà, 20 g bột năng, thì là thái nhỏ, đầu hành hoa, hành tím băm và 3 g tiêu đen xay còn lại vào tô. Trộn đều và quết thêm 3 phút cho nguyên liệu phân bố đều khắp khối chả.', 'Cho thì là và phần tiêu còn lại vào sau cùng để giữ trọn hương thơm tươi mát, không bị nồng hăng khi quết lâu.', NULL),
('vn-chien-04_v4_step_5', 'vn-chien-04', 5, 'cook', 'Nặn miếng tròn dẹt và chiên chả vàng phồng', 'Thoa 10 ml dầu ăn lên lòng bàn tay để chống dính, múc từng phần chả nặn thành miếng tròn dẹt dày khoảng 1,5 cm. Làm nóng 340 ml dầu ăn trong chảo trên lửa vừa đến khi dầu nóng già, thả chả vào chiên khoảng 6–7 phút, trở đều hai mặt cho đến khi miếng chả phồng căng, vỏ vàng ươm và chín kỹ tận lõi.', 'Chiên ở lửa vừa ổn định; lửa quá lớn khiến vỏ ngoài cháy nhanh mà bên trong chưa kịp chín phồng, còn lửa quá nhỏ làm chả ngấm dầu.', 7),
('vn-chien-04_v4_step_6', 'vn-chien-04', 6, 'finish', 'Thấm ráo dầu và thưởng thức nóng', 'Vớt chả cá ra đĩa có lót giấy thấm dầu để ráo bớt dầu thừa trong 2 phút. Xếp ra đĩa, dùng nóng kèm cơm trắng hoặc bún tươi, chấm cùng tương ớt cay ngọt.', NULL, 2),
('vn-chien-05_v4_step_1', 'vn-chien-05', 1, 'prep', 'Ngâm nở nấm hương, mộc nhĩ và miến dong', 'Ngâm riêng 8 g mộc nhĩ khô, 8 g nấm hương khô và 50 g miến dong khô vào 350 ml nước lọc ấm trong khoảng 12 phút cho nở mềm vừa. Rửa sạch nấm và mộc nhĩ, cắt bỏ chân nấm, vắt thật kiệt nước rồi băm nhỏ; miến vớt ra để thật ráo rồi cắt khúc ngắn 2–3 cm.', 'Phải vắt khô kiệt nấm, mộc nhĩ và để ráo miến dong để nhân nem khô ráo, tránh tiết nước làm bục vỏ khi chiên.', 12),
('vn-chien-05_v4_step_2', 'vn-chien-05', 2, 'prep', 'Sơ chế rau củ, tôm và ướp thịt xay', 'Gọt vỏ củ đậu, cà rốt rồi bào sợi ngắn; hành tây thái hạt lựu nhỏ; hành hoa, rau mùi ta rửa sạch để ráo thái nhỏ; hành tím băm nhuyễn. Tôm tươi bóc vỏ, rút chỉ đen, thái hạt lựu. Ướp 450 g thịt nạc vai xay với 15 ml dầu ăn, 5 ml nước mắm, 5 g hạt nêm, 4 g muối ăn và 4 g tiêu đen xay trong 10 phút.', NULL, 10),
('vn-chien-05_v4_step_3', 'vn-chien-05', 3, 'prep', 'Trộn hoàn chỉnh nhân nem trước khi gói', 'Cho toàn bộ tôm, mộc nhĩ, nấm hương, miến, củ đậu, hành tây, cà rốt, hành hoa, rau mùi ta và hành tím vào âu thịt đã ướp, trộn đều nhẹ tay. Ngay trước lúc bắt đầu cuốn mới đập 2 quả trứng gà vào đảo đều lần cuối để nhân kết dính vừa phải mà không chảy nước.', 'Cho trứng gà vào sau cùng ngay lúc chuẩn bị gói là mẹo giúp củ đậu và hành tây không ra nước trong thời gian chờ.', NULL),
('vn-chien-05_v4_step_4', 'vn-chien-05', 4, 'prep', 'Thoa giấm loãng và cuốn nem đều tay', 'Pha 5 ml giấm gạo với 50 ml nước lọc, dùng khăn sạch thấm nhẹ thoa đều mặt bánh đa nem cho mềm dẻo (có thể lót thêm 1/2 lá vào giữa cho chắc). Múc 2 muỗng canh nhân đặt vào đầu lá, gấp hai mép bên rồi cuộn tròn vừa tay thành khoảng 20 chiếc nem kích thước đều nhau.', 'Không cuốn nem quá chặt tay vì khi gặp nhiệt nhân thịt trứng nở ra sẽ dễ làm rách vỏ bánh đa nem.', NULL),
('vn-chien-05_v4_step_5', 'vn-chien-05', 5, 'cook', 'Rán nem hai lần lửa để vỏ giòn tan', 'Đun nóng 485 ml dầu ăn trong chảo sâu lòng trên lửa vừa, thả nem vào rán lần 1 trong 7 phút cho nem se mặt và chín khoảng 80% thì vớt ra giá để nguội hẳn. Trước khi ăn, đun dầu nóng lại ở lửa vừa-lớn rồi thả nem vào rán lần 2 thêm 3–4 phút cho đến khi vỏ nem vàng ruộm giòn rụm và nhân thịt tôm chín kỹ hoàn toàn, vớt ra giấy thấm dầu.', NULL, 11),
('vn-chien-05_v4_step_6', 'vn-chien-05', 6, 'finish', 'Pha nước chấm chua ngọt và bày đĩa', 'Khuấy tan 35 g đường cát trắng với 200 ml nước lọc ấm, sau đó thêm 45 ml nước mắm ngon và 40 ml giấm gạo nếm vừa vị chua ngọt hài hòa, cuối cùng thả tỏi băm và ớt băm vào để nổi đều đẹp mắt. Cắt nem làm đôi hoặc làm ba, dùng nóng kèm rau sống và nước chấm.', 'Hòa tan đường với nước ấm trước rồi mới cho nước mắm, tỏi ớt băm thả vào sau cùng sẽ giúp tỏi ớt nổi đều trên mặt chén.', NULL),
('vn-chien-06_v4_step_1', 'vn-chien-06', 1, 'prep', 'Làm sạch khử tanh và khía thân cá rô phi', 'Đánh sạch vảy, cắt bỏ mang và mổ bỏ ruột cá rô phi, chú ý cạo sạch lớp màng đen bên trong bụng cá để hết mùi tanh. Dùng 6 g muối ăn chà xát khắp mình và bụng cá trong 2 phút rồi rửa sạch lại bằng nước lạnh, dùng khăn sạch thấm thật khô cá và khía 3–4 đường chéo trên mỗi mặt thân cá.', 'Cạo thật sạch lớp màng đen trong bụng cá và chà xát muối kỹ giúp khử hoàn toàn mùi tanh bùn của cá rô phi đồng.', NULL),
('vn-chien-06_v4_step_2', 'vn-chien-06', 2, 'marinate', 'Ướp cá và pha hỗn hợp bột mì nhúng', 'Rắc đều 2 g muối ăn và 1 g tiêu đen xay vào các đường khía trên thân cá, ướp 10 phút cho thịt cá săn đậm vị. Trong tô lớn, khuấy đều 35 g bột mì đa dụng với 60 ml nước lọc, 2 g muối ăn và 1 g tiêu đen xay còn lại thành hỗn hợp sền sệt mịn không vón cục.', NULL, 10),
('vn-chien-06_v4_step_3', 'vn-chien-06', 3, 'cook', 'Chiên cá ngập dầu lửa vừa đến khi vàng giòn', 'Đổ 300 ml dầu ăn vào chảo lớn sâu lòng, đun lửa vừa đến khi dầu nóng già và thử đầu đũa thấy sủi tăm mạnh. Nhúng từng con cá qua tô bột mì cho phủ một lớp áo thật mỏng rồi nhẹ nhàng thả vào chảo, chiên mỗi mặt 7–8 phút không trở quá sớm đến khi da cá vàng giòn rụm và thịt cá chín trắng đục tận xương.', 'Giữ lửa vừa ổn định và đợi mặt dưới chín vàng cứng cáp mới lật để da cá không bị dính sát chảo hay vỡ nát.', 16),
('vn-chien-06_v4_step_4', 'vn-chien-06', 4, 'finish', 'Vớt cá lên rây cho ráo dầu', 'Khi hai mặt cá đã vàng giòn đều từ đầu đến đuôi, nhẹ nhàng gắp cá ra rây thưa hoặc đĩa có lót giấy thấm dầu, để nghỉ 2 phút cho thoát bớt dầu thừa giúp vỏ cá giòn lâu hơn.', 'Gác cá lên rây thưa hoặc giấy thấm dầu giúp hơi ẩm thoát đều, giữ lớp vỏ ngoài giòn rụm lâu hơn.', NULL),
('vn-chien-06_v4_step_5', 'vn-chien-06', 5, 'sauce', 'Giã nhuyễn gừng tỏi ớt và pha nước mắm', 'Giã nhuyễn 40 g gừng tươi, 1 củ tỏi khô và 2 quả ớt tươi (hoặc băm thật mịn). Hòa tan hoàn toàn 25 g đường cát trắng với 60 ml nước lọc ấm trong chén, sau đó thêm 60 ml nước mắm nguyên chất và nước cốt của 1,5 quả chanh tươi khuấy đều, cuối cùng cho gừng tỏi ớt vào.', 'Khuấy tan đường trước với nước ấm rồi mới thêm nước mắm, chanh và gừng tỏi ớt sau cùng để nước chấm sánh thơm và tỏi ớt nổi đẹp.', NULL),
('vn-chien-06_v4_step_6', 'vn-chien-06', 6, 'finish', 'Bày cá chiên ra đĩa và thưởng thức nóng', 'Đặt cá rô phi chiên giòn lên đĩa lớn, dọn ngay khi còn nóng hổi giòn tan cùng chén nước mắm gừng, ăn kèm cơm trắng nóng và rau luộc hoặc cuốn rau sống.', NULL, NULL),
('vn-hap-01_v4_step_1', 'vn-hap-01', 1, 'prep', 'Làm sạch và khử mùi hôi gà ta', 'Rửa sạch nửa con gà ta dưới vòi nước lạnh, cắt bỏ tuyến dầu ở phần đuôi. Dùng 6 g muối hạt và 10 g gừng đập dập chà xát kỹ cả bên ngoài da lẫn khoang bụng trong 2 phút để loại bỏ mùi hôi và chất nhờn, sau đó xả lại nhiều lần với nước sạch rồi thấm thật khô bằng khăn giấy.', 'Thấm thật ráo bề mặt da trước khi ướp sẽ giúp gia vị bám đều và da gà khi hấp xong căng bóng, không bị bở nhão.', NULL),
('vn-hap-01_v4_step_2', 'vn-hap-01', 2, 'prep', 'Sơ chế sả, gừng, hành tím và lá chanh', 'Cạo vỏ phần gừng còn lại, cắt 20 g thành lát mỏng và băm nhỏ 10 g. Bóc lớp bẹ già của 3 cây sả, đập dập cắt khúc 2 cây và thái lát mỏng 1 cây. Lá chanh rửa sạch lau khô, giữ 5 g lá nguyên để lót hấp, phần 5 g còn lại cuộn tròn thái sợi chỉ thật mảnh. Bóc vỏ 30 g hành tím đập dập, thái lát 1 quả ớt và băm nhỏ 1 quả ớt còn lại.', NULL, NULL),
('vn-hap-01_v4_step_3', 'vn-hap-01', 3, 'marinate', 'Ướp đậm đà phần thịt và da gà', 'Trộn đều 6 g muối hạt, 5 g hạt nêm, 1,5 g tiêu đen xay, 10 g gừng băm, 1 cây sả thái lát, 1 quả ớt thái lát và một ít lá chanh thái chỉ. Xoa đều hỗn hợp lên khắp mình gà, nhét phần gia vị vào mặt trong khoang bụng rồi bọc kín để ướp 15 phút cho thịt ngấm sâu hương thơm.', NULL, 15),
('vn-hap-01_v4_step_4', 'vn-hap-01', 4, 'cook', 'Chuẩn bị xửng hấp và hấp gà chín tới', 'Đổ 700 ml nước lọc vào đáy nồi hấp, đun sôi bùng trên lửa lớn. Lót 2 cây sả đập dập, 20 g gừng thái lát, 30 g hành tím đập dập và 5 g lá chanh nguyên lên mặt vỉ hấp. Đặt nửa con gà ta ngửa phần thịt lên trên, đậy kín nắp và hấp cách thủy ở lửa vừa trong 25 phút.', 'Không mở nắp vung liên tục trong 20 phút đầu để giữ ổn định nhiệt độ hơi nước và tránh thất thoát tinh dầu sả lá chanh.', 25),
('vn-hap-01_v4_step_5', 'vn-hap-01', 5, 'cook', 'Kiểm tra độ chín và làm giòn da gà', 'Dùng đầu đũa nhọn xiên vào phần thịt dày nhất ở má đùi, nếu thấy nước tiết ra trong suốt và không còn màu hồng là gà đã chín hoàn toàn. Tắt bếp, đậy vung ủ thêm 3 phút cho thịt mọng nước rồi vớt gà ra ngâm nhanh vào âu nước đá sạch khoảng 2 phút giúp da se giòn vàng đẹp.', 'Ủ thêm vài phút sau khi tắt bếp rồi mới sốc nhiệt nhanh giúp thớ thịt gà không bị khô xác mà lớp da vẫn săn giòn sần sật.', 5),
('vn-hap-01_v4_step_6', 'vn-hap-01', 6, 'sauce', 'Pha muối tiêu chanh ớt chấm gà', 'Trong lúc chờ gà nguội ráo, cho 6 g muối hạt, 1,5 g tiêu đen xay, 3 g đường cát trắng và 1 quả ớt băm nhỏ vào chén sạch. Vắt nước cốt 1 quả chanh tươi vào chén, khuấy nhẹ cho muối tan bớt tạo thành hỗn hợp chấm sánh nhẹ, thơm dịu vị chanh.', NULL, NULL),
('vn-hap-01_v4_step_7', 'vn-hap-01', 7, 'finish', 'Chặt gà và trình bày cùng lá chanh thái chỉ', 'Khi gà nguội bớt và da se khô, đặt lên thớt dùng dao sắc chặt thành từng miếng vuông vừa ăn, xếp ngay ngắn ra đĩa lớn. Rắc toàn bộ phần lá chanh thái chỉ còn lại phủ đều lên mặt da gà cho dậy mùi thơm, dọn ăn nóng kèm chén muối tiêu chanh ớt.', NULL, NULL),
('vn-hap-02_v4_step_1', 'vn-hap-02', 1, 'prep', 'Sơ chế và chần khử mùi thịt ba chỉ', 'Cạo sạch lông trên bì miếng thịt ba chỉ rút sườn, xát nhẹ 3 g muối hạt khắp miếng thịt rồi rửa sạch. Đun sôi 600 ml nước lọc với 3 g muối còn lại, thả thịt vào chần nhanh 2 phút để loại bỏ bọt bẩn, sau đó vớt ra xả sạch dưới vòi nước mát và thấm ráo.', 'Chần sơ thịt rồi rửa lại giúp nước luộc thứ hai trong veo và miếng thịt luộc trắng sạch, không có mùi hôi.', 3),
('vn-hap-02_v4_step_2', 'vn-hap-02', 2, 'cook', 'Luộc thịt ba chỉ trắng thơm chín tới', 'Đặt thịt vào nồi sạch, đổ 900 ml nước lọc lạnh ngập mặt thịt cùng 30 g hành tím đập dập, 20 g gừng thái lát và 15 ml giấm gạo trắng. Đun lửa lớn đến khi nước sôi bùng thì hớt sạch bọt, hạ xuống lửa vừa để sôi lăn tăn và luộc tiếp 20 phút cho thịt chín mềm.', 'Cho thịt vào từ nước lạnh giúp thịt chín đều từ ngoài vào trong và giữ phần nạc mềm ngọt, không bị co rút.', 20),
('vn-hap-02_v4_step_3', 'vn-hap-02', 3, 'cook', 'Ủ thịt và ngâm nước lạnh giúp giòn bì', 'Dùng đũa xiên qua phần thịt dày nhất, thấy nước ứa ra trong suốt không còn đỏ hồng là thịt đã chín. Tắt bếp và đậy nắp ngâm thịt thêm 5 phút trong nồi, sau đó vớt ngay ra thau nước lạnh sạch ngâm 5 phút cho thịt săn lại, bì giòn và không bị thâm mặt.', NULL, 10),
('vn-hap-02_v4_step_4', 'vn-hap-02', 4, 'sauce', 'Pha mắm tôm đánh bông với dầu nóng', 'Cho 45 g mắm tôm, 12 g đường cát trắng và 5 ml rượu trắng nấu ăn vào chén, vắt nước cốt 1 quả chanh tươi rồi dùng đũa đánh mạnh tay đến khi nổi bọt trắng mịn. Đun thật nóng 15 ml dầu ăn trên chảo nhỏ rồi rưới trực tiếp vào chén mắm tôm, khuấy đều và thêm tỏi băm nhuyễn cùng ớt hiểm thái lát.', 'Rưới dầu ăn đang sôi vào mắm tôm vừa giúp tiệt trùng an toàn, vừa khử bớt mùi nồng và làm bọt mắm bông xốp hấp dẫn.', NULL),
('vn-hap-02_v4_step_5', 'vn-hap-02', 5, 'prep', 'Chuẩn bị cà pháo muối, dưa leo và rau sống', 'Vớt 150 g cà pháo muối giòn ra để ráo nước rồi xếp ra đĩa nhỏ. Dưa leo rửa sạch thái lát chéo vừa ăn; các loại rau sống nhặt rửa sạch để thật ráo nước rồi bày ra đĩa riêng.', NULL, NULL),
('vn-hap-02_v4_step_6', 'vn-hap-02', 6, 'finish', 'Thái lát thịt mỏng và hoàn thiện mâm cơm', 'Thấm thật khô miếng thịt ba chỉ đã nguội, dùng dao bản rộng thật sắc thái ngang thớ thành từng lát mỏng đều từ 2–3 mm để thịt không bị dai. Xếp thịt xen lớp đẹp mắt ra đĩa, đặt cạnh đĩa cà pháo muối, rau sống, dưa leo và chén mắm tôm sủi bọt để thưởng thức ngay với cơm nóng.', NULL, NULL),
('vn-hap-03_v4_step_1', 'vn-hap-03', 1, 'prep', 'Làm sạch khử tanh và khứa thân cá điêu hồng', 'Cá điêu hồng đánh sạch vảy, bỏ mang, moi ruột và cạo sạch lớp màng đen dọc sống lưng để không bị tanh đắng. Chà xát 5 g muối hạt lên khắp thân cá rồi xả lại dưới vòi nước lạnh, thấm thật khô bằng khăn giấy. Dùng dao sắc khứa 3 đường chéo nông ở mỗi mặt thân cá.', 'Cạo sạch màng đen trong bụng cá và phần máu tụ gần xương sống là bí quyết giúp cá hấp ngọt thanh hoàn toàn không tanh.', NULL),
('vn-hap-03_v4_step_2', 'vn-hap-03', 2, 'prep', 'Sơ chế nấm hương, gừng, hành lá, thì là và ớt', 'Ngâm 15 g nấm hương khô trong nước ấm khoảng 20 phút cho nở mềm rồi cắt gốc, thái lát mỏng. Cạo vỏ gừng: 20 g thái lát mỏng, 25 g thái sợi chỉ. Hành lá cắt riêng phần đầu hành đập dập, lá xanh chẻ sợi dài 4 cm. Rửa sạch thì là cắt khúc 4 cm, ớt sừng bỏ hạt thái sợi chỉ.', NULL, 20),
('vn-hap-03_v4_step_3', 'vn-hap-03', 3, 'marinate', 'Ướp cá điêu hồng và chuẩn bị sốt xì dầu', 'Xoa đều lên cả trong lẫn ngoài thân cá 15 ml xì dầu, 15 ml rượu nấu ăn, 4 g hạt nêm và 1 g tiêu đen xay, để cá thấm gia vị trong 15 phút. Trong lúc đó, khuấy tan hỗn hợp sốt gồm 30 ml xì dầu còn lại, 15 ml dầu hào, 8 g đường cát trắng và 50 ml nước lọc.', NULL, 15),
('vn-hap-03_v4_step_4', 'vn-hap-03', 4, 'cook', 'Xếp cá vào đĩa sâu lòng và hấp lửa lớn', 'Rải 20 g gừng thái lát cùng phần đầu hành lá xuống đáy đĩa sâu lòng chịu nhiệt, đặt cá điêu hồng lên trên rồi nhét ít gừng sợi và hành chẻ vào bụng cá, rải nấm hương thái lát xung quanh. Đun sôi 800 ml nước lọc trong nồi hấp ở lửa lớn, đặt đĩa cá vào xửng và đậy kín nắp hấp 15 phút.', 'Nước phải thật sôi trước khi cho cá vào và duy trì lửa lớn để cá chín nhanh, thịt săn ngọt không bị nát bở.', 15),
('vn-hap-03_v4_step_5', 'vn-hap-03', 5, 'cook', 'Rưới sốt xì dầu và hấp thêm cho thấm vị', 'Mở nắp xửng, rưới đều toàn bộ chén sốt xì dầu dầu hào đã pha lên khắp mình cá, rải thêm thì là cắt khúc lên trên. Đậy kín vung và hấp tiếp trên lửa vừa thêm 5 phút cho đến khi mắt cá đục trắng, phần thịt dày ở lưng tách nhẹ khỏi xương là chín hoàn toàn.', NULL, 5),
('vn-hap-03_v4_step_6', 'vn-hap-03', 6, 'finish', 'Xối dầu sôi lên hành gừng và thưởng thức', 'Nhấc đĩa cá ra khỏi xửng, xếp phần hành lá chẻ sợi, 25 g gừng thái sợi chỉ và ớt sừng thái chỉ phủ đều lên thân cá, rắc thêm 1 g tiêu đen xay. Đun sôi 25 ml dầu ăn trên chảo nhỏ rồi dội trực tiếp lên lớp hành gừng để dậy mùi thơm và làm chín tái rau thơm, rưới tiếp 5 ml dầu mè và dọn ăn nóng ngay.', 'Dầu ăn phải đun thật nóng già mới dội lên hành lá và gừng sợi để tạo tiếng xèo nhẹ, làm hành gừng chín thơm mà không bị hăng.', NULL),
('vn-hap-04_v4_step_1', 'vn-hap-04', 1, 'prep', 'Ngâm tôm khô và sơ chế rau củ luộc', 'Rửa sạch 25 g tôm khô rồi ngâm trong 50 ml nước ấm khoảng 20 phút cho mềm, vớt ra để ráo. Tách súp lơ xanh thành miếng vừa ăn, gọt vỏ cà rốt cắt khúc vừa và gọt vỏ su su cắt miếng con chì đều nhau, rửa sạch toàn bộ rồi để ráo nước.', NULL, 20),
('vn-hap-04_v4_step_2', 'vn-hap-04', 2, 'cook', 'Thắng tóp mỡ giòn rụm trong nồi đất', 'Thái 200 g thịt ba chỉ thành hạt lựu vuông 1 cm. Cho thịt vào nồi đất hoặc chảo đáy dày, thắng trên lửa vừa và đảo đều tay khoảng 12 phút đến khi mỡ tiết ra hết và phần tóp mỡ vàng giòn rụm. Vớt tóp mỡ ra đĩa riêng, chắt bớt mỡ nước chỉ giữ lại khoảng 20 ml trong nồi.', 'Thắng tóp mỡ ở lửa vừa không quá gắt sẽ giúp mỡ ra kiệt, tóp vàng giòn đều mà không bị cháy khét hay bắn dầu.', 12),
('vn-hap-04_v4_step_3', 'vn-hap-04', 3, 'cook', 'Luộc rau củ giòn ngọt và giữ màu xanh tươi', 'Đun sôi 1,2 lít nước lọc với 10 g muối ăn trên lửa lớn. Thả cà rốt và su su vào luộc trước 3 phút, sau đó mới cho súp lơ xanh vào luộc chung thêm 2 phút đến khi rau củ vừa chín tới còn độ giòn. Vớt ngay rau củ ra rổ cho ráo hơi nước rồi xếp đẹp mắt ra đĩa.', 'Cho cà rốt và su su vào trước rồi mới thả súp lơ giúp các loại rau chín đồng đều mà súp lơ không bị nhũn hay ngả vàng.', 5),
('vn-hap-04_v4_step_4', 'vn-hap-04', 4, 'sauce', 'Pha hỗn hợp nước mắm đường kho quẹt', 'Bóc vỏ hành tím thái lát mỏng, tỏi băm nhỏ, hành lá thái khoanh nhỏ, rửa sạch tiêu xanh và ớt hiểm. Trong chén sạch, khuấy tan 55 ml nước mắm ngon với 35 g đường cát trắng, 4 g hạt nêm và 50 ml nước lọc để sẵn sàng kho.', NULL, NULL),
('vn-hap-04_v4_step_5', 'vn-hap-04', 5, 'cook', 'Xào tôm khô và rim kho quẹt sánh kẹo', 'Đun nóng lại phần mỡ nước trong nồi đất ở lửa vừa, cho hành tím và tỏi băm vào phi thơm vàng. Đổ tôm khô đã ngâm mềm vào đảo đều 2 phút cho săn thơm rồi rót hỗn hợp nước mắm đường vào, hạ lửa nhỏ liu riu và kho khoảng 8 phút đến khi nước sốt sánh sệt lại.', 'Kho bằng nồi đất trên lửa nhỏ liu riu giúp nước mắm đường keo sánh từ từ, giữ được độ bóng đẹp và hương thơm đậm đà đặc trưng.', 8),
('vn-hap-04_v4_step_6', 'vn-hap-04', 6, 'finish', 'Trộn tóp mỡ tiêu xanh và dọn thưởng thức', 'Thả phần tóp mỡ vàng giòn, 15 g tiêu xanh tươi và 2 quả ớt hiểm vào nồi kho quẹt, đảo đều thêm 1 phút để tóp mỡ áo đều lớp sốt mặn ngọt nhưng vẫn giữ độ giòn nhẹ. Rắc hành lá thái khoanh lên mặt niêu kho quẹt, dọn nóng ngay cạnh đĩa rau củ luộc giòn ngọt.', NULL, NULL),
('vn-hap-05_v4_step_1', 'vn-hap-05', 1, 'prep', 'Làm sạch mực ống và khử mùi tanh', 'Kéo nhẹ đầu mực tách khỏi thân, rút bỏ túi mực, nang sống lưng và toàn bộ nội tạng, cắt bỏ mắt và răng mực rồi lột bỏ lớp màng da sẫm bên ngoài. Bóp nhẹ mực với 30 ml rượu trắng nấu ăn và 15 g gừng đập dập trong 2 phút, xả sạch dưới vòi nước lạnh và thấm thật ráo.', 'Không làm vỡ túi mực khi rút ruột và chỉ dùng rượu gừng chà nhanh với nước mát để thịt mực giữ được độ giòn ngọt tự nhiên.', NULL),
('vn-hap-05_v4_step_2', 'vn-hap-05', 2, 'marinate', 'Khứa thân mực và ướp nhẹ gia vị', 'Dùng dao sắc khứa nhẹ các đường vảy rồng nông trên thân mực (hoặc cắt khoanh dày 2 cm nếu thích), phần râu mực cắt làm đôi. Ướp đều mực với 4 g muối ăn trong 10 phút cho thịt săn nhẹ và đậm đà hơn khi hấp.', NULL, 10),
('vn-hap-05_v4_step_3', 'vn-hap-05', 3, 'prep', 'Sơ chế gừng non, sả, hành tím, lá chanh và ớt', 'Thái 30 g gừng non thành sợi chỉ mảnh. Bóc bẹ già của 3 cây sả, đập dập rồi cắt khúc dài 5 cm. Bóc vỏ 30 g hành tím thái lát mỏng; thái vát 2 quả ớt sừng; lá chanh rửa sạch để một nửa nguyên lá và thái chỉ phần còn lại.', NULL, NULL),
('vn-hap-05_v4_step_4', 'vn-hap-05', 4, 'cook', 'Xếp đĩa và hấp mực nhanh trên lửa lớn', 'Lót một lớp sả đập dập, lá chanh nguyên và một nửa lượng gừng sợi dưới đáy đĩa sâu lòng chịu nhiệt, xếp mực ống lên trên rồi rải nốt gừng sợi, hành tím thái lát và ớt sừng phủ đều. Đun sôi bùng 600 ml nước lọc trong nồi hấp, đặt đĩa mực vào xửng đậy kín vung và hấp lửa lớn trong 8 phút.', 'Hấp mực nhanh ở lửa lớn chỉ 7–9 phút tùy độ dày thân mực; khi thịt mực chuyển trắng đục và các đường khứa nở bung đều là vừa chín tới, tránh hấp quá lâu làm mực ra nước và bị dai.', 8),
('vn-hap-05_v4_step_5', 'vn-hap-05', 5, 'sauce', 'Pha muối tiêu chanh chấm hải sản', 'Trong lúc chờ mực chín, trộn đều 5 g muối ăn còn lại với 2 g tiêu đen xay trong chén nhỏ, vắt nước cốt 1 quả chanh tươi vào khuấy tan tạo thành chén muối tiêu chanh chua cay hài hòa.', NULL, NULL),
('vn-hap-05_v4_step_6', 'vn-hap-05', 6, 'finish', 'Ủ ấm ngắn và trình bày đĩa mực hấp nóng', 'Tắt bếp và giữ đĩa mực trong nồi đậy nắp thêm 1 phút cho hương sả gừng thấm sâu rồi nhấc ra, gạn bỏ bớt phần nước hấp thừa nếu quá nhiều. Rắc phần lá chanh thái chỉ lên trên đĩa mực và thưởng thức nóng ngay cùng muối tiêu chanh.', 'Gạn bớt phần nước hấp tiết ra trước khi dọn giúp miếng mực ráo mặt, giữ trọn độ giòn sần sật và không làm loãng muối chấm.', NULL),
('vn-hap-06_v4_step_1', 'vn-hap-06', 1, 'prep', 'Làm sạch tôm sú và rút chỉ đen dọc lưng', 'Dùng kéo cắt gọn râu tôm, chân và phần gai nhọn ở đầu tôm, dùng tăm nhọn khều nhẹ ở đốt lưng thứ hai để rút sạch đường chỉ đen. Rửa nhanh tôm qua nước muối loãng rồi xả sạch lại với nước mát, để vào rổ cho thật ráo.', 'Rút chỉ đen bằng tăm ngay tại khe đốt vỏ giúp giữ nguyên con tôm đẹp mắt mà không bị rách lưng khi hấp.', NULL),
('vn-hap-06_v4_step_2', 'vn-hap-06', 2, 'marinate', 'Sơ chế gia vị và ướp tôm sú', 'Bóc bẹ già 3 cây sả: thái lát mỏng 1 cây để ướp tôm, 2 cây còn lại đập dập cắt khúc 5 cm. Thái lát mỏng 20 g gừng và 25 g hành tím; bỏ hạt thái sợi chỉ 1 quả ớt sừng. Trộn đều tôm với sả thái lát, 5 g muối hạt, 4 g đường cát trắng và một nhúm nhỏ tiêu đen xay, để ướp 10 phút cho ngấm.', NULL, 10),
('vn-hap-06_v4_step_3', 'vn-hap-06', 3, 'cook', 'Xếp tôm vào nồi cùng nước dừa xiêm', 'Trải lớp sả đập dập, gừng thái lát và hành tím thái lát xuống đáy chảo sâu lòng hoặc nồi đáy rộng. Xếp đều tôm sú đã ướp lên trên mặt lớp sả gừng rồi rót từ từ 350 ml nước dừa xiêm tươi vào nồi sao cho nước dừa xâm xấp khoảng một nửa thân tôm.', 'Nên chọn nước dừa xiêm tươi vừa chín tới có vị ngọt thanh tự nhiên để làm bật vị ngọt của tôm mà không bị chua gắt.', NULL),
('vn-hap-06_v4_step_4', 'vn-hap-06', 4, 'cook', 'Hấp tôm chín đỏ au trong nước dừa', 'Đậy kín nắp nồi và đun trên lửa lớn để nước dừa nhanh chóng sôi bùng, sau đó giữ lửa vừa hấp tiếp khoảng 7 phút cho đến khi toàn bộ vỏ tôm chuyển màu đỏ au, thịt tôm săn chắc và thân uốn cong hình chữ C là chín hoàn toàn.', 'Không hấp tôm quá 10 phút vì thịt tôm sẽ bị teo cứng, mất độ giòn ngọt và nước dừa bay hơi cạn.', 7),
('vn-hap-06_v4_step_5', 'vn-hap-06', 5, 'sauce', 'Pha muối tiêu chanh chấm tôm sú', 'Trong lúc chờ tôm chín, cho 5 g muối hạt còn lại và 2 g tiêu đen xay vào chén nhỏ, vắt nước cốt 1 quả chanh tươi vào khuấy đều cho tan nhẹ thành muối tiêu chanh sánh thơm.', NULL, NULL),
('vn-hap-06_v4_step_6', 'vn-hap-06', 6, 'finish', 'Trình bày đĩa tôm hấp nước dừa nóng hổi', 'Tắt bếp, gắp tôm xếp vòng tròn đẹp mắt quanh đĩa lớn (hoặc quanh miệng vỏ trái dừa tươi), rưới vài muỗng nước hấp dừa sả nóng hổi lên mình tôm cho bóng mượt, điểm thêm ớt sừng thái chỉ và dọn dùng nóng ngay cùng chén muối tiêu chanh.', NULL, NULL),
('vn-cuon-01_v4_step_1', 'vn-cuon-01', 1, 'prep', 'Sơ chế rau sống và làm đồ chua', 'Nhặt sạch xà lách, rau húng quế, hẹ lá và giá đỗ, ngâm nước muối loãng với 2 g muối trong 5 phút rồi xả sạch, vẩy thật ráo nước. Dưa leo bỏ ruột, thái thanh dài mỏng. Cà rốt và củ cải trắng bào sợi, trộn với 100 ml nước lọc, 75 ml giấm gạo, 30 g đường cát trắng và 2 g muối, ngâm ít nhất 15 phút cho thấm vị chua ngọt.', 'Rau sống và giá đỗ phải thật ráo nước thì khi cuốn bánh tráng không bị ướt nhũn hay rách.', 15),
('vn-cuon-01_v4_step_2', 'vn-cuon-01', 2, 'cook', 'Luộc chín thịt ba chỉ và thái lát mỏng', 'Đun sôi 1050 ml nước lọc với 1 củ hành tím đập dập và 2 g muối trên lửa lớn. Thả thịt ba chỉ vào luộc ở lửa vừa khoảng 15 phút đến khi dùng đũa xiên qua không còn nước hồng tiết ra là thịt chín kỹ. Vớt thịt ra ngâm ngay vào nước nguội sạch 10 phút cho thịt săn trắng, để ráo rồi thái lát mỏng.', 'Ngâm thịt ba chỉ qua nước mát ngay sau khi vớt giúp phần bì giòn ngon và lát thịt không bị thâm xỉn.', 15),
('vn-cuon-01_v4_step_3', 'vn-cuon-01', 3, 'cook', 'Luộc chín tôm sú và chẻ đôi', 'Dùng nồi nước luộc thịt đang sôi, thả tôm sú đã rửa sạch vào luộc trên lửa vừa khoảng 4 phút cho đến khi vỏ tôm chuyển đỏ au và thân cong săn chắc là chín hoàn toàn. Vớt tôm ra để nguội bớt, bóc sạch vỏ, rút bỏ chỉ đen trên sống lưng rồi chẻ đôi theo chiều dọc.', NULL, 4),
('vn-cuon-01_v4_step_4', 'vn-cuon-01', 4, 'sauce', 'Nấu tương đen bơ đậu phộng sánh mịn', 'Bắc chảo nhỏ lên bếp với 15 ml dầu ăn ở lửa vừa, cho tỏi băm vào phi thơm vàng nhạt. Hạ lửa nhỏ, trút 100 ml tương đen, 35 g bơ đậu phộng, 15 g đường cát trắng và 50 ml nước lọc vào khuấy đều tay khoảng 3 phút cho sốt hòa quyện sánh mịn, thêm 5 ml giấm gạo cho vị hài hòa rồi tắt bếp.', 'Đun sốt tương trên lửa nhỏ và khuấy liên tục để bơ đậu phộng tan mượt, không bị cháy xém đáy chảo.', NULL),
('vn-cuon-01_v4_step_5', 'vn-cuon-01', 5, 'prep', 'Rang giã đậu phộng và chuẩn bị nguyên liệu cuốn', 'Rang chín vàng đậu phộng trên lửa nhỏ, để nguội rồi xát sạch vỏ lụa, cho vào cối giã dập vừa giữ độ bùi. Ớt sừng bỏ hạt, băm nhỏ. Tách bún tươi thành từng lọn nhỏ vừa tay, xếp tất cả nhân tôm, thịt, dưa leo và rau thơm ra khay gọn gàng.', NULL, NULL),
('vn-cuon-01_v4_step_6', 'vn-cuon-01', 6, 'finish', 'Làm mềm bánh tráng và cuốn gỏi tròn chặt tay', 'Nhúng nhanh từng tờ bánh tráng qua nước sạch hoặc dùng khăn ẩm thoa đều hai mặt cho bánh vừa dẻo. Xếp lá xà lách, rau húng quế, giá đỗ, dưa leo, bún tươi và 2 lát thịt ba chỉ vào phần đầu bánh, gập hai mép bên rồi cuộn chặt 1 vòng. Đặt 3 nửa con tôm mặt đỏ úp xuống cùng 2 cọng hẹ thò đầu ra ngoài, cuộn tròn tiếp đến hết mép bánh. Múc tương ra chén, rắc đậu phộng rang giã dập và ớt sừng băm lên trên để chấm.', 'Đặt tôm sau vòng cuốn đầu tiên sẽ giúp phần lưng tôm đỏ au nổi rõ qua lớp bánh tráng trong veo cực kỳ đẹp mắt.', NULL),
('vn-cuon-02_v4_step_1', 'vn-cuon-02', 1, 'prep', 'Sơ chế rau thơm và cắt lá bánh phở', 'Rửa sạch xà lách xoăn, rau húng Láng và ngò rí, ngâm nước muối loãng 5 phút rồi vớt ra rổ vẩy thật ráo nước để lá bánh phở không bị nhão khi cuốn. Bóc từng lá bánh phở tươi vuông, dùng dao sắc cắt thành miếng chữ nhật kích thước khoảng 25×12 cm vừa chiều dài lá xà lách.', 'Dùng khăn sạch thấm khô lá rau hoàn toàn trước khi cuốn giúp cuốn phở chắc tay và giữ được dáng tròn đẹp.', NULL),
('vn-cuon-02_v4_step_2', 'vn-cuon-02', 2, 'marinate', 'Thái lát và ướp thịt bò thăn', 'Dùng dao sắc thái thịt bò thăn thành lát mỏng ngang thớ. Giã nhuyễn tỏi rồi vắt lấy nước cốt, giữ lại phần xác tỏi để riêng. Cho thịt bò vào tô, ướp cùng nước cốt tỏi, 15 ml nước mắm, 5 g hạt nêm, 2 g tiêu đen xay và 15 ml dầu ăn; trộn đều và để thấm trong 20 phút.', 'Ướp thịt bò với nước cốt tỏi và chút dầu ăn thay vì tỏi băm sẽ giúp xác tỏi không bị cháy khét khi xào lửa lớn mà thịt vẫn mềm bóng.', 20),
('vn-cuon-02_v4_step_3', 'vn-cuon-02', 3, 'prep', 'Làm dưa góp đu đủ xanh và cà rốt', 'Gọt vỏ đu đủ xanh và cà rốt, thái lát mỏng vừa ăn. Xóc đều với 4 g muối ăn, để yên 5 phút cho ra bớt nhựa hăng rồi xả sạch nhiều lần với nước lạnh, vắt nhẹ cho ráo giòn.', NULL, 5),
('vn-cuon-02_v4_step_4', 'vn-cuon-02', 4, 'sauce', 'Pha nước mắm chấm chua ngọt chuẩn Hà Nội', 'Hòa tan 33 g đường cát trắng với 165 ml nước lọc ấm, khuấy đều đến khi tan hết đường rồi để nguội. Rót tiếp 33 ml nước mắm ngon, 33 ml giấm gạo và 5 ml tương ớt vào khuấy đều, thả dưa góp đu đủ cà rốt vào bát nước chấm.', 'Nước chấm phở cuốn Hà Nội chuẩn vị pha theo tỉ lệ 1 mắm : 1 đường : 1 giấm : 5 nước để giữ vị thanh nhẹ, không lấn át hương rau thơm.', NULL),
('vn-cuon-02_v4_step_5', 'vn-cuon-02', 5, 'cook', 'Xào nhanh thịt bò trên lửa lớn', 'Làm nóng chảo đáy dày trên lửa lớn với 25 ml dầu ăn, cho phần xác tỏi vào phi thơm vàng trong 20 giây. Trút toàn bộ thịt bò đã ướp vào đảo thật nhanh tay trên lửa lớn khoảng 2 phút đến khi thịt vừa chuyển màu nâu chín đều, mềm mọng và không ra nước thì trút ngay ra đĩa.', 'Chảo phải thật nóng và xào nhanh tay ở lửa lớn để khóa nước ngọt bên trong từng lát bò, tránh xào lâu làm thịt bị dai.', 2),
('vn-cuon-02_v4_step_6', 'vn-cuon-02', 6, 'finish', 'Cuốn phở gọn đẹp và trình bày', 'Trải phẳng từng miếng bánh phở tươi lên đĩa sạch, đặt 1 lá xà lách, vài cọng húng Láng, ngò rí rồi gắp thịt bò xào dàn đều theo chiều ngang. Gập nhẹ đầu bánh và cuộn tròn chắc tay cho đến hết mép, bày phở cuốn ra đĩa ăn ngay kèm bát nước mắm dưa góp.', NULL, NULL),
('vn-cuon-03_v4_step_1', 'vn-cuon-03', 1, 'prep', 'Làm sạch và khử mùi tai heo', 'Dùng dao cạo sạch lông và chất bẩn ở các kẽ tai heo. Hòa 4 g muối ăn với ít nước cốt chanh chà xát kỹ khắp hai mặt tai trong 3 phút, sau đó ngâm tai heo với 30 ml giấm gạo trong 10 phút rồi rửa sạch lại bằng nước lạnh.', 'Ngâm tai heo qua giấm và muối giúp khử hoàn toàn mùi hôi mà vẫn giữ bề mặt tai trắng sạch.', 10),
('vn-cuon-03_v4_step_2', 'vn-cuon-03', 2, 'cook', 'Luộc chín giòn tai heo và ngâm nước đá', 'Cho tai heo vào nồi với 1200 ml nước lọc ngập mặt, thêm 4 g muối ăn và 15 g gừng tươi đập dập. Đun sôi trên lửa lớn rồi hạ lửa vừa luộc khoảng 15 phút cho tai vừa chín tới, giòn sần sật. Vớt ra ngâm ngay vào thau nước đá lạnh 15 phút cho tai trắng giòn, vớt ráo rồi thái sợi mỏng.', 'Không luộc tai quá mềm sẽ mất độ giòn sần sật đặc trưng; ngâm nước đá ngay khi vớt ra giúp tai giòn và không bị thâm.', 15),
('vn-cuon-03_v4_step_3', 'vn-cuon-03', 3, 'prep', 'Bào mỏng hoa chuối ngâm chanh muối', 'Bóc bỏ các bẹ già bên ngoài bắp hoa chuối tây, dùng dao sắc bào từng lát thật mỏng và thả ngay vào thau nước lạnh đã pha 4 g muối ăn cùng nước cốt 1 quả chanh tươi. Ngâm 15 phút cho ra hết nhựa chát, vớt ra rửa lại hai lần nước sạch rồi vắt nhẹ để thật ráo.', 'Chọn hoa chuối tây thay vì chuối tiêu và ngâm ngập nước chanh muối ngay khi bào giúp sợi hoa chuối trắng tinh, không bị thâm đen.', 15),
('vn-cuon-03_v4_step_4', 'vn-cuon-03', 4, 'prep', 'Sơ chế rau củ, phi hành và giã lạc rang', 'Bào sợi cà rốt, thái lát mỏng hành tây rồi ngâm nước đá 5 phút cho giòn bớt hăng, vớt ráo. Nhặt rửa sạch giá đỗ, rau răm, rau kinh giới và húng bạc hà, để ráo và thái nhỏ rau thơm. Phi thơm vàng giòn hành tím thái lát với 20 ml dầu ăn trên lửa nhỏ rồi vớt ra giấy thấm dầu. Rang vàng lạc, xát vỏ và giã dập vừa.', NULL, NULL),
('vn-cuon-03_v4_step_5', 'vn-cuon-03', 5, 'sauce', 'Pha nước trộn nộm chua ngọt đậm đà', 'Cho 35 ml nước mắm ngon, 35 g đường cát trắng và nước cốt 1 quả chanh tươi còn lại vào bát, khuấy kỹ cho đường tan hoàn toàn rồi thêm tỏi băm và 1 quả ớt tươi băm nhuyễn vào đảo đều.', NULL, NULL),
('vn-cuon-03_v4_step_6', 'vn-cuon-03', 6, 'finish', 'Trộn nộm thấm vị và trình bày ra đĩa', 'Cho hoa chuối, tai heo thái sợi, cà rốt, hành tây và giá đỗ vào âu lớn. Rưới từ từ nước trộn nộm vào, đảo nhẹ tay và để 10 phút cho nguyên liệu thấm đều. Chắt bớt nước tiết ra nếu có, thêm rau răm, rau kinh giới, húng bạc hà và 2/3 lượng lạc rang vào trộn đều lần cuối. Bày nộm ra đĩa, rắc phần lạc rang còn lại, hành phi giòn và ớt thái lát lên trên.', NULL, 10),
('vn-cuon-04_v4_step_1', 'vn-cuon-04', 1, 'cook', 'Làm sạch và luộc chín thịt gà ta', 'Chà xát đùi gà với 2 g muối ăn và vài lát gừng tươi để khử mùi hôi rồi rửa sạch. Cho gà vào nồi với 1200 ml nước lọc ngập mặt, thêm 4 g muối ăn, phần gừng còn lại và 10 g hành tím đập dập. Đun sôi trên lửa lớn rồi hạ lửa nhỏ luộc liu riu khoảng 20 phút, tắt bếp đậy vung ngâm gà thêm 10 phút cho thịt chín đều từ trong ra ngoài, không còn đỏ sát xương.', 'Luộc lửa nhỏ và ngâm thêm trong nồi sau khi tắt bếp giúp thịt gà mềm mọng, giữ trọn vị ngọt mà da gà không bị nứt rách.', 20),
('vn-cuon-04_v4_step_2', 'vn-cuon-04', 2, 'prep', 'Ngâm giấm đá hành tây và sơ chế rau củ', 'Bào sợi thật mỏng bắp cải trắng và cà rốt, rửa sạch rồi để rổ cho thật ráo nước. Hành tây thái lát mỏng, trộn cùng 30 ml giấm gạo, 12 g đường cát trắng, 2 g muối ăn và vài viên đá lạnh, để ngăn mát tủ lạnh 15 phút cho hành giòn và dịu hẳn vị hăng rồi vớt ra vắt ráo.', 'Ngâm hành tây trong giấm đường lạnh là bí quyết giúp sợi hành trong giòn và ngọt dịu tự nhiên.', 15),
('vn-cuon-04_v4_step_3', 'vn-cuon-04', 3, 'prep', 'Chuẩn bị rau thơm, hành phi và lạc rang', 'Nhặt rửa sạch rau răm rồi cắt khúc ngắn; lá chanh thái chỉ thật mảnh. Băm nhỏ tỏi và 2 quả ớt; quả ớt còn lại bỏ hạt thái sợi. Phi thơm vàng 20 g hành tím thái lát với 15 ml dầu ăn trên lửa nhỏ rồi vớt ráo dầu. Rang chín vàng đậu phộng, xát vỏ và giã dập.', NULL, NULL),
('vn-cuon-04_v4_step_4', 'vn-cuon-04', 4, 'sauce', 'Pha nước trộn gỏi chua ngọt', 'Khuấy tan 45 ml nước mắm ngon với 30 g đường cát trắng và nước cốt 2 quả chanh tươi trong chén đến khi đường tan hết. Thêm tỏi và ớt băm vào khuấy đều, nêm lại để đạt vị chua mặn ngọt hài hòa.', 'Khuấy tan hoàn toàn đường trong nước mắm và nước cốt chanh trước khi thả tỏi ớt sẽ giúp nước trộn dậy mùi thơm dịu hơn.', NULL),
('vn-cuon-04_v4_step_5', 'vn-cuon-04', 5, 'prep', 'Xé sợi thịt gà và ướp thấm trước', 'Vớt gà ra để nguội bớt rồi lọc bỏ xương, xé thịt theo thớ thành miếng dài vừa ăn. Cho thịt gà vào âu, rưới khoảng 1/3 lượng nước trộn gỏi vào đảo đều và ướp 5 phút cho từng thớ thịt đậm đà.', NULL, 5),
('vn-cuon-04_v4_step_6', 'vn-cuon-04', 6, 'finish', 'Trộn gỏi đều tay và hoàn thiện đĩa gỏi', 'Cho bắp cải bào, cà rốt và hành tây đã vắt ráo vào âu thịt gà, rưới phần nước trộn còn lại và dùng tay đeo găng bóp trộn nhẹ nhàng cho hòa quyện. Thêm rau răm và lá chanh thái chỉ vào đảo đều lần cuối, bày ra đĩa rồi rắc hành phi, đậu phộng rang giã dập và ớt thái sợi lên trên.', NULL, NULL),
('vn-cuon-05_v4_step_1', 'vn-cuon-05', 1, 'prep', 'Bào sợi và ngâm khử nhựa đu đủ, cà rốt', 'Khía nhẹ vài đường quanh vỏ đu đủ xanh cho chảy bớt nhựa rồi rửa sạch, gọt vỏ, bỏ hạt và bào sợi mỏng dài. Cà rốt gọt vỏ, bào sợi tương tự. Hòa 600 ml nước lọc với 20 ml giấm gạo và 5 g muối ăn, thả đu đủ và cà rốt vào ngâm 20 phút cho ra sạch nhựa.', 'Ngâm nước giấm muối giúp sợi đu đủ xanh giòn trắng, hết hẳn vị hăng chát tự nhiên.', 20),
('vn-cuon-05_v4_step_2', 'vn-cuon-05', 2, 'prep', 'Bóp muối, ướp đường giúp sợi nộm giòn tan', 'Vớt đu đủ và cà rốt ra, bóp nhẹ với 5 g muối ăn trong 2 phút rồi xả sạch lại bằng nước lạnh và vắt ráo. Trộn đều sợi rau củ với 20 g đường cát trắng, để yên 15 phút cho sợi đu đủ cứng giòn rồi vắt thật ráo phần nước tiết ra.', 'Ướp đường rồi vắt ráo trước khi trộn là bí quyết giúp sợi nộm giòn sần sật mà không bị chảy nước khi bày đĩa.', 15),
('vn-cuon-05_v4_step_3', 'vn-cuon-05', 3, 'cook', 'Rang lạc, phi hành tím và xé bò khô', 'Rang lạc trên lửa nhỏ khoảng 8 phút đến khi chín thơm vàng đều, để nguội bóc vỏ lụa và giã dập. Phi thơm vàng hành tím thái lát với 10 ml dầu ăn trên lửa nhỏ rồi vớt ra giấy thấm dầu. Xé thịt bò khô thành sợi mảnh vừa ăn, nhặt rửa sạch rau kinh giới và húng bạc hà rồi cắt nhỏ.', NULL, 8),
('vn-cuon-05_v4_step_4', 'vn-cuon-05', 4, 'sauce', 'Pha nước trộn nộm chua ngọt cay nhẹ', 'Khuấy tan 45 ml nước mắm ngon với 25 g đường cát trắng và nước cốt 1,5 quả chanh tươi đến khi tan hết đường. Thêm tỏi băm nhuyễn và 1 quả ớt tươi băm nhỏ vào đảo đều, nếm lại cho vừa vị chua ngọt mặn hài hòa.', NULL, NULL),
('vn-cuon-05_v4_step_5', 'vn-cuon-05', 5, 'prep', 'Áo sơ nộm với rau thơm và bò khô', 'Cho đu đủ xanh, cà rốt đã vắt ráo, thịt bò khô xé sợi cùng rau kinh giới và húng bạc hà vào âu trộn lớn, đảo tơi đều để các nguyên liệu phân bổ hài hòa.', NULL, NULL),
('vn-cuon-05_v4_step_6', 'vn-cuon-05', 6, 'finish', 'Rưới nước trộn và trình bày thưởng thức', 'Rưới đều bát nước trộn nộm vào âu, dùng đũa trộn nhẹ tay cho từng sợi đu đủ và bò khô thấm đẫm gia vị. Gắp nộm ra đĩa sâu lòng, rắc lạc rang giã dập, hành phi giòn và vài lát ớt tươi lên trên rồi thưởng thức ngay.', 'Chỉ rắc lạc rang và hành phi lên đĩa nộm ngay trước khi ăn để giữ độ giòn bùi và mùi thơm hấp dẫn.', NULL),
('vn-cuon-06_v4_step_1', 'vn-cuon-06', 1, 'prep', 'Sơ chế cây sả và băm tôm thịt', 'Rửa sạch 12 cây sả, bóc bớt bẹ già. Lấy 10 cây cắt khúc dài 14 cm, đập dập nhẹ phần đầu củ để làm xiên nướng giúp tinh dầu sả thấm vào thịt; 2 cây sả còn lại băm thật nhuyễn. Tôm tươi bóc vỏ, rút chỉ đen và băm nhuyễn.', NULL, NULL),
('vn-cuon-06_v4_step_2', 'vn-cuon-06', 2, 'marinate', 'Quết dẻo nhân nem lụi và ướp lạnh', 'Trộn đều 200 g thịt nạc vai heo xay, 300 g giò sống và tôm băm cùng sả băm, hành tím băm, 1/2 lượng tỏi băm, 16 g bột năng, 15 ml dầu hào, 20 ml dầu màu điều, 22 g đường cát trắng, 4 g hạt nêm, 5 ml nước mắm và 2 g tiêu đen xay. Quết mạnh tay 5 phút cho khối thịt dẻo mịn, bọc kín và cất ngăn mát tủ lạnh ít nhất 60 phút cho thấm và se chắc.', 'Giò sống đã có sẵn độ mặn nên chỉ nêm thêm rất ít nước mắm; ướp lạnh giúp thịt dẻo và dễ nặn bám chặt quanh thân sả.', 60),
('vn-cuon-06_v4_step_3', 'vn-cuon-06', 3, 'prep', 'Bọc nhân thịt quanh cây sả', 'Thoa nhẹ 10 ml dầu ăn lên găng tay, lấy một nắm thịt vừa tay dàn mỏng rồi bọc kín quanh phần đầu đập dập của từng cây sả, miết nhẹ hai đầu cho thịt ôm chặt không bị rơi tuột khi nướng, chừa phần cuống sả để cầm.', 'Nặn khối thịt thuôn dài vừa phải và miết kỹ hai đầu mép giúp nem chín đều từ trong ra ngoài mà không bị nứt.', NULL),
('vn-cuon-06_v4_step_4', 'vn-cuon-06', 4, 'cook', 'Nướng nem lụi và quét sốt mật ong bóng đẹp', 'Làm nóng nồi chiên không dầu hoặc lò nướng ở 180°C trước 5 phút. Xếp nem lụi lên vỉ và nướng 15 phút cho thịt săn chín bên trong. Pha 15 ml mật ong, 10 ml dầu hào và 10 ml dầu màu điều, lấy nem ra quét đều lên khắp bề mặt rồi nướng tiếp 10 phút ở 180°C đến khi nem chín kỹ hoàn toàn, vàng ruộm hơi xém cạnh và dậy mùi thơm lừng.', 'Quét hỗn hợp mật ong dầu điều ở lượt nướng sau giúp nem có màu nâu cánh gián bóng mượt mà không bị cháy khét đường.', 25),
('vn-cuon-06_v4_step_5', 'vn-cuon-06', 5, 'sauce', 'Chuẩn bị rau cuốn và pha nước chấm chua ngọt', 'Rửa sạch xà lách rau thơm để ráo; thái lát mỏng dài dưa leo, dứa chín và chuối xanh (ngâm nước muối loãng chống thâm rồi vớt ráo). Tách bún tươi vừa ăn và bày bánh tráng ra đĩa. Khuấy tan 45 ml nước mắm, 20 g đường cát trắng và 60 ml nước lọc, thêm nước cốt 1 quả chanh, phần tỏi băm còn lại và ớt băm nhuyễn.', NULL, NULL),
('vn-cuon-06_v4_step_6', 'vn-cuon-06', 6, 'finish', 'Trình bày nem lụi và cuốn bánh tráng thưởng thức', 'Bày nem lụi nóng ra đĩa lớn bên cạnh bún tươi, bánh tráng và rổ rau sống. Khi ăn, trải bánh tráng, xếp xà lách, rau thơm, dưa leo, chuối xanh, dứa thơm, bún tươi và tuốt 1 cây nem lụi đặt vào giữa rồi cuốn chặt tay, chấm cùng nước mắm tỏi ớt.', NULL, NULL),
('vn-bun-01_v4_step_1', 'vn-bun-01', 1, 'prep', 'Chần sạch xương ống bò', 'Rửa sơ xương ống bò rồi cho vào nồi với 1 lít nước lọc và 5 g muối ăn, đun lửa lớn đến khi sôi bùng và chần trong 5 phút cho tiết hết bọt bẩn. Đổ bỏ toàn bộ nước chần, rửa từng khúc xương dưới vòi nước lạnh cho thật sạch cặn.', 'Chần bỏ nước đầu và rửa sạch xương dưới vòi nước giúp nước dùng trong, không bị mùi hôi gây.', 5),
('vn-bun-01_v4_step_2', 'vn-bun-01', 2, 'prep', 'Nướng gia vị tươi và rang thảo mộc khô', 'Nướng 50 g gừng tươi, 1 củ hành tây và 45 g hành tím khô trên bếp cho đến khi sém vàng mặt ngoài và dậy mùi thơm, cạo sạch lớp cháy đen rồi rửa qua và đập dập nhẹ. Cho hoa hồi khô, quế thanh khô, thảo quả khô, hạt mùi khô và đinh hương khô lên chảo khô rang ở lửa nhỏ khoảng 2 phút đến khi thơm nồng thì cho vào túi vải sạch buộc chặt.', 'Rang thảo mộc ở lửa nhỏ vừa đủ dậy tinh dầu thơm; tránh rang cháy vì sẽ làm nước phở bị đắng và sậm màu.', 10),
('vn-bun-01_v4_step_3', 'vn-bun-01', 3, 'cook', 'Ninh nước dùng xương bò thanh ngọt', 'Cho xương ống bò đã chần sạch vào nồi lớn cùng 2,5 lít nước lọc lạnh, đun sôi trên lửa lớn rồi hớt thật kỹ lớp bọt nổi. Hạ xuống lửa nhỏ liu riu, thả gừng nướng, hành tây nướng và hành tím nướng vào ninh khoảng 2,5 giờ, sau đó mới cho túi thảo mộc khô vào ninh tiếp 30 phút để hương gia vị không bị bay hơi quá sớm.', 'Chỉ giữ lửa liu riu và không đậy kín nắp hoàn toàn để nước dùng sôi êm, trong và không bị đục.', 180),
('vn-bun-01_v4_step_4', 'vn-bun-01', 4, 'marinate', 'Thái mỏng và ướp thịt thăn bò', 'Thịt thăn bò thấm thật khô bằng khăn giấy, thái lát mỏng 1–2 mm ngang thớ để thịt mềm không dai. Trộn đều thịt bò với 1/2 lượng tỏi khô băm, 5 g gừng tươi băm nhuyễn và 2 g tiêu đen xay, ướp khoảng 15 phút cho thịt ngấm hương thơm.', NULL, 15),
('vn-bun-01_v4_step_5', 'vn-bun-01', 5, 'cook', 'Lọc và nêm nếm nước dùng phở', 'Vớt bỏ xương ống bò, hành gừng nướng và túi gia vị khô ra khỏi nồi nước dùng. Nêm vào nồi 15 g muối ăn, 30 g đường phèn và 20 ml nước mắm ngon, khuấy tan rồi nếm lại sao cho nước dùng đạt vị ngọt xương thanh tao, mặn dịu hài hòa và giữ sôi nóng trên lửa nhỏ.', NULL, NULL),
('vn-bun-01_v4_step_6', 'vn-bun-01', 6, 'prep', 'Chuẩn bị rau thơm và trụng bánh phở', 'Củ hành tây còn lại thái lát thật mỏng ngâm nước đá lạnh cho giòn và bớt hăng. Hành lá tươi tách đầu hành chẻ mỏng và phần lá xanh thái nhỏ; ngò gai thái khúc ngắn. Rửa sạch húng quế, giá đỗ, cắt múi chanh tươi và thái lát ớt tươi. Đun sôi nồi nước khác, trụng bánh phở tươi khoảng 10–15 giây cho nóng mềm rồi vẩy ráo, chia đều vào 4 tô.', NULL, NULL),
('vn-bun-01_v4_step_7', 'vn-bun-01', 7, 'cook', 'Xào tái lăn thịt bò trên lửa lớn', 'Bắc chảo sâu lòng lên bếp, cho 30 ml dầu ăn vào đun đến khi dầu thật nóng bốc khói nhẹ thì cho 1/2 lượng tỏi băm còn lại vào phi thơm. Trút toàn bộ thịt thăn bò đã ướp vào đảo thật nhanh tay trên lửa lớn trong khoảng 45 giây, rưới 10 ml nước mắm ngon lên thành chảo cho dậy mùi xém thơm rồi tắt bếp ngay khi thịt vừa chuyển tái hồng.', 'Chảo phải thật nóng và xào không quá 1 phút để thịt bò giữ được độ mềm ngọt bên trong và thơm cạnh ngoài.', 1),
('vn-bun-01_v4_step_8', 'vn-bun-01', 8, 'finish', 'Chan nước dùng và hoàn thiện tô phở', 'Xếp thịt thăn bò xào tái lăn lên trên bánh phở, thêm đầu hành chẻ, hành tây thái lát, hành lá và ngò gai. Chan nước dùng đang sôi sùng sục ngập mặt bánh phở để sức nóng giúp thịt bò chín hoàn toàn và quyện hương, dọn nóng ngay cùng húng quế, giá đỗ, chanh tươi và ớt tươi.', NULL, NULL),
('vn-bun-02_v4_step_1', 'vn-bun-02', 1, 'prep', 'Sơ chế thịt ba chỉ và thịt nạc vai', 'Xát nhẹ thịt ba chỉ heo với 3 g muối ăn rồi rửa sạch dưới vòi nước lạnh, thấm thật ráo và thái lát mỏng khoảng 0,5 cm bản vừa ăn. Để riêng thịt nạc vai heo xay vào tô sạch.', NULL, 5),
('vn-bun-02_v4_step_2', 'vn-bun-02', 2, 'prep', 'Vắt nước cốt sả hành và thắng nước hàng', 'Xay thật nhuyễn sả tươi và hành tím khô với 20 ml nước lọc rồi dùng rây vắt lấy phần nước cốt thơm, bỏ bã để thịt nướng không bị cháy sém xác hành sả. Thắng chảy 8 g đường vàng trên chảo nhỏ với 1 muỗng canh nước lọc đến khi chuyển màu nâu cánh gián thì tắt bếp.', 'Chỉ dùng nước cốt sả hành thay vì xác băm giúp miếng chả lên màu vàng ruộm mà không bị lốm đốm cháy đắng.', NULL),
('vn-bun-02_v4_step_3', 'vn-bun-02', 3, 'marinate', 'Ướp chả miếng và chả viên đậm đà', 'Pha hỗn hợp ướp gồm nước cốt sả hành, nước hàng vừa thắng, 10 ml nước mắm ngon, 4 g mắm tôm, 10 g đường cát trắng, 6 g hạt nêm, 4 g muối ăn và 3 g tiêu đen xay. Chia đôi hỗn hợp trộn kỹ vào thịt ba chỉ và thịt nạc vai xay, bọc kín để ngăn mát tủ lạnh ít nhất 1 giờ cho thấm vị. Trước khi nướng 15 phút, trộn thêm 1/2 muỗng cà phê nước cốt chanh tươi vào cả hai tô thịt để chả mềm mọng.', NULL, 60),
('vn-bun-02_v4_step_4', 'vn-bun-02', 4, 'prep', 'Làm dưa góp đu đủ cà rốt giòn ngon', 'Đu đủ xanh và cà rốt thái lát mỏng, bóp nhẹ với 3 g muối ăn để 5 phút cho ra nước hăng rồi xả sạch, vắt thật ráo. Trộn đều đu đủ cà rốt với 10 g đường cát trắng, 15 ml giấm gạo, 2 g muối ăn và 1 quả ớt hiểm đỏ băm, ướp trong ngăn mát 20 phút cho thấm giòn.', 'Bóp muối xả sạch và vắt ráo nước giúp đu đủ xanh hết nhựa mà vẫn giữ được độ giòn sần sật.', 20),
('vn-bun-02_v4_step_5', 'vn-bun-02', 5, 'cook', 'Vê chả viên và nướng thịt trên than hoa', 'Nặn thịt nạc vai xay thành từng viên tròn rồi ấn dẹt vừa ăn. Xếp chả miếng ba chỉ và chả viên lên vỉ, nướng trên bếp than hoa hồng lửa vừa (hoặc nồi chiên không dầu 190°C), lật đều tay mỗi 1–2 phút và phết nhẹ 15 ml dầu ăn lên bề mặt để chả không bị khô. Nướng khoảng 15–18 phút đến khi thịt chín kỹ hoàn toàn, mỡ tươm xèo xèo và hai mặt vàng xém thơm nức.', 'Không để than quá bốc lửa; lật vỉ đều tay và phết dầu ăn mỏng giúp chả chín sâu bên trong mà lớp ngoài bóng đẹp.', 16),
('vn-bun-02_v4_step_6', 'vn-bun-02', 6, 'sauce', 'Pha nước mắm chấm bún chả ấm nóng', 'Cho 230 ml nước lọc còn lại vào nồi nhỏ cùng 80 ml nước mắm ngon, 55 g đường cát trắng, 15 ml giấm gạo và phần nước cốt chanh tươi còn lại. Đun ở lửa nhỏ cho đường tan hoàn toàn và nước chấm vừa ấm nóng (không đun sôi mạnh để giữ hương thơm của mắm và chanh), tắt bếp rồi thả tỏi khô băm và 1 quả ớt hiểm đỏ băm vào.', NULL, NULL),
('vn-bun-02_v4_step_7', 'vn-bun-02', 7, 'finish', 'Rửa rau sống và bày biện thưởng thức', 'Rửa sạch xà lách tươi, lá tía tô cùng rau kinh giới và húng lủi, vẩy thật ráo nước. Chia bún gạo tươi ra đĩa, múc nước chấm ấm ra 4 bát, thả chả miếng, chả viên nướng nóng hổi cùng dưa góp đu đủ cà rốt vào bát và thưởng thức ngay cùng rau sống.', NULL, NULL),
('vn-bun-03_v4_step_1', 'vn-bun-03', 1, 'prep', 'Chần sạch chân giò heo và xương ống bò', 'Chà rửa chân giò heo và xương ống bò với 8 g muối ăn, sau đó cho vào nồi nước sôi chần 5 phút cho ra hết bọt bẩn rồi vớt ra rửa thật sạch dưới vòi nước lạnh.', NULL, 5),
('vn-bun-03_v4_step_2', 'vn-bun-03', 2, 'cook', 'Ninh nước dùng xương bò và chân giò', 'Cho xương ống bò, chân giò heo vào nồi cùng 2,5 lít nước lọc lạnh, thả 3 cây sả cây đập dập bó gọn và 20 g gừng tươi đập dập. Đun sôi trên lửa lớn, hớt sạch bọt rồi hạ lửa nhỏ ninh khoảng 75–90 phút; khi chân giò vừa chín mềm dẻo thì vớt ra ngâm nhanh vào nước nguội để da giòn, không bị thâm.', 'Vớt chân giò ngay khi vừa mềm sần sật và giữ lửa nhỏ khi ninh xương giúp nước dùng trong veo, không bị đục.', 80),
('vn-bun-03_v4_step_3', 'vn-bun-03', 3, 'cook', 'Luộc chín bắp bò hoa thơm mùi sả gừng', 'Cho bắp bò hoa vào nồi riêng với 500 ml nước lọc, 1 cây sả cây đập dập, 10 g gừng tươi và 1 củ hành tím đập dập, luộc lửa vừa khoảng 35–40 phút đến khi xiên đũa qua thấy thịt chín mềm. Vớt bắp bò ra để nguội hoàn toàn trong ngăn mát 20 phút rồi thái lát mỏng.', 'Để bắp bò nguội hẳn rồi ủ mát trước khi cắt giúp lát thịt săn chắc, mỏng đều và không bị nát.', 35),
('vn-bun-03_v4_step_4', 'vn-bun-03', 4, 'sauce', 'Phi sa tế sả ớt và lọc nước mắm ruốc', 'Hòa tan 25 g mắm ruốc Huế với 200 ml nước lọc, khuấy đều rồi để yên 15 phút cho lắng hết sạn cặn. Trong chảo nhỏ, đun nóng 25 ml dầu ăn và 20 ml dầu màu điều trên lửa vừa, phi thơm hành tím băm, tỏi khô băm và 2 cây sả băm nhuyễn; tắt bớt lửa rồi cho ớt bột Huế, 10 ml nước mắm và 5 g đường phèn vào đảo nhanh 2 phút thành hỗn hợp sa tế sánh đỏ.', 'Cho ớt bột khi dầu không quá sôi giúp sa tế lên màu đỏ tươi đẹp mà không bị cháy đen khét.', NULL),
('vn-bun-03_v4_step_5', 'vn-bun-03', 5, 'cook', 'Nêm mắm ruốc, luộc chả cua và hoàn thiện nước dùng', 'Vớt bỏ xương bò và sả gừng cũ khỏi nồi nước dùng, từ từ gạn lấy phần nước trong của mắm ruốc Huế đổ vào nồi (bỏ phần cặn đáy). Khi nước dùng sôi nhẹ, dùng muỗng múc từng viên chả cua Huế thả vào luộc khoảng 4–5 phút đến khi viên chả nổi lên chín căng thì vớt ra. Cho 2/3 phần sa tế vào nồi, nêm 20 ml nước mắm ngon, 15 g đường phèn, 10 g muối ăn và 12 g hạt nêm cho vị đậm đà hài hòa.', NULL, 10),
('vn-bun-03_v4_step_6', 'vn-bun-03', 6, 'finish', 'Sơ chế rau, trụng bún và lên tô bún bò Huế', 'Thái lát mỏng hành tây, cắt nhỏ hành lá và ngò rí; chuẩn bị hoa chuối bào, giá đỗ và chanh tươi. Trụng bún sợi to qua nước sôi cho mềm tơi rồi chia vào 4 tô, xếp khoanh chân giò heo, bắp bò thái lát và chả cua lên trên, chan ngập nước dùng nóng hổi, rắc hành tây, hành lá, ngò rí và dọn kèm sa tế còn lại cùng đĩa rau sống.', NULL, NULL);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('vn-bun-04_v4_step_1', 'vn-bun-04', 1, 'prep', 'Làm sạch cua đồng, khều gạch và lọc nước cua', 'Ngâm cua đồng tươi 30 phút cho nhả bùn rồi rửa nhiều lần thật sạch. Tách mai, bỏ yếm và dùng đầu đũa khều phần gạch vàng trong mai ra chén riêng. Giã nhuyễn phần thân cua cùng 3 g muối ăn, sau đó hòa với 2,4 lít nước lọc chia làm 3 lượt, bóp nhẹ và lọc qua rây mịn bỏ xác để thu nồi nước thịt cua sánh.', 'Cho chút muối khi giã cua và khuấy đều trước khi đun giúp protein cua kết dính thành tảng riêu chắc mịn.', NULL),
('vn-bun-04_v4_step_2', 'vn-bun-04', 2, 'cook', 'Rán vàng giòn đậu phụ trắng', 'Làm nóng chảo với 85 ml dầu ăn trên lửa vừa, thả từng miếng đậu phụ trắng đã thấm khô vào rán vàng đều các mặt trong khoảng 6–8 phút rồi vớt ra đĩa có giấy thấm dầu cho ráo bớt dầu thừa.', NULL, 7),
('vn-bun-04_v4_step_3', 'vn-bun-04', 3, 'cook', 'Phi hành xào gạch cua và cà chua', 'Dùng chảo khác đun nóng 15 ml dầu ăn, cho hành tím khô thái lát vào phi vàng thơm rồi vớt bớt nửa phần hành phi để riêng. Cho gạch cua vào đảo nhanh 1 phút trên lửa vừa đến khi dậy mùi thơm béo thì trút ra chén. Tiếp tục cho cà chua bổ múi cau vào chảo xào 3 phút cùng 10 ml nước mắm ngon và 5 g đường cát trắng cho cà chua mềm tiết màu đỏ cam.', 'Phi thơm hành tím rồi xào gạch cua riêng trước khi xào cà chua giúp nước dùng lên màu đỏ cam óng và thơm béo hơn.', 4),
('vn-bun-04_v4_step_4', 'vn-bun-04', 4, 'cook', 'Nấu riêu cua đồng đóng tảng xốp đẹp', 'Đặt nồi nước cua đã lọc lên bếp, nêm 10 g mắm tôm Bắc và 10 ml nước mắm ngon. Đun ở lửa vừa, dùng muôi khuấy nhẹ nhàng sát đáy nồi theo một chiều trong 3 phút đầu cho thịt cua không bén đáy; khi nước bắt đầu ấm nóng và riêu nổi lấm tấm thì ngưng khuấy, hạ lửa nhỏ. Đợi riêu kết thành tảng dày nổi lên mặt nước thì vớt nhẹ tảng riêu ra tô riêng để không bị vỡ.', 'Ngưng khuấy ngay khi nước bắt đầu nóng già và tuyệt đối không để sôi bùng mạnh để tảng riêu không bị tan nát.', 8),
('vn-bun-04_v4_step_5', 'vn-bun-04', 5, 'cook', 'Hoàn thiện nước dùng bún riêu chua thanh', 'Lọc 30 g cơm mẻ qua rây với 100 ml nước lọc cho vào nồi nước dùng cùng cà chua xào, gạch cua xào, đậu phụ rán vàng và 45 ml giấm bỗng. Nêm thêm 4 g muối ăn và 10 g hạt nêm cho vị chua thanh ngọt dịu hài hòa, đun sôi lăn tăn thêm 5 phút để đậu phụ ngấm vị nước riêu.', NULL, 5),
('vn-bun-04_v4_step_6', 'vn-bun-04', 6, 'finish', 'Thái bắp bò, chuẩn bị rau và chan bún nóng', 'Thái thật mỏng thịt bắp bò tươi; rửa sạch xà lách, rau kinh giới, lá tía tô với 3 g muối pha loãng rồi thái rối, cắt nhỏ hành lá và thái lát ớt tươi. Trụng bún tươi qua nước sôi chia vào 4 tô, xếp tảng riêu cua, đậu rán và cà chua lên trên; nhúng nhanh thịt bắp bò vào nồi nước dùng đang sôi 15–20 giây cho vừa chín tái mềm rồi xếp lên tô, chan ngập nước riêu nóng, rắc hành lá và dọn kèm rau sống, mắm tôm.', NULL, NULL),
('vn-bun-05_v4_step_1', 'vn-bun-05', 1, 'marinate', 'Sơ chế và ướp thịt nạc dăm nướng', 'Rửa thịt nạc dăm heo với 2 g muối ăn rồi xả sạch, thấm khô và thái lát mỏng 0,5 cm. Xay nhuyễn sả tươi, 20 g hành tím khô và 2/3 lượng tỏi khô, vắt lấy nước cốt thơm (bỏ xác) rồi trộn với 20 ml dầu hào, 15 ml mật ong nguyên chất, 15 ml nước mắm ngon, 10 g đường cát trắng, 2 g muối ăn và 10 ml dầu ăn. Trộn đều với thịt, bọc kín ướp ngăn mát ít nhất 1 giờ.', 'Vắt bỏ xác sả tỏi khi ướp giúp thịt thấm sâu hương thơm mà không bị cháy đen khi nướng trên lửa cao.', 60),
('vn-bun-05_v4_step_2', 'vn-bun-05', 2, 'prep', 'Làm đồ chua củ cải trắng và cà rốt', 'Củ cải trắng và 2/3 củ cà rốt bào sợi mảnh, bóp nhẹ với 2 g muối ăn để 10 phút cho mềm bớt hăng rồi xả sạch, vắt thật ráo. Trộn đều sợi củ với 20 g đường cát trắng và 35 ml giấm gạo, ủ trong ngăn mát tủ lạnh ít nhất 20 phút cho thấm giòn.', NULL, 20),
('vn-bun-05_v4_step_3', 'vn-bun-05', 3, 'cook', 'Cuốn chả giò và chiên vàng giòn', 'Trộn 150 g thịt heo xay với 1/3 củ cà rốt băm nhỏ, 10 g hành tím băm, 5 ml nước mắm ngon và 1 g muối ăn. Trải bánh tráng cuốn chả giò, múc lượng nhân vừa đủ cuộn tròn chặt tay thành 10–12 cuốn. Đun nóng 175 ml dầu ăn trên lửa vừa trong chảo sâu lòng, thả chả giò vào chiên khoảng 8–10 phút đến khi vỏ ngoài vàng rộm, giòn đều và nhân thịt heo chín kỹ thì vớt ra giấy thấm dầu.', 'Chiên chả giò ở lửa vừa giúp phần nhân thịt chín thấu bên trong mà lớp vỏ bánh tráng ngoài vẫn vàng giòn lâu.', 10),
('vn-bun-05_v4_step_4', 'vn-bun-05', 4, 'cook', 'Nướng thịt xém cạnh và thắng mỡ hành', 'Xiên thịt nạc dăm đã ướp lên vỉ nướng than hoa (hoặc xếp vào nồi chiên không dầu ở 200°C), nướng khoảng 14–16 phút và trở mặt giữa chừng đến khi thịt chín hẳn, vàng óng xém cạnh thơm lừng. Trong chén chịu nhiệt, trộn hành lá tươi thái nhỏ với 1 g muối ăn; đun sôi 15 ml dầu ăn trên chảo nhỏ rồi rưới nhanh vào chén hành, đảo đều cho hành chín tái xanh mướt.', NULL, 15),
('vn-bun-05_v4_step_5', 'vn-bun-05', 5, 'sauce', 'Pha nước mắm chua ngọt Nam Bộ', 'Hòa tan 35 g đường cát trắng với 80 ml nước lọc, 40 ml nước mắm ngon và 25 ml giấm gạo cho đến khi đường tan hết không còn lắng đáy, sau đó mới thả 1/3 lượng tỏi khô băm nhuyễn và ớt tươi băm vào để tỏi ớt nổi đẹp trên mặt chén.', 'Khuấy tan hoàn toàn đường trong hỗn hợp mắm giấm nước trước khi cho tỏi ớt băm sẽ giúp tỏi ớt nổi đều đẹp mắt.', NULL),
('vn-bun-05_v4_step_6', 'vn-bun-05', 6, 'finish', 'Chuẩn bị rau, cắt chả giò và hoàn thiện tô bún', 'Rửa sạch xà lách, rau thơm rồi thái sợi vừa ăn; dưa leo thái sợi mảnh; giá đỗ chần sơ nước sôi để ráo; giã dập đậu phộng rang. Chia xà lách, rau thơm lót đáy 4 tô, xếp bún tươi sợi nhỏ lên trên cùng dưa leo, giá đỗ, thịt nướng nóng, chả giò cắt khúc và đồ chua; rưới mỡ hành, rắc đậu phộng giã dập rồi chan nước mắm chua ngọt thưởng thức.', NULL, NULL),
('vn-bun-06_v4_step_1', 'vn-bun-06', 1, 'prep', 'Sơ chế gà ta và ngâm nấm, miến dong', 'Chà xát toàn bộ thân gà ta với 5 g muối ăn để khử mùi, cắt bỏ tuyến dầu ở phao câu rồi rửa sạch với nước lạnh. Nướng sơ gừng tươi, hành tây và 15 g hành tím khô cho dậy thơm, cạo sạch vỏ cháy. Ngâm nấm hương khô và mộc nhĩ khô vào nước ấm 15 phút cho nở mềm rồi rửa sạch, cắt bỏ chân cứng và thái sợi. Ngâm miến dong khô trong nước lạnh 7 phút cho mềm rồi vớt ra cắt khúc vừa ăn.', NULL, 15),
('vn-bun-06_v4_step_2', 'vn-bun-06', 2, 'cook', 'Luộc gà ta lửa nhỏ lấy nước dùng trong', 'Cho gà ta vào nồi lớn cùng 2,5 lít nước lọc lạnh, thêm gừng nướng, hành tây nướng và hành tím nướng. Đun ở lửa vừa đến khi nước vừa sôi tim thì hạ nhỏ lửa liu riu, luộc khoảng 30 phút và hớt bọt mỗi 5 phút để nước thật trong. Xiên đũa vào phần đùi gà thấy không còn nước hồng chảy ra là gà đã chín kỹ.', 'Luộc gà từ nước lạnh và giữ sôi lăn tăn ở lửa nhỏ giúp thịt gà chín đều, da không bị nứt rách và nước dùng trong vắt.', 30),
('vn-bun-06_v4_step_3', 'vn-bun-06', 3, 'prep', 'Xé thịt gà và nêm nước dùng ngọt thanh', 'Vớt gà ra ngâm nhanh vào tô nước nguội 5 phút để da giòn, vớt ráo rồi lọc bỏ xương và xé thịt gà thành miếng vừa ăn. Trả phần xương gà vào nồi ninh tiếp 10 phút cho ngọt nước rồi vớt bỏ xương và hành gừng. Nêm vào nồi nước dùng 10 g muối ăn, 15 ml nước mắm ngon và 10 g hạt nêm cho vừa miệng, giữ nóng trên lửa nhỏ.', 'Ngâm gà chín vào nước nguội vài phút giúp da gà săn bóng đẹp mắt và thịt giữ được độ ẩm ngọt.', NULL),
('vn-bun-06_v4_step_4', 'vn-bun-06', 4, 'marinate', 'Ướp thịt gà xé thấm vị đậm đà', 'Trộn đều phần thịt gà xé với 5 ml nước mắm ngon, 4 g đường cát trắng và 1 g tiêu đen xay, để nghỉ khoảng 10 phút cho thịt gà thấm gia vị trước khi xào.', NULL, 10),
('vn-bun-06_v4_step_5', 'vn-bun-06', 5, 'cook', 'Xào nấm hương mộc nhĩ cùng thịt gà', 'Đun nóng 25 ml dầu ăn trên chảo lửa vừa, cho 15 g hành tím khô băm nhỏ vào phi thơm. Trút nấm hương và mộc nhĩ thái sợi vào xào săn khoảng 4 phút cùng 5 ml nước mắm ngon, sau đó cho thịt gà đã ướp vào đảo đều tay thêm 3 phút đến khi thịt săn thơm thì tắt bếp.', 'Xào riêng nấm và thịt gà giúp phần topping thơm lừng mùi nấm hương mà không làm đục nồi nước dùng trong.', 7),
('vn-bun-06_v4_step_6', 'vn-bun-06', 6, 'finish', 'Chần miến dong và chan nước dùng nóng', 'Khi nước dùng đang sôi nhẹ, trụng miến dong vào nồi nước sôi khoảng 30–45 giây cho sợi miến vừa chín mềm dai (không trụng quá lâu tránh nát) rồi chia ra 4 tô. Xếp thịt gà xào nấm hương mộc nhĩ lên trên, chan nước dùng gà thật nóng ngập mặt miến, rắc hành lá, rau răm, ngò gai và 1 g tiêu đen xay còn lại rồi thưởng thức ngay.', NULL, NULL),
('vn-chay-01_v4_step_1', 'vn-chay-01', 1, 'prep', 'Sơ chế đậu phụ, nấm đông cô và gia vị tươi', 'Rửa nhẹ đậu phụ trắng qua nước sạch, dùng khăn giấy thấm thật khô rồi cắt miếng vuông cạnh 3,5–4 cm. Nấm đông cô tươi cắt bỏ phần chân cứng, rửa sạch nhẹ tay rồi để ráo, khía chữ thập nhẹ trên mũ nấm lớn để nhanh thấm vị. Hành boa-rô rửa sạch, thái nhỏ riêng phần thân trắng và phần lá xanh; ớt sừng thái lát mỏng.', 'Thấm thật ráo nước trên bề mặt đậu phụ giúp khi chiên không bị bắn dầu và lớp vỏ vàng giòn nhanh hơn.', NULL),
('vn-chay-01_v4_step_2', 'vn-chay-01', 2, 'sauce', 'Pha hỗn hợp nước sốt kho nấm tiêu', 'Cho vào chén 30 ml nước tương, 15 ml dầu hào chay, 12 g đường cát trắng, 4 g hạt nêm chay, 2 g muối ăn, 1,5 g tiêu đen xay thô (một nửa lượng tiêu) và 80 ml nước lọc. Khuấy đều tay đến khi đường và hạt nêm tan hoàn toàn thành hỗn hợp sốt đồng nhất.', 'Pha sẵn sốt trong chén giúp gia vị thấm đều khắp nồi đậu và nấm, tránh chỗ mặn chỗ nhạt khi kho.', NULL),
('vn-chay-01_v4_step_3', 'vn-chay-01', 3, 'cook', 'Chiên vàng đều các mặt đậu phụ', 'Làm nóng chảo chống dính trên lửa vừa với 20 ml dầu ăn thực vật. Nhẹ nhàng xếp từng miếng đậu phụ vào chiên khoảng 6 phút, lật trở đều tay đến khi các mặt se vàng giòn thì gắp ra đĩa có lót giấy thấm dầu.', 'Chiên tạo lớp vỏ se vàng giúp miếng đậu giữ nguyên hình dáng, không bị vỡ nát khi kho chung với nấm.', 6),
('vn-chay-01_v4_step_4', 'vn-chay-01', 4, 'cook', 'Phi thơm hành boa-rô và xào săn nấm', 'Dùng nồi đất hoặc chảo sâu lòng, cho 10 ml dầu ăn còn lại vào làm nóng trên lửa vừa, thả phần thân trắng hành boa-rô vào phi 30 giây cho dậy mùi thơm. Trút nấm đông cô vào đảo nhanh tay trong 3 phút đến khi mũ nấm săn lại và hơi xém cạnh.', NULL, 3),
('vn-chay-01_v4_step_5', 'vn-chay-01', 5, 'cook', 'Kho liu riu đậu phụ và nấm thấm sốt', 'Rót chén nước sốt kho đã pha vào nồi nấm, xếp nhẹ các miếng đậu phụ chiên vào và lắc nhẹ nồi cho sốt phủ đều. Đun sôi bùng trên lửa vừa rồi hạ xuống lửa nhỏ, kho liu riu không đậy nắp trong 9 phút đến khi nước sốt keo sánh óng ả và bám quanh từng miếng đậu, nấm.', 'Kho lửa nhỏ và tránh dùng đũa đảo mạnh mà chỉ rưới sốt lên mặt đậu sẽ giúp đậu thấm đượm gia vị mà vẫn nguyên miếng.', 9),
('vn-chay-01_v4_step_6', 'vn-chay-01', 6, 'finish', 'Hoàn thiện với dầu mè, tiêu đen và hành lá boa-rô', 'Nêm nếm lại sốt kho cho vừa khẩu vị, rắc phần lá xanh hành boa-rô, ớt sừng thái lát và rưới 5 ml dầu mè thơm vào, đảo thật nhẹ rồi tắt bếp. Rắc nốt 1,5 g tiêu đen xay còn lại lên mặt nồi kho và dọn nóng ăn kèm cơm trắng.', NULL, NULL),
('vn-chay-02_v4_step_1', 'vn-chay-02', 1, 'prep', 'Ngâm mềm hạt sen, táo đỏ và kỷ tử', 'Ngâm 150 g hạt sen khô trong nước ấm khoảng 30 phút cho mềm, kiểm tra và tách bỏ hết phần tim sen nếu còn để nước canh không bị đắng. Táo đỏ và kỷ tử khô rửa sạch bụi, ngâm nước ấm riêng trong 10 phút cho nở mềm rồi vớt ra để ráo.', 'Ngâm hạt sen trước giúp khi hầm nhanh bở tơi mà không bị sượng lõi bên trong.', 10),
('vn-chay-02_v4_step_2', 'vn-chay-02', 2, 'prep', 'Sơ chế củ sen, cà rốt, bắp ngọt và hai loại nấm', 'Củ sen gọt vỏ, thái khoanh dày 0,6 cm và ngâm ngay vào thau nước pha 3 g muối hột trong 5 phút cho khỏi thâm, sau đó rửa lại để ráo. Cà rốt gọt vỏ, tỉa hoa cắt khoanh 0,8 cm; bắp ngọt rửa sạch. Nấm đùi gà cắt bỏ gốc, thái lát 0,5 cm; nấm kim châm cắt gốc, tách chùm vừa ăn. Hành boa-rô thái riêng đầu trắng và lá xanh; mùi tàu thái nhỏ.', 'Ngâm củ sen trong nước muối loãng ngay sau khi thái giữ cho lát sen trắng giòn và đẹp mắt.', NULL),
('vn-chay-02_v4_step_3', 'vn-chay-02', 3, 'cook', 'Phi thơm hành boa-rô và xào sơ củ quả lấy ngọt', 'Đun nóng 15 ml dầu ăn trong nồi sâu lòng trên lửa vừa, phi thơm phần đầu trắng hành boa-rô trong 30 giây. Cho nấm đùi gà, củ sen, cà rốt, bắp ngọt và hạt sen vào đảo đều 2 phút cùng 4 g muối hột và 5 g hạt nêm chay cho nguyên liệu ngấm vị.', 'Xào sơ củ quả và nấm với chút gia vị trước khi đổ nước giúp nước canh ngọt đậm và thơm hơn.', 2),
('vn-chay-02_v4_step_4', 'vn-chay-02', 4, 'cook', 'Hầm mềm hạt sen, củ sen và táo đỏ', 'Đổ 1500 ml nước lọc vào nồi, bật lửa lớn đun sôi rồi hạ về lửa nhỏ, mở hé vung hầm 15 phút và hớt sạch bọt nổi để nước canh trong veo. Tiếp theo cho táo đỏ vào hầm thêm 10 phút cho hạt sen chín bở, củ sen mềm giòn và táo tiết vị ngọt dịu.', NULL, 25),
('vn-chay-02_v4_step_5', 'vn-chay-02', 5, 'cook', 'Nấu chín nấm kim châm và kỷ tử', 'Thả nấm kim châm và kỷ tử vào nồi canh, nêm thêm 3 g muối hột cùng 5 g hạt nêm chay còn lại. Đun sôi lăn tăn trên lửa vừa trong 3 phút cho nấm kim châm vừa chín tới, giữ được độ giòn ngọt tự nhiên.', 'Nấm kim châm chín rất nhanh, chỉ nên nấu 3 phút để không bị dai và mất vị ngọt thanh.', 3),
('vn-chay-02_v4_step_6', 'vn-chay-02', 6, 'finish', 'Hoàn thiện tô canh chay thanh mát', 'Nêm nếm lại độ mặn ngọt hài hòa của nước canh rồi tắt bếp, thả phần lá xanh hành boa-rô và mùi tàu thái nhỏ vào khuấy nhẹ. Múc canh nấm hạt sen táo đỏ ra tô lớn và thưởng thức ngay khi còn nóng ấm.', NULL, NULL),
('vn-chay-03_v4_step_1', 'vn-chay-03', 1, 'prep', 'Chần tơi sợi mì và sơ chế rau củ, nấm', 'Tách tơi 450 g mì sợi vàng tươi chay, chần thật nhanh qua nước ấm 1 phút cho sợi vừa mềm tơi rồi vớt ra rổ, rũ tơi và để ráo hoàn toàn nước. Nấm đùi gà thái lát mỏng; cà rốt gọt vỏ thái lát mỏng; cải ngọt cắt khúc 4 cm; hành boa-rô thái nhỏ; ngò rí cắt khúc. Hòa tan 10 g bột năng với 45 ml nước lọc để riêng.', 'Chỉ ngâm hoặc chần mì vừa mềm nhẹ để khi chiên sợi mì phồng giòn rụm mà không bị cứng hay ngấm dầu.', 2),
('vn-chay-03_v4_step_2', 'vn-chay-03', 2, 'cook', 'Chiên phồng giòn từng mẻ mì sợi vàng', 'Đun nóng khoảng 235 ml dầu ăn thực vật trong chảo sâu lòng trên lửa vừa đến khi dầu sôi sủi tăm quanh đầu đũa. Chia mì thành 3 phần, thả nhẹ từng phần vào chiên ngập dầu trong 3–4 phút, trở đều 2 mặt đến khi sợi mì phồng vàng giòn rụm thì vớt ra giấy thấm dầu.', 'Đảm bảo dầu đủ nóng trước khi thả mì để mì phồng nhanh, giòn lâu và không bị hút dầu.', 4),
('vn-chay-03_v4_step_3', 'vn-chay-03', 3, 'cook', 'Phi thơm hành boa-rô và xào săn nấm đùi gà, cà rốt', 'Đặt chảo khác lên bếp với 15 ml dầu ăn, làm nóng trên lửa lớn rồi phi thơm phần đầu trắng hành boa-rô trong 20 giây. Cho nấm đùi gà và cà rốt vào đảo nhanh tay 2 phút đến khi nấm săn lại, sau đó nêm 15 ml nước tương, 4 g hạt nêm chay, 3 g đường và 15 ml dầu hào chay.', NULL, 2),
('vn-chay-03_v4_step_4', 'vn-chay-03', 4, 'cook', 'Xào chín giòn cải ngọt và nêm sốt', 'Thêm phần cọng cải ngọt vào đảo 1 phút, sau đó cho phần lá cải ngọt cùng 75 ml nước lọc vào xào nhanh trên lửa lớn khoảng 2 phút cho rau vừa chín tới, vẫn giữ màu xanh mướt. Nêm tiếp 15 ml nước tương và 4 g hạt nêm chay còn lại rồi đảo đều.', 'Xào nhanh trên lửa lớn và cho cọng cải vào trước phần lá giúp cải chín đều mà giữ được độ giòn ngọt.', 2),
('vn-chay-03_v4_step_5', 'vn-chay-03', 5, 'sauce', 'Tạo độ sánh cho nước sốt với bột năng', 'Khuấy đều lại chén nước bột năng rồi rót từ từ vào chảo rau nấm đang sôi, vừa rót vừa đảo đều tay khoảng 1 phút đến khi nước sốt trở nên sánh bóng bám đều vào rau củ. Rưới 5 ml dầu mè thơm và rắc 1 g tiêu đen xay vào đảo nhẹ rồi tắt bếp.', NULL, NULL),
('vn-chay-03_v4_step_6', 'vn-chay-03', 6, 'finish', 'Trình bày và thưởng thức mì xào giòn nóng', 'Xếp các vắt mì đã chiên giòn ra đĩa lớn, múc phần nhân nấm đùi gà, cải ngọt, cà rốt cùng nước sốt sánh nóng hổi rưới đều lên trên. Rắc lá xanh hành boa-rô, ngò rí và 0,5 g tiêu đen xay còn lại rồi thưởng thức ngay khi mì còn giòn rụm.', NULL, NULL),
('vn-chay-04_v4_step_1', 'vn-chay-04', 1, 'prep', 'Sơ chế cà tím và các nguyên liệu ăn kèm', 'Chọn cà tím dài quả thẳng, vỏ căng bóng, rửa sạch rồi bổ đôi theo chiều dọc, dùng mũi dao khứa vài đường chéo trên bề mặt thịt cà để gia vị dễ thấm. Hành lá rửa sạch, vẩy thật ráo rồi thái nhỏ; tỏi khô và ớt sừng băm thật nhuyễn; đậu phộng rang giã dập.', 'Khứa đường chéo nhẹ trên mặt cắt cà tím giúp cà chín nhanh đều và giữ được sốt khi nướng lần hai.', NULL),
('vn-chay-04_v4_step_2', 'vn-chay-04', 2, 'cook', 'Nướng sơ cà tím cho thịt cà mềm ngọt', 'Làm nóng lò nướng hoặc nồi chiên không dầu ở 190°C trong 5 phút. Xếp cà tím lên khay có lót giấy bạc với mặt cắt hướng lên trên, nướng lần 1 trong 15 phút đến khi vỏ hơi xém và thịt cà mềm nhũn khi ấn nhẹ.', 'Nếu nướng trên bếp than hoa, có thể nướng nguyên quả và trở đều mỗi 4–5 phút để vỏ cháy xém thơm đặc trưng rồi mới tách vỏ.', 15),
('vn-chay-04_v4_step_3', 'vn-chay-04', 3, 'sauce', 'Pha sốt nước tương tỏi ớt chua ngọt dịu', 'Trong lúc chờ nướng cà, cho vào chén 30 ml nước tương, 60 ml nước lọc và 5 g đường cát trắng, khuấy đều tay đến khi đường tan hết. Tiếp tục thêm toàn bộ phần tỏi băm và ớt băm vào trộn đều để tạo vị mặn ngọt cay dịu hài hòa.', NULL, NULL),
('vn-chay-04_v4_step_4', 'vn-chay-04', 4, 'sauce', 'Chế biến mỡ hành xanh mướt thơm béo', 'Cho hành lá thái nhỏ cùng 2,5 g muối ăn vào chén chịu nhiệt. Đun nóng 30 ml dầu ăn thực vật trong chảo nhỏ trên lửa vừa khoảng 1 phút đến khi dầu sôi sủi tăm thì tắt bếp, đổ trực tiếp dầu nóng vào chén hành và đảo đều tay.', 'Trộn chút muối vào hành và đổ dầu sôi già khi đã tắt bếp giúp hành giữ màu xanh tươi mà không bị cháy đắng.', 1),
('vn-chay-04_v4_step_5', 'vn-chay-04', 5, 'cook', 'Tước thớ thịt cà tím và nướng thấm sốt lần hai', 'Lấy khay cà tím ra khỏi lò, dùng nĩa xăm nhẹ và tước dọc nhẹ nhàng cho phần thịt cà tơi ra thành thớ dài. Dùng muỗng rưới đều một nửa phần sốt nước tương tỏi ớt và một nửa mỡ hành lên khắp bề mặt cà tím, đưa lại vào lò nướng thêm 8 phút ở 180°C cho sốt thấm sâu vào từng thớ cà.', NULL, 8),
('vn-chay-04_v4_step_6', 'vn-chay-04', 6, 'finish', 'Phết mỡ hành, rắc đậu phộng và thưởng thức nóng', 'Xếp cà tím nướng ra đĩa dài, chan nốt phần sốt nước tương tỏi ớt và mỡ hành còn lại lên mặt cà. Rắc đều đậu phộng rang giã dập cùng 1 g tiêu đen xay và thưởng thức ngay khi còn nóng hổi với cơm trắng.', NULL, NULL),
('vn-chay-05_v4_step_1', 'vn-chay-05', 1, 'prep', 'Sơ chế nấm rơm, đậu hũ non và rau thơm', 'Nấm rơm gọt sạch phần gốc dính đất, rửa nhẹ dưới vòi nước rồi ngâm nước muối loãng 5 phút, xả lại nước sạch và để thật ráo; nấm to bổ làm đôi. Đậu hũ non cắt khoanh tròn dày 1,5–2 cm, xếp ngay ngắn vào đĩa sâu lòng. Tỏi và hành tím băm nhuyễn; hành lá, ngò rí thái nhỏ; ớt sừng thái lát.', 'Chọn nấm rơm búp còn tròn chắc chưa nở bung sẽ giữ được độ giòn ngọt đặc trưng khi xào.', NULL),
('vn-chay-05_v4_step_2', 'vn-chay-05', 2, 'cook', 'Hấp cách thủy đậu hũ non nóng đều', 'Đun sôi nước trong xửng hấp rồi đặt đĩa đậu hũ non vào, hấp cách thủy trên lửa vừa khoảng 10 phút đến khi từng khoanh đậu nóng ấm và hơi săn mặt lại. Nhấc đĩa đậu ra, chắt nhẹ phần nước thừa tiết ra trên đĩa để sốt không bị loãng.', 'Hấp riêng đậu hũ non trước rồi mới rưới sốt giúp từng khoanh đậu giữ nguyên hình tròn đẹp mắt, không bị vỡ nát.', 10),
('vn-chay-05_v4_step_3', 'vn-chay-05', 3, 'sauce', 'Pha chén nước sốt dầu hào chay', 'Trong lúc hấp đậu, cho vào chén 18 ml dầu hào chay, 22 ml nước tương, 6 g đường cát trắng, 4 g hạt nêm chay, 4 g bột bắp và 80 ml nước lọc. Khuấy kỹ cho đường và bột bắp tan hoàn toàn không bị lắng cặn dưới đáy chén.', NULL, NULL),
('vn-chay-05_v4_step_4', 'vn-chay-05', 4, 'cook', 'Phi thơm hành tỏi và xào săn nấm rơm', 'Làm nóng chảo với 20 ml dầu ăn trên lửa vừa, cho hành tím và tỏi băm vào phi khoảng 45 giây đến khi dậy mùi thơm và ngả vàng nhẹ. Vặn lửa lớn, thả nấm rơm vào đảo nhanh tay 3–4 phút cho nấm săn lại và thấm hương dầu thơm.', 'Xào nấm nhanh trên lửa lớn giúp nấm rơm chín giòn và không bị chảy nhiều nước.', 4),
('vn-chay-05_v4_step_5', 'vn-chay-05', 5, 'cook', 'Nấu sánh phần nước sốt nấm rơm', 'Khuấy đều lại chén sốt dầu hào chay rồi đổ vào chảo nấm, hạ xuống lửa vừa và đảo đều liên tục khoảng 2–3 phút đến khi nước sốt sôi lăn tăn, sánh bóng mượt và quyện quanh từng miếng nấm thì tắt bếp.', NULL, 3),
('vn-chay-05_v4_step_6', 'vn-chay-05', 6, 'finish', 'Rưới sốt lên đậu hũ non và hoàn thiện', 'Múc phần sốt nấm rơm đang nóng hổi rưới đều phủ lên từng khoanh đậu hũ non đã hấp. Rắc hành lá, ngò rí thái nhỏ, 1 g tiêu đen xay và xếp vài lát ớt sừng lên trên, dọn dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('vn-chay-06_v4_step_1', 'vn-chay-06', 1, 'prep', 'Sơ chế rau cải bẹ xanh, đậu phụ và gừng', 'Rau cải bẹ xanh nhặt bỏ lá úa và phần gốc già, tách bẹ rửa sạch nhiều lần rồi cắt khúc 3–4 cm, để ráo. Đậu phụ trắng cắt miếng vuông cạnh 2 cm. Gừng già cạo vỏ, đập dập một nửa (12,5 g), phần còn lại thái sợi mỏng; hành tím băm nhỏ; hành lá và ngò rí thái nhỏ.', 'Chọn bó cải bẹ xanh non, cọng mảnh vừa phải sẽ ít đắng và giòn ngọt hơn cải già.', NULL),
('vn-chay-06_v4_step_2', 'vn-chay-06', 2, 'cook', 'Phi thơm hành tím và gừng già đập dập', 'Đặt nồi lên bếp với 15 ml dầu ăn trên lửa vừa, cho hành tím băm và phần gừng đập dập vào phi khoảng 45 giây đến khi dậy mùi thơm cay ấm đặc trưng.', 'Phi thơm gừng đập dập trước giúp tinh dầu gừng tiết ra hòa vào nước dùng, làm ấm bụng và khử mùi tanh nhẹ của đậu.', NULL),
('vn-chay-06_v4_step_3', 'vn-chay-06', 3, 'cook', 'Nấu nước canh sôi và thả đậu phụ', 'Đổ 1000 ml nước lọc vào nồi, đậy nắp đun lửa lớn cho sôi bùng rồi hạ lửa vừa. Nhẹ nhàng thả từng miếng đậu phụ trắng vào, nấu sôi lăn tăn trong 4 phút cho đậu nóng đều và nước canh ngấm hương gừng.', NULL, 4),
('vn-chay-06_v4_step_4', 'vn-chay-06', 4, 'cook', 'Nêm gia vị cân bằng vị cải bẹ xanh', 'Nêm vào nồi canh 6 g hạt nêm chay, 3 g muối ăn, 2 g đường cát trắng và 15 ml nước tương, khuấy thật nhẹ tay tránh làm vỡ đậu và nếm lại cho vừa khẩu vị thanh dịu.', 'Thêm một chút đường cát trắng giúp dịu hẳn vị đắng nhẹ đặc trưng của rau cải bẹ xanh.', NULL),
('vn-chay-06_v4_step_5', 'vn-chay-06', 5, 'cook', 'Nấu cải bẹ xanh giữ màu xanh giòn', 'Tăng lên lửa lớn cho nước canh sôi mạnh trở lại rồi thả rau cải bẹ xanh cùng phần gừng thái sợi vào, dùng vá ấn nhẹ cho rau ngập nước. Nấu mở vung trong 2 phút đến khi cọng cải vừa chín tới, giữ nguyên màu xanh mướt.', 'Không đậy vung và không nấu cải quá 3 phút để rau không bị úa vàng và mất độ giòn.', 2),
('vn-chay-06_v4_step_6', 'vn-chay-06', 6, 'finish', 'Hoàn thiện và dọn canh nóng', 'Tắt bếp ngay khi cải vừa chín tới, thả hành lá và ngò rí thái nhỏ vào. Múc canh ra tô lớn, rắc 1 g tiêu đen xay lên trên và dùng nóng ngay trong bữa cơm.', NULL, NULL),
('vn-sang-01_v4_step_1', 'vn-sang-01', 1, 'prep', 'Làm tơi cơm nguội và ướp gia vị', 'Cho 360 g cơm nguội ra tô lớn, dùng tay sạch bóp nhẹ cho từng hạt cơm tách rời hoàn toàn. Trộn cơm với 5 ml nước mắm ngon, 3 g hạt nêm, 2 g đường cát trắng, 1,5 g muối ăn, 1/2 lượng tiêu đen xay và 10 ml dầu ăn để hạt cơm bóng mượt, thấm đều gia vị trước khi chiên.', 'Dùng cơm nấu ráo nước đã để nguội trong ngăn mát vài giờ sẽ giúp hạt cơm săn chắc, khi rang rất tơi mà không bị bết dính.', NULL),
('vn-sang-01_v4_step_2', 'vn-sang-01', 2, 'prep', 'Sơ chế tỏi, hành lá và cà chua', 'Bóc vỏ 1 củ tỏi khô, chia một nửa băm nhuyễn và một nửa thái lát mỏng đều nhau. Rửa sạch hành lá, tách riêng đầu hành trắng băm nhỏ, phần lá xanh thái nhuyễn. Rửa sạch cà chua chín, cắt lát mỏng để trang trí đĩa cơm.', NULL, NULL),
('vn-sang-01_v4_step_3', 'vn-sang-01', 3, 'cook', 'Phi thơm vàng giòn tỏi băm và tỏi lát', 'Đun nóng 20 ml dầu ăn trong chảo sâu lòng trên lửa vừa, thử đầu đũa thấy sủi tăm nhẹ thì hạ lửa nhỏ. Cho tỏi băm vào đảo đều tay khoảng 2 phút đến khi vừa ngả màu vàng nhạt thì vớt nhanh ra đĩa lót giấy thấm dầu. Tiếp tục thả tỏi thái lát vào phi thêm 1 phút đến khi nổi vàng giòn thì vớt ra ngay, giữ lại phần dầu tỏi trong chảo.', 'Vớt tỏi phi ngay khi chuyển màu vàng nhạt vì lượng nhiệt dư sẽ tiếp tục làm tỏi vàng giòn hoàn hảo mà không bị cháy đắng.', 3),
('vn-sang-01_v4_step_4', 'vn-sang-01', 4, 'cook', 'Đánh tan và chiên tơi trứng gà', 'Làm nóng lại chảo dầu tỏi trên lửa vừa, cho phần đầu hành lá băm vào đảo thơm 15 giây. Đập 2 quả trứng gà trực tiếp vào chảo, chờ 10 giây cho lớp đáy hơi se lại rồi dùng đũa khuấy đều theo vòng tròn tạo thành những mảng trứng vàng xốp mềm.', NULL, 1),
('vn-sang-01_v4_step_5', 'vn-sang-01', 5, 'cook', 'Rang cơm lửa lớn cho hạt săn tơi', 'Trút toàn bộ tô cơm đã ướp vào chảo trứng, tăng lên lửa lớn và đảo liên tục trong 5 phút. Dùng xẻng gỗ hoặc đũa tản đều để hạt cơm và trứng hòa quyện, rang đến khi thấy hạt cơm khô ráo, săn bóng và bắt đầu nhảy lách tách nhẹ trên mặt chảo.', 'Giữ lửa lớn và đảo đều tay giúp hơi ẩm thoát nhanh, hạt cơm săn giòn bên ngoài nhưng vẫn dẻo mềm bên trong.', 5),
('vn-sang-01_v4_step_6', 'vn-sang-01', 6, 'finish', 'Rưới nước mắm tạo hương và trình bày', 'Rưới 5 ml nước mắm ngon còn lại dọc quanh thành chảo đang nóng để dậy hương thơm đặc trưng, đảo thêm 30 giây rồi tắt bếp. Trút hành lá thái nhỏ và phần tiêu đen xay còn lại vào đảo đều. Múc cơm ra đĩa, xếp cà chua thái lát bên cạnh, rắc toàn bộ tỏi phi vàng giòn lên mặt và thưởng thức nóng.', 'Chỉ rắc tỏi phi lên mặt khi tắt bếp hoặc lúc bày đĩa để giữ nguyên độ giòn rụm đến miếng cuối cùng.', NULL),
('vn-sang-02_v4_step_1', 'vn-sang-02', 1, 'prep', 'Sơ chế dưa leo, ngò rí và ớt tươi', 'Rửa sạch dưa leo, cắt bỏ hai đầu rồi thái lát vát xéo mỏng khoảng 0,3 cm để khi kẹp dễ ăn và giữ độ giòn mát. Nhặt sạch rễ ngò rí, rửa kỹ rồi vẩy thật ráo nước để bánh không bị ướt mềm. Thái lát mỏng ớt sừng đỏ nếu dùng cay.', 'Vẩy thật ráo nước rau thơm và dưa leo trước khi kẹp giúp vỏ bánh mì giữ độ giòn lâu hơn.', NULL),
('vn-sang-02_v4_step_2', 'vn-sang-02', 2, 'cook', 'Làm nóng giòn vỏ bánh mì và phết pate', 'Làm nóng nồi chiên không dầu hoặc lò nướng ở 180°C, cho 2 ổ bánh mì vào nướng lại 3 phút cho vỏ ngoài nóng giòn rụm (hoặc áp chảo khô trên lửa vừa 2 phút mỗi mặt). Dùng dao răng cưa rạch dọc một bên thân bánh tạo khoang mở, phết đều 40 g pate gan heo vào hai mặt ruột của mỗi ổ bánh.', 'Phết pate lên cả hai mặt ruột khi bánh vừa nướng nóng sẽ giúp pate hơi chảy mềm, lan tỏa hương béo ngậy khắp ổ bánh.', 3),
('vn-sang-02_v4_step_3', 'vn-sang-02', 3, 'cook', 'Đun chảy bơ và chiên trứng ốp la lòng đào', 'Đặt chảo chống dính lên bếp với lửa vừa, cho 15 g bơ vào đun chảy đến khi sủi bọt lăn tăn nhưng không để cháy nâu. Hạ lửa nhỏ vừa, đập nhẹ 2 quả trứng gà vào chảo, giữ nguyên khoảng 2 phút cho lòng trắng đông trắng hoàn toàn và viền hơi vàng giòn trong khi lòng đỏ vẫn tròn mềm sóng sánh.', 'Chiên bơ ở lửa nhỏ vừa giúp trứng không bị cháy cạnh và giữ được hương thơm béo thanh đặc trưng.', 2),
('vn-sang-02_v4_step_4', 'vn-sang-02', 4, 'cook', 'Nêm gia vị lên mặt trứng ốp la', 'Khi trứng chín đạt khoảng 7 phần (lòng trắng đông chắc, lòng đỏ hơi se màng mỏng bên ngoài), rắc đều 1,5 g muối ăn và 1 g tiêu đen xay lên bề mặt trứng, nấu thêm 30 giây rồi tắt bếp ngay để giữ độ lòng đào chuẩn.', NULL, NULL),
('vn-sang-02_v4_step_5', 'vn-sang-02', 5, 'finish', 'Xếp nhân vào ổ bánh mì', 'Dùng xẻng mỏng nhẹ nhàng xúc từng quả trứng ốp la đặt gọn vào giữa lòng mỗi ổ bánh mì đã phết pate. Xếp tiếp các lát dưa leo giòn mát, vài nhánh ngò rí tươi và vài lát ớt sừng đỏ lên trên mặt trứng.', NULL, NULL),
('vn-sang-02_v4_step_6', 'vn-sang-02', 6, 'finish', 'Rưới xì dầu, tương ớt và thưởng thức nóng', 'Rưới đều 5 ml xì dầu và 7–8 ml tương ớt vào bên trong mỗi ổ bánh mì, khép nhẹ hai mép bánh lại để phần pate, lòng đào trứng và rau hòa quyện với nhau. Dọn ăn ngay khi bánh còn nóng giòn.', 'Tránh ấn quá mạnh tay khi vừa kẹp xong để lòng đỏ trứng không bị vỡ tràn ra ngoài trước khi cắn miếng đầu tiên.', NULL),
('vn-sang-03_v4_step_1', 'vn-sang-03', 1, 'prep', 'Vo sạch và rang thơm hỗn hợp gạo tẻ, gạo nếp', 'Trộn 100 g gạo tẻ với 20 g gạo nếp, vo nhanh qua 2 lần nước sạch rồi chắt thật ráo. Làm nóng nồi đáy dày không dầu trên lửa nhỏ, cho gạo vào rang đều tay khoảng 6 phút đến khi hạt gạo khô ráo, chuyển màu trắng đục và dậy hương thơm dịu.', 'Rang gạo không dầu trước khi nấu giúp hạt gạo săn lại, khi ninh chín sẽ nở bung sánh mịn mà không bị vữa nát.', 6),
('vn-sang-03_v4_step_2', 'vn-sang-03', 2, 'cook', 'Ninh cháo gạo rang trên lửa nhỏ vừa', 'Đổ 1,2 lít nước lọc đun sôi vào nồi gạo vừa rang, khuấy nhẹ đáy nồi một lượt rồi đậy hé nắp. Đun sôi bùng trên lửa vừa sau đó hạ lửa nhỏ ninh khoảng 18 phút, thỉnh thoảng khuấy đều sát đáy nồi để hạt gạo nở bung mềm nhừ và nước cháo sánh mịn.', 'Nên dùng nước nóng đổ vào gạo rang và khuấy sát đáy nồi 5 phút một lần để tránh tình trạng cháo bị bén khét.', 18),
('vn-sang-03_v4_step_3', 'vn-sang-03', 3, 'marinate', 'Ướp thịt heo xay và sơ chế gừng, tía tô, hành lá', 'Trong lúc ninh cháo, cho 180 g thịt heo nạc xay vào tô, ướp với 20 g hành tím băm, 5 ml nước mắm ngon, 2,5 g hạt nêm, 1,5 g muối ăn và 1 g tiêu đen xay, trộn đều để 10 phút cho thấm vị. Gừng già cạo vỏ thái chỉ mảnh; lá tía tô và hành lá rửa sạch rồi thái sợi nhỏ.', NULL, NULL),
('vn-sang-03_v4_step_4', 'vn-sang-03', 4, 'cook', 'Khuấy tơi thịt bằm vào nồi cháo đang sôi', 'Khi hạt gạo đã nở nhừ sánh mịn, múc một vá nước cháo nóng rưới vào tô thịt heo xay rồi dằm tơi ra trước khi trút từ từ vào nồi. Khuấy đều tay trên lửa vừa trong 4 phút để thịt chín hoàn toàn, tơi mịn mà không đóng cục và tiết vị ngọt tự nhiên.', 'Hòa chút nước cháo vào thịt xay trước khi thả vào nồi là bí quyết giúp thịt bằm tơi đều như ngoài hàng mà không cần xào nhiều dầu mỡ.', 4),
('vn-sang-03_v4_step_5', 'vn-sang-03', 5, 'cook', 'Nêm gia vị và thêm gừng tươi ấm bụng', 'Nêm thêm 10 ml nước mắm ngon, 2,5 g hạt nêm và 2,5 g muối ăn vào nồi cháo, khuấy nhẹ rồi nếm lại cho vừa khẩu vị thanh nhẹ. Thả 2/3 lượng gừng già thái chỉ vào nấu sôi lăn tăn thêm 1 phút để tinh dầu gừng hòa vào cháo.', NULL, NULL),
('vn-sang-03_v4_step_6', 'vn-sang-03', 6, 'finish', 'Lót rau thơm và múc cháo nóng giải cảm', 'Xếp một nửa lượng lá tía tô thái sợi, hành lá thái nhỏ và phần gừng thái chỉ còn lại xuống đáy 3 tô sứ sâu lòng. Múc cháo thịt bằm đang sôi sục lên trên để hơi nóng làm chín tái lá tía tô dậy mùi thơm, rắc thêm phần tía tô còn lại cùng 1 g tiêu đen xay lên mặt và thưởng thức nóng ngay.', 'Không đun lá tía tô quá lâu trong nồi vì tinh dầu dễ bay hơi và lá sẽ chuyển màu thâm đen kém đẹp mắt.', NULL),
('vn-sang-04_v4_step_1', 'vn-sang-04', 1, 'marinate', 'Thái mỏng và ướp mềm thịt bò thăn', 'Thấm khô 200 g thịt bò thăn rồi thái lát mỏng ngang thớ để thịt không bị dai. Cho bò vào tô, ướp cùng 5 ml xì dầu, 5 ml dầu hào, 3 g hạt nêm, 1 g tiêu đen xay, 1/2 lượng tỏi băm và hành tím băm cùng 5 ml dầu ăn trong 12 phút cho ngấm vị và giữ ẩm.', 'Thêm một chút dầu ăn vào ướp thịt bò giúp khóa ẩm khi xào lửa lớn và giúp các lát thịt tơi rời không dính chùm.', 12),
('vn-sang-04_v4_step_2', 'vn-sang-04', 2, 'prep', 'Sơ chế rau cải ngọt và trụng mì vừa dai', 'Cắt khúc 200 g rau cải ngọt dài 4 cm, để riêng phần cọng và lá. Đun sôi 800 ml nước lọc, thả 2 vắt mì vào trụng nhanh đúng 1 phút cho sợi mì vừa tơi rời, vớt ngay ra rổ xả qua nước lạnh cho săn sợi, để thật ráo rồi trộn với 5 ml dầu ăn chống dính.', 'Chỉ trụng mì vừa bung sợi khoảng 1 phút và xả ngay nước nguội để sợi mì giữ độ dai giòn khi đem xào lại trên chảo.', 1),
('vn-sang-04_v4_step_3', 'vn-sang-04', 3, 'cook', 'Xào nhanh rau cải ngọt giữ màu xanh giòn', 'Làm nóng 5 ml dầu ăn trong chảo lớn trên lửa lớn, phi thơm một phần nhỏ tỏi băm. Cho phần cọng cải ngọt vào đảo trước 45 giây rồi trút phần lá vào xào thêm 1 phút, nêm 2 g hạt nêm, thấy rau vừa xanh mướt chín tới thì trút ngay ra đĩa riêng.', NULL, NULL),
('vn-sang-04_v4_step_4', 'vn-sang-04', 4, 'cook', 'Áp chảo thịt bò trên lửa lớn', 'Thêm 5 ml dầu ăn vào chảo nóng, phi thơm phần tỏi và hành tím băm còn lại rồi trút toàn bộ thịt bò đã ướp vào đảo nhanh tay trên lửa lớn khoảng 90 giây đến khi thịt bò vừa săn đổi màu nâu hồng, chín tới mềm ngọt thì múc riêng ra đĩa.', 'Không xào thịt bò quá lâu trên bếp vì nhiệt dư sẽ làm thịt bị khô cứng và ra nhiều nước.', 2),
('vn-sang-04_v4_step_5', 'vn-sang-04', 5, 'cook', 'Xào mì thấm sốt cùng bò và rau cải', 'Trút mì đã trụng vào chảo nóng, rưới 10 ml xì dầu, 10 ml dầu hào và 1 g hạt nêm còn lại vào đảo đều trên lửa lớn 2 phút cho sợi mì săn bóng và ngấm đều màu nâu đẹp. Đổ đĩa thịt bò và rau cải ngọt trở lại chảo cùng hành lá cắt khúc, đảo nhanh 30 giây rồi tắt bếp.', NULL, NULL),
('vn-sang-04_v4_step_6', 'vn-sang-04', 6, 'finish', 'Chiên trứng ốp la lòng đào và hoàn thiện', 'Bắc một chảo chống dính nhỏ với 10 ml dầu ăn trên lửa vừa, đập 2 quả trứng gà vào ốp la khoảng 2 phút đến khi lòng trắng đông chắc mà lòng đỏ vẫn sánh mềm. Chia mì xào bò ra 2 đĩa, đặt mỗi đĩa một quả trứng ốp la lên trên, rắc ngò rí và 1 g tiêu đen xay còn lại rồi dùng nóng.', NULL, NULL),
('vn-sang-05_v4_step_1', 'vn-sang-05', 1, 'prep', 'Băm hạt lựu thật nhỏ rau củ', 'Gọt vỏ cà rốt, rửa sạch rồi băm hạt lựu thật nhỏ li ti khoảng 2 mm. Hành tây bóc vỏ, băm hạt lựu nhỏ tương tự cà rốt. Rửa sạch hành lá và thái nhuyễn đều để khi tráng không làm cộm hay rách lớp trứng mỏng.', 'Cắt rau củ càng nhỏ mịn thì trứng càng dễ cuộn chặt tay và rau củ kịp chín mềm ngọt ngay trong lúc tráng.', NULL),
('vn-sang-05_v4_step_2', 'vn-sang-05', 2, 'prep', 'Đánh tan trứng với sữa tươi và lọc qua rây', 'Đập 4 quả trứng gà vào tô lớn, đổ vào 30 ml sữa tươi không đường, 5 ml nước mắm ngon, 2 g hạt nêm và 2 g muối ăn. Dùng đũa khuấy tan nhẹ nhàng một chiều đến khi lòng trắng và lòng đỏ quyện đều hoàn toàn, sau đó lọc hỗn hợp qua rây mịn vào tô sạch để loại bỏ lợn cợn.', 'Bước lọc qua rây giúp loại bỏ phần lòng trắng còn dai và bọt khí, tạo bề mặt trứng cuộn mịn mượt không rỗ.', NULL),
('vn-sang-05_v4_step_3', 'vn-sang-05', 3, 'prep', 'Trộn rau củ vào hỗn hợp trứng lọc', 'Trút toàn bộ cà rốt, hành tây băm hạt lựu, hành lá thái nhỏ và 1 g tiêu đen xay vào tô trứng đã lọc, khuấy nhẹ cho rau củ phân bố đều khắp hỗn hợp.', NULL, NULL),
('vn-sang-05_v4_step_4', 'vn-sang-05', 4, 'cook', 'Tráng lớp trứng mỏng đầu tiên và cuộn tròn', 'Làm nóng chảo chống dính trên lửa vừa rồi hạ xuống lửa nhỏ, dùng giấy thấm phết một lớp dầu ăn thật mỏng đều đáy chảo. Khuấy nhẹ tô trứng để lấy cả rau củ, múc 1 vá canh đổ vào lắc nhẹ cho tráng đều đáy. Khi mặt trứng vừa se ẩm khoảng 70% trong 1 phút, dùng xẻng nhẹ nhàng cuộn tròn từ mép xa về một phía thành chảo.', 'Cuộn ngay khi mặt trên trứng còn hơi ướt ẩm sẽ giúp các vòng cuộn kết dính chặt với nhau mà không bị gãy nứt.', 2),
('vn-sang-05_v4_step_5', 'vn-sang-05', 5, 'cook', 'Nối tiếp các lớp trứng đến khi hết hỗn hợp', 'Phết thêm chút dầu ăn vào phần đáy chảo trống, múc tiếp 1 vá hỗn hợp trứng đổ vào và nâng nhẹ mép cuộn trứng lên cho trứng mới chảy lót xuống bên dưới. Chờ khoảng 1 phút cho lớp mới se mặt rồi cuộn nối tiếp vòng, lặp lại đều đặn 3–4 lượt trong khoảng 5 phút đến khi hết phần trứng.', NULL, 5),
('vn-sang-05_v4_step_6', 'vn-sang-05', 6, 'finish', 'Áp vàng nhẹ hai mặt và cắt khoanh tròn', 'Khi cuộn hết trứng, giữ cuốn trứng trên chảo thêm 30 giây mỗi mặt trên lửa nhỏ để chín hoàn toàn từ trong ra ngoài và tạo màu vàng đẹp. Gắp cuộn trứng ra thớt nghỉ 2 phút cho định hình chắc tay rồi dùng dao bén cắt thành từng khoanh dày 2 cm xếp ra đĩa, ăn nóng.', 'Chờ trứng nguội bớt 2 phút trước khi cắt giúp lát cắt sắc nét, rau củ bên trong không bị xô lệch.', NULL),
('vn-sang-06_v4_step_1', 'vn-sang-06', 1, 'prep', 'Ngâm nấm hương khô và luộc chín ức gà', 'Ngâm 20 g nấm hương khô trong nước ấm khoảng 20 phút cho nở mềm, cắt bỏ chân nấm, rửa sạch rồi thái sợi chỉ mỏng. Cho 300 g ức gà vào nồi cùng 1,44 lít nước lọc và 2 g muối ăn, đun sôi rồi hạ lửa vừa luộc 12 phút, thường xuyên hớt bọt cho nước dùng thật trong. Vớt ức gà ra để nguội bớt rồi xé sợi nhỏ vừa ăn, giữ lại toàn bộ nước luộc gà.', 'Hớt bọt kỹ ngay khi nước vừa sôi giúp nước dùng súp gà trong veo và không bị mùi hôi.', 12),
('vn-sang-06_v4_step_2', 'vn-sang-06', 2, 'prep', 'Chuẩn bị ngô ngọt, bột năng và trứng đánh tan', 'Rửa sạch 200 g hạt ngô ngọt tươi để ráo. Hòa tan hoàn toàn 25 g bột năng với 60 ml nước lọc nguội trong chén nhỏ cho không còn vón cục. Đập 2 quả trứng gà vào chén, đánh tan nhẹ bằng đũa; rửa sạch hành lá và ngò rí rồi thái nhỏ.', NULL, NULL),
('vn-sang-06_v4_step_3', 'vn-sang-06', 3, 'cook', 'Phi thơm hành tím, xào sơ gà xé và nấm hương', 'Làm nóng 10 ml dầu ăn trong nồi sạch trên lửa vừa, cho 20 g hành tím băm nhỏ vào phi thơm. Trút thịt ức gà xé sợi và nấm hương thái sợi vào đảo đều khoảng 3 phút cho thơm săn rồi đổ toàn bộ nước luộc gà và hạt ngô ngọt vào nồi, đun sôi trở lại trong 4 phút để hạt ngô chín mềm ngọt.', 'Xào nhanh thịt gà xé cùng nấm hương và hành tím trước khi chan nước dùng giúp tô súp thơm đậm đà hơn nhiều.', 4),
('vn-sang-06_v4_step_4', 'vn-sang-06', 4, 'cook', 'Nêm gia vị và tạo độ sánh mượt cho súp', 'Nêm 4 g muối ăn còn lại và 6 g hạt nêm vào nồi nước dùng đang sôi nhẹ, nếm lại cho vừa vị ngọt thanh. Khuấy lại chén nước bột năng cho đều rồi rót từ từ từng dòng nhỏ vào nồi, vừa rót vừa khuấy đều tay một chiều trên lửa nhỏ khoảng 2 phút đến khi súp sánh mượt trong veo.', 'Rót bột năng thật chậm và khuấy đều tay liên tục giúp súp sánh mịn đồng nhất, không bị vón cục.', 2),
('vn-sang-06_v4_step_5', 'vn-sang-06', 5, 'cook', 'Rót trứng tạo vân hoa mềm mượt', 'Giữ nồi súp sôi lăn tăn trên lửa nhỏ, rót từ từ chén trứng gà đã đánh tan qua rây (hoặc rưới dòng nhỏ cao tay) đồng thời dùng đũa khuấy nhẹ nhàng theo chiều kim đồng hồ để tạo thành các vân hoa trứng mỏng tơi đẹp mắt. Nấu thêm 1 phút cho trứng chín hẳn rồi tắt bếp.', NULL, NULL),
('vn-sang-06_v4_step_6', 'vn-sang-06', 6, 'finish', 'Múc súp ra bát, thêm dầu mè và rau thơm', 'Múc súp gà nóng hổi ra 4 bát, nhỏ đều 5 ml dầu mè thơm lên bề mặt, rắc hành lá thái nhỏ, ngò rí và 2 g tiêu trắng xay. Thưởng thức ngay khi súp còn nóng sánh.', NULL, NULL),
('vn-lau-01_v4_step_1', 'vn-lau-01', 1, 'prep', 'Chần sườn sụn và ninh nước dùng ngọt trong', 'Chặt 400 g sườn sụn heo thành miếng 3 cm, chà nhẹ với 2 g muối ăn rồi chần nước sôi 3 phút, vớt ra xả sạch. Cho sườn sụn vào nồi cùng 1300 ml nước lọc và 3 g muối ăn, đun sôi rồi hạ lửa nhỏ ninh 25 phút và hớt sạch bọt để sườn mềm sần sật, nước dùng trong ngọt.', 'Ninh sườn sụn ở lửa nhỏ vừa phải sẽ giữ được phần sụn giòn sần sật mà không bị mềm bở quá mức.', 25),
('vn-lau-01_v4_step_2', 'vn-lau-01', 2, 'prep', 'Lọc cua đồng lấy nước cốt và khêu gạch cua', 'Rửa sạch 500 g cua đồng tươi, tách mai khêu riêng phần gạch cua vàng vào chén nhỏ. Giã hoặc xay nhuyễn phần thân cua với 1 g muối ăn rồi hòa cùng 1500 ml nước lọc, bóp kỹ và lọc qua rây 2–3 lần bỏ bã xác cua để thu phần nước thịt cua mịn.', NULL, 10),
('vn-lau-01_v4_step_3', 'vn-lau-01', 3, 'prep', 'Rán vàng đậu phụ và sơ chế rau nhúng lẩu', 'Cắt 4 bìa đậu phụ thành miếng vuông 2,5 cm, làm nóng chảo với 30 ml dầu ăn trên lửa vừa và chiên vàng giòn đều các mặt rồi vớt ra đĩa có giấy thấm dầu. Bổ múi cau 4 quả cà chua; băm nhỏ hành tím; rửa sạch rau muống chẻ, hoa chuối bào, tía tô, kinh giới, hành lá và bày bắp bò, váng đậu, chả cá, bún tươi ra khay.', NULL, 8),
('vn-lau-01_v4_step_4', 'vn-lau-01', 4, 'cook', 'Nấu đóng tảng riêu cua vàng xốp', 'Đặt nồi nước lọc cua đồng lên bếp ở lửa vừa, khuấy nhẹ đều tay theo một chiều trong 2 phút đầu để thịt cua không dính đáy nồi, sau đó dừng khuấy. Khi mảng riêu cua kết tủa nổi dày lên mặt, hạ lửa nhỏ đun liu riu thêm 2–3 phút cho riêu chín định hình rồi dùng vá lỗ nhẹ nhàng vớt riêng tảng riêu cua ra tô.', 'Tuyệt đối không khuấy khi nước cua bắt đầu nóng và không để sôi trào mạnh để mảng riêu cua đóng thành tảng lớn, xốp mịn không bị vỡ nát.', 8),
('vn-lau-01_v4_step_5', 'vn-lau-01', 5, 'cook', 'Chưng gạch cua với dầu điều và xào cà chua', 'Làm nóng chảo với 20 ml dầu màu điều trên lửa vừa, phi thơm hành tím băm rồi cho gạch cua vào đảo nhanh 1 phút cho dậy mùi thơm béo (múc bớt phần hành phi vàng để riêng rắc mặt). Trút cà chua bổ múi cau vào xào 3 phút đến khi cà chua hơi mềm và tiết sắc đỏ cam đẹp mắt.', NULL, 3),
('vn-lau-01_v4_step_6', 'vn-lau-01', 6, 'cook', 'Pha nước lẩu riêu chua thanh với giấm bỗng', 'Trút phần nước sườn sụn đã ninh (cả sườn) vào nồi nước lọc cua, thêm hỗn hợp cà chua gạch cua vừa xào. Hòa tan 10 g mắm tôm Bắc với ít nước dùng rồi lọc bỏ cặn đổ vào nồi, nêm 100 ml giấm bỗng, 25 ml nước mắm ngon, 10 g hạt nêm, 2 g muối ăn còn lại và 10 ml sa tế ớt cho dậy vị chua thanh nồng nàn.', 'Cho giấm bỗng vào sau cùng khi nước lẩu sắp dọn để giữ trọn hương thơm nồng dịu đặc trưng mà không bị bay hơi hết.', NULL),
('vn-lau-01_v4_step_7', 'vn-lau-01', 7, 'finish', 'Bày nồi lẩu lên bếp từ và thưởng thức nóng', 'Chuyển nồi nước dùng sang nồi lẩu điện hoặc bếp từ đặt giữa bàn, xếp đậu phụ rán vàng, tảng riêu cua đồng, hành lá cắt khúc và hành phi lên trên rồi đun sôi đều 3–5 phút để riêu cua chín kỹ hoàn toàn. Khi nước sôi lăn tăn, thực khách nhúng bắp bò hoa thái mỏng khoảng 15–20 giây cho vừa chín mềm, nhúng kèm váng đậu, chả cá, rau muống chẻ, hoa chuối và thưởng thức cùng bún tươi, tía tô, kinh giới.', NULL, NULL),
('vn-lau-02_v4_step_1', 'vn-lau-02', 1, 'prep', 'Làm sạch và ướp thịt gà ta đậm vị', 'Chà xát 1200 g thịt gà ta với 4 g muối ăn trong 2 phút để hết mùi hôi, rửa sạch để ráo rồi chặt miếng vừa ăn 3,5–4 cm. Ướp gà với 15 ml nước mắm, 5 g hạt nêm, 2 g tiêu đen xay, một nửa lượng tỏi băm, một nửa sả băm và 1 quả ớt hiểm băm trong 20 phút cho thịt săn thấm vị.', 'Ướp gà đủ 20 phút trước khi xào giúp phần thịt bám chặt gia vị, khi hầm không bị nhạt lõi bên trong.', 20),
('vn-lau-02_v4_step_2', 'vn-lau-02', 2, 'prep', 'Sơ chế lá giang, sả và các loại rau nhúng lẩu', 'Nhặt lấy phần lá non của 200 g lá giang tươi, rửa sạch để ráo rồi dùng tay vò nhẹ cho lá hơi dập để dễ tiết vị chua. Đập dập 2 cây sả cắt khúc 5 cm, bổ múi cau 2 quả cà chua; rửa sạch rau muống chẻ, hoa chuối bào, ngò gai, rau ngổ cắt khúc 2 cm và bày bún gạo tươi ra đĩa.', 'Chỉ nên vò lá giang vừa dập trước khi thả vào nồi; vò quá nát và nấu quá lâu trong nồi inox/nhôm dễ làm nước có vị chát nhẹ.', NULL),
('vn-lau-02_v4_step_3', 'vn-lau-02', 3, 'cook', 'Phi hành thơm và xào săn thịt gà ta', 'Làm nóng nồi đáy dày trên lửa vừa với 20 ml dầu ăn, cho hành tím thái lát vào phi vàng giòn rồi vớt một nửa ra chén để rắc mặt sau cùng. Cho tỏi băm, sả băm còn lại và sả cây đập dập vào phi thơm 30 giây, trút thịt gà đã ướp vào đảo săn 5 phút đến khi da gà căng bóng và thịt hơi chuyển vàng.', NULL, 5),
('vn-lau-02_v4_step_4', 'vn-lau-02', 4, 'cook', 'Hầm gà lấy nước dùng ngọt thanh', 'Đổ 2000 ml nước lọc vào nồi gà, bật lửa lớn đun sôi bùng rồi hớt sạch bọt nổi. Hạ xuống lửa vừa nhỏ, thả cà chua bổ múi cau và 1 quả ớt hiểm đập dập vào hầm thêm 18 phút đến khi thịt gà chín mềm hoàn toàn, không còn sắc đỏ bên trong xương và nước dùng ngọt thanh.', NULL, 18),
('vn-lau-02_v4_step_5', 'vn-lau-02', 5, 'cook', 'Thả lá giang tạo vị chua thanh và nêm gia vị', 'Nâng lửa vừa, thả toàn bộ lá giang đã vò dập vào nồi nấu khoảng 3 phút cho lá tiết vị chua thanh tự nhiên vào nước dùng. Nêm tiếp 25 ml nước mắm ngon, 7 g hạt nêm, 4 g muối ăn, 10 g đường cát trắng và 10 ml sa tế ớt sao cho cân bằng hài hòa vị chua cay mặn ngọt.', 'Nêm đường sau khi lá giang đã tiết hết vị chua sẽ giúp bạn dễ căn chỉnh độ chua ngọt tròn vị chuẩn Nam Bộ nhất.', 3),
('vn-lau-02_v4_step_6', 'vn-lau-02', 6, 'finish', 'Dọn nồi lẩu lên bếp bàn và nhúng rau tươi', 'Chuyển nồi lẩu sang bếp từ hoặc bếp ga mini đặt giữa bàn, rắc ngò gai, rau ngổ, hành phi vàng và 1 quả ớt hiểm thái lát lên mặt. Khi nước sôi lăn tăn, thực khách nhúng rau muống chẻ và hoa chuối bào ăn kèm bún gạo tươi nóng hổi.', NULL, NULL),
('vn-lau-03_v4_step_1', 'vn-lau-03', 1, 'prep', 'Sơ chế sạch tôm sú, mực ống và cá phi lê', 'Cắt râu và rút chỉ đen lưng 450 g tôm sú tươi rồi rửa sạch. Làm sạch 400 g mực ống tươi, lột bỏ túi mực và da ngoài nếu thích, khía vảy rồng nhẹ bên trong rồi thái khoanh hoặc miếng vừa ăn. Thái lát xéo dày 1 cm 300 g phi lê cá tươi, xếp tất cả hải sản lên đĩa lớn bọc màng thực phẩm giữ mát.', 'Giữ hải sản trong ngăn mát hoặc đặt trên lớp đá lạnh trước khi dọn bàn giúp thịt tôm, mực luôn tươi giòn và không bị tanh.', NULL),
('vn-lau-03_v4_step_2', 'vn-lau-03', 2, 'prep', 'Lọc me chín và sơ chế nấm, rau nhúng lẩu', 'Ngâm 60 g cơm me chín với 120 ml nước nóng, dằm nhuyễn rồi lọc qua rây bỏ hạt. Cắt gốc và rửa sạch nấm kim châm, nấm đùi gà thái lát xéo; rửa sạch rau muống và cải thảo cắt khúc 5 cm; băm nhỏ hành tím, tỏi khô, 1 cây sả; đập dập 3 cây sả còn lại, thái lát riềng, vò nhẹ lá chanh, bổ múi cau cà chua và thái lát dứa.', NULL, NULL),
('vn-lau-03_v4_step_3', 'vn-lau-03', 3, 'cook', 'Phi thơm sả riềng và xào sốt nền cà chua dứa', 'Làm nóng nồi trên lửa vừa với 25 ml dầu ăn, cho hành tím, tỏi, sả băm, sả cây đập dập và riềng thái lát vào phi thơm khoảng 2 phút. Thêm phần cà chua băm và dứa thái lát vào xào đều 3 phút đến khi cà chua mềm nhuyễn ra màu, tiếp tục đảo cùng 20 ml tương ớt và 20 ml tương cà cho dậy hương.', 'Xào tương ớt và tương cà trực tiếp trong dầu nóng cùng cà chua giúp màu nước lẩu đỏ cam óng đẹp mà không bị tách dầu.', 5),
('vn-lau-03_v4_step_4', 'vn-lau-03', 4, 'cook', 'Nấu sôi nước dùng chua cay thơm lá chanh', 'Đổ 1680 ml nước lọc vào nồi, bật lửa lớn đun sôi bùng rồi hớt bọt. Hạ lửa vừa nấu 6 phút cho sả, riềng và dứa tiết hết vị ngọt thơm, sau đó rót nước cốt me đã lọc vào cùng cà chua bổ múi cau, 1 quả ớt đập dập, 25 ml nước mắm ngon, 20 g đường cát trắng và 6 g muối ăn cho đạt vị chua cay mặn ngọt hài hòa.', NULL, 6),
('vn-lau-03_v4_step_5', 'vn-lau-03', 5, 'cook', 'Thả lá chanh và chuyển nước lẩu ra bàn tiệc', 'Thả lá chanh đã vò nhẹ vào nồi lẩu đun thêm 1 phút cho tinh dầu lan tỏa rồi tắt bếp chuyển sang nồi lẩu điện đặt giữa bàn, giữ sôi lăn tăn ở mức lửa vừa.', 'Chỉ thả lá chanh vào cuối bước nấu nước dùng để hương thơm thanh mát không bị đắng do đun lâu.', NULL),
('vn-lau-03_v4_step_6', 'vn-lau-03', 6, 'finish', 'Nhúng chín hải sản, nấm và rau xanh ăn kèm bún', 'Khi nước lẩu sôi sùng sục, cho nấm đùi gà vào trước 2 phút rồi lần lượt nhúng phi lê cá, tôm sú (khoảng 3 phút đến khi chuyển màu đỏ cam chín đều), mực ống (1–2 phút cho giòn sần sật), nấm kim châm, rau muống và cải thảo. Gắp ăn nóng kèm bún tươi và 2 quả ớt thái lát chấm nước mắm.', NULL, NULL),
('vn-lau-04_v4_step_1', 'vn-lau-04', 1, 'prep', 'Chần xương ống và sơ chế, ướp thịt gà ta', 'Rửa sạch 400 g xương ống heo rồi chần nước sôi 3 phút, xả sạch bọt bẩn. Chà xát 1200 g thịt gà ta với 4 g muối hạt, rửa sạch chặt miếng vừa ăn rồi ướp với 10 ml nước mắm, 5 g hạt nêm, 1,5 g tiêu đen xay và một nửa lượng tỏi băm trong 15 phút.', NULL, 15),
('vn-lau-04_v4_step_2', 'vn-lau-04', 2, 'prep', 'Sơ chế các loại nấm tươi, rau củ và thảo mộc', 'Cắt bỏ phần gốc bám đất của nấm đùi gà, nấm bào ngư, nấm kim châm, nấm hương tươi và nấm rơm; rửa nhẹ tay qua nước sạch rồi để ráo, thái lát nấm đùi gà và xếp thập cẩm nấm ra khay lớn. Cắt khoanh bắp ngọt, củ cải trắng, cà rốt; rửa sạch táo đỏ, kỷ tử, cải thảo, rau cải cúc và cắt khối 2,5 cm đậu phụ non.', 'Không bóp hay ngâm nấm quá lâu trong nước để các loại nấm giữ được độ giòn ngọt và hương thơm tự nhiên khi nhúng lẩu.', NULL),
('vn-lau-04_v4_step_3', 'vn-lau-04', 3, 'cook', 'Ninh xương ống cùng bắp ngọt và củ cải trắng', 'Cho xương ống heo đã chần vào nồi lớn cùng 3000 ml nước lọc, bắp ngọt cắt khoanh, củ cải trắng và 3 g muối hạt. Đun sôi bùng rồi hạ lửa nhỏ liu riu, đậy hé vung ninh khoảng 25 phút và thường xuyên hớt bọt để thu nước dùng trong vắt, ngọt thanh.', 'Ninh xương cùng củ cải trắng và bắp ngọt giúp nước lẩu ngọt tự nhiên sâu vị mà không cần dùng nhiều đường hay bột ngọt.', 25),
('vn-lau-04_v4_step_4', 'vn-lau-04', 4, 'cook', 'Phi thơm hành tỏi và xào săn thịt gà', 'Trong chảo hoặc nồi khác, làm nóng 15 ml dầu ăn trên lửa vừa, phi thơm 25 g hành tím băm và tỏi băm còn lại khoảng 30 giây. Cho gà ta đã ướp vào đảo săn 4 phút đến khi thịt săn chắc và lớp da hơi vàng thơm.', NULL, 4),
('vn-lau-04_v4_step_5', 'vn-lau-04', 5, 'cook', 'Nấu gà với nấm hương, cà rốt, táo đỏ và kỷ tử', 'Vớt bỏ xương ống từ nồi nước ninh hoặc giữ lại tùy thích, trút thịt gà đã xào săn vào nồi nước dùng cùng cà rốt, nấm hương tươi và táo đỏ kỷ tử. Ninh lửa vừa 15 phút cho gà chín mềm hoàn toàn và thấm vị thảo mộc, sau đó nêm 10 ml nước mắm ngon, 7 g hạt nêm và 3 g muối hạt còn lại sao cho vừa thanh dịu.', 'Cho một phần nấm hương tươi vào hầm cùng nước dùng sẽ giúp hương thơm nấm quyện sâu vào nước lẩu ngay từ đầu.', 15),
('vn-lau-04_v4_step_6', 'vn-lau-04', 6, 'finish', 'Bày nồi lẩu nấm và nhúng ăn nóng với mì trứng', 'Chuyển nồi lẩu ra bếp giữa bàn, nhẹ nhàng thả đậu phụ non vào đun sôi lăn tăn. Lần lượt nhúng nấm đùi gà, nấm bào ngư, nấm rơm, nấm kim châm khoảng 2–3 phút cho chín giòn ngọt, nhúng thêm cải thảo, rau cải cúc và ăn kèm mì trứng vắt đã trụng chín ráo.', NULL, NULL),
('vn-lau-05_v4_step_1', 'vn-lau-05', 1, 'prep', 'Ninh xương ống heo với hành tây và cà rốt', 'Chặt nhỏ 500 g xương ống heo, chà nhẹ với 2 g muối hạt rồi chần nước sôi 3 phút, rửa sạch bọt bẩn. Cho xương vào nồi cùng 2200 ml nước lọc, 1 củ hành tây bổ tư, 1 củ cà rốt thái khoanh và 5 g muối hạt, đun sôi rồi hạ lửa nhỏ liu riu ninh 25 phút và thường xuyên hớt bọt để nước dùng thật trong ngọt.', NULL, 25),
('vn-lau-05_v4_step_2', 'vn-lau-05', 2, 'prep', 'Quết dẻo dai chả cá thác lác với đầu hành thì là', 'Cho 450 g thịt cá thác lác nạo lạnh vào tô lớn cùng 15 ml nước mắm ngon, 4 g hạt nêm, 2 g tiêu trắng xay, đầu hành lá băm nhuyễn, một nửa hành tím băm, một nửa thì là thái nhỏ và 5 ml dầu ăn. Dùng muỗng chắc tay miết và quết liên tục theo một chiều khoảng 10 phút đến khi khối cá dẻo quánh, bám dính chặt vào tô.', 'Giữ thịt cá thác lác thật lạnh trong lúc quết và thoa chút dầu ăn vào muỗng sẽ giúp chả cá dai giòn tự nhiên, không bị bở hay dính tay.', 10),
('vn-lau-05_v4_step_3', 'vn-lau-05', 3, 'prep', 'Bào mỏng khổ qua và ngâm đá lạnh cho giòn mát', 'Bổ đôi 3 quả khổ qua tươi, dùng muỗng nạo thật sạch phần ruột và màng trắng bên trong để giảm vị đắng. Thái hoặc bào khổ qua thành lát thật mỏng, ngâm ngập vào thau nước đá lạnh pha 1 g muối hạt trong 10 phút cho khổ qua giòn rụm, sau đó vớt ráo xếp lên đĩa đá. Rửa sạch nấm kim châm, nấm rơm, rau cải cúc, rau muống và bày bún gạo tươi ra đĩa.', 'Nạo sạch phần màng trắng trong ruột khổ qua và ngâm nước đá lạnh giúp khổ qua giữ màu xanh ngọc, giòn sần sật và bớt đắng rõ rệt.', 10);
INSERT OR IGNORE INTO recipe_standard_v4_steps (id, recipe_id, step_number, phase, title, instruction, tip, timer_minutes) VALUES
('vn-lau-05_v4_step_4', 'vn-lau-05', 4, 'cook', 'Phi thơm hành tím và nêm nước lẩu thanh dịu', 'Làm nóng chảo nhỏ với 10 ml dầu ăn còn lại, phi thơm phần hành tím thái lát còn lại rồi trút vào nồi nước dùng xương đã ninh (có thể vớt bỏ xác hành tây và xương ống cho gọn nồi lẩu). Nêm 15 ml nước mắm ngon, 4 g hạt nêm và 12 g đường phèn khuấy tan, nếm lại vị ngọt thanh dịu.', NULL, NULL),
('vn-lau-05_v4_step_5', 'vn-lau-05', 5, 'cook', 'Múc viên chả cá thác lác thả chín trong nồi lẩu', 'Đặt nồi nước dùng lên bếp lẩu giữa bàn ở lửa vừa cho sôi lăn tăn. Thoa chút dầu lên 2 chiếc muỗng, khéo léo vo thành từng viên chả cá thác lác tròn dẹt rồi thả trực tiếp vào nồi nước dùng đang sôi cùng nấm rơm, nấu khoảng 4 phút đến khi từng viên cá nổi lên mặt nước, căng phồng và chín chắc hoàn toàn.', 'Duy trì nước lẩu sôi lăn tăn vừa phải khi thả viên cá thác lác để chả chín từ từ, nở phồng đẹp mắt và không bị rã bở.', 4),
('vn-lau-05_v4_step_6', 'vn-lau-05', 6, 'finish', 'Nhúng khổ qua, rau thơm và dùng nóng với bún', 'Rắc hành lá, ngò rí và phần thì là còn lại vào nồi lẩu. Khi ăn, gắp khổ qua bào mỏng nhúng nhanh vào nước lẩu sôi khoảng 15–20 giây cho vừa chín tái giòn ngọt, nhúng thêm nấm kim châm, rau cải cúc, rau muống rồi thưởng thức ngay cùng chả cá thác lác dai ngọt, bún gạo tươi và nước mắm ớt thái lát.', NULL, NULL),
('gl-01_v4_step_1', 'gl-01', 1, 'prep', 'Sơ chế tỏi, cà chua và húng quế', 'Bóc vỏ 2 tép tỏi tươi, chẻ đôi lấy bỏ phần lõi xanh ở giữa cho đỡ hăng rồi thái lát mỏng. Trút 400 g cà chua lột vỏ nghiền hộp Ý ra tô, dùng nĩa dằm sơ cho nát vừa còn chút thịt quả. Rửa sạch 8 g lá húng quế Tây tươi, thấm khô nước.', 'Tách bỏ lõi xanh giữa tép tỏi giúp dầu tỏi thơm ngọt mà không bị hăng gắt khi phi.', NULL),
('gl-01_v4_step_2', 'gl-01', 2, 'sauce', 'Phi tỏi với dầu ô liu trên lửa nhỏ', 'Bắc chảo sâu lòng lên bếp ở lửa nhỏ, cho 30 ml dầu ô liu nguyên chất vào làm ấm nhẹ. Thả tỏi lát vào phi đều tay khoảng 2 phút đến khi tỏi dậy mùi thơm và vừa ngả màu vàng nhạt thì hạ lửa thật nhỏ.', 'Không để dầu quá nóng hay tỏi chuyển nâu vì tỏi cháy sẽ làm sốt cà chua bị đắng.', 2),
('gl-01_v4_step_3', 'gl-01', 3, 'sauce', 'Ninh sốt cà chua Pomodoro sánh mịn', 'Trút toàn bộ cà chua nghiền vào chảo dầu tỏi, đảo đều và nêm 2 g muối hạt cùng 1 g tiêu đen xay. Đun sôi nhẹ rồi hạ lửa nhỏ, ninh liu riu khoảng 15 phút cho sốt sánh đặc lại và bay bớt vị chua gắt. Thả 4 lá húng quế Tây vào đảo nhẹ rồi ninh thêm 3 phút.', NULL, 18),
('gl-01_v4_step_4', 'gl-01', 4, 'cook', 'Luộc mì Ý đạt độ dai al dente', 'Đun sôi mạnh nồi lớn với 2 lít nước lọc, cho 10 g muối hạt vào khuấy tan rồi thả 200 g mì Ý Spaghetti khô vào. Luộc ở lửa lớn trong khoảng 8 phút (ít hơn 1 phút so với hướng dẫn trên bao bì) để sợi mì chín dẻo bên ngoài, còn hơi chắc lõi ở giữa.', 'Nước luộc mì cần đủ nhiều và có vị mặn nhẹ để sợi mì ngấm vị từ bên trong và không bị dính.', 8),
('gl-01_v4_step_5', 'gl-01', 5, 'cook', 'Nhũ tương hóa sốt với nước luộc mì', 'Trước khi vớt mì, múc giữ lại khoảng 120 ml nước luộc mì đục tinh bột. Gắp mì Ý cho thẳng vào chảo sốt cà chua, rưới thêm 2–3 muỗng canh nước luộc mì rồi bật lửa vừa, đảo và xóc đều tay 2 phút đến khi lớp sốt đỏ óng bám đều quanh từng sợi mì.', NULL, 2),
('gl-01_v4_step_6', 'gl-01', 6, 'finish', 'Hoàn thiện và rắc phô mai Parmesan', 'Tắt bếp, nếm lại độ mặn ngọt vừa miệng rồi chia mì ra 2 đĩa sâu lòng. Rắc 20 g phô mai Parmesan bào mịn nếu thích cùng phần lá húng quế Tây tươi còn lại lên trên và thưởng thức ngay khi còn nóng.', NULL, NULL),
('gl-02_v4_step_1', 'gl-02', 1, 'prep', 'Rang giã hoa tiêu và sơ chế hương liệu', 'Làm nóng chảo khô trên lửa nhỏ, cho 3 g hoa tiêu Tứ Xuyên vào rang khoảng 2 phút đến khi dậy mùi thơm đặc trưng rồi giã mịn thành bột, giữ lại 1/4 lượng bột hoa tiêu để rắc mặt sau cùng. Tỏi khô và gừng tươi băm thật nhuyễn; hành lá tách đầu hành trắng băm nhỏ và lá xanh thái khúc; băm nhuyễn tương ớt đậu bản Doubanjiang và đậu tương đen lên men Douchi; hòa tan 8 g bột bắp với 45 ml nước lọc.', 'Chỉ rang hoa tiêu trên lửa nhỏ và nhặt bỏ hạt đen bên trong trước khi giã sẽ tránh được vị đắng khét.', 2),
('gl-02_v4_step_2', 'gl-02', 2, 'prep', 'Cắt đậu phụ non và chần nước muối ấm', 'Nhẹ tay cắt 450 g đậu phụ non thành từng khối vuông cạnh 2 cm. Đun nóng 800 ml nước lọc cùng 2 g muối ăn đến khi vừa sôi lăn tăn, thả nhẹ đậu phụ vào chần 2 phút rồi dùng vợt lỗ vớt ra rổ thưa cho ráo nước, tránh làm vỡ nát miếng đậu.', 'Chần đậu phụ với nước muối loãng giúp khử mùi đậu sống và làm bề mặt miếng đậu săn chắc, ít vỡ khi om sốt.', 2),
('gl-02_v4_step_3', 'gl-02', 3, 'cook', 'Xào săn thịt heo xay', 'Ướp nhẹ 150 g thịt heo xay với 1 g muối ăn. Đặt chảo sâu lòng lên lửa vừa lớn, làm nóng 25 ml dầu ăn thực vật rồi cho thịt heo xay vào đảo tơi liên tục khoảng 3 phút đến khi thịt săn chắc, ráo nước và hơi xém vàng cạnh. Trút thịt ra chén riêng, giữ lại dầu thơm trong chảo.', NULL, 3),
('gl-02_v4_step_4', 'gl-02', 4, 'cook', 'Phi tương ớt đậu bản tạo dầu đỏ', 'Hạ lửa nhỏ, thêm 15 ml dầu ăn thực vật còn lại vào chảo, cho tương ớt đậu bản Doubanjiang đã băm nhuyễn vào đảo đều tay khoảng 1 phút cho đến khi dầu chuyển màu đỏ cam óng đẹp. Tiếp tục cho đậu tương đen lên men Douchi, 4 g ớt bột khô Tứ Xuyên, tỏi băm, gừng băm và đầu hành trắng vào xào thơm thêm 30 giây.', 'Xào tương ớt đậu bản ở lửa nhỏ giúp dầu tiết màu đỏ tự nhiên và dậy mùi thơm đậm mà không làm cháy tỏi gừng.', 2),
('gl-02_v4_step_5', 'gl-02', 5, 'cook', 'Nấu nước sốt và om thấm đậu phụ', 'Cho 3/4 phần bột hoa tiêu Tứ Xuyên vào đảo nhanh 15 giây, lập tức đổ 200 ml nước dùng gà, 15 ml xì dầu nhạt, 3 g đường cát trắng cùng một nửa lượng thịt heo xay vào nồi. Đun sôi nhẹ rồi hạ lửa nhỏ om 2 phút, sau đó thả nhẹ nhàng toàn bộ đậu phụ non vào, nghiêng lắc chảo hoặc dùng lưng muôi đẩy nhẹ, om liu riu 6 phút để đậu ngấm sâu gia vị.', 'Tuyệt đối không dùng đũa đảo mạnh tay; chỉ cần đẩy nhẹ bằng lưng muôi từ mép chảo vào trong để giữ nguyên khối đậu vuông đẹp.', 8),
('gl-02_v4_step_6', 'gl-02', 6, 'finish', 'Sánh sốt, rưới dầu mè và hoàn thiện', 'Khuấy đều chén nước bột bắp cho không bị lắng đáy, rót một nửa vào chảo sốt đang sôi nhẹ rồi đẩy nhẹ đậu phụ 30 giây cho sốt bắt đầu sánh, tiếp tục rót phần nước bột bắp còn lại đến khi sốt sánh bóng bám đều từng miếng đậu. Rắc nốt nửa phần thịt heo xay giòn lên trên, rưới 5 ml dầu mè thơm, tắt bếp dọn ra đĩa sâu lòng và rắc phần lá hành xanh cùng bột hoa tiêu giữ riêng lên mặt.', NULL, NULL),
('gl-03_v4_step_1', 'gl-03', 1, 'prep', 'Sơ chế cà chua và hành lá', 'Rửa sạch 4 quả cà chua chín đỏ, khoét bỏ phần cuống cứng rồi bổ thành những múi cau nhỏ đều nhau để cà chua nhanh mềm và tiết nước khi xào. Hành lá tươi rửa sạch, thái nhỏ toàn bộ để riêng.', 'Chọn cà chua chín đỏ mọng nhưng còn chắc tay sẽ cho nước sốt đậm màu đẹp và vị ngọt tự nhiên hơn.', NULL),
('gl-03_v4_step_2', 'gl-03', 2, 'prep', 'Đánh tan trứng gà với gia vị', 'Đập 4 quả trứng gà tươi vào tô, thêm 1,5 g muối ăn, 1 g tiêu trắng xay, 3 ml dầu mè thơm và 5 ml rượu Thiệu Hưng. Dùng đũa đánh đều tay khoảng 1 phút cho lòng trắng và lòng đỏ hòa quyện hơi nổi bọt nhẹ.', 'Nêm rượu Thiệu Hưng và dầu mè ngay vào tô trứng giúp trứng dậy mùi thơm, khử tanh và chiên lên xốp mềm hơn.', 1),
('gl-03_v4_step_3', 'gl-03', 3, 'cook', 'Chiên xốp trứng gà trên chảo nóng', 'Làm nóng chảo sâu lòng trên lửa vừa lớn đến khi bề mặt hơi bốc khói nhẹ, rót 25 ml dầu ăn thực vật tráng đều lòng chảo. Đổ hỗn hợp trứng gà vào, dùng sạn gỗ đẩy nhẹ từ ngoài vào trong tạo thành từng mảng trứng mềm xốp. Khi trứng vừa đông khoảng 85–90% nhưng bề mặt vẫn còn hơi ẩm bóng thì lập tức xúc ra đĩa riêng.', 'Không chiên trứng quá khô vì trứng sẽ còn được đảo tiếp trong sốt cà chua ở bước sau.', 2),
('gl-03_v4_step_4', 'gl-03', 4, 'cook', 'Xào cà chua với hành lá', 'Thêm 10 ml dầu ăn thực vật còn lại vào chảo, bật lửa lớn, cho toàn bộ cà chua múi cau và một nửa lượng hành lá thái nhỏ vào đảo nhanh tay trong 1 phút cho cà chua bắt đầu xém cạnh và thơm nhẹ.', NULL, 1),
('gl-03_v4_step_5', 'gl-03', 5, 'cook', 'Om mềm cà chua tạo sốt chua ngọt', 'Thêm 8 g đường cát trắng, 2,5 g muối ăn còn lại cùng 60 ml nước lọc vào chảo cà chua, đảo nhẹ rồi cho phần trứng gà đã chiên trở lại chảo. Đậy nắp vung, hạ lửa vừa và om khoảng 2 phút cho cà chua mềm nhừ, tiết nước sốt đỏ sánh quyện vào trứng.', 'Đậy nắp giúp cà chua chín mềm ra nước nhanh mà không cần dùng nhiều dầu ăn.', 2),
('gl-03_v4_step_6', 'gl-03', 6, 'finish', 'Hoàn thiện và trình bày nóng', 'Mở nắp, dùng sạn đảo nhẹ 20–30 giây cho sốt cà chua áo đều từng miếng trứng vàng mềm, nêm lại muối và đường nếu cần rồi rắc nốt phần hành lá thái nhỏ còn lại lên trên. Tắt bếp, trút ra đĩa sâu lòng và dùng nóng ngay cùng cơm trắng.', NULL, NULL),
('gl-04_v4_step_1', 'gl-04', 1, 'prep', 'Sơ chế và ướp thịt đùi gà với rượu Sake', 'Làm sạch 280 g thịt đùi gà lọc xương, thấm khô bằng khăn giấy rồi cắt miếng vuông cạnh 2 cm theo góc dao nghiêng để miếng thịt dày đều. Cho thịt gà vào bát, rưới 15 ml rượu Sake nấu ăn lên trộn đều và ướp trong 5 phút cho thịt mềm và hết mùi tanh.', 'Cắt thịt gà theo góc dao nghiêng giúp tăng diện tích tiếp xúc với nước sốt, thịt chín nhanh và thấm đều hơn mà không bị khô.', 5),
('gl-04_v4_step_2', 'gl-04', 2, 'sauce', 'Thái rau củ và pha hỗn hợp nước sốt om', 'Thái dọc 1/2 củ hành tây thành múi mỏng 5 mm và cắt nhỏ 1/2 bó hành lá. Trong bát nhỏ, khuấy tan 120 ml nước dùng Dashi, 30 ml nước tương Nhật, 30 ml rượu ngọt Mirin và 8 g đường cát trắng đến khi đường hòa quyện hoàn toàn.', 'Hòa tan đường trước trong nước sốt nguội sẽ giúp nước om trong chảo đậm đều ngay từ đầu, tránh bị cháy đường ở đáy chảo.', NULL),
('gl-04_v4_step_3', 'gl-04', 3, 'cook', 'Nấu mềm hành tây trong nước sốt', 'Đổ hỗn hợp nước sốt Dashi đã pha vào chảo nông đường kính 20 cm, đặt lên bếp lửa vừa và không đậy nắp. Khi nước sốt vừa sôi lăn tăn, thả hành tây thái mỏng vào dàn đều, nấu mở nắp khoảng 3 phút cho đến khi hành tây chuyển trong và tiết vị ngọt tự nhiên.', NULL, 3),
('gl-04_v4_step_4', 'gl-04', 4, 'cook', 'Om chín hoàn toàn thịt đùi gà', 'Xếp đều từng miếng thịt đùi gà đã ướp vào chảo nước sốt đang sôi nhẹ trên lửa vừa. Nấu khoảng 4–5 phút và trở mặt gà giữa chừng cho đến khi thịt gà chuyển màu trắng đục hoàn toàn, không còn sắc hồng ở lõi và nước sốt hơi rút sánh lại.', NULL, 5),
('gl-04_v4_step_5', 'gl-04', 5, 'cook', 'Đánh nhẹ và rưới trứng thành hai lần', 'Đập 3 quả trứng gà vào bát, dùng đũa gạt cắt lòng trắng 5–6 nhịp cho tơi nhẹ, giữ lại vân trắng vàng. Rưới 2/3 phần trứng (ưu tiên lòng trắng) vào giữa chảo trên lửa vừa nhỏ, chờ 30 giây cho trứng hơi se mặt rồi rưới nốt 1/3 trứng còn lại đều khắp, đậy vung nấu thêm 1–2 phút đến khi trứng chín tới mềm mịn.', 'Không đánh trứng tan bông hoàn toàn vì sẽ làm món trứng mất đi vân cẩm thạch trắng vàng đẹp mắt và độ béo bùi đặc trưng.', 2),
('gl-04_v4_step_6', 'gl-04', 6, 'finish', 'Trình bày tô cơm Oyakodon và thưởng thức nóng', 'Xới 360 g cơm gạo Nhật nóng vào hai tô donburi, lắc nhẹ chảo rồi trượt nguyên mảng gà trứng cùng nước sốt phủ kín mặt cơm. Rắc hành lá thái nhỏ và chút bột ớt 7 vị Nhật Shichimi lên trên rồi dọn ăn ngay khi còn nóng.', NULL, NULL),
('gl-05_v4_step_1', 'gl-05', 1, 'prep', 'Sơ chế kim chi, rau củ và dằm tơi cơm nguội', 'Vắt nhẹ 160 g kim chi cải thảo ủ chua để chắt riêng khoảng 40 ml nước kim chi vào chén, phần cái thái nhỏ cỡ 1 cm. Thái hạt lựu nhỏ hành tây và cà rốt, thái nhỏ hành lá. Dùng tay hoặc thìa dằm nhẹ cho 450 g cơm trắng nguội hạt ngắn tơi đều, không vón cục.', 'Dùng cơm nguội để qua đêm trong tủ lạnh giúp hạt cơm se mặt, khi chiên sẽ săn tơi và không bị bết dính.', NULL),
('gl-05_v4_step_2', 'gl-05', 2, 'sauce', 'Pha hỗn hợp sốt Gochujang chua cay', 'Cho 20 g tương ớt Hàn Quốc (Gochujang), 15 ml nước tương và phần nước kim chi đã vắt vào chén nhỏ, khuấy đều tay cho đến khi hỗn hợp sốt hòa quyện sánh mịn.', 'Pha sẵn sốt trước giúp gia vị bám đều lên từng hạt cơm khi đảo nhanh trên chảo nóng.', NULL),
('gl-05_v4_step_3', 'gl-05', 3, 'cook', 'Xào thơm hành tây, cà rốt và kim chi', 'Làm nóng chảo sâu lòng trên lửa vừa với 5 ml dầu thực vật, cho đầu hành lá, hành tây và cà rốt vào đảo đều 2 phút đến khi hành tây hơi trong. Tiếp tục cho phần kim chi cải thảo thái nhỏ vào xào thêm 2 phút cho kim chi săn ráo và dậy mùi thơm đặc trưng.', NULL, 4),
('gl-05_v4_step_4', 'gl-05', 4, 'cook', 'Rang cơm và áo đều sốt Gochujang', 'Tăng lên lửa lớn, trút toàn bộ 450 g cơm trắng nguội vào chảo, đảo đều và ép nhẹ mặt cơm xuống đáy chảo khoảng 3 phút cho hạt cơm nóng ráo, săn chắc. Rưới đều chén sốt Gochujang vào, đảo nhanh tay thêm 2 phút để từng hạt cơm nhuộm màu đỏ cam bóng đẹp và thấm gia vị.', 'Dàn cơm mỏng trên mặt chảo vài giây trước khi đảo sẽ tạo lớp cháy xém nhẹ rất thơm.', 5),
('gl-05_v4_step_5', 'gl-05', 5, 'cook', 'Chiên trứng ốp la lòng đào', 'Trong một chảo chống dính nhỏ, đun nóng 5 ml dầu thực vật còn lại trên lửa vừa, đập nhẹ 2 quả trứng gà tươi vào chiên khoảng 3 phút đến khi lòng trắng đông chín hoàn toàn, viền hơi giòn còn lòng đỏ vẫn giữ độ sánh lòng đào.', NULL, 3),
('gl-05_v4_step_6', 'gl-05', 6, 'finish', 'Trộn dầu mè và trình bày đĩa cơm', 'Tắt bếp chảo cơm chiên, rưới 10 ml dầu mè rang, rắc phần hành lá xanh và một nửa lượng hạt mè trắng rang vào đảo đều một lượt cho thơm. Xới cơm ra 2 đĩa, đặt trứng ốp la lên trên, rắc nốt phần hạt mè trắng rang và rong biển lá khô xé nhỏ rồi thưởng thức ngay khi nóng.', NULL, NULL),
('gl-06_v4_step_1', 'gl-06', 1, 'prep', 'Giã tỏi ớt và sơ chế rau củ', 'Cho 1/2 củ tỏi khô bóc vỏ cùng 3 quả ớt hiểm vào cối, giã dập thành hỗn hợp sần sùi để tinh dầu tiết ra mạnh hơn so với băm. Thái lát xéo 1 quả ớt sừng đỏ. Tước xơ 100 g đậu que và cắt khúc ngắn 1 cm. Nhặt 25 g lá húng quế Thái, rửa nhẹ rồi vẩy thật ráo.', 'Không nên giã tỏi ớt quá nhuyễn thành bột vì khi gặp dầu nóng rất dễ cháy khét và tạo vị đắng.', NULL),
('gl-06_v4_step_2', 'gl-06', 2, 'sauce', 'Pha sẵn nước sốt xào đậm đà', 'Trộn đều trong một chén nhỏ gồm 15 ml xì dầu đen đặc Thái, 15 ml xì dầu nhạt, 10 ml nước mắm ngon, 5 g đường cát trắng và 30 ml nước lọc. Khuấy kỹ đến khi đường tan hoàn toàn để sẵn ngay cạnh bếp.', 'Các bước xào Pad Krapow diễn ra rất nhanh trên lửa lớn nên việc pha sẵn sốt giúp thịt không bị quá lửa trong lúc nêm.', NULL),
('gl-06_v4_step_3', 'gl-06', 3, 'cook', 'Phi thơm tỏi ớt và xào săn thịt heo băm', 'Đun nóng chảo sâu lòng trên lửa lớn với 20 ml dầu ăn đến khi dầu lăn tăn hơi nóng, cho hỗn hợp tỏi và ớt hiểm giã dập vào đảo nhanh khoảng 20 giây cho dậy mùi thơm nồng. Lập tức trút 300 g thịt heo xay vào chảo, dùng xẻng dằm tơi đều tay và xào liên tục khoảng 4 phút đến khi thịt săn rời, ráo nước và chín hoàn toàn không còn màu hồng.', 'Giữ lửa lớn và dằm thịt thật tơi ngay từ đầu để thịt ra hết nước thừa nhanh, áp chảo hơi xém cạnh sẽ thơm mùi khói chảo.', 4),
('gl-06_v4_step_4', 'gl-06', 4, 'cook', 'Xào đậu que và áo đều nước sốt', 'Cho 100 g đậu que cắt khúc cùng ớt sừng đỏ thái lát vào chảo thịt, đảo đều 1 phút trên lửa lớn. Khuấy lại chén nước sốt rồi rưới hết vào chảo, tiếp tục đảo nhanh tay thêm 2 phút cho nước sốt sôi bùng, keo nhẹ lại và bám bóng đều quanh từng hạt thịt heo.', NULL, 3),
('gl-06_v4_step_5', 'gl-06', 5, 'finish', 'Tắt bếp và đảo nhanh lá húng quế Thái', 'Tắt bếp ngay khi nước sốt vừa sệt, cho toàn bộ 25 g lá húng quế Thái vào chảo và đảo nhanh 10–15 giây cho lá vừa xẹp xuống, tỏa hương thơm nồng nàn nhờ nhiệt dư rồi trút ngay ra đĩa.', 'Cho lá húng quế vào sau khi đã tắt bếp giúp giữ trọn màu xanh tươi và tinh dầu thơm đặc trưng của lá quế.', NULL),
('gl-06_v4_step_6', 'gl-06', 6, 'cook', 'Chiên trứng gà ốp la viền giòn kiểu Thái', 'Dùng một chảo nhỏ làm nóng 15 ml dầu ăn còn lại trên lửa vừa lớn đến khi dầu thật nóng già, nhẹ nhàng trượt từng quả trứng gà (2 quả) vào chiên khoảng 2 phút. Nghiêng nhẹ chảo và múc dầu nóng rưới lên mặt lòng trắng để viền trứng phồng giòn vàng rụm trong khi lòng đỏ vẫn béo sánh lòng đào rồi vớt ra.', NULL, 2),
('gl-06_v4_step_7', 'gl-06', 7, 'finish', 'Trình bày cơm đĩa Pad Krapow nóng hổi', 'Ép nhẹ 300 g cơm trắng nóng vào chén rồi úp ra 2 đĩa, múc phần thịt heo băm xào lá quế sang bên cạnh và đặt mỗi đĩa 1 quả trứng ốp la giòn viền lên trên, dọn dùng ngay khi còn nóng.', NULL, NULL),
('gl-07_v4_step_1', 'gl-07', 1, 'prep', 'Trộn cơm dầu mè và ướp thịt bò', 'Xới 650 g cơm trắng dẻo hạt ngắn còn âm ấm ra tô lớn, trộn đều với 2,5 g muối ăn, 15 ml dầu mè rang và 9 g hạt mè trắng rang rồi để nguội bớt. Ở tô khác, ướp 200 g thịt bò thăn thái sợi với 30 ml nước tương, 5 g đường cát trắng, một nửa lượng tỏi khô băm nhuyễn, 5 ml dầu mè rang và 1 g tiêu đen xay trong 15 phút.', 'Nêm gia vị khi cơm còn ấm giúp muối tan đều và hạt cơm bóng thơm mà không bị nát.', 15),
('gl-07_v4_step_2', 'gl-07', 2, 'prep', 'Chần rau chân vịt và vắt thật ráo', 'Đun sôi 1 lít nước lọc trên lửa lớn, thả 200 g rau chân vịt vào chần nhanh trong 45 giây cho vừa chín xanh mướt. Vớt ngay ra thau nước lạnh cho giữ màu, sau đó vắt thật kiệt nước bằng hai tay và trộn đều với 10 ml dầu mè rang, 1 g muối ăn cùng phần tỏi khô băm nhuyễn còn lại.', 'Vắt rau thật ráo là bí quyết giúp cuộn Kimbap không bị ướt nhão và giữ được độ giòn của rong biển.', 1),
('gl-07_v4_step_3', 'gl-07', 3, 'cook', 'Tráng trứng mỏng và xào cà rốt', 'Đánh tan 3 quả trứng gà tươi với 1 g muối ăn, làm nóng chảo chống dính với 7 ml dầu thực vật trên lửa nhỏ rồi đổ trứng vào tráng thành 2–3 lớp mỏng vàng đều, để nguội và thái sợi dài. Tiếp tục dùng 6 ml dầu thực vật xào nhanh cà rốt thái sợi với 0,5 g muối ăn trên lửa vừa khoảng 2 phút đến khi vừa chín tới nhưng vẫn giữ độ giòn.', NULL, 5),
('gl-07_v4_step_4', 'gl-07', 4, 'cook', 'Xào chín thịt bò trên lửa lớn', 'Làm nóng chảo với 7 ml dầu thực vật còn lại trên lửa lớn, trút toàn bộ thịt bò thăn đã ướp vào đảo nhanh tay trong 3 phút đến khi thịt săn chín hoàn toàn và hơi xém cạnh thơm lừng, sau đó trút ra đĩa để ráo bớt nước.', NULL, 3),
('gl-07_v4_step_5', 'gl-07', 5, 'finish', 'Trải cơm, xếp nhân và cuộn chặt Kimbap', 'Đặt 1 tấm mành tre lên mặt phẳng sạch, trải 1 lá rong biển lá khô cuộn Kimbap (mặt nhám hướng lên trên). Dàn đều khoảng 130 g cơm trộn thành lớp mỏng phủ 3/4 diện tích lá, chừa mép trên khoảng 2 cm. Xếp lần lượt thịt bò xào, trứng tráng thái sợi, cà rốt, rau chân vịt và 1 thanh củ cải muối vàng thành hàng ngang gọn gàng.', 'Thấm một chút nước lên đầu ngón tay khi dàn cơm để cơm không dính tay và giữ lớp cơm mỏng đều.', NULL),
('gl-07_v4_step_6', 'gl-07', 6, 'finish', 'Cuộn tròn, phết dầu mè và cắt khoanh', 'Cuộn chặt tay từ mép dưới qua mành tre, vừa cuộn vừa nén nhẹ để nhân cố định ở giữa, thấm chút nước lên mép rong biển trống để dán kín cuộn. Lặp lại cho đủ 5 cuộn, phết 5 ml dầu mè rang còn lại lên mặt ngoài vỏ rong biển cho bóng thơm rồi dùng dao sắc lau ẩm cắt thành từng khoanh tròn dày 1,5–2 cm.', NULL, NULL),
('gl-08_v4_step_1', 'gl-08', 1, 'prep', 'Luộc trứng gà lòng đào và sơ chế nguyên liệu', 'Đun sôi nước trong nồi nhỏ, thả nhẹ 2 quả trứng gà vào luộc đúng 7 phút trên lửa vừa để đạt độ lòng đào dẻo, sau đó vớt ra ngâm ngay vào nước lạnh rồi bóc vỏ. Rửa sạch 300 g bánh gạo Hàn Quốc dạng thỏi, cắt miếng chả cá Hàn Quốc, cắt vuông bắp cải trắng và cắt khúc 4 cm hành lá tươi.', 'Nếu dùng bánh gạo bảo quản lạnh bị cứng, ngâm nước ấm 10–15 phút trước khi nấu giúp bánh chín đều mà không nát bề mặt.', 7),
('gl-08_v4_step_2', 'gl-08', 2, 'sauce', 'Pha nước sốt cay ngọt Gochujang', 'Đổ 480 ml nước dùng cá cơm tảo bẹ vào chảo sâu lòng, cho 38 g tương ớt Hàn Quốc (Gochujang), 3 g ớt bột Hàn Quốc (Gochugaru), 10 ml nước tương, 16 g đường cát trắng, 15 ml siro ngô và tỏi khô băm nhuyễn vào khuấy tan hoàn toàn trên lửa vừa.', 'Khuấy tan hoàn toàn tương ớt Gochujang trước khi thả bánh gạo để sốt mịn đều, không bị vón cục.', NULL),
('gl-08_v4_step_3', 'gl-08', 3, 'cook', 'Nấu mềm bánh gạo trong nước sốt', 'Khi nước sốt sôi lăn tăn, thả toàn bộ bánh gạo Hàn Quốc dạng thỏi vào chảo, hạ lửa vừa-nhỏ và nấu khoảng 6 phút. Khuấy nhẹ tay thường xuyên để tinh bột từ bánh gạo tiết ra làm nước sốt sánh dần và bánh không bị dính đáy chảo.', NULL, 6),
('gl-08_v4_step_4', 'gl-08', 4, 'cook', 'Thêm bắp cải và chả cá Hàn Quốc', 'Cho bắp cải trắng và chả cá Hàn Quốc thái miếng vào chảo, đảo đều nhẹ nhàng và tiếp tục đun liu riu thêm 4 phút cho bắp cải chín mềm tiết vị ngọt tự nhiên, chả cá nở phồng thấm sốt cay ngọt đỏ au.', 'Không đun quá cạn vì nước sốt Tokbokki sẽ đặc thêm nhẹ khi nguội bớt.', 4),
('gl-08_v4_step_5', 'gl-08', 5, 'cook', 'Áo sốt cho trứng gà luộc và hành lá', 'Thả trứng gà luộc đã bóc vỏ cùng hành lá tươi cắt khúc vào chảo, dùng muỗng rưới đều phần sốt sánh lên mặt trứng và nấu thêm 1–2 phút cho hành vừa chín tái dậy mùi thơm.', NULL, NULL),
('gl-08_v4_step_6', 'gl-08', 6, 'finish', 'Rưới dầu mè và dọn nóng', 'Tắt bếp, rưới 5 ml dầu mè rang lên khắp mặt chảo và đảo nhẹ một lượt. Múc Tokbokki cùng chả cá, bắp cải ra đĩa sâu lòng, cắt đôi trứng gà đặt lên trên và rắc hạt mè trắng rang trang trí rồi thưởng thức ngay.', NULL, NULL),
('gl-09_v4_step_1', 'gl-09', 1, 'prep', 'Ngâm nấm hương khô và sơ chế nấm tươi', 'Ngâm 8 g nấm hương khô trong 50 ml nước lọc ấm khoảng 15 phút cho nở mềm hoàn toàn, vắt nhẹ ráo nước rồi cắt bỏ chân nấm, thái lát mỏng. Phần 50 g nấm tươi cắt bỏ gốc, tách thành từng nhánh nhỏ vừa miệng và 30 g chả cá Nhật thái 4 lát mỏng.', NULL, 15),
('gl-09_v4_step_2', 'gl-09', 2, 'marinate', 'Sơ chế và ướp tôm cùng thịt gà với rượu Sake', 'Lột vỏ 80 g tôm tươi, rút bỏ chỉ đen sống lưng; cắt 70 g thịt đùi gà thành miếng nhỏ 1,5 cm. Cho tôm và gà vào hai bát riêng, rưới mỗi bát 10 ml rượu Sake nấu ăn (tổng 20 ml) và ướp 10 phút giúp thịt thơm và sạch mùi.', NULL, 10),
('gl-09_v4_step_3', 'gl-09', 3, 'sauce', 'Pha hỗn hợp trứng dashi và lọc qua rây mịn', 'Đập 2 quả trứng gà vào bát, dùng đũa đánh tan nhẹ nhàng sát đáy bát theo đường zíc zắc để tránh nổi bọt. Rót từ từ 220 ml nước dùng Dashi đã nguội hoàn toàn cùng 5 ml nước tương Nhật, 5 ml rượu ngọt Mirin và 1 g muối ăn vào khuấy đều, sau đó lọc hỗn hợp qua rây mịn 2 lần vào ca rót.', 'Nước dùng Dashi bắt buộc phải nguội trước khi trộn với trứng để tránh làm trứng chín vón cục ngay trong bát.', NULL),
('gl-09_v4_step_4', 'gl-09', 4, 'prep', 'Xếp nhân và rót trứng vào hai chén sứ', 'Chia đều thịt đùi gà, nấm hương thái lát và nấm tươi xuống đáy hai chén sứ có nắp. Đặt tôm tươi và lát chả cá Nhật lên lớp trên để tạo điểm nhấn màu sắc, từ từ rót hỗn hợp trứng qua thành chén đến khoảng 80% dung tích, hớt sạch bọt khí li ti trên bề mặt rồi đậy kín nắp chén hoặc bọc màng giấy bạc.', 'Hớt sạch toàn bộ bọt khí trên mặt chén trước khi hấp giúp bề mặt trứng chín bóng láng như gương.', NULL),
('gl-09_v4_step_5', 'gl-09', 5, 'cook', 'Hấp cách thủy trứng ở lửa nhỏ nhất', 'Đun sôi nồi nước cao đến khoảng nửa thân chén hấp, sau đó hạ ngay xuống mức lửa nhỏ nhất để nước chỉ lăn tăn hơi nóng ở 85–90°C. Nhẹ nhàng đặt hai chén trứng vào nồi, đậy nắp nồi hơi hé một khe nhỏ bằng chiếc đũa và hấp liu riu 22–25 phút cho đến khi trứng đông mịn hoàn toàn và tôm gà chín kỹ.', 'Tuyệt đối không để nước trong nồi sôi bùng vì nhiệt quá cao sẽ khiến trứng tách nước và bị rỗ mặt như tổ ong.', 24),
('gl-09_v4_step_6', 'gl-09', 6, 'finish', 'Kiểm tra độ chín và dọn thưởng thức nóng', 'Mở nắp chén, dùng đầu xiên tre châm nhẹ vào giữa phần trứng: nếu nước tiết ra trong veo (không đục) là trứng đã chín đều và gà tôm đạt chuẩn an toàn. Rắc hành lá thái mỏng lên mặt chén, đậy nắp lại 1 phút cho dậy hương rồi dọn dùng nóng với thìa nhỏ.', NULL, NULL),
('gl-10_v4_step_1', 'gl-10', 1, 'prep', 'Tăng hương sốt cà ri xanh và sơ chế nguyên liệu', 'Cho 45 g sốt cà ri xanh Thái, 4 g mắm tôm và 10 g lá húng quế Thái vào cối giã hoặc máy xay nhỏ, nghiền quyện thành hỗn hợp xanh mượt dậy mùi tươi mới. Cắt 400 g thịt đùi gà thành miếng vuông 3–4 cm. Cắt 170 g cà tím thành múi cau vừa ăn, thái sợi 1/2 quả ớt chuông đỏ và thái lát 2 quả ớt sừng đỏ.', 'Giã thêm lá húng quế tươi cùng mắm tôm giúp sốt cà ri đóng gói có màu xanh đẹp và hương thơm đậm như giã tay tại nhà.', NULL),
('gl-10_v4_step_2', 'gl-10', 2, 'cook', 'Đun tách dầu cốt dừa và xào thơm sốt cà ri', 'Múc 120 ml phần kem đặc phía trên của nước cốt dừa cho vào nồi đáy dày, đun trên lửa vừa và khuấy nhẹ khoảng 4 phút đến khi nước bay hơi bớt và thấy lớp dầu dừa trong óng ánh tách nổi lên mặt. Cho toàn bộ hỗn hợp sốt cà ri xanh vào đảo đều tay thêm 3–4 phút cho đến khi sốt thơm nồng và sánh bóng.', 'Kỹ thuật tách dầu trực tiếp từ nước cốt dừa giúp món cà ri Thái có độ béo ngậy tự nhiên mà không cần dùng thêm dầu ăn.', 4),
('gl-10_v4_step_3', 'gl-10', 3, 'cook', 'Xào săn đùi gà và om mềm với nước dùng', 'Cho 400 g thịt đùi gà vào nồi sốt cà ri, đảo đều khoảng 3 phút trên lửa vừa để từng miếng thịt săn lại và áo kín lớp sốt thơm. Rót 180 ml nước dùng gà vào nồi, thả 4 g lá chanh Thái xé nhỏ bỏ gân vào rồi hạ lửa nhỏ, đậy hé nắp om liu riu 12 phút đến khi thịt gà chín mềm hoàn toàn và thấm vị.', NULL, 12),
('gl-10_v4_step_4', 'gl-10', 4, 'cook', 'Nấu cà tím, ớt chuông và nêm gia vị', 'Vớt bỏ bớt lá chanh cứng nếu thích, cho 170 g cà tím và 1/2 quả ớt chuông đỏ thái sợi vào nồi nấu tiếp khoảng 5 phút đến khi cà tím vừa chín mềm mà vẫn giữ nguyên khối không nát. Nêm 20 g đường thốt nốt băm nhỏ cùng 20 ml nước mắm ngon, khuấy tan rồi nếm điều chỉnh cho vị mặn ngọt cay béo hài hòa.', NULL, 5),
('gl-10_v4_step_5', 'gl-10', 5, 'cook', 'Hòa phần nước cốt dừa còn lại', 'Rót 180 ml nước cốt dừa còn lại vào nồi, khuấy nhẹ tay và đun sôi lăn tăn trên lửa nhỏ thêm 2 phút để nước cà ri sánh mịn, hòa quyện đều màu xanh ngọc dịu mắt.', 'Không đun sôi mạnh sau khi đã cho phần cốt dừa cuối vào vì nhiệt cao sẽ làm cốt dừa bị tách béo và lợn cợn.', 2),
('gl-10_v4_step_6', 'gl-10', 6, 'finish', 'Tắt bếp thả húng quế và dọn nóng', 'Tắt bếp ngay rồi cho 15 g lá húng quế Thái còn lại vào đảo nhẹ cho lá vừa héo dậy mùi thơm. Múc cà ri xanh thịt gà ra tô sâu lòng, xếp vài lát ớt sừng đỏ lên trên và dọn nóng ngay.', NULL, NULL),
('gl-11_v4_step_1', 'gl-11', 1, 'prep', 'Thái hạt lựu thịt xông khói và rau củ nền', 'Thái hạt lựu nhỏ 75 g thịt ba chỉ xông khói Pancetta. Gọt vỏ cà rốt, nhặt rửa cần tây và bóc vỏ hành tây rồi băm thật nhỏ cả ba loại rau củ để làm nền soffritto giúp sốt ngọt tự nhiên.', NULL, NULL),
('gl-11_v4_step_2', 'gl-11', 2, 'cook', 'Xào thịt xông khói và rau củ soffritto', 'Bắc nồi đáy dày lên bếp ở lửa vừa, cho 15 ml dầu ô liu và thịt ba chỉ xông khói vào đảo 4 phút đến khi ra mỡ và hơi xém cạnh. Trút cà rốt, cần tây và hành tây vào xào chậm khoảng 8 phút đến khi rau mềm trong và thơm ngọt, không để cháy xém.', 'Xào chậm rau củ trên lửa vừa giúp giải phóng đường tự nhiên tạo độ ngọt sâu cho sốt Bolognese.', 8),
('gl-11_v4_step_3', 'gl-11', 3, 'cook', 'Xào săn thịt bò xay và khử rượu vang', 'Tăng lên lửa vừa-lớn, cho 250 g thịt bò xay vào nồi, dùng muỗng gỗ dằm tơi và đảo đều khoảng 6 phút đến khi thịt săn chắc, chín hoàn toàn hết màu hồng. Đổ 100 ml rượu vang trắng khô nấu ăn vào, đảo đều 3 phút đến khi cồn bay hơi hết.', NULL, 9),
('gl-11_v4_step_4', 'gl-11', 4, 'sauce', 'Hầm sốt cà chua cùng nước dùng bò và sữa tươi', 'Đổ 300 g sốt cà chua xay nhuyễn Passata vào nồi, nêm 4 g muối ăn và 2 g tiêu đen xay. Hạ lửa thật nhỏ, đậy vung hờ và hầm liu riu khoảng 40 phút, thỉnh thoảng khuấy đều và châm dần 250 ml nước dùng bò nếu sốt đặc. Khi còn 10 phút cuối, rót 100 ml sữa tươi nguyên kem vào khuấy đều cho sốt béo mịn.', 'Sữa tươi giúp trung hòa vị chua gắt của cà chua và làm thịt bò xay mềm mượt hơn.', 40),
('gl-11_v4_step_5', 'gl-11', 5, 'cook', 'Luộc mì Ý Spaghetti chín độ al dente', 'Khi sốt gần hầm xong, đun sôi mạnh nồi với 2,5 lít nước lọc cùng 8 g muối ăn. Thả 250 g mì Ý Spaghetti khô vào luộc khoảng 8–9 phút cho đến khi sợi mì chín dai vừa tới, giữ lại 100 ml nước luộc mì trước khi vớt.', NULL, 9),
('gl-11_v4_step_6', 'gl-11', 6, 'finish', 'Trộn mì với sốt và rắc phô mai', 'Cho mì đã vớt vào nồi sốt Bolognese cùng 2–3 muỗng canh nước luộc mì, đảo đều trên lửa vừa 1 phút cho sốt bám đều từng sợi mì. Tắt bếp, chia ra 3 đĩa sâu lòng, rắc 30 g phô mai Parmesan bào lên trên nếu thích rồi thưởng thức nóng.', 'Mì và sốt trộn nóng trực tiếp giúp tinh bột từ nước luộc kết dính sốt thịt vào sợi mì đồng đều.', NULL),
('gl-12_v4_step_1', 'gl-12', 1, 'prep', 'Sơ chế cà chua hai kiểu cắt và gia vị', 'Rửa sạch 3,5 quả cà chua chín đỏ: 2,5 quả bổ múi cau để giữ kết cấu miếng khi ăn, 1 quả thái hạt lựu nhỏ để nhanh tiết nước làm sốt sánh. Gọt vỏ 6 g gừng tươi, thái lát mỏng; hành lá tươi rửa sạch, thái nhỏ.', 'Kết hợp cà chua thái hạt lựu và cà chua bổ múi cau giúp phần sốt sánh nhanh mà vẫn giữ được miếng cà chua đẹp mắt.', NULL),
('gl-12_v4_step_2', 'gl-12', 2, 'prep', 'Đánh trứng gà với sữa tươi', 'Đập 3 quả trứng gà tươi vào tô, rót vào 20 ml sữa tươi không đường rồi dùng đũa đánh đều nhẹ tay đến khi hỗn hợp đồng nhất, mịn mượt.', 'Thêm một ít sữa tươi vào trứng là bí quyết giúp trứng sau khi xào có độ bồng mềm, béo mượt như trứng chần kiểu Hồng Kông.', NULL),
('gl-12_v4_step_3', 'gl-12', 3, 'cook', 'Chiên mềm trứng gà trên lửa vừa lớn', 'Làm nóng chảo chống dính hoặc chảo lòng sâu với 20 ml dầu ăn trung tính trên lửa vừa lớn. Đổ tô trứng đánh sữa vào, đợi mép trứng vừa se lại thì đẩy nhẹ từ rìa vào giữa tạo các lớp gợn sóng mềm. Khi trứng vừa đông khoảng 80% và vẫn còn ẩm bóng, lập tức trút ra đĩa riêng.', NULL, 2),
('gl-12_v4_step_4', 'gl-12', 4, 'cook', 'Phi gừng thơm và xào nhừ cà chua', 'Thêm 10 ml dầu ăn trung tính còn lại vào chảo, hạ lửa vừa rồi cho các lát gừng tươi vào phi thơm khoảng 1 phút. Tiếp theo, thả cà chua thái hạt lựu vào đảo 2 phút cho mềm nhuyễn ra nước, rồi cho tiếp phần cà chua bổ múi cau vào xào thêm 3 phút đến khi cà chua mềm mọng.', NULL, 5),
('gl-12_v4_step_5', 'gl-12', 5, 'sauce', 'Nêm sốt tương cà, xì dầu và dầu hào', 'Hạ lửa vừa nhỏ, nêm vào chảo cà chua 30 ml tương cà chua, 15 ml xì dầu nhạt, 8 ml dầu hào, 5 g đường cát trắng và 1 g tiêu trắng xay. Đảo đều nhẹ tay khoảng 1 phút để các gia vị tan hoàn toàn, tạo thành phần sốt đỏ cam sánh mịn.', 'Nếm thử độ đậm của sốt trước khi cho trứng vào để dễ điều chỉnh cân bằng giữa vị chua ngọt của tương cà và vị mặn dịu của xì dầu.', NULL),
('gl-12_v4_step_6', 'gl-12', 6, 'finish', 'Đảo quyện trứng với sốt và hoàn thiện', 'Trút toàn bộ trứng gà chiên mềm trở lại chảo sốt cà chua, đảo nhẹ tay 30 giây theo chuyển động hất nhẹ từ dưới lên để sốt áo đều quanh từng mảng trứng mà không làm nát trứng. Tắt bếp, rắc hành lá tươi thái nhỏ lên trên và dùng nóng ngay với cơm trắng.', NULL, NULL),
('imp-199ff78d3d8c8ab3_v4_step_1', 'imp-199ff78d3d8c8ab3', 1, 'prep', 'Sơ chế tôm, giữ đầu vỏ và ướp thịt tôm', 'Rửa sạch 250 g tôm tươi, lột bỏ vỏ và tách riêng phần đầu tôm vào chén sạch để nấu nước dùng. Rạch nhẹ sống lưng rút sạch chỉ đen, rửa lại thịt tôm với nước lạnh rồi để ráo. Ướp phần thịt tôm với một nửa chỗ hành tím băm, 5 ml nước mắm, 2 g muối ăn và 1 g tiêu đen xay trong 10 phút cho thấm vị.', 'Tận dụng phần đầu và vỏ tôm rửa sạch để đun lấy nước dùng giúp nồi canh ngọt đậm tự nhiên mà không cần nhiều gia vị.', 10),
('imp-199ff78d3d8c8ab3_v4_step_2', 'imp-199ff78d3d8c8ab3', 2, 'prep', 'Cắt miếng bí đỏ và băm rau thơm gia vị', 'Gọt vỏ bí đỏ, bỏ hết ruột và hạt, rửa sạch rồi thái miếng vuông cạnh 2,5–3 cm để bí chín đều mà vẫn giữ nguyên khối. Băm nhuyễn phần hành tím còn lại và 10 g tỏi khô; rửa sạch hành lá và ngò rí rồi thái nhỏ.', NULL, NULL),
('imp-199ff78d3d8c8ab3_v4_step_3', 'imp-199ff78d3d8c8ab3', 3, 'cook', 'Nấu và lọc nước dùng ngọt từ đầu vỏ tôm', 'Cho phần đầu và vỏ tôm vào nồi cùng 1,1 lít nước lọc, đun sôi trên lửa lớn rồi hạ lửa vừa nấu thêm 5 phút cho tiết hết chất ngọt. Dùng rây lọc bỏ toàn bộ xác đầu vỏ tôm, giữ lại phần nước dùng tôm trong veo.', NULL, 5),
('imp-199ff78d3d8c8ab3_v4_step_4', 'imp-199ff78d3d8c8ab3', 4, 'cook', 'Phi thơm hành tỏi và xào săn thịt tôm', 'Làm nóng nồi nấu canh trên lửa vừa với 15 ml dầu ăn, cho phần hành tím băm còn lại và tỏi băm vào phi thơm vàng nhẹ. Trút phần thịt tôm đã ướp vào đảo nhanh tay 1–2 phút đến khi tôm vừa săn lại và chuyển màu đỏ cam thì trút tôm ra chén riêng.', 'Xào tôm vừa săn tới rồi vớt ra trước khi hầm bí giúp thịt tôm không bị nấu quá lâu dẫn đến khô bã.', 2),
('imp-199ff78d3d8c8ab3_v4_step_5', 'imp-199ff78d3d8c8ab3', 5, 'cook', 'Nấu bí đỏ chín mềm trong nước dùng tôm', 'Đổ phần nước dùng tôm đã lọc vào nồi vừa xào tôm, đun sôi trên lửa lớn rồi thả toàn bộ bí đỏ cắt miếng vào. Hạ xuống lửa vừa và nấu khoảng 8 phút đến khi dùng đầu đũa xiên qua miếng bí thấy mềm bùi mà không bị nát.', 'Không đậy nắp quá kín và giữ lửa vừa giúp bí chín bùi đều mà miếng bí vẫn giữ nguyên cạnh đẹp mắt.', 8),
('imp-199ff78d3d8c8ab3_v4_step_6', 'imp-199ff78d3d8c8ab3', 6, 'finish', 'Trút tôm vào nồi, nêm nếm và hoàn thiện', 'Nêm 8 g hạt nêm, 3 g muối còn lại và 10 ml nước mắm vào nồi canh, khuấy nhẹ cho tan đều. Thả chén thịt tôm đã xào vào đun sôi lăn tăn thêm 1 phút để tôm chín kỹ hoàn toàn và hòa vị với bí. Tắt bếp, rắc hành lá, ngò rí thái nhỏ và 1 g tiêu đen xay lên mặt rồi múc ra tô dùng nóng.', NULL, NULL),
('imp-ab36e38b07f3a57b_v4_step_1', 'imp-ab36e38b07f3a57b', 1, 'prep', 'Chần sơ sườn non và vắt nước cốt dứa', 'Rửa sạch 600 g sườn non với 2 g muối, chặt miếng 3–4 cm rồi chần trong nồi nước sôi có 2 g muối khoảng 3 phút cho ra bọt bẩn, vớt ra rửa lại nước sạch và để ráo. Gọt vỏ bỏ mắt dứa; một nửa thái miếng tam giác vừa ăn, nửa còn lại giã hoặc băm nhuyễn vắt lấy nước cốt.', 'Ướp sườn với nước cốt dứa tươi không chỉ tạo vị chua ngọt thanh mà enzyme tự nhiên trong dứa còn giúp thớ thịt mềm nhanh hơn.', 4),
('imp-ab36e38b07f3a57b_v4_step_2', 'imp-ab36e38b07f3a57b', 2, 'marinate', 'Ướp sườn non thấm gia vị và nước cốt dứa', 'Cho sườn vào tô lớn, ướp với toàn bộ nước cốt dứa, 35 ml nước mắm ngon, 10 g đường cát trắng, 2 g muối và 1 g tiêu đen xay. Trộn đều rồi ướp trong 25 phút cho sườn ngấm gia vị.', 'Không nên ướp sườn với nước cốt dứa quá 45 phút vì enzyme bromelain có thể làm bề mặt thịt bị bở quá mức.', 25),
('imp-ab36e38b07f3a57b_v4_step_3', 'imp-ab36e38b07f3a57b', 3, 'cook', 'Xào sơ dứa cho dịu vị chua', 'Làm nóng chảo với 10 ml dầu ăn trên lửa vừa, phi thơm một nửa lượng hành tím và tỏi băm. Cho phần dứa cắt miếng cùng 5 g đường cát trắng vào đảo nhanh 4 phút cho dứa bóng mượt và dịu bớt độ chua gắt, trút ra đĩa riêng.', 'Xào trước và chỉ thả dứa vào nồi ở giai đoạn cuối giúp miếng dứa giữ được độ giòn ngọt, không bị nát vụn khi kho.', 4),
('imp-ab36e38b07f3a57b_v4_step_4', 'imp-ab36e38b07f3a57b', 4, 'sauce', 'Thắng nước màu và xào săn sườn non', 'Dùng nồi đáy dày làm nóng 15 ml dầu ăn và 10 g đường cát trắng còn lại trên lửa nhỏ đến khi đường chuyển màu nâu cánh gián, rót nhanh 30 ml nước nóng khuấy đều rồi cho phần hành tím và tỏi băm còn lại vào phi thơm. Trút sườn đã ướp vào đảo săn trên lửa vừa 6 phút cho từng miếng sườn lên màu đẹp.', NULL, 6),
('imp-ab36e38b07f3a57b_v4_step_5', 'imp-ab36e38b07f3a57b', 5, 'cook', 'Kho nhỏ lửa cho sườn non chín mềm', 'Đổ 220 ml nước lọc nóng vào xâm xấp mặt sườn, đun sôi rồi hạ lửa nhỏ, đậy hé vung kho liu riu 25 phút cho thịt sườn chín mềm và nước kho bắt đầu sánh nhẹ.', NULL, 25),
('imp-ab36e38b07f3a57b_v4_step_6', 'imp-ab36e38b07f3a57b', 6, 'finish', 'Kho cùng dứa, nêm lại và trình bày', 'Cho phần dứa đã xào, 10 ml nước mắm còn lại và ớt sừng thái lát vào nồi, đảo nhẹ và kho mở nắp thêm 5 phút trên lửa vừa đến khi nước sốt sánh kẹo bám đều quanh sườn và dứa. Tắt bếp, múc ra đĩa, rắc hành lá cắt nhỏ và 1 g tiêu đen xay còn lại lên trên.', NULL, 5),
('imp-26a36c69306143bc_v4_step_1', 'imp-26a36c69306143bc', 1, 'marinate', 'Làm sạch tôm tươi và ướp gia vị', 'Tôm tươi bóc sạch vỏ, bỏ đầu, rạch nhẹ sống lưng để rút hết chỉ đen, rửa sạch rồi thấm thật ráo nước. Cho tôm vào tô ướp cùng một nửa lượng tỏi băm, 2,5 g hạt nêm và 1 g tiêu đen xay, trộn đều và để thấm khoảng 10 phút.', 'Thấm khô tôm trước khi ướp và xào giúp tôm lên màu đẹp và không bị bắn dầu.', 10),
('imp-26a36c69306143bc_v4_step_2', 'imp-26a36c69306143bc', 2, 'prep', 'Chần sơ và sốc lạnh bông cải xanh', 'Tách bông cải xanh thành từng miếng vừa ăn, rửa sạch và để ráo. Đun sôi nồi nước với 6 g muối ăn trên lửa lớn, thả bông cải vào chần khoảng 1 phút cho vừa chuyển xanh mướt thì vớt ngay ra ngâm vào tô nước đá lạnh 2 phút, sau đó vớt ra rổ để ráo hoàn toàn. Hòa tan 4 g bột bắp với 30 ml nước lọc trong chén nhỏ.', 'Chần nhanh và ngâm nước đá giúp bông cải giữ độ giòn sần sật và màu xanh tươi mắt sau khi xào.', 2),
('imp-26a36c69306143bc_v4_step_3', 'imp-26a36c69306143bc', 3, 'cook', 'Xào săn tôm trên lửa lớn', 'Đặt chảo lên bếp lửa lớn, làm nóng 15 ml dầu ăn rồi cho một phần tỏi băm còn lại vào phi thơm. Trút tôm đã ướp vào đảo nhanh tay khoảng 1,5–2 phút đến khi tôm chuyển màu đỏ cam đều, thân cong tròn săn chắc và chín hoàn toàn thì trút ra đĩa riêng.', 'Không xào tôm quá lâu để thịt tôm giữ được độ giòn ngọt, không bị khô bở.', 2),
('imp-26a36c69306143bc_v4_step_4', 'imp-26a36c69306143bc', 4, 'cook', 'Xào bông cải xanh và hành tây', 'Thêm 15 ml dầu ăn còn lại vào chảo, phi thơm nốt phần tỏi băm cùng hành tây thái múi cau trong 45 giây. Cho bông cải xanh đã ráo nước vào đảo đều trên lửa lớn khoảng 2 phút cho rau nóng đều và thấm dầu tỏi.', NULL, 2),
('imp-26a36c69306143bc_v4_step_5', 'imp-26a36c69306143bc', 5, 'cook', 'Rưới sốt bột bắp và đảo quyện cùng tôm', 'Trút đĩa tôm đã xào trở lại chảo bông cải xanh, nêm 15 ml nước mắm ngon, 2,5 g hạt nêm và 2 g muối ăn. Khuấy lại chén nước bột bắp cho khỏi lắng rồi rưới đều vào chảo, đảo nhanh tay khoảng 1 phút cho lớp sốt sánh nhẹ áo bóng quanh tôm và bông cải.', NULL, NULL),
('imp-26a36c69306143bc_v4_step_6', 'imp-26a36c69306143bc', 6, 'finish', 'Hoàn thiện hương dầu mè và dọn nóng', 'Rưới 3 ml dầu mè thơm vào chảo, đảo đều một lượt rồi tắt bếp ngay. Bày tôm xào bông cải xanh ra đĩa và rắc 1 g tiêu đen xay còn lại lên trên, thưởng thức nóng với cơm trắng.', NULL, NULL),
('imp-b87b71d57128cc07_v4_step_1', 'imp-b87b71d57128cc07', 1, 'prep', 'Làm sạch nhớt, cắt khúc và ướp cá lóc', 'Chà xát cá lóc với 4 g muối ăn và vài lát chanh tươi để hết nhớt, rửa sạch nhiều lần rồi thấm thật khô và cắt khúc dày khoảng 2 cm, khía nhẹ trên da. Băm nhuyễn sả tươi, tỏi, hành tím và 2 quả ớt. Ướp cá với 1/2 lượng sả băm, 1/2 tỏi băm, hành tím, 1 quả ớt băm, 2 g muối, 4 g hạt nêm, 4 g đường, 2 g tiêu đen xay và 3 g bột nghệ trong 20 phút cho thấm.', 'Khứa nhẹ trên da và thấm khô mặt cá trước khi ướp giúp gia vị bám sâu và khi chiên không bị bắn dầu.', 20),
('imp-b87b71d57128cc07_v4_step_2', 'imp-b87b71d57128cc07', 2, 'prep', 'Pha bột áo chiên giòn cho cá', 'Cho 50 g bột chiên giòn, 2 g muối ăn còn lại và 60 ml nước lọc vào tô, khuấy đều đến khi thu được hỗn hợp bột sền sệt mịn màng đủ bám một lớp áo mỏng quanh khúc cá.', NULL, NULL),
('imp-b87b71d57128cc07_v4_step_3', 'imp-b87b71d57128cc07', 3, 'cook', 'Chiên vàng giòn sả băm và tỏi băm trước', 'Đun nóng 250 ml dầu ăn trong chảo sâu lòng ở lửa vừa, thả 1/2 phần sả băm còn lại vào chiên trước khoảng 3 phút cho vàng thơm rồi mới cho 1/2 phần tỏi băm còn lại vào đảo thêm 1 phút đến khi vàng giòn đều thì vớt ngay ra rây để ráo dầu.', 'Sả chứa nhiều nước và lâu chín hơn tỏi nên phải chiên sả trước rồi mới thả tỏi vào, tránh để tỏi cháy đắng.', 4),
('imp-b87b71d57128cc07_v4_step_4', 'imp-b87b71d57128cc07', 4, 'cook', 'Chiên ngập dầu cá lóc tẩm bột đến khi giòn rụm', 'Giữ chảo dầu thơm đang nóng ở lửa vừa, nhúng từng khúc cá lóc đã ướp (gạt bớt sả băm để không cháy) qua lớp bột chiên giòn sệt rồi thả vào chiên mỗi mặt 4 phút cho vàng ươm. Cuối cùng tăng lửa lớn trong 1 phút để thoát bớt dầu và vỏ giòn lâu, kiểm tra thịt cá trắng đục chín hoàn toàn rồi vớt ra giấy thấm dầu.', 'Tăng lửa lớn 1 phút cuối trước khi vớt là mẹo giúp đẩy dầu thừa ra ngoài, giúp cá lóc giòn lâu mà không bị ngấy.', 9),
('imp-b87b71d57128cc07_v4_step_5', 'imp-b87b71d57128cc07', 5, 'finish', 'Xóc cá cùng sả tỏi phi và pha nước chấm', 'Chắt hết dầu trong chảo, cho cá chiên vào xóc nhanh tay cùng sả tỏi chiên vàng và 1 quả ớt băm còn lại trong 30 giây cho bám đều hương thơm. Trong chén nhỏ, khuấy tan 30 ml nước mắm ngon với 4 g đường, vài giọt nước cốt chanh và ớt thái lát để làm nước chấm.', NULL, NULL),
('imp-b87b71d57128cc07_v4_step_6', 'imp-b87b71d57128cc07', 6, 'finish', 'Bày cá chiên sả ớt ra đĩa và thưởng thức', 'Xếp các khúc cá lóc chiên vàng giòn ra đĩa, rắc hết phần sả tỏi phi giòn lên mặt cùng lát ớt tươi trang trí và dọn ăn ngay với cơm trắng nóng.', NULL, NULL);
